/* Original curriculum-referenced starter questions. Teacher review and local sequencing required. */
window.GRADE_CONTENT_VERSION = "hk-curriculum-2026-10-v2";
window.GRADE_CONTENT = [{"id":"s1-chinese-01","grade":1,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"從動作推知心情","cn":"从动作推知心情","en":"Inferring emotion from actions"},"question":{"zh":"小段：『輪到她上臺時，她把講稿捏成一團，走了兩步又回頭望老師。』哪個推論最有文字支持？","cn":"小段：『轮到她上台时，她把讲稿捏成一团，走了两步又回头望老师。』哪个推论最有文字支持？","en":"Read: 『輪到她上台時，她把講稿捏成一團，走了兩步又回頭望老師。』 Which inference is best supported?"},"options":[{"text":{"zh":"她已決定放棄演講","cn":"她已决定放弃演讲","en":"She has decided to abandon the speech"},"correct":false,"feedback":{"zh":"文中沒有交代她離場或放棄。","cn":"文中没有交代她离场或放弃。","en":"The passage does not say she leaves or withdraws."},"id":"a"},{"text":{"zh":"她因老師遲到而生氣","cn":"她因老师迟到而生气","en":"She is angry because the teacher is late"},"correct":false,"feedback":{"zh":"文中沒有遲到這個原因。","cn":"文中没有迟到这个原因。","en":"No lateness is mentioned."},"id":"b"},{"text":{"zh":"她緊張，可能在尋求鼓勵","cn":"她紧张，可能在寻求鼓励","en":"She is nervous and may be seeking reassurance"},"correct":true,"feedback":{"zh":"捏稿、回望都是動作線索，推論保留了可能性。","cn":"捏稿、回望都是动作线索，推论保留了可能性。","en":"The crumpled notes and backward glance support a cautious inference."},"id":"c"}],"takeaway":{"zh":"推論須有具體字句支持，也要保留未能確定的部分。","cn":"推论须有具体字句支持，也要保留未能确定的部分。","en":"Ground an inference in textual details and retain uncertainty."}},{"id":"s1-chinese-02","grade":1,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"指代與段落銜接","cn":"指代与段落衔接","en":"Reference and cohesion"},"question":{"zh":"『學校增加了午間閱讀時段，也把圖書角移到走廊。這兩項改動讓借閱更方便。』『這兩項改動』指甚麼？","cn":"『学校增加了午间阅读时段，也把图书角移到走廊。这两项改动让借阅更方便。』『这两项改动』指甚么？","en":"In『學校增加了午間閱讀時段，也把圖書角移到走廊。這兩項改動讓借閱更方便。』 what does『這兩項改動』refer to?"},"options":[{"text":{"zh":"增加閱讀時段及遷移圖書角","cn":"增加阅读时段及迁移图书角","en":"Adding reading time and moving the book corner"},"correct":true,"feedback":{"zh":"指代須對應前句的兩個行動。","cn":"指代须对应前句的两个行动。","en":"The reference links to the two actions in the preceding sentence."},"id":"a"},{"text":{"zh":"閱讀和借閱的學生","cn":"阅读和借阅的学生","en":"The students who read and borrow"},"correct":false,"feedback":{"zh":"『改動』指措施，不是人物。","cn":"『改动』指措施，不是人物。","en":"The expression refers to changes, not people."},"id":"b"},{"text":{"zh":"走廊及午間","cn":"走廊及午间","en":"The corridor and lunchtime"},"correct":false,"feedback":{"zh":"兩者是地方與時間，未包含改變的動作。","cn":"两者是地方与时间，未包含改变的动作。","en":"These name a place and time, not the actions taken."},"id":"c"}],"takeaway":{"zh":"辨認指代時，兼看語意、數量和上下文。","cn":"辨认指代时，兼看语意、数量和上下文。","en":"Resolve reference using meaning, number and context."}},{"id":"s1-chinese-03","grade":1,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"抓住事件主線","cn":"抓住事件主线","en":"Selecting a narrative summary"},"question":{"zh":"『雨愈下愈大，球賽取消了。隊員起初抱怨，後來搬開課室桌椅，邀請低年級同學一起玩室內接力。散場時，大家相約再辦。』哪個摘要最完整而不加推測？","cn":"『雨愈下愈大，球赛取消了。队员起初抱怨，后来搬开课室桌椅，邀请低年级同学一起玩室内接力。散场时，大家相约再办。』哪个摘要最完整而不加推测？","en":"Read: 『雨愈下愈大，球賽取消了。隊員起初抱怨，後來搬開課室桌椅，邀請低年級同學一起玩室內接力。散場時，大家相約再辦。』Choose a concise summary without invention."},"options":[{"text":{"zh":"老師命令隊員舉辦活動，所以大家不滿","cn":"老师命令队员举办活动，所以大家不满","en":"A teacher ordered the activity, making everyone unhappy"},"correct":false,"feedback":{"zh":"原文沒有老師命令，結尾亦不是不滿。","cn":"原文没有老师命令，结尾亦不是不满。","en":"The order is invented and the ending is misrepresented."},"id":"a"},{"text":{"zh":"球賽因雨取消，隊員改辦受歡迎的室內活動","cn":"球赛因雨取消，队员改办受欢迎的室内活动","en":"Rain cancelled the match; the team organised a well-received indoor activity"},"correct":true,"feedback":{"zh":"包含起因、轉變和結果，沒有新增原因。","cn":"包含起因、转变和结果，没有新增原因。","en":"This retains the cause, change and outcome without inventing motives."},"id":"b"},{"text":{"zh":"隊員搬桌椅後散場","cn":"队员搬桌椅后散场","en":"The team moved desks and then left"},"correct":false,"feedback":{"zh":"只取零碎動作，漏掉事件轉變。","cn":"只取零碎动作，漏掉事件转变。","en":"This omits the central change in the event."},"id":"c"}],"takeaway":{"zh":"摘要保留主線與轉變，不逐項抄細節。","cn":"摘要保留主线与转变，不逐项抄细节。","en":"A summary preserves the main sequence and change rather than listing details."}},{"id":"s2-chinese-01","grade":2,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"比喻的表達作用","cn":"比喻的表达作用","en":"Explaining a metaphor"},"question":{"zh":"『每逢爭執，班長總像橋樑，把兩邊的話接起來。』『橋樑』在此主要突出甚麼？","cn":"『每逢争执，班长总像桥梁，把两边的话接起来。』『桥梁』在此主要突出甚么？","en":"In『每逢爭執，班長總像橋樑，把兩邊的話接起來。』 what does the bridge metaphor emphasise?"},"options":[{"text":{"zh":"班長促進雙方溝通","cn":"班长促进双方沟通","en":"The monitor connects opposing views"},"correct":true,"feedback":{"zh":"橋樑連接兩端，對應調解中的溝通作用。","cn":"桥梁连接两端，对应调解中的沟通作用。","en":"A bridge connects two sides, matching the mediator's role."},"id":"a"},{"text":{"zh":"班長身材高大","cn":"班长身材高大","en":"The monitor is physically tall"},"correct":false,"feedback":{"zh":"上下文談爭執，沒有描述身高。","cn":"上下文谈争执，没有描述身高。","en":"The context concerns conflict, not height."},"id":"b"},{"text":{"zh":"班長永遠沒有自己的意見","cn":"班长永远没有自己的意见","en":"The monitor never has personal opinions"},"correct":false,"feedback":{"zh":"協助溝通不等於沒有立場。","cn":"协助沟通不等于没有立场。","en":"Facilitating communication does not imply having no views."},"id":"c"}],"takeaway":{"zh":"說明修辭作用，要把形象與具體語境連起來。","cn":"说明修辞作用，要把形象与具体语境连起来。","en":"Explain how a figurative image works in its specific context."}},{"id":"s2-chinese-02","grade":2,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"實用文的對象","cn":"实用文的对象","en":"Writing for an audience"},"question":{"zh":"學生會寫信向校長申請延長圖書館午間開放。哪個開頭最能清楚交代目的及理由？","cn":"学生会写信向校长申请延长图书馆午间开放。哪个开头最能清楚交代目的及理由？","en":"The student council requests longer lunchtime library access. Which opening best states the purpose and reason?"},"options":[{"text":{"zh":"如果不延長開放，就代表學校不重視閱讀。","cn":"如果不延长开放，就代表学校不重视阅读。","en":"Refusing longer access means the school does not value reading."},"correct":false,"feedback":{"zh":"把單一決定等同整體價值判斷，語氣武斷。","cn":"把单一决定等同整体价值判断，语气武断。","en":"This makes an unsupported judgment from one possible decision."},"id":"a"},{"text":{"zh":"本會建議午間延長開放十五分鐘，讓較遲午膳的同學也能借閱。","cn":"本会建议午间延长开放十五分钟，让较迟午膳的同学也能借阅。","en":"We propose an extra fifteen minutes so students with later lunch can borrow books."},"correct":true,"feedback":{"zh":"對象、建議和受益原因清楚，語氣得體。","cn":"对象、建议和受益原因清楚，语气得体。","en":"The proposal and its reason are clear and appropriately expressed."},"id":"b"},{"text":{"zh":"圖書館是我們學校的一座建築物。","cn":"图书馆是我们学校的一座建筑物。","en":"The library is a building at our school."},"correct":false,"feedback":{"zh":"陳述常識，未交代申請目的。","cn":"陈述常识，未交代申请目的。","en":"This states a general fact without the request."},"id":"c"}],"takeaway":{"zh":"實用文須配合對象、目的及可核實的理由。","cn":"实用文须配合对象、目的及可核实的理由。","en":"Practical writing should fit its audience, purpose and substantiated reasons."}},{"id":"s2-chinese-03","grade":2,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"文言詞義與語境","cn":"文言词义与语境","en":"Interpreting a classical-style word"},"question":{"zh":"自擬短句：『少年問路，翁指橋曰：「由此往，近矣。」少年從之。』末句『從』最合語境的意思是甚麼？","cn":"自拟短句：『少年问路，翁指桥曰：「由此往，近矣。」少年从之。』末句『从』最合语境的意思是甚么？","en":"In this original classical-style passage, 『少年問路，翁指橋曰：「由此往，近矣。」少年從之。』 what does『從』mean?"},"options":[{"text":{"zh":"從某個地方出發的介詞","cn":"从某个地方出发的介词","en":"A preposition meaning from a place"},"correct":false,"feedback":{"zh":"此處『從』後沒有出發地，而是指代建議的『之』。","cn":"此处『从』后没有出发地，而是指代建议的『之』。","en":"No departure place follows; the pronoun refers back to the advice."},"id":"a"},{"text":{"zh":"隨從的名詞","cn":"随从的名词","en":"A noun meaning attendant"},"correct":false,"feedback":{"zh":"句中需要少年所做的動作，不是身分名詞。","cn":"句中需要少年所做的动作，不是身分名词。","en":"The sentence requires the boy's action, not a role noun."},"id":"b"},{"text":{"zh":"依照老人的指示行事","cn":"依照老人的指示行事","en":"Follow the elder's directions"},"correct":true,"feedback":{"zh":"『之』承接前面的建議，表示依從。","cn":"『之』承接前面的建议，表示依从。","en":"The pronoun links to the advice, supporting the sense of following it."},"id":"c"}],"takeaway":{"zh":"文言一詞多義，應以句法和前文判斷。","cn":"文言一词多义，应以句法和前文判断。","en":"Use syntax and preceding context to distinguish meanings of a classical word."}},{"id":"s3-chinese-01","grade":3,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"論點與論據","cn":"论点与论据","en":"Matching evidence to a claim"},"question":{"zh":"哪項證據最直接支持「分流上車能減少校巴隊伍等候時間」？","cn":"哪项证据最直接支持「分流上车能减少校巴队伍等候时间」？","en":"Which evidence most directly supports the claim that separate boarding queues reduce school-bus waiting time?"},"options":[{"text":{"zh":"司機的制服在去年更換。","cn":"司机的制服在去年更换。","en":"Drivers received new uniforms last year."},"correct":false,"feedback":{"zh":"制服更換與這項分流安排的效果沒有直接證據關係。","cn":"制服更换与这项分流安排的效果没有直接证据关系。","en":"A uniform change supplies no direct evidence about this boarding arrangement."},"id":"a"},{"text":{"zh":"在相近人數下，試行分流後平均等候由 12 分鐘降至 7 分鐘。","cn":"在相近人数下，试行分流后平均等候由 12 分钟降至 7 分钟。","en":"With similar passenger numbers, mean waiting time fell from 12 to 7 minutes after the trial."},"correct":true,"feedback":{"zh":"這項資料直接量度主張涉及的等候時間，且交代人數條件。","cn":"这项资料直接量度主张涉及的等候时间，且交代人数条件。","en":"This directly measures the claimed waiting-time outcome and states a comparable passenger count."},"id":"b"},{"text":{"zh":"校巴車身改用新的藍色油漆。","cn":"校巴车身改用新的蓝色油漆。","en":"The buses were repainted blue."},"correct":false,"feedback":{"zh":"車身顏色沒有直接量度排隊時間或分流效果。","cn":"车身颜色没有直接量度排队时间或分流效果。","en":"Vehicle colour does not directly measure waiting time or queue separation."},"id":"c"}],"takeaway":{"zh":"支持論點的證據應直接量度相關結果，並交代可比條件。","cn":"支持论点的证据应直接量度相关结果，并交代可比条件。","en":"Evidence should directly measure the relevant outcome and state comparable conditions."}},{"id":"s3-chinese-02","grade":3,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"回應反方理由","cn":"回应反方理由","en":"Responding to an objection"},"question":{"zh":"有人反對增設花圃，理由是沒有人手長期打理。哪個回應最直接處理這項疑慮？","cn":"有人反对增设花圃，理由是没有人手长期打理。哪个回应最直接处理这项疑虑？","en":"Someone opposes a new garden because there is insufficient staff for ongoing maintenance. Which response directly addresses the objection?"},"options":[{"text":{"zh":"花比水泥地漂亮，所以不用討論人手。","cn":"花比水泥地漂亮，所以不用讨论人手。","en":"Flowers look nicer than concrete, so staffing need not be discussed."},"correct":false,"feedback":{"zh":"美觀沒有回應持續維護的資源問題。","cn":"美观没有回应持续维护的资源问题。","en":"Appearance does not address ongoing maintenance resources."},"id":"a"},{"text":{"zh":"反對的人一定討厭大自然。","cn":"反对的人一定讨厌大自然。","en":"Opponents must dislike nature."},"correct":false,"feedback":{"zh":"這攻擊提出疑慮的人，沒有回應其理由。","cn":"这攻击提出疑虑的人，没有回应其理由。","en":"This attacks people rather than responding to their reason."},"id":"b"},{"text":{"zh":"先試設一小區，由受訓園藝組輪值，記錄所需工時後再檢討。","cn":"先试设一小区，由受训园艺组轮值，记录所需工时后再检讨。","en":"Trial a small plot with a trained gardening-club rota, recording maintenance hours before review."},"correct":true,"feedback":{"zh":"這承認持續人手的限制，提出可檢驗的安排。","cn":"这承认持续人手的限制，提出可检验的安排。","en":"This acknowledges the staffing constraint and proposes a testable arrangement."},"id":"c"}],"takeaway":{"zh":"回應異議應處理其核心理由，不把對方簡化成標籤。","cn":"回应异议应处理其核心理由，不把对方简化成标签。","en":"Answer the substance of an objection instead of labelling its speaker."}},{"id":"s3-chinese-03","grade":3,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"因果推論的限度","cn":"因果推论的限度","en":"Limits of causal language"},"question":{"zh":"報告說減廢宣傳後午膳剩食下降；同月供應商亦調小份量。哪個標題最忠於資料？","cn":"报告说减废宣传后午膳剩食下降；同月供应商亦调小份量。哪个标题最忠于资料？","en":"A report says lunch waste fell after a campaign; the supplier also reduced portions that month. Which headline is most faithful?"},"options":[{"text":{"zh":"午膳剩食減少；宣傳與份量調整的影響仍待分辨。","cn":"午膳剩食减少；宣传与份量调整的影响仍待分辨。","en":"Lunch waste falls; effects of the campaign and portion changes remain to be separated."},"correct":true,"feedback":{"zh":"兩項改變同時出現，不能單獨確定宣傳的因果效果。","cn":"两项改变同时出现，不能单独确定宣传的因果效果。","en":"Two changes coincide, so the campaign effect cannot be isolated."},"id":"a"},{"text":{"zh":"宣傳已證明是剩食下降的唯一原因。","cn":"宣传已证明是剩食下降的唯一原因。","en":"The campaign is proven to be the sole cause of lower waste."},"correct":false,"feedback":{"zh":"這忽略同時調整份量的另一解釋。","cn":"这忽略同时调整份量的另一解释。","en":"This ignores the simultaneous portion change as an alternative explanation."},"id":"b"},{"text":{"zh":"所有學生已改變飲食習慣。","cn":"所有学生已改变饮食习惯。","en":"Every student has changed eating habits."},"correct":false,"feedback":{"zh":"總剩食資料不能證明每位學生的行為變化。","cn":"总剩食资料不能证明每位学生的行为变化。","en":"Aggregate waste does not establish each individual student’s behaviour change."},"id":"c"}],"takeaway":{"zh":"語氣強度應配合證據，時間先後不足以證明單一因果。","cn":"语气强度应配合证据，时间先后不足以证明单一因果。","en":"Match claim strength to evidence; sequence alone does not prove sole causation."}},{"id":"s4-chinese-01","grade":4,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"意象與情感轉折","cn":"意象与情感转折","en":"Imagery and emotional change"},"question":{"zh":"『初到舊校舍，我只嫌牆上裂痕難看。離校那天，夕陽落進裂痕，像替歲月縫上金線。』裂痕意象的變化主要表達甚麼？","cn":"『初到旧校舍，我只嫌墙上裂痕难看。离校那天，夕阳落进裂痕，像替岁月缝上金线。』裂痕意象的变化主要表达甚么？","en":"Read: 『初到舊校舍，我只嫌牆上裂痕難看。離校那天，夕陽落進裂痕，像替歲月縫上金線。』 What does the changed image express?"},"options":[{"text":{"zh":"校舍已完成修補工程","cn":"校舍已完成修补工程","en":"The building has been repaired"},"correct":false,"feedback":{"zh":"『像』標示比喻，不能當作工程紀錄。","cn":"『像』标示比喻，不能当作工程纪录。","en":"The simile is not evidence of physical repair."},"id":"a"},{"text":{"zh":"敘述者始終認為校舍毫無價值","cn":"叙述者始终认为校舍毫无价值","en":"The narrator consistently sees no value in the building"},"correct":false,"feedback":{"zh":"這忽略『金線』帶來的珍惜意味。","cn":"这忽略『金线』带来的珍惜意味。","en":"This ignores the positive value suggested by golden stitching."},"id":"b"},{"text":{"zh":"敘述者由嫌棄轉為珍惜共同生活的痕跡","cn":"叙述者由嫌弃转为珍惜共同生活的痕迹","en":"The narrator comes to value traces of shared experience"},"correct":true,"feedback":{"zh":"同一景物被重新理解，呼應前後態度轉變。","cn":"同一景物被重新理解，呼应前后态度转变。","en":"The same feature is reinterpreted, marking an emotional change."},"id":"c"}],"takeaway":{"zh":"分析意象時留意其在篇章中的變化，而非只列修辭名稱。","cn":"分析意象时留意其在篇章中的变化，而非只列修辞名称。","en":"Analyse how an image changes across a passage, not only its rhetorical label."}},{"id":"s4-chinese-02","grade":4,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"虛詞與論述關係","cn":"虚词与论述关系","en":"Connectives in classical-style prose"},"question":{"zh":"自擬短文：『眾以路遠而止，舟子曰：「遠非不可至，惟須備糧。」乃整舟而行。』『乃』在末句主要承接甚麼？","cn":"自拟短文：『众以路远而止，舟子曰：「远非不可至，惟须备粮。」乃整舟而行。』『乃』在末句主要承接甚么？","en":"In this original passage, 『眾以路遠而止，舟子曰：「遠非不可至，惟須備糧。」乃整舟而行。』 what relationship does『乃』express?"},"options":[{"text":{"zh":"接受建議後，於是準備船隻出發","cn":"接受建议后，于是准备船只出发","en":"After accepting the advice, they therefore prepare and depart"},"correct":true,"feedback":{"zh":"末句是前述商議後的後續行動。","cn":"末句是前述商议后的后续行动。","en":"The final action follows from the preceding advice."},"id":"a"},{"text":{"zh":"出發很久之後纔有人提出建議","cn":"出发很久之后才有人提出建议","en":"The advice is offered long after departure"},"correct":false,"feedback":{"zh":"這倒置了篇章的先後次序。","cn":"这倒置了篇章的先后次序。","en":"This reverses the order of events."},"id":"b"},{"text":{"zh":"儘管沒有船，仍能出發","cn":"尽管没有船，仍能出发","en":"They depart despite having no boat"},"correct":false,"feedback":{"zh":"『乃』此處不表示這項讓步，文中亦沒有缺船。","cn":"『乃』此处不表示这项让步，文中亦没有缺船。","en":"Neither that concession nor a missing boat appears in the passage."},"id":"c"}],"takeaway":{"zh":"虛詞的功能要放回論述和事件順序中理解。","cn":"虚词的功能要放回论述和事件顺序中理解。","en":"Interpret a connective through the argument and sequence of events."}},{"id":"s4-chinese-03","grade":4,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"整合資料提出建議","cn":"整合资料提出建议","en":"Integrating information into a proposal"},"question":{"zh":"材料甲：60% 受訪者希望運動會有安靜休息區。材料乙：只得兩名輪值職員，中午需求最高。哪個建議最能綜合兩份材料？","cn":"材料甲：60% 受访者希望运动会有安静休息区。材料乙：只得两名轮值职员，中午需求最高。哪个建议最能综合两份材料？","en":"Source A: 60% of respondents want a quiet rest area at sports day. Source B: only two staff can rotate, and demand peaks at noon. Which proposal best integrates both?"},"options":[{"text":{"zh":"兩名職員必定不能管理任何形式的休息區。","cn":"两名职员必定不能管理任何形式的休息区。","en":"Two staff cannot possibly manage any form of rest area."},"correct":false,"feedback":{"zh":"這沒有考慮縮小規模或試行，結論超出材料。","cn":"这没有考虑缩小规模或试行，结论超出材料。","en":"This rules out scaled trials without supporting evidence."},"id":"a"},{"text":{"zh":"先在中午試開一個安靜休息區，按可用人手安排，並檢討使用情況。","cn":"先在中午试开一个安静休息区，按可用人手安排，并检讨使用情况。","en":"Trial one quiet rest area at noon with available staffing, then review its use."},"correct":true,"feedback":{"zh":"這同時回應休息需求、時段資料及人手限制。","cn":"这同时回应休息需求、时段资料及人手限制。","en":"This combines the need for rest, timing evidence and staffing constraint."},"id":"b"},{"text":{"zh":"全日開十個休息區，因為 60% 希望有休息地方。","cn":"全日开十个休息区，因为 60% 希望有休息地方。","en":"Open ten rest areas all day because 60% want a place to rest."},"correct":false,"feedback":{"zh":"民意支持不能取消人手限制，材料亦沒有支持十個區的數量。","cn":"民意支持不能取消人手限制，材料亦没有支持十个区的数量。","en":"Support does not remove the staffing limit or justify ten areas."},"id":"c"}],"takeaway":{"zh":"綜合寫作要轉化資料為有條件、可實行的論述。","cn":"综合写作要转化资料为有条件、可实行的论述。","en":"Integrated writing turns evidence into a qualified, feasible argument."}},{"id":"s5-chinese-01","grade":5,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"反語與敘述態度","cn":"反语与叙述态度","en":"Irony and stance"},"question":{"zh":"『校門掛起「聆聽每把聲音」的橫額。諮詢會卻在學生上課時舉行，最後記錄寫着：「沒有學生反對。」這真是一次周全的聆聽。』末句的作用是甚麼？","cn":"『校门挂起「聆听每把声音」的横额。咨询会却在学生上课时举行，最后记录写着：「没有学生反对。」这真是一次周全的聆听。』末句的作用是甚么？","en":"Read: 『校門掛起「聆聽每把聲音」的橫額。諮詢會卻在學生上課時舉行，最後記錄寫着：「沒有學生反對。」這真是一次周全的聆聽。』 What does the final sentence do?"},"options":[{"text":{"zh":"以反語批評程序與宣稱不一致","cn":"以反语批评程序与宣称不一致","en":"Uses irony to criticise a gap between process and claim"},"correct":true,"feedback":{"zh":"上課時間排除了參與機會，與『周全』形成反差。","cn":"上课时间排除了参与机会，与『周全』形成反差。","en":"The exclusionary timing contradicts the praise of comprehensive listening."},"id":"a"},{"text":{"zh":"直接證明所有學生贊同措施","cn":"直接证明所有学生赞同措施","en":"Proves every student supports the policy"},"correct":false,"feedback":{"zh":"缺席者沒有發言，不等於贊同。","cn":"缺席者没有发言，不等于赞同。","en":"Silence from absent participants is not agreement."},"id":"b"},{"text":{"zh":"客觀記錄會議開幕時間","cn":"客观记录会议开幕时间","en":"Objectively records the meeting's starting time"},"correct":false,"feedback":{"zh":"末句是態度表達，不是時間資料。","cn":"末句是态度表达，不是时间资料。","en":"The sentence expresses a stance, not timing data."},"id":"c"}],"takeaway":{"zh":"判斷反語須結合字面意思與上下文的矛盾。","cn":"判断反语须结合字面意思与上下文的矛盾。","en":"Identify irony through the tension between literal wording and context."}},{"id":"s5-chinese-02","grade":5,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"限制語與論證精確度","cn":"限制语与论证精确度","en":"Qualifying a claim precisely"},"question":{"zh":"社團時段自願問卷收到 80 份回覆，其中 56 人支持改到星期三。草稿寫「全校七成人支持星期三」。怎樣修訂最精確？","cn":"社团时段自愿问卷收到 80 份回复，其中 56 人支持改到星期三。草稿写「全校七成人支持星期三」。怎样修订最精确？","en":"A voluntary club-scheduling survey receives 80 responses, 56 favouring Wednesday. The draft claims 70% of the whole school supports Wednesday. What is the most precise revision?"},"options":[{"text":{"zh":"全校沒有人支持","cn":"全校没有人支持","en":"Nobody in the school supports it"},"correct":false,"feedback":{"zh":"56名支持者與這個結論直接矛盾。","cn":"56名支持者与这个结论直接矛盾。","en":"The 56 supporting responses contradict this claim."},"id":"a"},{"text":{"zh":"七成回覆者支持星期三；這不能確定全校的支持比例。","cn":"七成回复者支持星期三；这不能确定全校的支持比例。","en":"70% of respondents support Wednesday; this does not establish the school-wide proportion."},"correct":true,"feedback":{"zh":"須分清自願回覆者與全校學生，不能直接外推。","cn":"须分清自愿回复者与全校学生，不能直接外推。","en":"Distinguish voluntary respondents from the whole student population."},"id":"b"},{"text":{"zh":"全校至少七成支持","cn":"全校至少七成支持","en":"At least 70% of the school supports it"},"correct":false,"feedback":{"zh":"資料沒有提供全校支持比例的下限。","cn":"资料没有提供全校支持比例的下限。","en":"No school-wide lower bound is established."},"id":"c"}],"takeaway":{"zh":"寫作中的限制語應交代樣本及結論的適用範圍。","cn":"写作中的限制语应交代样本及结论的适用范围。","en":"Qualifiers should identify the sample and the scope of a conclusion."}},{"id":"s5-chinese-03","grade":5,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"表面矛盾與資料口徑","cn":"表面矛盾与资料口径","en":"Reconciling apparent disagreement"},"question":{"zh":"報告甲說博物館實地參觀人次下降；報告乙說整體參與增加，並計入網上展覽。哪個綜合最合理？","cn":"报告甲说博物馆实地参观人次下降；报告乙说整体参与增加，并计入网上展览。哪个综合最合理？","en":"Report A says physical museum visits fell; report B says overall engagement rose and includes online exhibitions. What is the soundest synthesis?"},"options":[{"text":{"zh":"兩報告必有一份造假","cn":"两报告必有一份造假","en":"One report must be fabricated"},"correct":false,"feedback":{"zh":"不同定義已足以產生不同趨勢，未有造假證據。","cn":"不同定义已足以产生不同趋势，未有造假证据。","en":"Different definitions can explain the trends without evidence of fabrication."},"id":"a"},{"text":{"zh":"網上參與增加，就證明實地參觀也增加。","cn":"网上参与增加，就证明实地参观也增加。","en":"Increased online engagement proves physical visits also increased."},"correct":false,"feedback":{"zh":"兩種參與方式可有不同趨勢，不能互相代替。","cn":"两种参与方式可有不同趋势，不能互相代替。","en":"The two forms of engagement can follow different trends and cannot stand in for each other."},"id":"b"},{"text":{"zh":"兩者量度範圍不同，可以同時成立；先統一定義再比較。","cn":"两者量度范围不同，可以同时成立；先统一定义再比较。","en":"Their measures differ and may both be true; align definitions before comparing."},"correct":true,"feedback":{"zh":"實地參觀與包含網上活動的總參與不是同一指標。","cn":"实地参观与包含网上活动的总参与不是同一指标。","en":"Physical visits and total engagement including online activities are different indicators."},"id":"c"}],"takeaway":{"zh":"綜合相異資料前，先核對定義、範圍及分母。","cn":"综合相异资料前，先核对定义、范围及分母。","en":"Before synthesising conflicting sources, compare definitions, scope and denominators."}},{"id":"s6-chinese-01","grade":6,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"辨識稻草人論證","cn":"辨识稻草人论证","en":"Recognising a distorted rebuttal"},"question":{"zh":"甲主張『高風險AI評分應保留教師覆核』。乙回應『甲想禁止所有科技，讓學校倒退』。乙的主要論證問題是甚麼？","cn":"甲主张『高风险AI评分应保留教师覆核』。乙回应『甲想禁止所有科技，让学校倒退』。乙的主要论证问题是甚么？","en":"A argues that high-stakes AI scoring should retain teacher review. B replies that A wants to ban all technology and hold schools back. What is the main flaw?"},"options":[{"text":{"zh":"甲沒有說明任何使用AI的場景","cn":"甲没有说明任何使用AI的场景","en":"A specifies no AI-use context"},"correct":false,"feedback":{"zh":"高風險評分已是一個具體範圍。","cn":"高风险评分已是一个具体范围。","en":"High-stakes scoring defines a specific context."},"id":"a"},{"text":{"zh":"把有限度的覆核要求歪曲為全面禁止","cn":"把有限度的覆核要求歪曲为全面禁止","en":"Distorting a limited review requirement into a total ban"},"correct":true,"feedback":{"zh":"乙反駁的是擴大的主張，不是甲實際說法。","cn":"乙反驳的是扩大的主张，不是甲实际说法。","en":"B attacks an exaggerated position rather than the stated claim."},"id":"b"},{"text":{"zh":"A 沒有提供足夠數據，所以 B 已回應覆核是否必要。","cn":"A 没有提供足够数据，所以 B 已回应覆核是否必要。","en":"A lacks numerical data, so B has already answered whether review is necessary."},"correct":false,"feedback":{"zh":"即使 A 可補證據，B 仍須回應有限覆核要求，不能把它改成全面禁用。","cn":"即使 A 可补证据，B 仍须回应有限覆核要求，不能把它改成全面禁用。","en":"Even if A needs more evidence, B still needs to address the limited review proposal rather than turn it into a total ban."},"id":"c"}],"takeaway":{"zh":"有效反駁須準確重述對方論點及限制條件。","cn":"有效反驳须准确重述对方论点及限制条件。","en":"A valid rebuttal represents the opposing claim and its limits accurately."}},{"id":"s6-chinese-02","grade":6,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"敘述視角的可靠程度","cn":"叙述视角的可靠程度","en":"Evaluating narrative reliability"},"question":{"zh":"『他在臺下低頭，我認定他不屑我的演講。多年後讀到他的日記，才知那天他正記下我說的每一句話。』後一句如何改變前文？","cn":"『他在台下低头，我认定他不屑我的演讲。多年后读到他的日记，才知那天他正记下我说的每一句话。』后一句如何改变前文？","en":"Read: 『他在台下低頭，我認定他不屑我的演講。多年後讀到他的日記，才知那天他正記下我說的每一句話。』How does the second sentence reshape the first?"},"options":[{"text":{"zh":"證明第一人稱敘述的全部事實都是虛構","cn":"证明第一人称叙述的全部事实都是虚构","en":"Proves all facts in first-person narration are invented"},"correct":false,"feedback":{"zh":"一項誤判不使所有可觀察事實都失效。","cn":"一项误判不使所有可观察事实都失效。","en":"One mistaken interpretation does not invalidate every observed fact."},"id":"a"},{"text":{"zh":"使低頭這個動作不曾發生","cn":"使低头这个动作不曾发生","en":"Means the downward glance never happened"},"correct":false,"feedback":{"zh":"被修正的是動機判斷，不是動作本身。","cn":"被修正的是动机判断，不是动作本身。","en":"The motive is reinterpreted; the action remains."},"id":"b"},{"text":{"zh":"揭示當年『我』把可見動作誤作確定的心理證據","cn":"揭示当年『我』把可见动作误作确定的心理证据","en":"Reveals that the narrator mistook an action for certain evidence of motive"},"correct":true,"feedback":{"zh":"新資料區分了觀察與當年的主觀解釋。","cn":"新资料区分了观察与当年的主观解释。","en":"New evidence separates the observation from its earlier interpretation."},"id":"c"}],"takeaway":{"zh":"分析敘述可靠性，要區分事件、知覺與推測。","cn":"分析叙述可靠性，要区分事件、知觉与推测。","en":"Distinguish events, perceptions and inferences when assessing narrative reliability."}},{"id":"s6-chinese-03","grade":6,"subjectId":"chinese","roomId":"chinese","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"結論的綜合與保留","cn":"结论的综合与保留","en":"A qualified synthesis"},"question":{"zh":"論證材料：AI回饋令初稿修改更快，但小組只試了兩週，部分非標準用語被誤改；學生仍需自行決定。哪個結語最能保留材料中的張力？","cn":"论证材料：AI回馈令初稿修改更快，但小组只试了两周，部分非标准用语被误改；学生仍需自行决定。哪个结语最能保留材料中的张力？","en":"Evidence: AI feedback speeds initial revision, but a two-week trial finds some non-standard expressions wrongly changed; students must decide. Which conclusion best preserves these tensions?"},"options":[{"text":{"zh":"可把AI用作初步回饋，但應保留作者判斷，並延長試行檢查不同語言背景的效果。","cn":"可把AI用作初步回馈，但应保留作者判断，并延长试行检查不同语言背景的效果。","en":"Use AI for initial feedback while retaining author judgment and extending evaluation across language backgrounds."},"correct":true,"feedback":{"zh":"結合效益、限制和後續條件，沒有把短期結果普遍化。","cn":"结合效益、限制和后续条件，没有把短期结果普遍化。","en":"This combines benefits, limits and further conditions without universalising a short trial."},"id":"a"},{"text":{"zh":"修改速度較快，已足以證明AI可取代寫作教學。","cn":"修改速度较快，已足以证明AI可取代写作教学。","en":"Faster revision proves AI can replace writing instruction."},"correct":false,"feedback":{"zh":"速度不等於整體學習成效，亦忽略誤改。","cn":"速度不等于整体学习成效，亦忽略误改。","en":"Speed does not establish overall learning effectiveness and ignores errors."},"id":"b"},{"text":{"zh":"只要有一處誤改，所有AI回饋便毫無用處。","cn":"只要有一处误改，所有AI回馈便毫无用处。","en":"One wrong correction makes all AI feedback useless."},"correct":false,"feedback":{"zh":"把局部失誤擴大成絕對否定，同樣超出材料。","cn":"把局部失误扩大成绝对否定，同样超出材料。","en":"This generalises a local failure into an unsupported absolute rejection."},"id":"c"}],"takeaway":{"zh":"成熟結論可同時保留效益與限制，並提出可檢查的條件。","cn":"成熟结论可同时保留效益与限制，并提出可检查的条件。","en":"A mature conclusion can retain benefits and limitations while specifying testable conditions."}},{"id":"s1-english-01","grade":1,"subjectId":"english","roomId":"english","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"通告中的條件","cn":"通告中的条件","en":"Conditions in a notice"},"question":{"zh":"通告寫：‘Bring a signed form by Friday. Students without a form may watch but cannot climb.’ Mei 沒有表格。她可以怎樣？","cn":"通告写：‘Bring a signed form by Friday. Students without a form may watch but cannot climb.’ Mei 没有表格。她可以怎样？","en":"A notice says: ‘Bring a signed form by Friday. Students without a form may watch but cannot climb.’ Mei has no form. What may she do?"},"options":[{"text":{"zh":"觀看活動，但不能攀爬。","cn":"观看活动，但不能攀爬。","en":"Watch the activity, but not climb."},"correct":true,"feedback":{"zh":"‘may watch’ 與 ‘cannot climb’ 分別說明許可和限制。","cn":"‘may watch’ 与 ‘cannot climb’ 分别说明许可和限制。","en":"‘May watch’ gives permission; ‘cannot climb’ sets a limit."},"id":"a"},{"text":{"zh":"只要帶運動鞋便可以攀爬。","cn":"只要带运动鞋便可以攀爬。","en":"Climb if she brings trainers."},"correct":false,"feedback":{"zh":"通告沒有以運動鞋代替表格的規定。","cn":"通告没有以运动鞋代替表格的规定。","en":"The notice does not allow trainers to replace the form."},"id":"b"},{"text":{"zh":"不能進入活動場地。","cn":"不能进入活动场地。","en":"Stay away from the activity entirely."},"correct":false,"feedback":{"zh":"‘may watch’ 明確容許觀看。","cn":"‘may watch’ 明确容许观看。","en":"‘May watch’ explicitly permits attendance as an observer."},"id":"c"}],"takeaway":{"zh":"閱讀通告時同時找出許可、限制和所需條件。","cn":"阅读通告时同时找出许可、限制和所需条件。","en":"Read permissions, restrictions and required conditions together."}},{"id":"s1-english-02","grade":1,"subjectId":"english","roomId":"english","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"清楚的問路請求","cn":"清楚的问路请求","en":"A clear request for directions"},"question":{"zh":"你第一次到校，要禮貌地向職員詢問圖書館位置。哪句最合適？","cn":"你第一次到校，要礼貌地向职员询问图书馆位置。哪句最合适？","en":"On your first school visit, you politely ask a staff member where the library is. Which sentence fits best?"},"options":[{"text":{"zh":"You know the library, don't you?","cn":"You know the library, don't you?","en":"You know the library, don't you?"},"correct":false,"feedback":{"zh":"這句只問對方是否知道圖書館，沒有清楚詢問位置。","cn":"这句只问对方是否知道图书馆，没有清楚询问位置。","en":"This asks whether the person knows the library, rather than clearly requesting its location."},"id":"a"},{"text":{"zh":"Could you tell me where the library is, please?","cn":"Could you tell me where the library is, please?","en":"Could you tell me where the library is, please?"},"correct":true,"feedback":{"zh":"這句交代清楚需要，間接問句使用 ‘where the library is’。","cn":"这句交代清楚需要，间接问句使用 ‘where the library is’。","en":"This is a clear polite request; the indirect question uses ‘where the library is’."},"id":"b"},{"text":{"zh":"Could you tell me where is the library, please?","cn":"Could you tell me where is the library, please?","en":"Could you tell me where is the library, please?"},"correct":false,"feedback":{"zh":"間接問句的主語 ‘the library’ 應在動詞 ‘is’ 前。","cn":"间接问句的主语 ‘the library’ 应在动词 ‘is’ 前。","en":"In an indirect question, the subject ‘the library’ comes before ‘is’."},"id":"c"}],"takeaway":{"zh":"請求要符合對象和目的；禮貌詞並不能代替清楚句意。","cn":"请求要符合对象和目的；礼貌词并不能代替清楚句意。","en":"Match a request to its audience and purpose; politeness also needs clarity."}},{"id":"s1-english-03","grade":1,"subjectId":"english","roomId":"english","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"從行動推斷感受","cn":"从行动推断感受","en":"Inferring feelings from actions"},"question":{"zh":"讀原創句子：‘Before her turn, Asha checked her notes three times. When her name was called, she took a deep breath and walked to the front.’ 哪項推斷最有支持？","cn":"读原创句子：‘Before her turn, Asha checked her notes three times. When her name was called, she took a deep breath and walked to the front.’ 哪项推断最有支持？","en":"Read this original passage: ‘Before her turn, Asha checked her notes three times. When her name was called, she took a deep breath and walked to the front.’ Which inference is best supported?"},"options":[{"text":{"zh":"她對題目完全沒有準備。","cn":"她对题目完全没有准备。","en":"She has done no preparation at all."},"correct":false,"feedback":{"zh":"筆記是準備的線索，不能從緊張推斷完全未準備。","cn":"笔记是准备的线索，不能从紧张推断完全未准备。","en":"Her notes are evidence of preparation; nerves do not prove she is unprepared."},"id":"a"},{"text":{"zh":"她肯定會得到全班最高分。","cn":"她肯定会得到全班最高分。","en":"She will certainly receive the highest mark."},"correct":false,"feedback":{"zh":"段落沒有交代表現或評分，不能推斷結果。","cn":"段落没有交代表现或评分，不能推断结果。","en":"The passage gives no performance or assessment evidence."},"id":"b"},{"text":{"zh":"她有點緊張，但仍準備發言。","cn":"她有点紧张，但仍准备发言。","en":"She feels nervous but is prepared to speak."},"correct":true,"feedback":{"zh":"重複查看筆記及深呼吸支持緊張；走到前面顯示她仍參與。","cn":"重复查看笔记及深呼吸支持紧张；走到前面显示她仍参与。","en":"Repeated checking and a deep breath suggest nerves; walking forward shows participation."},"id":"c"}],"takeaway":{"zh":"推論必須連結文本細節，並保留未能確定的部分。","cn":"推论必须连结文本细节，并保留未能确定的部分。","en":"Link an inference to textual details and leave uncertain outcomes open."}},{"id":"s2-english-01","grade":2,"subjectId":"english","roomId":"english","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"先後發生的事件","cn":"先后发生的事件","en":"Ordering past events"},"question":{"zh":"‘By the time the rehearsal began, Jo ___ the sound equipment.’ 文意是 Jo 先檢查器材，綵排才開始。應填哪項？","cn":"‘By the time the rehearsal began, Jo ___ the sound equipment.’ 文意是 Jo 先检查器材，彩排才开始。应填哪项？","en":"‘By the time the rehearsal began, Jo ___ the sound equipment.’ Jo checked the equipment before the rehearsal started. Which form fits?"},"options":[{"text":{"zh":"has checked","cn":"has checked","en":"has checked"},"correct":false,"feedback":{"zh":"現在完成式通常連結現在；此句以過去的綵排作參照。","cn":"现在完成式通常连结现在；此句以过去的彩排作参照。","en":"The present perfect links to the present, but the reference point here is a past rehearsal."},"id":"a"},{"text":{"zh":"had checked","cn":"had checked","en":"had checked"},"correct":true,"feedback":{"zh":"過去完成式表達另一過去事件之前已完成的動作。","cn":"过去完成式表达另一过去事件之前已完成的动作。","en":"The past perfect marks completion before another past event."},"id":"b"},{"text":{"zh":"will check","cn":"will check","en":"will check"},"correct":false,"feedback":{"zh":"將來式不符合兩件事均已在過去發生的時間線。","cn":"将来式不符合两件事均已在过去发生的时间线。","en":"The future form does not fit two events located in the past."},"id":"c"}],"takeaway":{"zh":"選擇時態前，先確定事件的參照時間和先後。","cn":"选择时态前，先确定事件的参照时间和先后。","en":"Identify the reference time and event order before choosing a tense."}},{"id":"s2-english-02","grade":2,"subjectId":"english","roomId":"english","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"連接相反觀點","cn":"连接相反观点","en":"Linking contrasting ideas"},"question":{"zh":"要連接 ‘The route is longer’ 和 ‘It has fewer stairs’，並建議輪椅使用者考慮這條路。哪句最清楚保留兩點？","cn":"要连接 ‘The route is longer’ 和 ‘It has fewer stairs’，并建议轮椅使用者考虑这条路。哪句最清楚保留两点？","en":"Link ‘The route is longer’ and ‘It has fewer stairs’ when suggesting a route for a wheelchair user to consider. Which sentence keeps both points clearly?"},"options":[{"text":{"zh":"The route is longer because it has fewer stairs.","cn":"The route is longer because it has fewer stairs.","en":"The route is longer because it has fewer stairs."},"correct":false,"feedback":{"zh":"原有資料沒有證明樓梯較少是路程較長的原因。","cn":"原有资料没有证明楼梯较少是路程较长的原因。","en":"The given information does not establish that fewer stairs cause the longer route."},"id":"a"},{"text":{"zh":"The route has fewer stairs, so its distance is shorter.","cn":"The route has fewer stairs, so its distance is shorter.","en":"The route has fewer stairs, so its distance is shorter."},"correct":false,"feedback":{"zh":"這句把 ‘longer’ 的原意改成 ‘shorter’。","cn":"这句把 ‘longer’ 的原意改成 ‘shorter’。","en":"This changes the original meaning from ‘longer’ to ‘shorter’."},"id":"b"},{"text":{"zh":"Although the route is longer, it has fewer stairs.","cn":"Although the route is longer, it has fewer stairs.","en":"Although the route is longer, it has fewer stairs."},"correct":true,"feedback":{"zh":"‘Although’ 表示距離與樓梯數目的取捨；仍需核對路線是否完全無梯級。","cn":"‘Although’ 表示距离与楼梯数目的取舍；仍需核对路线是否完全无梯级。","en":"‘Although’ shows the trade-off; the route still needs checking for step-free access."},"id":"c"}],"takeaway":{"zh":"連接詞應表達材料真正支持的關係，而非額外製造因果。","cn":"连接词应表达材料真正支持的关系，而非额外制造因果。","en":"Use a connective that matches the supported relationship, without inventing causation."}},{"id":"s2-english-03","grade":2,"subjectId":"english","roomId":"english","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"代詞與論點連貫","cn":"代词与论点连贯","en":"Reference and coherence"},"question":{"zh":"‘The council suggested planting trees beside the court. It also recommended shaded seats. These measures would give students cooler places to rest.’ ‘These measures’ 指甚麼？","cn":"‘The council suggested planting trees beside the court. It also recommended shaded seats. These measures would give students cooler places to rest.’ ‘These measures’ 指甚么？","en":"‘The council suggested planting trees beside the court. It also recommended shaded seats. These measures would give students cooler places to rest.’ What does ‘These measures’ refer to?"},"options":[{"text":{"zh":"種樹和設置有遮蔭的座位。","cn":"种树和设置有遮荫的座位。","en":"Planting trees and providing shaded seats."},"correct":true,"feedback":{"zh":"複數短語總結前兩句的兩項建議。","cn":"复数短语总结前两句的两项建议。","en":"The plural phrase summarises the two proposals in the preceding sentences."},"id":"a"},{"text":{"zh":"只指學生會本身。","cn":"只指学生会本身。","en":"Only the council itself."},"correct":false,"feedback":{"zh":"學生會是提出建議的組織，不是兩項措施。","cn":"学生会是提出建议的组织，不是两项措施。","en":"The council proposes the measures; it is not itself the measures."},"id":"b"},{"text":{"zh":"只指測量球場溫度。","cn":"只指测量球场温度。","en":"Only measuring the court temperature."},"correct":false,"feedback":{"zh":"‘measures’ 在此指措施；段落沒有提及測量。","cn":"‘measures’ 在此指措施；段落没有提及测量。","en":"Here ‘measures’ means actions, and no temperature measurement is mentioned."},"id":"c"}],"takeaway":{"zh":"利用上下文與單複數線索辨認指涉，避免只按單字常見意思理解。","cn":"利用上下文与单复数线索辨认指涉，避免只按单字常见意思理解。","en":"Use context and number agreement to resolve reference, rather than one familiar word meaning."}},{"id":"s3-english-01","grade":3,"subjectId":"english","roomId":"english","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"報告中的被動語態","cn":"报告中的被动语态","en":"Passive voice in a report"},"question":{"zh":"報告重點是匿名問卷，而非派發者：‘Two hundred anonymous questionnaires ___ to students last Monday.’ 哪項正確？","cn":"报告重点是匿名问卷，而非派发者：‘Two hundred anonymous questionnaires ___ to students last Monday.’ 哪项正确？","en":"A report focuses on anonymous questionnaires rather than who distributed them: ‘Two hundred anonymous questionnaires ___ to students last Monday.’ Which form is correct?"},"options":[{"text":{"zh":"distributed","cn":"distributed","en":"distributed"},"correct":false,"feedback":{"zh":"這會令問卷變成主動派發東西的主語，句意不成立。","cn":"这会令问卷变成主动派发东西的主语，句意不成立。","en":"This makes the questionnaires perform the distribution, which does not fit the meaning."},"id":"a"},{"text":{"zh":"are distributing","cn":"are distributing","en":"are distributing"},"correct":false,"feedback":{"zh":"現在進行式主動語態既不符合時間，也不符合動作關係。","cn":"现在进行式主动语态既不符合时间，也不符合动作关系。","en":"The present progressive active form fits neither the time nor who receives the action."},"id":"b"},{"text":{"zh":"were distributed","cn":"were distributed","en":"were distributed"},"correct":true,"feedback":{"zh":"複數問卷是接受動作的對象，‘last Monday’ 要求過去式。","cn":"复数问卷是接受动作的对象，‘last Monday’ 要求过去式。","en":"The plural questionnaires receive the action, and ‘last Monday’ locates it in the past."},"id":"c"}],"takeaway":{"zh":"語態要配合誰做動作、誰接受動作，以及報告焦點。","cn":"语态要配合谁做动作、谁接受动作，以及报告焦点。","en":"Choose voice by the action roles and the report's focus."}},{"id":"s3-english-02","grade":3,"subjectId":"english","roomId":"english","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"撮要保留限制條件","cn":"撮要保留限制条件","en":"Summarising with conditions"},"question":{"zh":"‘The pilot reading club attracted 24 students. Most attended regularly, but interviews were conducted only with six volunteers.’ 哪句撮要最準確？","cn":"‘The pilot reading club attracted 24 students. Most attended regularly, but interviews were conducted only with six volunteers.’ 哪句撮要最准确？","en":"‘The pilot reading club attracted 24 students. Most attended regularly, but interviews were conducted only with six volunteers.’ Which summary is most accurate?"},"options":[{"text":{"zh":"出席大致穩定，但訪談只涵蓋六名自願者。","cn":"出席大致稳定，但访谈只涵盖六名自愿者。","en":"Attendance was generally regular, but interviews covered only six volunteers."},"correct":true,"feedback":{"zh":"這句保留正面觀察及資料範圍。","cn":"这句保留正面观察及资料范围。","en":"This retains both the positive observation and the evidence boundary."},"id":"a"},{"text":{"zh":"所有參加者均接受訪問並支持計劃。","cn":"所有参加者均接受访问并支持计划。","en":"All participants were interviewed and supported the programme."},"correct":false,"feedback":{"zh":"只有六名自願者受訪；原文也沒有交代他們的評價。","cn":"只有六名自愿者受访；原文也没有交代他们的评价。","en":"Only six volunteers were interviewed, and their opinions are not stated."},"id":"b"},{"text":{"zh":"只有六名學生參加閱讀會。","cn":"只有六名学生参加阅读会。","en":"Only six students joined the reading club."},"correct":false,"feedback":{"zh":"六人是受訪數目，參加人數是二十四。","cn":"六人是受访数目，参加人数是二十四。","en":"Six is the interview sample; twenty-four is the participation count."},"id":"c"}],"takeaway":{"zh":"撮要要壓縮字數，不能把樣本數、參與數和結論混為一談。","cn":"撮要要压缩字数，不能把样本数、参与数和结论混为一谈。","en":"A summary reduces length without merging sample size, participation and conclusions."}},{"id":"s3-english-03","grade":3,"subjectId":"english","roomId":"english","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"按讀者需要修訂","cn":"按读者需要修订","en":"Revising for an audience"},"question":{"zh":"校報給新生的句子是：‘Utilisation of the equipment-lending facility necessitates prior registration.’ 哪個版本最清楚而不改變要求？","cn":"校报给新生的句子是：‘Utilisation of the equipment-lending facility necessitates prior registration.’ 哪个版本最清楚而不改变要求？","en":"A newsletter for new students says: ‘Utilisation of the equipment-lending facility necessitates prior registration.’ Which revision is clearest without changing the requirement?"},"options":[{"text":{"zh":"The facility is available to everyone without registration.","cn":"The facility is available to everyone without registration.","en":"The facility is available to everyone without registration."},"correct":false,"feedback":{"zh":"這句刪去原文的必要條件。","cn":"这句删去原文的必要条件。","en":"This removes the required condition."},"id":"a"},{"text":{"zh":"Register before you borrow equipment.","cn":"Register before you borrow equipment.","en":"Register before you borrow equipment."},"correct":true,"feedback":{"zh":"直接動詞清楚交代所需步驟與次序。","cn":"直接动词清楚交代所需步骤与次序。","en":"Direct verbs clearly communicate the action and its order."},"id":"b"},{"text":{"zh":"You might register after borrowing equipment.","cn":"You might register after borrowing equipment.","en":"You might register after borrowing equipment."},"correct":false,"feedback":{"zh":"‘might’ 和 ‘after’ 把必須事先登記的要求改了。","cn":"‘might’ 和 ‘after’ 把必须事先登记的要求改了。","en":"‘Might’ and ‘after’ change the requirement to register first."},"id":"c"}],"takeaway":{"zh":"簡明英語應減少閱讀負擔，同時保留原有條件。","cn":"简明英语应减少阅读负担，同时保留原有条件。","en":"Plain English reduces reading effort while preserving conditions."}},{"id":"s4-english-01","grade":4,"subjectId":"english","roomId":"english","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"假設與現實","cn":"假设与现实","en":"Hypothetical situations"},"question":{"zh":"學校目前沒有空置課室。‘If the school had a spare room, we ___ a quiet study area.’ 哪項最適合這個假設？","cn":"学校目前没有空置课室。‘If the school had a spare room, we ___ a quiet study area.’ 哪项最适合这个假设？","en":"The school currently has no spare classroom. ‘If the school had a spare room, we ___ a quiet study area.’ Which form fits this hypothetical situation?"},"options":[{"text":{"zh":"could create","cn":"could create","en":"could create"},"correct":true,"feedback":{"zh":"‘If ... had’ 配合 ‘could create’，表達與目前情況不同的可能安排。","cn":"‘If ... had’ 配合 ‘could create’，表达与目前情况不同的可能安排。","en":"‘If ... had’ with ‘could create’ expresses a possibility under a different present situation."},"id":"a"},{"text":{"zh":"had created","cn":"had created","en":"had created"},"correct":false,"feedback":{"zh":"這是過去完成式，並不構成此句的假設結果。","cn":"这是过去完成式，并不构成此句的假设结果。","en":"The past perfect does not express the hypothetical result needed here."},"id":"b"},{"text":{"zh":"create yesterday","cn":"create yesterday","en":"create yesterday"},"correct":false,"feedback":{"zh":"動詞形式及 ‘yesterday’ 都與目前假設不符。","cn":"动词形式及 ‘yesterday’ 都与目前假设不符。","en":"Both the verb form and ‘yesterday’ conflict with the present hypothetical situation."},"id":"c"}],"takeaway":{"zh":"條件句的形式反映時間與現實程度，不只是固定詞語配對。","cn":"条件句的形式反映时间与现实程度，不只是固定词语配对。","en":"Conditional forms reflect time and reality, not just memorised word pairs."}},{"id":"s4-english-02","grade":4,"subjectId":"english","roomId":"english","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"比較兩項建議","cn":"比较两项建议","en":"Comparing proposals"},"question":{"zh":"Proposal A: 40 extra seats, costs $80,000, removes a garden. Proposal B: 25 extra seats, costs $30,000, keeps the garden. 文章要比較成本及環境取捨。哪句最有用？","cn":"Proposal A: 40 extra seats, costs $80,000, removes a garden. Proposal B: 25 extra seats, costs $30,000, keeps the garden. 文章要比较成本及环境取舍。哪句最有用？","en":"Proposal A adds 40 seats for $80,000 but removes a garden. Proposal B adds 25 seats for $30,000 and keeps it. Which sentence best compares cost and environmental trade-offs?"},"options":[{"text":{"zh":"A 的費用較高，因此所有人都反對。","cn":"A 的费用较高，因此所有人都反对。","en":"A costs more, so everyone opposes it."},"correct":false,"feedback":{"zh":"費用資料不能證明所有人的態度。","cn":"费用资料不能证明所有人的态度。","en":"Cost figures cannot establish everyone's opinion."},"id":"a"},{"text":{"zh":"B 增加的座位較少，但費用較低且保留花園。","cn":"B 增加的座位较少，但费用较低且保留花园。","en":"B provides fewer extra seats, but costs less and preserves the garden."},"correct":true,"feedback":{"zh":"這句同時交代兩方案在數量、費用與環境上的差異。","cn":"这句同时交代两方案在数量、费用与环境上的差异。","en":"This compares capacity, cost and the environmental difference."},"id":"b"},{"text":{"zh":"B 的座位最多，而且不用花費。","cn":"B 的座位最多，而且不用花费。","en":"B provides the most seats at no cost."},"correct":false,"feedback":{"zh":"B 的座位較少，且費用是三萬元。","cn":"B 的座位较少，且费用是三万元。","en":"B adds fewer seats and still costs $30,000."},"id":"c"}],"takeaway":{"zh":"比較段落應使用相同準則，避免把數據改寫成未有證據的民意。","cn":"比较段落应使用相同准则，避免把数据改写成未有证据的民意。","en":"Compare options using common criteria without inventing public opinion."}},{"id":"s4-english-03","grade":4,"subjectId":"english","roomId":"english","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"辨認語氣與含意","cn":"辨认语气与含意","en":"Tone and implied criticism"},"question":{"zh":"原創評論寫：‘How considerate: the consultation on student wellbeing was held while every class was sitting an examination.’ 作者最可能表達甚麼？","cn":"原创评论写：‘How considerate: the consultation on student wellbeing was held while every class was sitting an examination.’ 作者最可能表达甚么？","en":"An original commentary says: ‘How considerate: the consultation on student wellbeing was held while every class was sitting an examination.’ What is the writer most likely expressing?"},"options":[{"text":{"zh":"真心讚賞考試能改善所有人的身心健康。","cn":"真心赞赏考试能改善所有人的身心健康。","en":"Sincere praise that exams improve everyone's wellbeing."},"correct":false,"feedback":{"zh":"句子批評的是諮詢時間；沒有證明考試的健康效果。","cn":"句子批评的是咨询时间；没有证明考试的健康效果。","en":"The contrast concerns consultation timing, not evidence of exam benefits."},"id":"a"},{"text":{"zh":"主張永久取消所有諮詢活動。","cn":"主张永久取消所有咨询活动。","en":"A demand to end all consultations permanently."},"correct":false,"feedback":{"zh":"批評一次安排不等於要求取消整類活動。","cn":"批评一次安排不等于要求取消整类活动。","en":"Criticising one arrangement does not imply ending all consultations."},"id":"b"},{"text":{"zh":"諷刺安排妨礙學生參與。","cn":"讽刺安排妨碍学生参与。","en":"Irony about scheduling that prevents student participation."},"correct":true,"feedback":{"zh":"表面的讚賞與無法出席的情境形成反差。","cn":"表面的赞赏与无法出席的情境形成反差。","en":"The apparent praise conflicts with the situation that prevents attendance."},"id":"c"}],"takeaway":{"zh":"語氣可由字面意思與情境的反差表達；推論仍須限制範圍。","cn":"语气可由字面意思与情境的反差表达；推论仍须限制范围。","en":"Tone can arise from a contrast between literal words and context; keep the inference proportionate."}},{"id":"s5-english-01","grade":5,"subjectId":"english","roomId":"english","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"限定證據能支持的說法","cn":"限定证据能支持的说法","en":"Calibrating a claim"},"question":{"zh":"A voluntary survey found that 36 of 50 respondents preferred later library hours. 哪句報告最符合證據？","cn":"A voluntary survey found that 36 of 50 respondents preferred later library hours. 哪句报告最符合证据？","en":"A voluntary survey found that 36 of 50 respondents preferred later library hours. Which report sentence matches the evidence?"},"options":[{"text":{"zh":"The survey proves later hours improve examination results.","cn":"The survey proves later hours improve examination results.","en":"The survey proves later hours improve examination results."},"correct":false,"feedback":{"zh":"調查只量度偏好，沒有量度成績或因果關係。","cn":"调查只量度偏好，没有量度成绩或因果关系。","en":"The survey measures preference, not attainment or causation."},"id":"a"},{"text":{"zh":"Most respondents preferred later hours; the voluntary sample may not represent the whole school.","cn":"Most respondents preferred later hours; the voluntary sample may not represent the whole school.","en":"Most respondents preferred later hours; the voluntary sample may not represent the whole school."},"correct":true,"feedback":{"zh":"‘respondents’ 界定資料範圍；後半句交代抽樣限制。","cn":"‘respondents’ 界定资料范围；后半句交代抽样限制。","en":"‘Respondents’ defines the evidence scope; the second clause states the sampling limitation."},"id":"b"},{"text":{"zh":"Exactly 72% of all students demand later hours.","cn":"Exactly 72% of all students demand later hours.","en":"Exactly 72% of all students demand later hours."},"correct":false,"feedback":{"zh":"72% 是受訪者比例，不能直接推廣到全校；‘demand’ 也加強了原意。","cn":"72% 是受访者比例，不能直接推广到全校；‘demand’ 也加强了原意。","en":"72% describes respondents, not necessarily the whole school; ‘demand’ also overstates preference."},"id":"c"}],"takeaway":{"zh":"用詞強度、母體範圍和研究量度必須一致。","cn":"用词强度、母体范围和研究量度必须一致。","en":"Match the strength and population scope of a claim to what was measured."}},{"id":"s5-english-02","grade":5,"subjectId":"english","roomId":"english","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"有效回應反對意見","cn":"有效回应反对意见","en":"Responding to a counterargument"},"question":{"zh":"你主張延長圖書館開放時間。反對者指出職員工時限制。哪句最能推進討論？","cn":"你主张延长图书馆开放时间。反对者指出职员工时限制。哪句最能推进讨论？","en":"You propose extending library hours. An objection concerns staff working hours. Which response advances the discussion most effectively?"},"options":[{"text":{"zh":"Anyone who mentions staffing dislikes reading.","cn":"Anyone who mentions staffing dislikes reading.","en":"Anyone who mentions staffing dislikes reading."},"correct":false,"feedback":{"zh":"這是批評提出意見的人，沒有處理工時問題。","cn":"这是批评提出意见的人，没有处理工时问题。","en":"This attacks people rather than addressing staff time."},"id":"a"},{"text":{"zh":"Students want it, so staff capacity is irrelevant.","cn":"Students want it, so staff capacity is irrelevant.","en":"Students want it, so staff capacity is irrelevant."},"correct":false,"feedback":{"zh":"需求並不使實際資源限制消失。","cn":"需求并不使实际资源限制消失。","en":"Demand does not remove a practical resource constraint."},"id":"b"},{"text":{"zh":"A limited trial on one afternoon, with agreed staffing and a review, could test feasibility.","cn":"A limited trial on one afternoon, with agreed staffing and a review, could test feasibility.","en":"A limited trial on one afternoon, with agreed staffing and a review, could test feasibility."},"correct":true,"feedback":{"zh":"這句承認限制，提出可檢驗且具體的調整。","cn":"这句承认限制，提出可检验且具体的调整。","en":"This acknowledges the constraint and offers a specific, testable adjustment."},"id":"c"}],"takeaway":{"zh":"有力的反駁要回應對方最相關的理由，並提供可行證據或調整。","cn":"有力的反驳要回应对方最相关的理由，并提供可行证据或调整。","en":"A strong response addresses the relevant objection with evidence or a feasible adjustment."}},{"id":"s5-english-03","grade":5,"subjectId":"english","roomId":"english","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"綜合看似矛盾的資料","cn":"综合看似矛盾的资料","en":"Synthesising apparently conflicting evidence"},"question":{"zh":"Report A says printed-book loans fell by 10%. Report B says total reading sessions rose by 15%, including e-books. 哪項綜合最合理？","cn":"Report A says printed-book loans fell by 10%. Report B says total reading sessions rose by 15%, including e-books. 哪项综合最合理？","en":"Report A says printed-book loans fell by 10%. Report B says total reading sessions rose by 15%, including e-books. Which synthesis is most reasonable?"},"options":[{"text":{"zh":"兩份報告可同時成立，因為量度的範圍不同。","cn":"两份报告可同时成立，因为量度的范围不同。","en":"Both reports may be consistent because they measure different categories."},"correct":true,"feedback":{"zh":"紙本借閱與包含電子書的總閱讀節次不是同一指標。","cn":"纸本借阅与包含电子书的总阅读节次不是同一指标。","en":"Printed loans and total sessions including e-books are different indicators."},"id":"a"},{"text":{"zh":"兩個百分比相加，證明紙本借閱增加 5%。","cn":"两个百分比相加，证明纸本借阅增加 5%。","en":"Adding the percentages proves printed loans rose by 5%."},"correct":false,"feedback":{"zh":"不同指標的變幅不能直接相加當成紙本變幅。","cn":"不同指标的变幅不能直接相加当成纸本变幅。","en":"Changes in different indicators cannot be added to obtain a printed-loan change."},"id":"b"},{"text":{"zh":"百分比一升一跌，所以必有一份報告造假。","cn":"百分比一升一跌，所以必有一份报告造假。","en":"One percentage rises and the other falls, so one report must be fabricated."},"correct":false,"feedback":{"zh":"不同範圍可以呈相反走勢，並不構成造假的證據。","cn":"不同范围可以呈相反走势，并不构成造假的证据。","en":"Different categories can move in different directions without fabrication."},"id":"c"}],"takeaway":{"zh":"綜合資料前先比較定義、時間與範圍，不能只比較數字方向。","cn":"综合资料前先比较定义、时间与范围，不能只比较数字方向。","en":"Compare definitions, periods and scope before synthesising numerical findings."}},{"id":"s6-english-01","grade":6,"subjectId":"english","roomId":"english","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"修正懸垂修飾語","cn":"修正悬垂修饰语","en":"Repairing a dangling modifier"},"question":{"zh":"背景：委員會審核申請並發現錯誤。草稿寫 ‘After reviewing the applications, several errors were found.’ 哪個版本修正動作主語不清的問題，並保留先後意思？","cn":"背景：委员会审核申请并发现错误。草稿写 ‘After reviewing the applications, several errors were found.’ 哪个版本修正动作主语不清的问题，并保留先后意思？","en":"Context: a committee reviewed applications and found errors. A draft says: ‘After reviewing the applications, several errors were found.’ Which revision fixes the unclear action subject and preserves the sequence?"},"options":[{"text":{"zh":"After reviewing the applications, several errors were found by the committee.","cn":"After reviewing the applications, several errors were found by the committee.","en":"After reviewing the applications, several errors were found by the committee."},"correct":false,"feedback":{"zh":"句首 reviewing 的動作主語仍接到主句的 errors；被動句末加委員會並未修正懸垂關係。","cn":"句首 reviewing 的动作主语仍接到主句的 errors；被动句末加委员会并未修正悬垂关系。","en":"The introductory reviewing phrase still attaches to the main-clause subject errors; adding the committee in a by-phrase does not fix the dangling attachment."},"id":"a"},{"text":{"zh":"Before reviewing the applications, the committee found several errors.","cn":"Before reviewing the applications, the committee found several errors.","en":"Before reviewing the applications, the committee found several errors."},"correct":false,"feedback":{"zh":"主語清楚，但 before 把原文先審核後發現的順序改了。","cn":"主语清楚，但 before 把原文先审核后发现的顺序改了。","en":"The subject is clear, but before reverses the original sequence of reviewing and then finding errors."},"id":"b"},{"text":{"zh":"After reviewing the applications, the committee found several errors.","cn":"After reviewing the applications, the committee found several errors.","en":"After reviewing the applications, the committee found several errors."},"correct":true,"feedback":{"zh":"主語 ‘the committee’ 同時負責 reviewing 及 found，動作關係清楚。","cn":"主语 ‘the committee’ 同时负责 reviewing 及 found，动作关系清楚。","en":"‘The committee’ performs both reviewing and finding, so the action roles are clear."},"id":"c"}],"takeaway":{"zh":"句首分詞結構應能與主句主語建立合理的動作關係。","cn":"句首分词结构应能与主句主语建立合理的动作关系。","en":"An introductory participial phrase should logically attach to the main-clause subject."}},{"id":"s6-english-02","grade":6,"subjectId":"english","roomId":"english","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"區分概述與批判綜合","cn":"区分概述与批判综合","en":"Critical synthesis across sources"},"question":{"zh":"Source A reports faster homework feedback with AI. Source B reports missed errors in culturally specific writing. 你要寫建議段落，哪句最能綜合兩者？","cn":"Source A reports faster homework feedback with AI. Source B reports missed errors in culturally specific writing. 你要写建议段落，哪句最能综合两者？","en":"Source A reports faster homework feedback with AI. Source B reports missed errors in culturally specific writing. Which recommendation best synthesises both?"},"options":[{"text":{"zh":"Use AI for initial feedback, with human review of meaning and cultural context; speed alone is insufficient.","cn":"Use AI for initial feedback, with human review of meaning and cultural context; speed alone is insufficient.","en":"Use AI for initial feedback, with human review of meaning and cultural context; speed alone is insufficient."},"correct":true,"feedback":{"zh":"建議保留效率優點，同時以覆核回應文化語境的限制。","cn":"建议保留效率优点，同时以覆核回应文化语境的限制。","en":"The recommendation retains the efficiency benefit while addressing contextual errors through review."},"id":"a"},{"text":{"zh":"Faster feedback means every cultural interpretation is accurate.","cn":"Faster feedback means every cultural interpretation is accurate.","en":"Faster feedback means every cultural interpretation is accurate."},"correct":false,"feedback":{"zh":"速度與語境準確度是不同面向，不能互相證明。","cn":"速度与语境准确度是不同面向，不能互相证明。","en":"Speed and contextual accuracy are different dimensions; one does not prove the other."},"id":"b"},{"text":{"zh":"Because some errors occur, neither source contains useful information.","cn":"Because some errors occur, neither source contains useful information.","en":"Because some errors occur, neither source contains useful information."},"correct":false,"feedback":{"zh":"有限制的證據仍可用來設計有條件的建議。","cn":"有限制的证据仍可用来设计有条件的建议。","en":"Limited evidence can still inform a qualified recommendation."},"id":"c"}],"takeaway":{"zh":"批判綜合要把不同證據轉成有條件、可解釋的立場。","cn":"批判综合要把不同证据转成有条件、可解释的立场。","en":"Critical synthesis turns different evidence into a qualified, explainable position."}},{"id":"s6-english-03","grade":6,"subjectId":"english","roomId":"english","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"評估因果主張的論據","cn":"评估因果主张的论据","en":"Evaluating a causal argument"},"question":{"zh":"An editorial claims a new study app caused higher exam scores. Its only evidence is that app users scored higher than non-users. 哪項補充資料最直接削弱其因果推論？","cn":"An editorial claims a new study app caused higher exam scores. Its only evidence is that app users scored higher than non-users. 哪项补充资料最直接削弱其因果推论？","en":"An editorial claims a new study app caused higher exam scores. Its only evidence is that users scored higher than non-users. Which additional finding most directly weakens the causal inference?"},"options":[{"text":{"zh":"文章用了三段文字描述介面。","cn":"文章用了三段文字描述介面。","en":"The editorial spends three paragraphs describing the interface."},"correct":false,"feedback":{"zh":"篇幅安排不直接檢驗學習效果的因果主張。","cn":"篇幅安排不直接检验学习效果的因果主张。","en":"Article structure does not directly test the claimed causal effect."},"id":"a"},{"text":{"zh":"使用者在下載程式之前已取得較高成績。","cn":"使用者在下载程式之前已取得较高成绩。","en":"Users already had higher scores before downloading the app."},"correct":true,"feedback":{"zh":"起點差異提供另一解釋，削弱把後來差距全歸因於程式的說法。","cn":"起点差异提供另一解释，削弱把后来差距全归因于程式的说法。","en":"A prior difference supplies an alternative explanation for the later gap."},"id":"b"},{"text":{"zh":"程式可在兩種手機系統使用。","cn":"程式可在两种手机系统使用。","en":"The app runs on two phone operating systems."},"correct":false,"feedback":{"zh":"系統相容性本身不解釋兩組成績差異。","cn":"系统相容性本身不解释两组成绩差异。","en":"Compatibility alone does not explain the groups' score difference."},"id":"c"}],"takeaway":{"zh":"評論因果論證時，要找基線、選擇偏差及可能的替代解釋。","cn":"评论因果论证时，要找基线、选择偏差及可能的替代解释。","en":"Evaluate causal arguments through baseline differences, selection and alternative explanations."}},{"id":"s1-maths-01","grade":1,"subjectId":"maths","roomId":"maths","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"分配與比","cn":"分配与比","en":"Sharing in a ratio"},"question":{"zh":"兩班按 2:3 分配 45 本新書。較少的一班應得多少本？","cn":"两班按 2:3 分配 45 本新书。较少的一班应得多少本？","en":"Two classes share 45 new books in the ratio 2:3. How many go to the smaller share?"},"options":[{"text":{"zh":"30 本","cn":"30 本","en":"30 books"},"correct":false,"feedback":{"zh":"2:3 的分母是兩份加三份，不是三份。","cn":"2:3 的分母是两份加三份，不是三份。","en":"The whole contains 2+3 parts, not 3 parts."},"id":"a"},{"text":{"zh":"18 本","cn":"18 本","en":"18 books"},"correct":true,"feedback":{"zh":"共五份，每份九本；兩份是十八本。","cn":"共五份，每份九本；两份是十八本。","en":"There are five parts of nine books; two parts give 18."},"id":"b"},{"text":{"zh":"22.5 本","cn":"22.5 本","en":"22.5 books"},"correct":false,"feedback":{"zh":"平均分配忽略了 2:3 的條件。","cn":"平均分配忽略了 2:3 的条件。","en":"Equal sharing ignores the stated 2:3 ratio."},"id":"c"}],"takeaway":{"zh":"按比分配，先求總份數，再求每份大小。","cn":"按比分配，先求总份数，再求每份大小。","en":"Find the total number of ratio parts before calculating each share."}},{"id":"s1-maths-02","grade":1,"subjectId":"maths","roomId":"maths","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"周界的代數模型","cn":"周界的代数模型","en":"An algebraic perimeter"},"question":{"zh":"長方形園圃長為 (x+3) 米、闊為 x 米，周界 30 米。闊是多少？","cn":"长方形园圃长为 (x+3) 米、阔为 x 米，周界 30 米。阔是多少？","en":"A rectangular garden is (x+3)m long and x m wide. Its perimeter is 30 m. What is its width?"},"options":[{"text":{"zh":"13.5 米","cn":"13.5 米","en":"13.5 m"},"correct":false,"feedback":{"zh":"只相加一次長和闊，算的是半周界。","cn":"只相加一次长和阔，算的是半周界。","en":"Adding one length and one width gives half the perimeter."},"id":"a"},{"text":{"zh":"7.5 米","cn":"7.5 米","en":"7.5 m"},"correct":false,"feedback":{"zh":"這相當於把長方形誤當成正方形。","cn":"这相当于把长方形误当成正方形。","en":"This incorrectly treats the rectangle as a square."},"id":"b"},{"text":{"zh":"6 米","cn":"6 米","en":"6 m"},"correct":true,"feedback":{"zh":"2(x+3)+2x=30，所以4x=24。","cn":"2(x+3)+2x=30，所以4x=24。","en":"2(x+3)+2 x=30, so 4 x=24."},"id":"c"}],"takeaway":{"zh":"用圖形關係建立方程，並把答案代回原條件。","cn":"用图形关系建立方程，并把答案代回原条件。","en":"Build an equation from the geometry and check the solution in the original conditions."}},{"id":"s1-maths-03","grade":1,"subjectId":"maths","roomId":"maths","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"平均數與極端值","cn":"平均数与极端值","en":"Mean and an extreme value"},"question":{"zh":"五天借書量是 8、9、9、10、44。要描述一般一天的借書量，哪個說法最合理？","cn":"五天借书量是 8、9、9、10、44。要描述一般一天的借书量，哪个说法最合理？","en":"Daily loans are 8, 9, 9, 10, 44. Which statement best describes a typical day?"},"options":[{"text":{"zh":"中位數 9 較能反映大部分日子；平均數是 16","cn":"中位数 9 较能反映大部分日子；平均数是 16","en":"Median 9 represents most days better; the mean is 16"},"correct":true,"feedback":{"zh":"44拉高平均數；中位數取排序後中央值。","cn":"44拉高平均数；中位数取排序后中央值。","en":"44 pulls the mean upward; the median is the middle ordered value."},"id":"a"},{"text":{"zh":"平均數 16 表示至少三天借出 16 本","cn":"平均数 16 表示至少三天借出 16 本","en":"Mean 16 means at least three days had 16 loans"},"correct":false,"feedback":{"zh":"平均數不表示多數觀察值必須等於它。","cn":"平均数不表示多数观察值必须等于它。","en":"A mean need not equal most observations."},"id":"b"},{"text":{"zh":"刪去 44，因為大數一定是錯誤","cn":"删去 44，因为大数一定是错误","en":"Delete 44 because a large value must be wrong"},"correct":false,"feedback":{"zh":"極端值可能是真實活動日，不能未查證便刪除。","cn":"极端值可能是真实活动日，不能未查证便删除。","en":"An unusual event may be real; investigate before deleting it."},"id":"c"}],"takeaway":{"zh":"選統計量時要看分佈；極端值不等於錯誤資料。","cn":"选统计量时要看分布；极端值不等于错误资料。","en":"Choose summaries with the distribution in mind; an extreme value is not automatically an error."}},{"id":"s2-maths-01","grade":2,"subjectId":"maths","roomId":"maths","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"百分率的基準","cn":"百分率的基准","en":"Changing percentage bases"},"question":{"zh":"一件售價 $200 的校隊外套先減價20%，再按減價後價錢加價20%。最後售價是多少？","cn":"一件售价 $200 的校队外套先减价20%，再按减价后价钱加价20%。最后售价是多少？","en":"A $200 team jacket is discounted 20%, then increased 20% from the discounted price. What is the final price?"},"options":[{"text":{"zh":"$200","cn":"$200","en":"$200"},"correct":false,"feedback":{"zh":"減價與加價的百分率相同，不表示金額相同。","cn":"减价与加价的百分率相同，不表示金额相同。","en":"Equal percentage rates do not mean equal cash changes."},"id":"a"},{"text":{"zh":"$160","cn":"$160","en":"$160"},"correct":false,"feedback":{"zh":"160只是完成第一次減價的售價。","cn":"160只是完成第一次减价的售价。","en":"160 is the price after the first change only."},"id":"b"},{"text":{"zh":"$192","cn":"$192","en":"$192"},"correct":true,"feedback":{"zh":"200×0.8×1.2=192，兩次百分率的基準不同。","cn":"200×0.8×1.2=192，两次百分率的基准不同。","en":"200×0.8×1.2=192; the percentage bases differ."},"id":"c"}],"takeaway":{"zh":"連續百分率變化應相乘，不應直接互相抵消。","cn":"连续百分率变化应相乘，不应直接互相抵消。","en":"Multiply successive percentage factors rather than cancelling their rates."}},{"id":"s2-maths-02","grade":2,"subjectId":"maths","roomId":"maths","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"票價的聯立方程","cn":"票价的联立方程","en":"Simultaneous ticket equations"},"question":{"zh":"兩張成人票及三張學生票共 $84；一張成人票及兩張學生票共 $48。學生票是多少？","cn":"两张成人票及三张学生票共 $84；一张成人票及两张学生票共 $48。学生票是多少？","en":"Two adult and three student tickets cost $84; one adult and two student tickets cost $48. What is a student ticket price?"},"options":[{"text":{"zh":"$12","cn":"$12","en":"$12"},"correct":true,"feedback":{"zh":"第二式乘二後減第一式，得一張學生票$12。","cn":"第二式乘二后减第一式，得一张学生票$12。","en":"Double the second equation and subtract the first to obtain$12."},"id":"a"},{"text":{"zh":"$24","cn":"$24","en":"$24"},"correct":false,"feedback":{"zh":"$24是代回方程後得到的成人票價。","cn":"$24是代回方程后得到的成人票价。","en":"$24 is the adult price after substitution."},"id":"b"},{"text":{"zh":"$16.8","cn":"$16.8","en":"$16.8"},"correct":false,"feedback":{"zh":"總價除五假設兩種票價相同。","cn":"总价除五假设两种票价相同。","en":"Dividing 84 by 5 assumes both ticket types cost the same."},"id":"c"}],"takeaway":{"zh":"聯立方程要同時符合兩項條件。","cn":"联立方程要同时符合两项条件。","en":"A simultaneous solution must satisfy both conditions."}},{"id":"s2-maths-03","grade":2,"subjectId":"maths","roomId":"maths","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"坡道是否達標","cn":"坡道是否达标","en":"Testing a ramp model"},"question":{"zh":"設計規格要求斜邊長與垂直高度的比至少為13:5。一條直角三角形坡道高0.5米、水平長1.2米。只按這項規格，判斷如何？","cn":"设计规格要求斜边长与垂直高度的比至少为13:5。一条直角三角形坡道高0.5米、水平长1.2米。只按这项规格，判断如何？","en":"A design requires slope length: vertical height to be at least 13:5. A right-triangle ramp rises 0.5 m over 1.2 m horizontally. Considering only this specification, what follows?"},"options":[{"text":{"zh":"達標：斜邊等於1.2+0.5=1.7米","cn":"达标：斜边等于1.2+0.5=1.7米","en":"Passes because slope=1.2+0.5=1.7 m"},"correct":false,"feedback":{"zh":"直角三角形的斜邊不能直接把兩直角邊相加。","cn":"直角三角形的斜边不能直接把两直角边相加。","en":"The hypotenuse is not the sum of the two perpendicular sides."},"id":"a"},{"text":{"zh":"剛好達標：斜邊1.3米，比為13:5","cn":"刚好达标：斜边1.3米，比为13:5","en":"Exactly meets it: slope 1.3 m gives 13:5"},"correct":true,"feedback":{"zh":"√(0.5²+1.2²)=1.3；此題不代表真實無障礙法規。","cn":"√(0.5²+1.2²)=1.3；此题不代表真实无障碍法规。","en":"Pythagoras gives 1.3 m. This hypothetical specification is not an accessibility regulation."},"id":"b"},{"text":{"zh":"不達標：水平長與高度比是12:5","cn":"不达标：水平长与高度比是12:5","en":"Fails because horizontal length:height is 12:5"},"correct":false,"feedback":{"zh":"規格指定斜邊長，不是水平長。","cn":"规格指定斜边长，不是水平长。","en":"The specification refers to slope length, not horizontal length."},"id":"c"}],"takeaway":{"zh":"先辨清模型中的量，再用勾股定理驗證。","cn":"先辨清模型中的量，再用勾股定理验证。","en":"Identify the quantities in the model before applying Pythagoras."}},{"id":"s3-maths-01","grade":3,"subjectId":"maths","roomId":"maths","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"相似圖形的面積","cn":"相似图形的面积","en":"Area under enlargement"},"question":{"zh":"校園地圖等比例放大，所有長度變為原來的1.5倍。一個原面積40平方釐米的區域，放大後面積是多少？","cn":"校园地图等比例放大，所有长度变为原来的1.5倍。一个原面积40平方厘米的区域，放大后面积是多少？","en":"A campus map is enlarged uniformly by a length factor 1.5. An area was 40 cm². What is its enlarged area?"},"options":[{"text":{"zh":"90 平方釐米","cn":"90 平方厘米","en":"90 cm²"},"correct":true,"feedback":{"zh":"面積放大倍數為1.5²=2.25。","cn":"面积放大倍数为1.5²=2.25。","en":"The area factor is 1.5²=2.25."},"id":"a"},{"text":{"zh":"60 平方釐米","cn":"60 平方厘米","en":"60 cm²"},"correct":false,"feedback":{"zh":"1.5是長度倍數；面積涉及兩個方向。","cn":"1.5是长度倍数；面积涉及两个方向。","en":"1.5 is the length factor; area scales in two dimensions."},"id":"b"},{"text":{"zh":"100 平方釐米","cn":"100 平方厘米","en":"100 cm²"},"correct":false,"feedback":{"zh":"面積倍數不是1+1.5。","cn":"面积倍数不是1+1.5。","en":"The area factor is not 1+1.5."},"id":"c"}],"takeaway":{"zh":"相似圖形長度比為k，面積比為k²。","cn":"相似图形长度比为k，面积比为k²。","en":"Similar figures with length ratio k have area ratio k²."}},{"id":"s3-maths-02","grade":3,"subjectId":"maths","roomId":"maths","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"不放回抽樣","cn":"不放回抽样","en":"Sampling without replacement"},"question":{"zh":"袋中有三枚紅棋和兩枚藍棋，隨機抽兩枚且不放回。兩枚都是藍色的概率是多少？","cn":"袋中有三枚红棋和两枚蓝棋，随机抽两枚且不放回。两枚都是蓝色的概率是多少？","en":"A bag contains 3 red and 2 blue counters. Two are drawn randomly without replacement. What is the probability both are blue?"},"options":[{"text":{"zh":"2/5","cn":"2/5","en":"2/5"},"correct":false,"feedback":{"zh":"這只計算了第一枚是藍色。","cn":"这只计算了第一枚是蓝色。","en":"This accounts only for the first blue draw."},"id":"a"},{"text":{"zh":"1/10","cn":"1/10","en":"1/10"},"correct":true,"feedback":{"zh":"(2/5)×(1/4)=1/10；抽走一枚後總數改變。","cn":"(2/5)×(1/4)=1/10；抽走一枚后总数改变。","en":"(2/5)×(1/4)=1/10; the second draw has fewer counters."},"id":"b"},{"text":{"zh":"4/25","cn":"4/25","en":"4/25"},"correct":false,"feedback":{"zh":"這是假設第一次抽到藍棋後放回。","cn":"这是假设第一次抽到蓝棋后放回。","en":"This assumes the first blue counter is replaced."},"id":"c"}],"takeaway":{"zh":"不放回抽樣會改變下一次抽取的條件。","cn":"不放回抽样会改变下一次抽取的条件。","en":"Sampling without replacement changes the conditions of the next draw."}},{"id":"s3-maths-03","grade":3,"subjectId":"maths","roomId":"maths","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"量度誤差的界限","cn":"量度误差的界限","en":"Bounds of measurement"},"question":{"zh":"長方形板的長和闊分別量得12釐米及8釐米，均四捨五入至最接近的釐米。其真正面積的上界是多少？","cn":"长方形板的长和阔分别量得12厘米及8厘米，均四舍五入至最接近的厘米。其真正面积的上界是多少？","en":"A rectangular board is measured as 12 cm by 8 cm, each rounded to the nearest centimetre. What is the upper bound of its true area?"},"options":[{"text":{"zh":"96 平方釐米","cn":"96 平方厘米","en":"96 cm²"},"correct":false,"feedback":{"zh":"96是用顯示數值算出的估計，不是上界。","cn":"96是用显示数值算出的估计，不是上界。","en":"96 is the estimate from displayed values, not an upper bound."},"id":"a"},{"text":{"zh":"117 平方釐米","cn":"117 平方厘米","en":"117 cm²"},"correct":false,"feedback":{"zh":"四捨五入至整數的誤差界限為0.5，而不是1。","cn":"四舍五入至整数的误差界限为0.5，而不是1。","en":"Rounding to the nearest unit gives a half-unit bound, not one unit."},"id":"b"},{"text":{"zh":"106.25 平方釐米（不包括）","cn":"106.25 平方厘米（不包括）","en":"106.25 cm² (exclusive)"},"correct":true,"feedback":{"zh":"長<12.5、闊<8.5，所以面積<106.25。","cn":"长<12.5、阔<8.5，所以面积<106.25。","en":"Length<12.5 and width<8.5, so area<106.25."},"id":"c"}],"takeaway":{"zh":"運算前先寫量度值的上下界，避免把估計當精確值。","cn":"运算前先写量度值的上下界，避免把估计当精确值。","en":"Establish measurement bounds before calculation instead of treating rounded values as exact."}},{"id":"s4-maths-01","grade":4,"subjectId":"maths","roomId":"maths","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"二次方程與情境","cn":"二次方程与情境","en":"Interpreting quadratic roots"},"question":{"zh":"長方形花圃闊x米、長(x+2)米，面積48平方米。方程有根6和−8，哪個可用？","cn":"长方形花圃阔x米、长(x+2)米，面积48平方米。方程有根6和−8，哪个可用？","en":"A garden is x m wide and (x+2)m long with area 48 m². The equation has roots 6 and −8. Which is admissible?"},"options":[{"text":{"zh":"只有 x=−8","cn":"只有 x=−8","en":"Only x=−8"},"correct":false,"feedback":{"zh":"負長度不符合題目的實際量。","cn":"负长度不符合题目的实际量。","en":"A negative length is invalid in this model."},"id":"a"},{"text":{"zh":"只有 x=6","cn":"只有 x=6","en":"Only x=6"},"correct":true,"feedback":{"zh":"長度須為正；6×8=48。","cn":"长度须为正；6×8=48。","en":"Lengths must be positive; 6×8=48."},"id":"b"},{"text":{"zh":"兩個根都可用","cn":"两个根都可用","en":"Both roots"},"correct":false,"feedback":{"zh":"代數根仍要符合花圃長度的情境限制。","cn":"代数根仍要符合花圃长度的情境限制。","en":"Algebraic roots must also satisfy the contextual length constraint."},"id":"c"}],"takeaway":{"zh":"求根後須檢查定義域和情境限制。","cn":"求根后须检查定义域和情境限制。","en":"After solving, check the domain and contextual restrictions."}},{"id":"s4-maths-02","grade":4,"subjectId":"maths","roomId":"maths","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"直線交點的意義","cn":"直线交点的意义","en":"Interpreting a line intersection"},"question":{"zh":"打印店A收費為$30+$0.20n，B為$0.35n，n是頁數。何時A開始比B便宜？","cn":"打印店A收费为$30+$0.20n，B为$0.35n，n是页数。何时A开始比B便宜？","en":"Printing shop A charges $30+$0.20 n and B charges $0.35 n for n pages. When is A cheaper?"},"options":[{"text":{"zh":"n<200","cn":"n<200","en":"n<200"},"correct":false,"feedback":{"zh":"固定費用令A在少量打印時較貴。","cn":"固定费用令A在少量打印时较贵。","en":"The fixed fee makes A more expensive for smaller jobs."},"id":"a"},{"text":{"zh":"n≥200","cn":"n≥200","en":"n≥200"},"correct":false,"feedback":{"zh":"200頁時兩店同價，尚未是較便宜。","cn":"200页时两店同价，尚未是较便宜。","en":"At 200 pages the costs are equal, not cheaper."},"id":"b"},{"text":{"zh":"n>200","cn":"n>200","en":"n>200"},"correct":true,"feedback":{"zh":"30<0.15n，所以超過200頁才較便宜。","cn":"30<0.15n，所以超过200页才较便宜。","en":"30<0.15 n, so A is cheaper above 200 pages."},"id":"c"}],"takeaway":{"zh":"交點表示同價；比較便宜與否需要解不等式。","cn":"交点表示同价；比较便宜与否需要解不等式。","en":"The intersection means equal cost; cheaper-than comparisons require an inequality."}},{"id":"s4-maths-03","grade":4,"subjectId":"maths","roomId":"maths","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"指數模型的限制","cn":"指数模型的限制","en":"Limits of an exponential model"},"question":{"zh":"模型N=100×2ᵗ把影片每日觀看量假定為前一天兩倍。第5天預測3200。哪項新證據最直接削弱模型長期適用性？","cn":"模型N=100×2ᵗ把影片每日观看量假定为前一天两倍。第5天预测3200。哪项新证据最直接削弱模型长期适用性？","en":"The model N=100×2ᵗ assumes daily views double. It predicts 3200 on day 5. Which new evidence most directly weakens its long-term use?"},"options":[{"text":{"zh":"可接觸的觀眾有限，而且新增觀看率已下降","cn":"可接触的观众有限，而且新增观看率已下降","en":"The reachable audience is limited and growth has slowed"},"correct":true,"feedback":{"zh":"固定倍增需要持續成立的條件；受眾飽和會破壞它。","cn":"固定倍增需要持续成立的条件；受众饱和会破坏它。","en":"Constant doubling requires persistent conditions; audience saturation undermines them."},"id":"a"},{"text":{"zh":"模型在首五天的預測與觀察吻合。","cn":"模型在首五天的预测与观察吻合。","en":"Its predictions matched observations for the first five days."},"correct":false,"feedback":{"zh":"短期吻合支持短期適用，沒有直接反駁長期增長假設。","cn":"短期吻合支持短期适用，没有直接反驳长期增长假设。","en":"A short-term match supports short-term fit; it does not directly refute long-term growth."},"id":"b"},{"text":{"zh":"首日瀏覽量其實是 120，而非 100。","cn":"首日浏览量其实是 120，而非 100。","en":"The initial number of views was 120 rather than 100."},"correct":false,"feedback":{"zh":"這要求修正起始值，卻未直接檢驗每天倍增可否長期持續。","cn":"这要求修正起始值，却未直接检验每天倍增可否长期持续。","en":"This changes the starting value but does not directly test whether daily doubling can continue."},"id":"c"}],"takeaway":{"zh":"計算正確不等於模型在所有時間都有效。","cn":"计算正确不等于模型在所有时间都有效。","en":"Correct calculation does not guarantee a model remains valid over time."}},{"id":"s5-maths-01","grade":5,"subjectId":"maths","roomId":"maths","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"相切與半徑","cn":"相切与半径","en":"Tangents and radii"},"question":{"zh":"圓心O到圓外點P距離13釐米，半徑OT=5釐米，PT在T點與圓相切。PT長多少？","cn":"圆心O到圆外点P距离13厘米，半径OT=5厘米，PT在T点与圆相切。PT长多少？","en":"OP=13 cm from centre O to external point P; radius OT=5 cm and PT is tangent at T. Find PT."},"options":[{"text":{"zh":"8 釐米","cn":"8 厘米","en":"8 cm"},"correct":false,"feedback":{"zh":"13−5忽略了OT與PT互相垂直。","cn":"13−5忽略了OT与PT互相垂直。","en":"13−5 ignores the right angle between OT and PT."},"id":"a"},{"text":{"zh":"√194 釐米","cn":"√194 厘米","en":"√194 cm"},"correct":false,"feedback":{"zh":"OP是斜邊，求PT須相減平方。","cn":"OP是斜边，求PT须相减平方。","en":"OP is the hypotenuse, so subtract the squared radius."},"id":"b"},{"text":{"zh":"12 釐米","cn":"12 厘米","en":"12 cm"},"correct":true,"feedback":{"zh":"半徑垂直切線，PT=√(13²−5²)=12。","cn":"半径垂直切线，PT=√(13²−5²)=12。","en":"Radius and tangent are perpendicular; PT=√(13²−5²)=12."},"id":"c"}],"takeaway":{"zh":"先利用圓的幾何性質，再選合適計算關係。","cn":"先利用圆的几何性质，再选合适计算关系。","en":"Use the circle property to establish the geometry before calculating."}},{"id":"s5-maths-02","grade":5,"subjectId":"maths","roomId":"maths","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"條件概率的分母","cn":"条件概率的分母","en":"The conditional denominator"},"question":{"zh":"40名學生中，18人參加音樂社、15人參加美術社、6人兩者都參加。已知隨機選中的學生參加美術社，他也參加音樂社的概率？","cn":"40名学生中，18人参加音乐社、15人参加美术社、6人两者都参加。已知随机选中的学生参加美术社，他也参加音乐社的概率？","en":"Of 40 students, 18 join music, 15 join art and 6 join both. Given that a randomly selected student joins art, what is the probability they also join music?"},"options":[{"text":{"zh":"6/15=2/5","cn":"6/15=2/5","en":"6/15=2/5"},"correct":true,"feedback":{"zh":"已知參加美術社，把樣本空間限於15人。","cn":"已知参加美术社，把样本空间限于15人。","en":"Conditioning on art restricts the sample space to 15 students."},"id":"a"},{"text":{"zh":"6/40=3/20","cn":"6/40=3/20","en":"6/40=3/20"},"correct":false,"feedback":{"zh":"這是隨機學生同時參加兩社的無條件概率。","cn":"这是随机学生同时参加两社的无条件概率。","en":"This is the unconditional probability of joining both clubs."},"id":"b"},{"text":{"zh":"6/18=1/3","cn":"6/18=1/3","en":"6/18=1/3"},"correct":false,"feedback":{"zh":"這是已知參加音樂社時的反向條件概率。","cn":"这是已知参加音乐社时的反向条件概率。","en":"This reverses the condition by starting with music members."},"id":"c"}],"takeaway":{"zh":"條件概率先限制樣本空間；條件不能隨意交換。","cn":"条件概率先限制样本空间；条件不能随意交换。","en":"Conditional probability restricts the sample space; reversing the condition changes the question."}},{"id":"s5-maths-03","grade":5,"subjectId":"maths","roomId":"maths","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"標準差與變換","cn":"标准差与变换","en":"Transforming spread"},"question":{"zh":"一組分數平均60、標準差8。每個分數都按 y=1.5x+10 轉換。新平均和標準差是甚麼？","cn":"一组分数平均60、标准差8。每个分数都按 y=1.5x+10 转换。新平均和标准差是甚么？","en":"Scores have mean 60 and standard deviation 8. Every score becomes y=1.5 x+10. What are the new mean and standard deviation?"},"options":[{"text":{"zh":"平均90，標準差12","cn":"平均90，标准差12","en":"Mean 90, standard deviation 12"},"correct":false,"feedback":{"zh":"標準差算對，但平均漏了加10。","cn":"标准差算对，但平均漏了加10。","en":"The spread is correct, but the mean omitted the added 10."},"id":"a"},{"text":{"zh":"平均100，標準差12","cn":"平均100，标准差12","en":"Mean 100, standard deviation 12"},"correct":true,"feedback":{"zh":"平均作同樣線性變換；加常數不改變分散程度。","cn":"平均作同样线性变换；加常数不改变分散程度。","en":"The mean transforms linearly; adding a constant does not change spread."},"id":"b"},{"text":{"zh":"平均100，標準差22","cn":"平均100，标准差22","en":"Mean 100, standard deviation 22"},"correct":false,"feedback":{"zh":"標準差不能加上10；所有數值同移不改變距離。","cn":"标准差不能加上10；所有数值同移不改变距离。","en":"Do not add 10 to the standard deviation; shifting all values preserves distances."},"id":"c"}],"takeaway":{"zh":"平移改變中心，縮放同時改變中心及分散程度。","cn":"平移改变中心，缩放同时改变中心及分散程度。","en":"A shift changes location; scaling also changes spread."}},{"id":"s6-maths-01","grade":6,"subjectId":"maths","roomId":"maths","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"對數與倍增時間","cn":"对数与倍增时间","en":"Logarithms and growth time"},"question":{"zh":"儲量模型V=500×1.08ᵗ，t以年計。求V首次達1000的連續時間，應計哪個式子？","cn":"储量模型V=500×1.08ᵗ，t以年计。求V首次达1000的连续时间，应计哪个式子？","en":"For V=500×1.08ᵗ with t in years, which expression gives the continuous time when V first reaches 1000?"},"options":[{"text":{"zh":"log(2)/log(1.08)","cn":"log(2)/log(1.08)","en":"log(2)/log(1.08)"},"correct":true,"feedback":{"zh":"先除500得1.08ᵗ=2，再取同底對數。","cn":"先除500得1.08ᵗ=2，再取同底对数。","en":"Divide by 500 to obtain 1.08ᵗ=2, then take logarithms with the same base."},"id":"a"},{"text":{"zh":"log(1000)/log(1.08)","cn":"log(1000)/log(1.08)","en":"log(1000)/log(1.08)"},"correct":false,"feedback":{"zh":"這漏除了初始值500。","cn":"这漏除了初始值500。","en":"This omits division by the initial amount 500."},"id":"b"},{"text":{"zh":"2/0.08","cn":"2/0.08","en":"2/0.08"},"correct":false,"feedback":{"zh":"這把複合增長誤當固定量的線性增加。","cn":"这把复合增长误当固定量的线性增加。","en":"This treats compound growth as a fixed linear increase."},"id":"c"}],"takeaway":{"zh":"未知數在指數時，先整理比例再使用對數。","cn":"未知数在指数时，先整理比例再使用对数。","en":"When the unknown is an exponent, isolate the growth ratio before using logarithms."}},{"id":"s6-maths-02","grade":6,"subjectId":"maths","roomId":"maths","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"限制條件與最佳值","cn":"限制条件与最佳值","en":"Optimising under constraints"},"question":{"zh":"製作x個袋和y本冊，限制為x≥0、y≥0、x+y≤10、2x+y≤14。收益P=5x+3y。在可行頂點(0,0)、(0,10)、(4,6)、(7,0)中，哪點最佳？","cn":"制作x个袋和y本册，限制为x≥0、y≥0、x+y≤10、2x+y≤14。收益P=5x+3y。在可行顶点(0,0)、(0,10)、(4,6)、(7,0)中，哪点最佳？","en":"Make x bags and y booklets with x, y≥0, x+y≤10, 2 x+y≤14. Revenue P=5 x+3 y. Which feasible vertex is best: (0, 0), (0, 10), (4, 6), (7, 0)?"},"options":[{"text":{"zh":"(0,10)，收益30","cn":"(0,10)，收益30","en":"(0, 10), revenue 30"},"correct":false,"feedback":{"zh":"產量最多的一點不一定有最高收益。","cn":"产量最多的一点不一定有最高收益。","en":"The largest item count need not maximise revenue."},"id":"a"},{"text":{"zh":"(4,6)，收益38","cn":"(4,6)，收益38","en":"(4, 6), revenue 38"},"correct":true,"feedback":{"zh":"各點收益為0、30、38、35，最大為38。","cn":"各点收益为0、30、38、35，最大为38。","en":"The objective values are 0, 30, 38, 35; 38 is greatest."},"id":"b"},{"text":{"zh":"(7,0)，收益35","cn":"(7,0)，收益35","en":"(7, 0), revenue 35"},"correct":false,"feedback":{"zh":"每袋收益較高，不表示全製袋的總收益最高。","cn":"每袋收益较高，不表示全制袋的总收益最高。","en":"A larger unit return does not make an all-bag plan optimal."},"id":"c"}],"takeaway":{"zh":"比較可行頂點的目標函數，而非只看單價或產量。","cn":"比较可行顶点的目标函数，而非只看单价或产量。","en":"Compare objective values at feasible vertices, not only prices or output counts."}},{"id":"s6-maths-03","grade":6,"subjectId":"maths","roomId":"maths","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"統計比較的反轉","cn":"统计比较的反转","en":"When pooled rates mislead"},"question":{"zh":"方法A：基礎題90/100答對、進階題1/10；方法B：基礎題19/20、進階題20/100。A總正確率較高。哪項評估最合理？","cn":"方法A：基础题90/100答对、进阶题1/10；方法B：基础题19/20、进阶题20/100。A总正确率较高。哪项评估最合理？","en":"Method A: 90/100 basic and 1/10 advanced correct. B: 19/20 basic and 20/100 advanced correct. A has a higher pooled rate. Which evaluation is strongest?"},"options":[{"text":{"zh":"A在每一類題都較好","cn":"A在每一类题都较好","en":"A is better on every task type"},"correct":false,"feedback":{"zh":"分組計算顯示兩類都是B較高。","cn":"分组计算显示两类都是B较高。","en":"Calculating within each type shows B is higher in both."},"id":"a"},{"text":{"zh":"只要總題數不同，所有正確率都不能比較","cn":"只要总题数不同，所有正确率都不能比较","en":"No rates can be compared if totals differ"},"correct":false,"feedback":{"zh":"比率容許不同樣本量；此處關鍵是題型組成及不確定性。","cn":"比率容许不同样本量；此处关键是题型组成及不确定性。","en":"Rates can compare unequal sample sizes; task mix and uncertainty are the issues here."},"id":"b"},{"text":{"zh":"B在兩類題均較高；兩者題型比例不同，須標準化比較","cn":"B在两类题均较高；两者题型比例不同，须标准化比较","en":"B is better within each type; standardise the different task mixes"},"correct":true,"feedback":{"zh":"基礎90%對95%、進階10%對20%；混合權重可反轉結論。","cn":"基础90%对95%、进阶10%对20%；混合权重可反转结论。","en":"Basic rates 90% vs 95%, advanced 10% vs 20%; different weights can reverse the pooled comparison."},"id":"c"}],"takeaway":{"zh":"總平均會受組成影響；比較表現須檢查分組及權重。","cn":"总平均会受组成影响；比较表现须检查分组及权重。","en":"Pooled performance depends on composition; inspect groups and weights."}},{"id":"s1-chemistry-01","grade":1,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"科學：量度液體體積","cn":"科学：量度液体体积","en":"Science: measuring liquid volume"},"question":{"zh":"水在量筒內形成凹液面。要減少視差，應如何讀數？","cn":"水在量筒内形成凹液面。要减少视差，应如何读数？","en":"Water forms a concave meniscus in a measuring cylinder. How should you read its volume to reduce parallax error?"},"options":[{"text":{"zh":"手持量筒傾斜，從上方讀最高點。","cn":"手持量筒倾斜，从上方读最高点。","en":"Tilt the cylinder and read the highest point from above."},"correct":false,"feedback":{"zh":"傾斜和斜視都會使讀數偏離正確體積。","cn":"倾斜和斜视都会使读数偏离正确体积。","en":"Tilting and viewing from above distort the reading."},"id":"a"},{"text":{"zh":"只讀最接近的整十刻度，不理會小刻度。","cn":"只读最接近的整十刻度，不理会小刻度。","en":"Use the nearest multiple of ten and ignore smaller divisions."},"correct":false,"feedback":{"zh":"忽略可讀的小刻度會降低量度精確度。","cn":"忽略可读的小刻度会降低量度精确度。","en":"Ignoring readable subdivisions reduces measurement precision."},"id":"b"},{"text":{"zh":"視線與凹液面最低點同高，量筒放在水平桌面。","cn":"视线与凹液面最低点同高，量筒放在水平桌面。","en":"Read the bottom of the meniscus at eye level, with the cylinder on a level bench."},"correct":true,"feedback":{"zh":"眼睛與刻度同高可減少視差；水應讀凹液面最低點。","cn":"眼睛与刻度同高可减少视差；水应读凹液面最低点。","en":"An eye-level reading reduces parallax; read the bottom of water's meniscus."},"id":"c"}],"takeaway":{"zh":"量度須配合儀器刻度、正確視線與一致程序。","cn":"量度须配合仪器刻度、正确视线与一致程序。","en":"Use the instrument's scale, correct viewing position and a consistent procedure."}},{"id":"s1-chemistry-02","grade":1,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"科學：分離混合物","cn":"科学：分离混合物","en":"Science: separating a mixture"},"question":{"zh":"混合物含沙和食鹽。要分別取得乾沙與食鹽，哪個次序合理？所有加熱均由老師監督。","cn":"混合物含沙和食盐。要分别取得干沙与食盐，哪个次序合理？所有加热均由老师监督。","en":"A mixture contains sand and salt. Which sequence can recover dry sand and salt separately? All heating is teacher-supervised."},"options":[{"text":{"zh":"加水攪拌 → 過濾 → 乾燥沙；把濾液蒸發結晶。","cn":"加水搅拌 → 过滤 → 干燥沙；把滤液蒸发结晶。","en":"Add water and stir → filter → dry the sand; evaporate the filtrate to obtain salt."},"correct":true,"feedback":{"zh":"鹽溶於水而沙不溶，過濾先分出沙，蒸發再取得鹽。","cn":"盐溶于水而沙不溶，过滤先分出沙，蒸发再取得盐。","en":"Salt dissolves but sand does not; filtration separates sand and evaporation recovers salt."},"id":"a"},{"text":{"zh":"直接過濾乾混合物，再用磁鐵分鹽。","cn":"直接过滤干混合物，再用磁铁分盐。","en":"Filter the dry mixture, then remove salt with a magnet."},"correct":false,"feedback":{"zh":"沒有溶劑時過濾不能按溶解性分離；食鹽也不具磁性。","cn":"没有溶剂时过滤不能按溶解性分离；食盐也不具磁性。","en":"Dry filtration does not separate by solubility, and salt is not magnetic."},"id":"b"},{"text":{"zh":"加水後只取濾紙上的物質，便得到兩者。","cn":"加水后只取滤纸上的物质，便得到两者。","en":"Add water and keep only the filter residue to recover both."},"correct":false,"feedback":{"zh":"食鹽會留在濾液中，丟棄濾液便失去食鹽。","cn":"食盐会留在滤液中，丢弃滤液便失去食盐。","en":"Salt remains dissolved in the filtrate, so discarding it loses the salt."},"id":"c"}],"takeaway":{"zh":"分離方法利用物質性質的差異，並要追蹤每種物質去了哪裏。","cn":"分离方法利用物质性质的差异，并要追踪每种物质去了哪里。","en":"Separation uses differences in properties; track where each substance goes."}},{"id":"s1-chemistry-03","grade":1,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"科學：辨認混雜變項","cn":"科学：辨认混杂变项","en":"Science: identifying confounding variables"},"question":{"zh":"甲把細糖放入 60°C 水，乙把糖粒放入 20°C 水；甲溶解較快。他們想研究溫度的影響。應怎樣改良？","cn":"甲把细糖放入 60°C 水，乙把糖粒放入 20°C 水；甲溶解较快。他们想研究温度的影响。应怎样改良？","en":"A uses fine sugar in water at 60°C; B uses large sugar crystals at 20°C. A dissolves faster. They want to study temperature. How should they improve the comparison?"},"options":[{"text":{"zh":"只做一次更快的計時便可證明溫度是唯一原因。","cn":"只做一次更快的计时便可证明温度是唯一原因。","en":"Time one trial more precisely to prove temperature is the only cause."},"correct":false,"feedback":{"zh":"計時精確不能消除實驗設計中的混雜因素。","cn":"计时精确不能消除实验设计中的混杂因素。","en":"Precise timing does not remove a confounding variable in the design."},"id":"a"},{"text":{"zh":"使用相同大小及質量的糖、水量和攪拌方法，只改變溫度。","cn":"使用相同大小及质量的糖、水量和搅拌方法，只改变温度。","en":"Keep sugar size and mass, water volume and stirring the same; change only temperature."},"correct":true,"feedback":{"zh":"糖粒大小也影響溶解速率，必須控制才能隔離溫度的影響。","cn":"糖粒大小也影响溶解速率，必须控制才能隔离温度的影响。","en":"Particle size also affects dissolution rate, so it must be controlled to isolate temperature."},"id":"b"},{"text":{"zh":"把甲的水量加倍，其他不變。","cn":"把甲的水量加倍，其他不变。","en":"Double A's water volume and keep everything else unchanged."},"correct":false,"feedback":{"zh":"這增加另一個變項，並未控制糖粒大小。","cn":"这增加另一个变项，并未控制糖粒大小。","en":"This adds another variable without controlling particle size."},"id":"c"}],"takeaway":{"zh":"公平測試須控制可能影響結果的其他變項。","cn":"公平测试须控制可能影响结果的其他变项。","en":"A fair test controls other variables that may affect the outcome."}},{"id":"s2-chemistry-01","grade":2,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"科學：細胞結構與功能","cn":"科学：细胞结构与功能","en":"Science: cell structures and functions"},"question":{"zh":"顯微鏡下的洋蔥表皮細胞有明顯外框。哪個配對最準確？","cn":"显微镜下的洋葱表皮细胞有明显外框。哪个配对最准确？","en":"Onion epidermal cells show a clear outer boundary under a microscope. Which structure–function pairing is most accurate?"},"options":[{"text":{"zh":"細胞壁提供支持；細胞膜控制物質進出。","cn":"细胞壁提供支持；细胞膜控制物质进出。","en":"The cell wall provides support; the cell membrane regulates movement of substances."},"correct":true,"feedback":{"zh":"細胞壁與細胞膜是不同結構，功能不能互換。","cn":"细胞壁与细胞膜是不同结构，功能不能互换。","en":"The wall and membrane are different structures with different functions."},"id":"a"},{"text":{"zh":"細胞核提供所有外部支持，細胞壁儲存全部遺傳物質。","cn":"细胞核提供所有外部支持，细胞壁储存全部遗传物质。","en":"The nucleus provides all external support; the wall stores all genetic material."},"correct":false,"feedback":{"zh":"細胞核含主要遺傳物質；細胞壁主要提供支持。","cn":"细胞核含主要遗传物质；细胞壁主要提供支持。","en":"The nucleus contains the main genetic material; the wall mainly provides support."},"id":"b"},{"text":{"zh":"所有植物細胞都必須含大量葉綠體。","cn":"所有植物细胞都必须含大量叶绿体。","en":"Every plant cell must contain many chloroplasts."},"correct":false,"feedback":{"zh":"例如洋蔥鱗莖表皮通常沒有葉綠體，不能概括所有植物細胞。","cn":"例如洋葱鳞茎表皮通常没有叶绿体，不能概括所有植物细胞。","en":"Onion bulb epidermal cells typically lack chloroplasts; not all plant cells have them."},"id":"c"}],"takeaway":{"zh":"根據結構和功能解釋細胞，避免把典型圖像當成所有細胞的樣子。","cn":"根据结构和功能解释细胞，避免把典型图像当成所有细胞的样子。","en":"Explain cells through structure and function, without treating a typical diagram as universal."}},{"id":"s2-chemistry-02","grade":2,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"科學：串聯電路的電壓","cn":"科学：串联电路的电压","en":"Science: voltage in a series circuit"},"question":{"zh":"在理想電路中，2 Ω 和 4 Ω 電阻串聯接上 12 V 電源。已知 V = IR。4 Ω 電阻兩端電壓是多少？","cn":"在理想电路中，2 Ω 和 4 Ω 电阻串联接上 12 V 电源。已知 V = IR。4 Ω 电阻两端电压是多少？","en":"In an ideal circuit, 2 Ω and 4 Ω resistors are connected in series to a 12 V source. Use V = IR. What is the voltage across the 4 Ω resistor?"},"options":[{"text":{"zh":"6 V","cn":"6 V","en":"6 V"},"correct":false,"feedback":{"zh":"電阻不相等，電壓並非平均分配。","cn":"电阻不相等，电压并非平均分配。","en":"The resistances differ, so the voltage is not shared equally."},"id":"a"},{"text":{"zh":"8 V","cn":"8 V","en":"8 V"},"correct":true,"feedback":{"zh":"總電阻 6 Ω，電流 12÷6=2 A；4 Ω 上的電壓為 2×4=8 V。","cn":"总电阻 6 Ω，电流 12÷6=2 A；4 Ω 上的电压为 2×4=8 V。","en":"Total resistance is 6 Ω, so current is 2 A; the voltage across 4 Ω is 2×4=8 V."},"id":"b"},{"text":{"zh":"12 V","cn":"12 V","en":"12 V"},"correct":false,"feedback":{"zh":"12 V 是兩個串聯電阻的總電壓，不是各自的電壓。","cn":"12 V 是两个串联电阻的总电压，不是各自的电压。","en":"12 V is the total across both series resistors, not across each one."},"id":"c"}],"takeaway":{"zh":"串聯電路電流相同，電壓按電阻大小分配。","cn":"串联电路电流相同，电压按电阻大小分配。","en":"Series components carry the same current; voltage divides in proportion to resistance."}},{"id":"s2-chemistry-03","grade":2,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"科學：從氣體變化推論","cn":"科学：从气体变化推论","en":"Science: interpreting gas changes"},"question":{"zh":"兩組相同水草分別放在光亮和黑暗中，其他條件相同。光亮組氧氣增加，黑暗組氧氣減少。哪個解釋最合理？","cn":"两组相同水草分别放在光亮和黑暗中，其他条件相同。光亮组氧气增加，黑暗组氧气减少。哪个解释最合理？","en":"Identical aquatic plants are kept in light or darkness under otherwise equal conditions. Oxygen rises in the light group and falls in the dark group. Which explanation best fits?"},"options":[{"text":{"zh":"植物只在黑暗時呼吸，光亮時完全停止。","cn":"植物只在黑暗时呼吸，光亮时完全停止。","en":"Plants respire only in darkness and stop completely in light."},"correct":false,"feedback":{"zh":"植物在光亮時也進行呼吸，不能把氧氣增加理解為沒有呼吸。","cn":"植物在光亮时也进行呼吸，不能把氧气增加理解为没有呼吸。","en":"Plants also respire in light; rising oxygen does not mean respiration has stopped."},"id":"a"},{"text":{"zh":"光亮組的氧氣增加代表水草只呼吸而沒有光合作用。","cn":"光亮组的氧气增加代表水草只呼吸而没有光合作用。","en":"The oxygen increase means the illuminated plants respire without photosynthesising."},"correct":false,"feedback":{"zh":"呼吸消耗氧氣，不能單獨解釋氧氣淨增加。","cn":"呼吸消耗氧气，不能单独解释氧气净增加。","en":"Respiration consumes oxygen and cannot alone explain a net increase."},"id":"b"},{"text":{"zh":"光亮組光合作用產氧多於呼吸耗氧；黑暗組仍呼吸。","cn":"光亮组光合作用产氧多于呼吸耗氧；黑暗组仍呼吸。","en":"In light, photosynthesis produces more oxygen than respiration uses; in darkness, respiration continues."},"correct":true,"feedback":{"zh":"觀察到的是產氧和耗氧兩個過程的淨結果。","cn":"观察到的是产氧和耗氧两个过程的净结果。","en":"The observation is the net result of oxygen production and use."},"id":"c"}],"takeaway":{"zh":"同時存在的過程可能互相抵銷；量度常顯示淨變化。","cn":"同时存在的过程可能互相抵销；量度常显示净变化。","en":"Simultaneous processes can offset each other; measurements often show a net change."}},{"id":"s3-chemistry-01","grade":3,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"科學：原子與離子","cn":"科学：原子与离子","en":"Science: atoms and ions"},"question":{"zh":"一粒子有 12 個質子、12 個中子及 10 個電子。其質量數和電荷分別是甚麼？","cn":"一粒子有 12 个质子、12 个中子及 10 个电子。其质量数和电荷分别是甚么？","en":"A particle has 12 protons, 12 neutrons and 10 electrons. What are its mass number and charge?"},"options":[{"text":{"zh":"質量數 12，沒有電荷。","cn":"质量数 12，没有电荷。","en":"Mass number 12; no charge."},"correct":false,"feedback":{"zh":"12 是質子數；質子和電子數不同，所以不是中性。","cn":"12 是质子数；质子和电子数不同，所以不是中性。","en":"12 is the proton number; unequal proton and electron counts mean it is not neutral."},"id":"a"},{"text":{"zh":"質量數 24，電荷 2+。","cn":"质量数 24，电荷 2+。","en":"Mass number 24; charge 2+."},"correct":true,"feedback":{"zh":"質量數為質子加中子；正電荷比負電荷多 2。","cn":"质量数为质子加中子；正电荷比负电荷多 2。","en":"Mass number is protons plus neutrons; there are two more positive than negative charges."},"id":"b"},{"text":{"zh":"質量數 22，電荷 2−。","cn":"质量数 22，电荷 2−。","en":"Mass number 22; charge 2−."},"correct":false,"feedback":{"zh":"電子不計入質量數；電子較少應帶正電。","cn":"电子不计入质量数；电子较少应带正电。","en":"Electrons are not counted in the mass number; fewer electrons gives a positive charge."},"id":"c"}],"takeaway":{"zh":"分清質子數、質量數和淨電荷，使用各自定義計算。","cn":"分清质子数、质量数和净电荷，使用各自定义计算。","en":"Distinguish proton number, mass number and net charge using their definitions."}},{"id":"s3-chemistry-02","grade":3,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"科學：中和與能量轉移","cn":"科学：中和与能量转移","en":"Science: neutralisation and energy transfer"},"question":{"zh":"在老師示範中，酸與鹼混合後溫度由 22°C 升至 28°C。忽略外界熱量交換，哪項解釋合理？","cn":"在老师示范中，酸与碱混合后温度由 22°C 升至 28°C。忽略外界热量交换，哪项解释合理？","en":"In a teacher demonstration, mixing an acid and an alkali raises the temperature from 22°C to 28°C. Ignoring heat exchange with the surroundings, which interpretation is reasonable?"},"options":[{"text":{"zh":"反應吸收溶液熱能，所以溶液升溫。","cn":"反应吸收溶液热能，所以溶液升温。","en":"The reaction absorbs thermal energy from the solution, making it warmer."},"correct":false,"feedback":{"zh":"若反應從溶液吸熱而無其他來源，溶液會降溫。","cn":"若反应从溶液吸热而无其他来源，溶液会降温。","en":"Absorbing energy from the solution would cool it without another energy source."},"id":"a"},{"text":{"zh":"所有酸鹼混合後必定變成 pH 7。","cn":"所有酸碱混合后必定变成 pH 7。","en":"Every acid–alkali mixture must end at pH 7."},"correct":false,"feedback":{"zh":"最終 pH 還取決於酸鹼種類及用量；升溫不能證明完全中和。","cn":"最终 pH 还取决于酸碱种类及用量；升温不能证明完全中和。","en":"Final pH depends on substances and amounts; warming alone does not prove complete neutralisation."},"id":"b"},{"text":{"zh":"反應釋放能量到溶液，屬放熱反應。","cn":"反应释放能量到溶液，属放热反应。","en":"The reaction transfers energy to the solution and is exothermic."},"correct":true,"feedback":{"zh":"溶液升溫顯示反應釋出的能量增加了溶液的熱能。","cn":"溶液升温显示反应释出的能量增加了溶液的热能。","en":"The temperature rise indicates energy released by the reaction increases the solution's thermal energy."},"id":"c"}],"takeaway":{"zh":"溫度變化提供能量轉移證據，但不能代替其他化學量度。","cn":"温度变化提供能量转移证据，但不能代替其他化学量度。","en":"Temperature change provides evidence of energy transfer, not every other chemical property."}},{"id":"s3-chemistry-03","grade":3,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"科學：空氣阻力的證據","cn":"科学：空气阻力的证据","en":"Science: evidence about air resistance"},"question":{"zh":"同一張紙先攤平、再揉成球，從相同高度分別放手。紙球較快到地面。哪項結論最符合這個設計？","cn":"同一张纸先摊平、再揉成球，从相同高度分别放手。纸球较快到地面。哪项结论最符合这个设计？","en":"The same sheet is dropped flat and then crumpled into a ball from the same height. The ball reaches the ground sooner. Which conclusion best matches the design?"},"options":[{"text":{"zh":"質量相同而形狀不同，結果支持形狀影響空氣阻力。","cn":"质量相同而形状不同，结果支持形状影响空气阻力。","en":"Mass is unchanged while shape differs; the result supports an effect of shape on air resistance."},"correct":true,"feedback":{"zh":"同一張紙保持質量，形狀改變迎風面及空氣阻力。","cn":"同一张纸保持质量，形状改变迎风面及空气阻力。","en":"Using the same sheet keeps mass fixed while shape changes the area presented to the air."},"id":"a"},{"text":{"zh":"紙球的重力必定是原來的兩倍。","cn":"纸球的重力必定是原来的两倍。","en":"The ball's gravitational force must be twice as large."},"correct":false,"feedback":{"zh":"紙的質量沒有變，不能由落地較快推斷重力加倍。","cn":"纸的质量没有变，不能由落地较快推断重力加倍。","en":"The mass has not changed; faster falling does not imply twice the gravitational force."},"id":"b"},{"text":{"zh":"真空中也一定有相同時間差。","cn":"真空中也一定有相同时间差。","en":"The same time difference must occur in a vacuum."},"correct":false,"feedback":{"zh":"此實驗在空氣中進行，不能把空氣阻力的結果直接套用到真空。","cn":"此实验在空气中进行，不能把空气阻力的结果直接套用到真空。","en":"This air-based result cannot be transferred unchanged to a vacuum."},"id":"c"}],"takeaway":{"zh":"辨認實驗保持了甚麼、改變了甚麼，再界定結論範圍。","cn":"辨认实验保持了甚么、改变了甚么，再界定结论范围。","en":"Identify what was held constant and changed before setting a conclusion's scope."}},{"id":"s4-chemistry-01","grade":4,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"化學：離子晶體的導電性","cn":"化学：离子晶体的导电性","en":"Chemistry: conduction in ionic substances"},"question":{"zh":"固態氯化鈉不導電，熔融氯化鈉導電。最合理的微觀解釋是甚麼？","cn":"固态氯化钠不导电，熔融氯化钠导电。最合理的微观解释是甚么？","en":"Solid sodium chloride does not conduct electricity, but molten sodium chloride does. Which microscopic explanation is best?"},"options":[{"text":{"zh":"固體完全沒有帶電粒子，熔融才產生離子。","cn":"固体完全没有带电粒子，熔融才产生离子。","en":"The solid has no charged particles; melting creates ions."},"correct":false,"feedback":{"zh":"固體本來已由離子組成，差別是離子的流動性。","cn":"固体本来已由离子组成，差别是离子的流动性。","en":"The solid already contains ions; their mobility changes."},"id":"a"},{"text":{"zh":"熔融令氯化鈉變成金屬，靠自由電子導電。","cn":"熔融令氯化钠变成金属，靠自由电子导电。","en":"Melting turns sodium chloride into a metal conducting by free electrons."},"correct":false,"feedback":{"zh":"物態改變不會令離子化合物變成金屬。","cn":"物态改变不会令离子化合物变成金属。","en":"A change of state does not turn an ionic compound into a metal."},"id":"b"},{"text":{"zh":"熔融時離子可自由移動並傳遞電荷。","cn":"熔融时离子可自由移动并传递电荷。","en":"Ions can move through the melt and carry charge."},"correct":true,"feedback":{"zh":"固體內離子位置固定；熔融後可移動，毋須假設產生自由電子。","cn":"固体内离子位置固定；熔融后可移动，毋须假设产生自由电子。","en":"Ions are fixed in the solid lattice but mobile in the melt; free electrons are not the charge carriers."},"id":"c"}],"takeaway":{"zh":"解釋導電性時須指出可移動的帶電粒子。","cn":"解释导电性时须指出可移动的带电粒子。","en":"Explain conductivity by identifying mobile charge carriers."}},{"id":"s4-chemistry-02","grade":4,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"化學：物質的量與氣體體積","cn":"化学：物质的量与气体体积","en":"Chemistry: amount and gas volume"},"question":{"zh":"CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂。10.0 g 純 CaCO₃ 與過量酸完全反應。CaCO₃ 摩爾質量 100 g mol⁻¹；該條件下氣體摩爾體積 24.0 dm³ mol⁻¹。CO₂ 體積？","cn":"CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂。10.0 g 纯 CaCO₃ 与过量酸完全反应。CaCO₃ 摩尔质量 100 g mol⁻¹；该条件下气体摩尔体积 24.0 dm³ mol⁻¹。CO₂ 体积？","en":"CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂. 10.0 g of pure CaCO₃ reacts completely with excess acid. Its molar mass is 100 g mol⁻¹; gas molar volume is 24.0 dm³ mol⁻¹. What volume of CO₂ forms?"},"options":[{"text":{"zh":"2.40 dm³","cn":"2.40 dm³","en":"2.40 dm³"},"correct":true,"feedback":{"zh":"CaCO₃ 為 0.100 mol；CO₂ 比例 1:1，體積 0.100×24.0=2.40 dm³。","cn":"CaCO₃ 为 0.100 mol；CO₂ 比例 1:1，体积 0.100×24.0=2.40 dm³。","en":"CaCO₃ is 0.100 mol; the CO₂ ratio is 1:1, giving 0.100×24.0=2.40 dm³."},"id":"a"},{"text":{"zh":"4.80 dm³","cn":"4.80 dm³","en":"4.80 dm³"},"correct":false,"feedback":{"zh":"係數 2 屬 HCl，並非 CO₂；不能把 CO₂ 物質的量加倍。","cn":"系数 2 属 HCl，并非 CO₂；不能把 CO₂ 物质的量加倍。","en":"The coefficient 2 belongs to HCl, not CO₂; it does not double the CO₂ amount."},"id":"b"},{"text":{"zh":"240 dm³","cn":"240 dm³","en":"240 dm³"},"correct":false,"feedback":{"zh":"須先把克數除以摩爾質量，不能直接乘摩爾體積。","cn":"须先把克数除以摩尔质量，不能直接乘摩尔体积。","en":"Convert grams to moles before multiplying by molar volume."},"id":"c"}],"takeaway":{"zh":"依次轉換質量、物質的量比及體積，保留單位。","cn":"依次转换质量、物质的量比及体积，保留单位。","en":"Convert mass to amount, apply the mole ratio, then convert to volume with units."}},{"id":"s4-chemistry-03","grade":4,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"化學：限制反應物","cn":"化学：限制反应物","en":"Chemistry: limiting reagent"},"question":{"zh":"Mg + 2HCl → MgCl₂ + H₂。0.120 mol Mg 與 0.200 mol HCl 反應至完成。哪項正確？","cn":"Mg + 2HCl → MgCl₂ + H₂。0.120 mol Mg 与 0.200 mol HCl 反应至完成。哪项正确？","en":"Mg + 2HCl → MgCl₂ + H₂. 0.120 mol Mg reacts with 0.200 mol HCl to completion. Which statement is correct?"},"options":[{"text":{"zh":"H₂ 為 0.200 mol，餘下 Mg 0.100 mol。","cn":"H₂ 为 0.200 mol，余下 Mg 0.100 mol。","en":"0.200 mol H₂ forms and 0.100 mol Mg remains."},"correct":false,"feedback":{"zh":"HCl:H₂ 是 2:1，不能直接以 HCl 的物質的量作氫氣產量。","cn":"HCl:H₂ 是 2:1，不能直接以 HCl 的物质的量作氢气产量。","en":"The HCl:H₂ ratio is 2:1, so the HCl amount is not the H₂ yield."},"id":"a"},{"text":{"zh":"H₂ 為 0.100 mol，餘下 Mg 0.020 mol。","cn":"H₂ 为 0.100 mol，余下 Mg 0.020 mol。","en":"0.100 mol H₂ forms and 0.020 mol Mg remains."},"correct":true,"feedback":{"zh":"HCl 只足以消耗 0.100 mol Mg，所以酸是限制反應物。","cn":"HCl 只足以消耗 0.100 mol Mg，所以酸是限制反应物。","en":"The HCl can consume only 0.100 mol Mg, so acid is limiting."},"id":"b"},{"text":{"zh":"H₂ 為 0.120 mol，兩種反應物都剛好用完。","cn":"H₂ 为 0.120 mol，两种反应物都刚好用完。","en":"0.120 mol H₂ forms and both reactants are used up."},"correct":false,"feedback":{"zh":"消耗 0.120 mol Mg 需要 0.240 mol HCl，比現有的多。","cn":"消耗 0.120 mol Mg 需要 0.240 mol HCl，比现有的多。","en":"Consuming 0.120 mol Mg requires 0.240 mol HCl, more than is available."},"id":"c"}],"takeaway":{"zh":"先比較反應式所需比例，才判斷產量及剩餘物。","cn":"先比较反应式所需比例，才判断产量及剩余物。","en":"Compare required stoichiometric ratios before finding yield and leftovers."}},{"id":"s5-chemistry-01","grade":5,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"化學：電子轉移與氧化","cn":"化学：电子转移与氧化","en":"Chemistry: electron transfer and oxidation"},"question":{"zh":"反應中 Fe²⁺ 變成 Fe³⁺。哪項半反應及解釋正確？","cn":"反应中 Fe²⁺ 变成 Fe³⁺。哪项半反应及解释正确？","en":"Fe²⁺ changes to Fe³⁺ in a reaction. Which half-equation and explanation are correct?"},"options":[{"text":{"zh":"Fe²⁺ → Fe³⁺ + e⁻；失電子，被氧化。","cn":"Fe²⁺ → Fe³⁺ + e⁻；失电子，被氧化。","en":"Fe²⁺ → Fe³⁺ + e⁻; it loses an electron and is oxidised."},"correct":true,"feedback":{"zh":"電荷由 +2 增至 +3 對應失去一個負電荷。","cn":"电荷由 +2 增至 +3 对应失去一个负电荷。","en":"Changing from +2 to +3 corresponds to losing one negative charge."},"id":"a"},{"text":{"zh":"Fe²⁺ + e⁻ → Fe³⁺；得電子，被還原。","cn":"Fe²⁺ + e⁻ → Fe³⁺；得电子，被还原。","en":"Fe²⁺ + e⁻ → Fe³⁺; it gains an electron and is reduced."},"correct":false,"feedback":{"zh":"左邊總電荷 +1，右邊 +3，電荷不守恆。","cn":"左边总电荷 +1，右边 +3，电荷不守恒。","en":"The charge is +1 on the left and +3 on the right, so it is unbalanced."},"id":"b"},{"text":{"zh":"Fe²⁺ → Fe³⁺ + 3e⁻；失去三個電子。","cn":"Fe²⁺ → Fe³⁺ + 3e⁻；失去三个电子。","en":"Fe²⁺ → Fe³⁺ + 3e⁻; it loses three electrons."},"correct":false,"feedback":{"zh":"氧化數只增加 1，並非失去三個電子。","cn":"氧化数只增加 1，并非失去三个电子。","en":"The oxidation number rises by one, not three."},"id":"c"}],"takeaway":{"zh":"半反應必須守恆原子及電荷；用電子得失判斷氧化還原。","cn":"半反应必须守恒原子及电荷；用电子得失判断氧化还原。","en":"Balance atoms and charge in half-equations; use electron transfer to identify redox."}},{"id":"s5-chemistry-02","grade":5,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"化學：量熱法與反應焓","cn":"化学：量热法与反应焓","en":"Chemistry: calorimetry and enthalpy"},"question":{"zh":"0.0500 mol 反應物反應，使 100 g 溶液升溫 7.0°C。比熱容量 4.2 J g⁻¹ °C⁻¹；忽略熱損失。每摩爾反應焓約為多少？","cn":"0.0500 mol 反应物反应，使 100 g 溶液升温 7.0°C。比热容量 4.2 J g⁻¹ °C⁻¹；忽略热损失。每摩尔反应焓约为多少？","en":"Reaction of 0.0500 mol warms 100 g of solution by 7.0°C. Specific heat capacity is 4.2 J g⁻¹ °C⁻¹; ignore heat loss. What is the approximate molar enthalpy change?"},"options":[{"text":{"zh":"−2.94 kJ mol⁻¹","cn":"−2.94 kJ mol⁻¹","en":"−2.94 kJ mol⁻¹"},"correct":false,"feedback":{"zh":"2.94 kJ 是本次 0.0500 mol 的熱量，還須換算每摩爾。","cn":"2.94 kJ 是本次 0.0500 mol 的热量，还须换算每摩尔。","en":"2.94 kJ is the heat for 0.0500 mol; it must be converted to a per-mole value."},"id":"a"},{"text":{"zh":"−58.8 kJ mol⁻¹","cn":"−58.8 kJ mol⁻¹","en":"−58.8 kJ mol⁻¹"},"correct":true,"feedback":{"zh":"q=100×4.2×7=2940 J；反應放熱，ΔH=−2.940÷0.0500=−58.8 kJ mol⁻¹。","cn":"q=100×4.2×7=2940 J；反应放热，ΔH=−2.940÷0.0500=−58.8 kJ mol⁻¹。","en":"q=2940 J; the reaction releases heat, so ΔH=−2.940/0.0500=−58.8 kJ mol⁻¹."},"id":"b"},{"text":{"zh":"+58.8 kJ mol⁻¹","cn":"+58.8 kJ mol⁻¹","en":"+58.8 kJ mol⁻¹"},"correct":false,"feedback":{"zh":"數值大小正確，但升溫表示反應向溶液放熱，反應焓應為負。","cn":"数值大小正确，但升温表示反应向溶液放热，反应焓应为负。","en":"The magnitude is right, but warming means the reaction releases heat, giving a negative enthalpy change."},"id":"c"}],"takeaway":{"zh":"分清溶液吸收的熱量與反應焓符號，並換算每摩爾。","cn":"分清溶液吸收的热量与反应焓符号，并换算每摩尔。","en":"Distinguish solution heat gain from reaction enthalpy sign and convert to a molar quantity."}},{"id":"s5-chemistry-03","grade":5,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"化學：速率與總產量","cn":"化学：速率与总产量","en":"Chemistry: rate versus total yield"},"question":{"zh":"兩次反應的反應物用量、溫度相同。加催化劑後氣體體積曲線起初更陡，但最後平臺相同。最合理解釋是甚麼？","cn":"两次反应的反应物用量、温度相同。加催化剂后气体体积曲线起初更陡，但最后平台相同。最合理解释是甚么？","en":"Two reactions use the same amounts and temperature. With a catalyst, the gas-volume curve is initially steeper but reaches the same final plateau. Which explanation fits best?"},"options":[{"text":{"zh":"催化劑增加反應物的物質的量，因此平臺相同。","cn":"催化剂增加反应物的物质的量，因此平台相同。","en":"The catalyst increases the amount of reactant, causing the same plateau."},"correct":false,"feedback":{"zh":"用量相同且平臺相同，沒有反應物增多的證據。","cn":"用量相同且平台相同，没有反应物增多的证据。","en":"The stated amounts and identical plateau do not support extra reactant."},"id":"a"},{"text":{"zh":"曲線較陡證明平衡產量必定增加一倍。","cn":"曲线较陡证明平衡产量必定增加一倍。","en":"The steeper curve proves the equilibrium yield has doubled."},"correct":false,"feedback":{"zh":"起始斜率不能代替終點產量；相同平臺更直接否定加倍。","cn":"起始斜率不能代替终点产量；相同平台更直接否定加倍。","en":"Initial slope is not final yield; the equal plateau contradicts a doubling."},"id":"b"},{"text":{"zh":"催化劑增加反應速率，但沒有改變此反應的最終氣體產量。","cn":"催化剂增加反应速率，但没有改变此反应的最终气体产量。","en":"The catalyst increases the rate but does not change this reaction's final gas yield."},"correct":true,"feedback":{"zh":"斜率表示速率，平臺表示總氣量，兩者要分開解讀。","cn":"斜率表示速率，平台表示总气量，两者要分开解读。","en":"Slope represents rate; the plateau represents total gas volume."},"id":"c"}],"takeaway":{"zh":"曲線不同部分代表不同量；速率改善不等於總產量提高。","cn":"曲线不同部分代表不同量；速率改善不等于总产量提高。","en":"Different graph features represent different quantities; faster reaction does not mean greater total yield."}},{"id":"s6-chemistry-01","grade":6,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"化學：有機反應條件","cn":"化学：有机反应条件","en":"Chemistry: conditions in organic reactions"},"question":{"zh":"在課堂理論分析中，乙醇與過量酸化重鉻酸鉀在迴流條件下充分反應，主要有機產物是甚麼？","cn":"在课堂理论分析中，乙醇与过量酸化重铬酸钾在回流条件下充分反应，主要有机产物是甚么？","en":"In a theoretical classroom analysis, ethanol reacts thoroughly with excess acidified potassium dichromate under reflux. What is the main organic product?"},"options":[{"text":{"zh":"只會得到乙醛，不能繼續氧化。","cn":"只会得到乙醛，不能继续氧化。","en":"Only ethanal, which cannot be oxidised further."},"correct":false,"feedback":{"zh":"乙醛可進一步氧化；蒸餾收集與過量氧化劑迴流的條件不同。","cn":"乙醛可进一步氧化；蒸馏收集与过量氧化剂回流的条件不同。","en":"Ethanal can oxidise further; distilling it off differs from refluxing with excess oxidant."},"id":"a"},{"text":{"zh":"乙酸。","cn":"乙酸。","en":"Ethanoic acid."},"correct":true,"feedback":{"zh":"過量氧化劑和迴流使第一級醇進一步氧化至羧酸。","cn":"过量氧化剂和回流使第一级醇进一步氧化至羧酸。","en":"Excess oxidant and reflux allow a primary alcohol to oxidise further to a carboxylic acid."},"id":"b"},{"text":{"zh":"乙烯。","cn":"乙烯。","en":"Ethene."},"correct":false,"feedback":{"zh":"乙烯涉及脫水；題目提供的是氧化條件。","cn":"乙烯涉及脱水；题目提供的是氧化条件。","en":"Ethene formation involves dehydration; the stated conditions are oxidising."},"id":"c"}],"takeaway":{"zh":"有機產物取決於試劑、用量和反應條件，不只取決於起始物。","cn":"有机产物取决于试剂、用量和反应条件，不只取决于起始物。","en":"Organic products depend on reagents, amounts and conditions as well as starting material."}},{"id":"s6-chemistry-02","grade":6,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"化學：平衡與工業取捨","cn":"化学：平衡与工业取舍","en":"Chemistry: equilibrium and industrial compromise"},"question":{"zh":"N₂(g)+3H₂(g) ⇌ 2NH₃(g)，正反應放熱。降低溫度有利平衡產率，但工業不採極低溫，主要原因是甚麼？","cn":"N₂(g)+3H₂(g) ⇌ 2NH₃(g)，正反应放热。降低温度有利平衡产率，但工业不采极低温，主要原因是甚么？","en":"N₂(g)+3H₂(g) ⇌ 2NH₃(g) is exothermic forward. Lower temperature favours equilibrium yield. Why is an extremely low temperature not used industrially?"},"options":[{"text":{"zh":"降低溫度會使放熱反應的平衡完全向左。","cn":"降低温度会使放热反应的平衡完全向左。","en":"Lowering temperature shifts this exothermic equilibrium entirely to the left."},"correct":false,"feedback":{"zh":"降溫有利放熱方向，不能用錯誤的平衡方向解釋工業選擇。","cn":"降温有利放热方向，不能用错误的平衡方向解释工业选择。","en":"Lowering temperature favours the exothermic direction; this explanation reverses it."},"id":"a"},{"text":{"zh":"催化劑能使任意低溫下的平衡產率必定達到 100%。","cn":"催化剂能使任意低温下的平衡产率必定达到 100%。","en":"A catalyst guarantees 100% equilibrium yield at any low temperature."},"correct":false,"feedback":{"zh":"催化劑改變速率，不改變同溫下的平衡常數。","cn":"催化剂改变速率，不改变同温下的平衡常数。","en":"A catalyst changes rates, not the equilibrium constant at a given temperature."},"id":"b"},{"text":{"zh":"低溫使反應過慢，需在產率、速率及成本之間折衷。","cn":"低温使反应过慢，需在产率、速率及成本之间折衷。","en":"A very low temperature makes the reaction too slow, requiring a compromise among yield, rate and cost."},"correct":true,"feedback":{"zh":"平衡位置與達到平衡的速率是不同考慮。","cn":"平衡位置与达到平衡的速率是不同考虑。","en":"Equilibrium position and the rate of reaching it are different considerations."},"id":"c"}],"takeaway":{"zh":"工業條件需要同時考慮熱力學、動力學與資源。","cn":"工业条件需要同时考虑热力学、动力学与资源。","en":"Industrial conditions balance thermodynamic, kinetic and resource considerations."}},{"id":"s6-chemistry-03","grade":6,"subjectId":"chemistry","roomId":"chemistry","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"化學：滴定數據與異常值","cn":"化学：滴定数据与异常值","en":"Chemistry: titration data and anomalous values"},"question":{"zh":"25.00 cm³ NaOH 以 0.1000 mol dm⁻³ HCl 滴定，三次體積為 24.80、24.85、26.10 cm³；第三次註明越過終點。按前兩次相近讀數計，NaOH 濃度約多少？","cn":"25.00 cm³ NaOH 以 0.1000 mol dm⁻³ HCl 滴定，三次体积为 24.80、24.85、26.10 cm³；第三次注明越过终点。按前两次相近读数计，NaOH 浓度约多少？","en":"25.00 cm³ NaOH is titrated with 0.1000 mol dm⁻³ HCl. Titres are 24.80, 24.85 and 26.10 cm³; the third is recorded as overshooting. Using the first two concordant readings, what is the NaOH concentration?"},"options":[{"text":{"zh":"0.0993 mol dm⁻³","cn":"0.0993 mol dm⁻³","en":"0.0993 mol dm⁻³"},"correct":true,"feedback":{"zh":"平均 24.825 cm³；HCl:NaOH 為 1:1，濃度=0.1000×24.825÷25.00≈0.0993。","cn":"平均 24.825 cm³；HCl:NaOH 为 1:1，浓度=0.1000×24.825÷25.00≈0.0993。","en":"The mean is 24.825 cm³; the 1:1 ratio gives 0.1000×24.825/25.00≈0.0993."},"id":"a"},{"text":{"zh":"0.1010 mol dm⁻³","cn":"0.1010 mol dm⁻³","en":"0.1010 mol dm⁻³"},"correct":false,"feedback":{"zh":"這接近把已記錄越過終點的讀數也平均；忽略了明確實驗證據。","cn":"这接近把已记录越过终点的读数也平均；忽略了明确实验证据。","en":"This approximately averages in the known overshoot, ignoring the recorded experimental evidence."},"id":"b"},{"text":{"zh":"0.0497 mol dm⁻³","cn":"0.0497 mol dm⁻³","en":"0.0497 mol dm⁻³"},"correct":false,"feedback":{"zh":"HCl 與 NaOH 的反應比是 1:1，沒有除以二的理由。","cn":"HCl 与 NaOH 的反应比是 1:1，没有除以二的理由。","en":"HCl and NaOH react 1:1; there is no factor of two."},"id":"c"}],"takeaway":{"zh":"以實驗記錄及相近讀數判斷數據品質，不應只因結果不合預期而刪數據。","cn":"以实验记录及相近读数判断数据品质，不应只因结果不合预期而删数据。","en":"Judge data using procedure notes and concordance, not merely whether a result matches expectations."}},{"id":"s1-geography-01","grade":1,"subjectId":"geography","roomId":"geography","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"地圖比例尺與距離","cn":"地图比例尺与距离","en":"Map scale and distance"},"question":{"zh":"一幅比例尺 1:25,000 的地圖上，兩點直線距離為 4 cm。實際直線距離是多少？","cn":"一幅比例尺 1:25,000 的地图上，两点直线距离为 4 cm。实际直线距离是多少？","en":"Two points are 4 cm apart on a 1:25,000 map. What is their straight-line ground distance?"},"options":[{"text":{"zh":"1 km","cn":"1 km","en":"1 km"},"correct":true,"feedback":{"zh":"4×25,000=100,000 cm，即 1,000 m 或 1 km。","cn":"4×25,000=100,000 cm，即 1,000 m 或 1 km。","en":"4×25,000=100,000 cm, which is 1,000 m or 1 km."},"id":"a"},{"text":{"zh":"100 km","cn":"100 km","en":"100 km"},"correct":false,"feedback":{"zh":"須把釐米正確換算成公里；100,000 cm 不是 100 km。","cn":"须把厘米正确换算成公里；100,000 cm 不是 100 km。","en":"Convert centimetres correctly: 100,000 cm is not 100 km."},"id":"b"},{"text":{"zh":"0.1 km","cn":"0.1 km","en":"0.1 km"},"correct":false,"feedback":{"zh":"0.1 km 是 10,000 cm，少了一個十倍。","cn":"0.1 km 是 10,000 cm，少了一个十倍。","en":"0.1 km is 10,000 cm, a factor of ten too small."},"id":"c"}],"takeaway":{"zh":"比例尺計算先用相同單位，再換成適合表達的地面距離。","cn":"比例尺计算先用相同单位，再换成适合表达的地面距离。","en":"Use matching units for scale calculations, then convert to a useful ground-distance unit."}},{"id":"s1-geography-02","grade":1,"subjectId":"geography","roomId":"geography","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"等高線與坡度","cn":"等高线与坡度","en":"Contours and gradient"},"question":{"zh":"同一幅地圖上，甲路與乙路都由 100 m 上升到 200 m。甲路的等高線較密，乙路較疏。哪項判斷最合理？","cn":"同一幅地图上，甲路与乙路都由 100 m 上升到 200 m。甲路的等高线较密，乙路较疏。哪项判断最合理？","en":"On the same map, routes A and B both rise from 100 m to 200 m. Contours are closer together along A. Which judgement is most reasonable?"},"options":[{"text":{"zh":"甲路終點一定比乙路高。","cn":"甲路终点一定比乙路高。","en":"A must end higher than B."},"correct":false,"feedback":{"zh":"題目已說兩條路的終點均為 200 m。","cn":"题目已说两条路的终点均为 200 m。","en":"Both endpoints are explicitly at 200 m."},"id":"a"},{"text":{"zh":"甲路平均較陡；兩路的總垂直上升相同。","cn":"甲路平均较陡；两路的总垂直上升相同。","en":"A is generally steeper; both have the same total vertical rise."},"correct":true,"feedback":{"zh":"相同高差在較短水平距離內出現，代表較大坡度。","cn":"相同高差在较短水平距离内出现，代表较大坡度。","en":"The same rise over a shorter horizontal distance gives a steeper gradient."},"id":"b"},{"text":{"zh":"乙路較陡，因為等高線較少擠在一起。","cn":"乙路较陡，因为等高线较少挤在一起。","en":"B is steeper because its contours are farther apart."},"correct":false,"feedback":{"zh":"等高線疏代表同一高差分佈在較長水平距離。","cn":"等高线疏代表同一高差分布在较长水平距离。","en":"Widely spaced contours spread the same rise over a longer horizontal distance."},"id":"c"}],"takeaway":{"zh":"把高差與水平距離一併解讀，不能只數線條。","cn":"把高差与水平距离一并解读，不能只数线条。","en":"Interpret vertical rise together with horizontal distance, not just the number of lines."}},{"id":"s1-geography-03","grade":1,"subjectId":"geography","roomId":"geography","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"校園實地考察的取樣","cn":"校园实地考察的取样","en":"Sampling in a campus field study"},"question":{"zh":"學生想比較全校不同地方的垃圾量，卻只在垃圾桶旁數垃圾。哪個改良最能提高代表性？","cn":"学生想比较全校不同地方的垃圾量，却只在垃圾桶旁数垃圾。哪个改良最能提高代表性？","en":"Students want to compare litter across the campus but count only beside bins. Which change most improves representativeness?"},"options":[{"text":{"zh":"只在最多垃圾的桶旁重複十次。","cn":"只在最多垃圾的桶旁重复十次。","en":"Repeat ten counts only at the dirtiest bin."},"correct":false,"feedback":{"zh":"重複可增加該點資料，仍不能代表其他區域。","cn":"重复可增加该点资料，仍不能代表其他区域。","en":"Repetition adds information about that site but not the other areas."},"id":"a"},{"text":{"zh":"改用較漂亮的地圖展示原有數字。","cn":"改用较漂亮的地图展示原有数字。","en":"Display the same counts on a more attractive map."},"correct":false,"feedback":{"zh":"展示品質不能修正取樣範圍的偏差。","cn":"展示品质不能修正取样范围的偏差。","en":"Presentation quality cannot correct biased sampling coverage."},"id":"b"},{"text":{"zh":"先把校園分成不同區域，在各區按一致方法選點及計數。","cn":"先把校园分成不同区域，在各区按一致方法选点及计数。","en":"Divide the campus into areas and choose/count sites consistently within each area."},"correct":true,"feedback":{"zh":"涵蓋不同環境可減少只選特殊位置造成的偏差。","cn":"涵盖不同环境可减少只选特殊位置造成的偏差。","en":"Covering different environments reduces bias from selecting one special type of location."},"id":"c"}],"takeaway":{"zh":"實地考察需把研究範圍、取樣位置和一致程序連結。","cn":"实地考察需把研究范围、取样位置和一致程序连结。","en":"Connect the study area, sampling locations and consistent procedures in fieldwork."}},{"id":"s2-geography-01","grade":2,"subjectId":"geography","roomId":"geography","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"河曲的侵蝕與沉積","cn":"河曲的侵蚀与沉积","en":"Erosion and deposition in a meander"},"question":{"zh":"河曲外岸水流較快，內岸較慢。若其他條件相近，最可能出現哪個配對？","cn":"河曲外岸水流较快，内岸较慢。若其他条件相近，最可能出现哪个配对？","en":"Water flows faster at a meander's outer bank and slower at its inner bank. Under otherwise similar conditions, which pairing is most likely?"},"options":[{"text":{"zh":"兩岸永遠沒有變化。","cn":"两岸永远没有变化。","en":"Neither bank ever changes."},"correct":false,"feedback":{"zh":"流水會侵蝕、搬運和沉積，河岸並非固定不變。","cn":"流水会侵蚀、搬运和沉积，河岸并非固定不变。","en":"Flowing water erodes, transports and deposits material, so banks are not permanently fixed."},"id":"a"},{"text":{"zh":"外岸侵蝕較強，內岸較易沉積。","cn":"外岸侵蚀较强，内岸较易沉积。","en":"Stronger erosion at the outer bank; more deposition at the inner bank."},"correct":true,"feedback":{"zh":"較快水流有較大侵蝕能力；減速時較易沉積所搬運物。","cn":"较快水流有较大侵蚀能力；减速时较易沉积所搬运物。","en":"Faster flow has greater erosive capacity; slowing flow more readily deposits transported material."},"id":"b"},{"text":{"zh":"外岸只沉積，內岸只侵蝕。","cn":"外岸只沉积，内岸只侵蚀。","en":"Deposition only at the outer bank; erosion only at the inner bank."},"correct":false,"feedback":{"zh":"這倒轉了題目水流速度所支持的主要過程。","cn":"这倒转了题目水流速度所支持的主要过程。","en":"This reverses the main processes supported by the stated flow speeds."},"id":"c"}],"takeaway":{"zh":"把水流能量與侵蝕、搬運、沉積過程連結。","cn":"把水流能量与侵蚀、搬运、沉积过程连结。","en":"Link flow energy to erosion, transport and deposition."}},{"id":"s2-geography-02","grade":2,"subjectId":"geography","roomId":"geography","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"都市地表與地表徑流","cn":"都市地表与地表径流","en":"Urban surfaces and runoff"},"question":{"zh":"同一場雨中，面積相同的草地有 30% 雨水成為地表徑流，鋪面地有 80%。兩地各收到 1,000 L 雨水。鋪面地多產生多少徑流？","cn":"同一场雨中，面积相同的草地有 30% 雨水成为地表径流，铺面地有 80%。两地各收到 1,000 L 雨水。铺面地多产生多少径流？","en":"During the same storm, 30% of rain becomes runoff on grass and 80% on paving. Equal areas each receive 1,000 L. How much more runoff comes from the paved area?"},"options":[{"text":{"zh":"50 L","cn":"50 L","en":"50 L"},"correct":false,"feedback":{"zh":"差異是 50 個百分點，要乘以 1,000 L，不是直接當作 50 L。","cn":"差异是 50 个百分点，要乘以 1,000 L，不是直接当作 50 L。","en":"The difference is 50 percentage points of 1,000 L, not 50 L."},"id":"a"},{"text":{"zh":"1,100 L","cn":"1,100 L","en":"1,100 L"},"correct":false,"feedback":{"zh":"1,100 L 是兩者總徑流，題目問差額。","cn":"1,100 L 是两者总径流，题目问差额。","en":"1,100 L is their combined runoff; the question asks for the difference."},"id":"b"},{"text":{"zh":"500 L","cn":"500 L","en":"500 L"},"correct":true,"feedback":{"zh":"800−300=500 L；較少滲透令更多雨水流向排水系統。","cn":"800−300=500 L；较少渗透令更多雨水流向排水系统。","en":"800−300=500 L; less infiltration sends more water to drainage."},"id":"c"}],"takeaway":{"zh":"用雨量、土地覆蓋與滲透解釋徑流，分清差額和總量。","cn":"用雨量、土地覆盖与渗透解释径流，分清差额和总量。","en":"Explain runoff through rainfall, land cover and infiltration; distinguish difference from total."}},{"id":"s2-geography-03","grade":2,"subjectId":"geography","roomId":"geography","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"迎風坡與背風坡","cn":"迎风坡与背风坡","en":"Windward and leeward slopes"},"question":{"zh":"潮濕氣流吹向山脈，迎風坡降雨較多，背風坡較乾。哪個過程鏈最合理？","cn":"潮湿气流吹向山脉，迎风坡降雨较多，背风坡较干。哪个过程链最合理？","en":"Moist air approaches a mountain range. The windward slope is wetter and the leeward slope drier. Which sequence best explains this?"},"options":[{"text":{"zh":"氣流上升冷卻凝結降雨；越山後下沉增暖，相對濕度下降。","cn":"气流上升冷却凝结降雨；越山后下沉增暖，相对湿度下降。","en":"Air rises, cools and condenses; after crossing, it descends and warms, reducing relative humidity."},"correct":true,"feedback":{"zh":"上升冷卻與下沉增暖可解釋兩坡差異。","cn":"上升冷却与下沉增暖可解释两坡差异。","en":"Cooling during ascent and warming during descent explain the contrast."},"id":"a"},{"text":{"zh":"氣流上升時愈來愈熱，所以水汽直接變成雨。","cn":"气流上升时愈来愈热，所以水汽直接变成雨。","en":"Rising air becomes hotter, so vapour directly turns to rain."},"correct":false,"feedback":{"zh":"此機制通常涉及上升冷卻至凝結，並非升溫造成凝結。","cn":"此机制通常涉及上升冷却至凝结，并非升温造成凝结。","en":"This mechanism involves cooling to condensation, not heating causing condensation."},"id":"b"},{"text":{"zh":"山脈吸走所有氧氣，所以背風坡乾燥。","cn":"山脉吸走所有氧气，所以背风坡干燥。","en":"Mountains remove all oxygen, making the leeward slope dry."},"correct":false,"feedback":{"zh":"氧氣被吸走並不是地形雨的成因。","cn":"氧气被吸走并不是地形雨的成因。","en":"Oxygen removal is not the mechanism of orographic rainfall."},"id":"c"}],"takeaway":{"zh":"用連貫的物理過程解釋空間差異，而不只背誦兩坡名稱。","cn":"用连贯的物理过程解释空间差异，而不只背诵两坡名称。","en":"Explain spatial differences through a connected physical process, not only slope labels."}},{"id":"s3-geography-01","grade":3,"subjectId":"geography","roomId":"geography","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"板塊邊界與自然災害","cn":"板块边界与自然灾害","en":"Plate boundaries and natural hazards"},"question":{"zh":"海洋板塊向大陸板塊移動並隱沒。哪組現象最符合這種邊界？","cn":"海洋板块向大陆板块移动并隐没。哪组现象最符合这种边界？","en":"An oceanic plate converges with and subducts beneath a continental plate. Which set of features best fits this boundary?"},"options":[{"text":{"zh":"兩板塊遠離，中央形成洋中脊。","cn":"两板块远离，中央形成洋中脊。","en":"The plates separate and form a mid-ocean ridge."},"correct":false,"feedback":{"zh":"洋中脊對應張裂邊界，與題目的聚合隱沒不同。","cn":"洋中脊对应张裂边界，与题目的聚合隐没不同。","en":"A mid-ocean ridge fits divergence, not the stated convergent subduction."},"id":"a"},{"text":{"zh":"只有水平錯動的地震，完全沒有隱沒。","cn":"只有水平错动的地震，完全没有隐没。","en":"Only earthquakes from horizontal sliding, with no subduction."},"correct":false,"feedback":{"zh":"這描述轉形邊界的主要移動方式，與題目明確的隱沒不同。","cn":"这描述转形边界的主要移动方式，与题目明确的隐没不同。","en":"This describes mainly transform motion, unlike the subduction explicitly stated."},"id":"b"},{"text":{"zh":"海溝、地震和火山活動。","cn":"海沟、地震和火山活动。","en":"A trench, earthquakes and volcanic activity."},"correct":true,"feedback":{"zh":"隱沒形成海溝及地震帶，相關巖漿活動可形成火山。","cn":"隐没形成海沟及地震带，相关岩浆活动可形成火山。","en":"Subduction produces a trench and earthquake zone; associated magma can feed volcanoes."},"id":"c"}],"takeaway":{"zh":"由板塊移動方式推斷地形與災害，避免混淆邊界類型。","cn":"由板块移动方式推断地形与灾害，避免混淆边界类型。","en":"Infer landforms and hazards from plate motion without mixing boundary types."}},{"id":"s3-geography-02","grade":3,"subjectId":"geography","roomId":"geography","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"人口總量與密度","cn":"人口总量与密度","en":"Population totals and density"},"question":{"zh":"甲區人口 150,000、面積 30 km²；乙區人口 80,000、面積 10 km²。哪項比較正確？","cn":"甲区人口 150,000、面积 30 km²；乙区人口 80,000、面积 10 km²。哪项比较正确？","en":"Area A has 150,000 people in 30 km²; B has 80,000 in 10 km². Which comparison is correct?"},"options":[{"text":{"zh":"乙區人口較少，但密度較高：8,000 對 5,000 人/km²。","cn":"乙区人口较少，但密度较高：8,000 对 5,000 人/km²。","en":"B has fewer people but higher density: 8,000 versus 5,000 people/km²."},"correct":true,"feedback":{"zh":"密度等於人口除以面積，總人口較多不等於密度較高。","cn":"密度等于人口除以面积，总人口较多不等于密度较高。","en":"Density is population divided by area; a larger total need not mean higher density."},"id":"a"},{"text":{"zh":"甲區密度較高，因為總人口較多。","cn":"甲区密度较高，因为总人口较多。","en":"A is denser because it has more people."},"correct":false,"feedback":{"zh":"這忽略了甲區面積也是乙區三倍。","cn":"这忽略了甲区面积也是乙区三倍。","en":"This ignores that A has three times B's area."},"id":"b"},{"text":{"zh":"兩區密度相同，因為都是市區。","cn":"两区密度相同，因为都是市区。","en":"Both have equal density because both are urban."},"correct":false,"feedback":{"zh":"地區名稱不能取代人口與面積的計算。","cn":"地区名称不能取代人口与面积的计算。","en":"An urban label cannot replace the population-to-area calculation."},"id":"c"}],"takeaway":{"zh":"空間比較需要選擇合適分母，總量和密度回答不同問題。","cn":"空间比较需要选择合适分母，总量和密度回答不同问题。","en":"Spatial comparisons need an appropriate denominator; totals and densities answer different questions."}},{"id":"s3-geography-03","grade":3,"subjectId":"geography","roomId":"geography","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"都市熱島的考察設計","cn":"都市热岛的考察设计","en":"Designing an urban heat-island study"},"question":{"zh":"學生中午在市中心量得 34°C，傍晚在郊區量得 28°C，便把 6°C 全歸因於都市熱島。主要改良是甚麼？","cn":"学生中午在市中心量得 34°C，傍晚在郊区量得 28°C，便把 6°C 全归因于都市热岛。主要改良是甚么？","en":"Students record 34°C downtown at noon and 28°C in the countryside at dusk, attributing all 6°C to an urban heat island. What is the main improvement?"},"options":[{"text":{"zh":"只保留 34°C，因為市中心讀數較高。","cn":"只保留 34°C，因为市中心读数较高。","en":"Keep only 34°C because it is the higher urban reading."},"correct":false,"feedback":{"zh":"沒有比較點便更不能判斷都市熱島差異。","cn":"没有比较点便更不能判断都市热岛差异。","en":"Removing the comparison makes the urban–rural difference harder to assess."},"id":"a"},{"text":{"zh":"在相近高度和遮蔭條件下同步量度多個市區及郊區地點，並重複。","cn":"在相近高度和遮荫条件下同步量度多个市区及郊区地点，并重复。","en":"Measure several urban and rural sites simultaneously under comparable height/shade conditions, and repeat."},"correct":true,"feedback":{"zh":"時間與量度環境會影響氣溫，須控制纔可比較土地利用。","cn":"时间与量度环境会影响气温，须控制才可比较土地利用。","en":"Time and measurement conditions affect temperature and must be controlled to compare land use."},"id":"b"},{"text":{"zh":"只把兩個讀數四捨五入成整十數。","cn":"只把两个读数四舍五入成整十数。","en":"Round both temperatures to the nearest ten."},"correct":false,"feedback":{"zh":"取整數沒有消除中午與傍晚的時間差異。","cn":"取整数没有消除中午与傍晚的时间差异。","en":"Rounding does not remove the noon-versus-dusk confound."},"id":"c"}],"takeaway":{"zh":"比較地理因素時，要控制時間、位置和儀器條件。","cn":"比较地理因素时，要控制时间、位置和仪器条件。","en":"Control time, location conditions and instruments when comparing geographical factors."}},{"id":"s4-geography-01","grade":4,"subjectId":"geography","roomId":"geography","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"沿岸漂移與海岸管理","cn":"沿岸漂移与海岸管理","en":"Longshore drift and coastal management"},"question":{"zh":"沿岸漂移把沙由西向東搬運。新丁壩在西側累積沙，東側海灘變窄。最合理解釋是甚麼？","cn":"沿岸漂移把沙由西向东搬运。新丁坝在西侧累积沙，东侧海滩变窄。最合理解释是甚么？","en":"Longshore drift transports sand west to east. A new groyne traps sand on its west side while the beach to the east narrows. What best explains this?"},"options":[{"text":{"zh":"丁壩攔截沉積物，令下游方向的沙供應減少。","cn":"丁坝拦截沉积物，令下游方向的沙供应减少。","en":"The groyne intercepts sediment, reducing supply in the downdrift direction."},"correct":true,"feedback":{"zh":"海岸管理會改變沉積物收支，保護一處可能影響鄰近海岸。","cn":"海岸管理会改变沉积物收支，保护一处可能影响邻近海岸。","en":"Coastal structures alter sediment budgets; protecting one site can affect neighbouring coasts."},"id":"a"},{"text":{"zh":"丁壩增加東側的沙供應，但沙越多海灘越窄。","cn":"丁坝增加东侧的沙供应，但沙越多海滩越窄。","en":"The groyne increases sand supply to the east, and extra sand narrows the beach."},"correct":false,"feedback":{"zh":"題目西側堆沙符合攔截供應；東側變窄不能用額外沉積解釋。","cn":"题目西侧堆沙符合拦截供应；东侧变窄不能用额外沉积解释。","en":"West-side accumulation indicates interception; extra deposition would not explain eastern narrowing."},"id":"b"},{"text":{"zh":"東側海灘變窄證明沿岸漂移已完全消失。","cn":"东侧海滩变窄证明沿岸漂移已完全消失。","en":"The narrowing eastern beach proves longshore drift has stopped everywhere."},"correct":false,"feedback":{"zh":"攔截部分沙供應不等於所有沿岸搬運停止。","cn":"拦截部分沙供应不等于所有沿岸搬运停止。","en":"Intercepting sediment does not mean all longshore transport has ceased."},"id":"c"}],"takeaway":{"zh":"評估海岸工程須考慮沉積物系統與鄰近地區的影響。","cn":"评估海岸工程须考虑沉积物系统与邻近地区的影响。","en":"Evaluate coastal engineering within the sediment system and its effects on neighbouring areas."}},{"id":"s4-geography-02","grade":4,"subjectId":"geography","roomId":"geography","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"河流流量估算","cn":"河流流量估算","en":"Estimating river discharge"},"question":{"zh":"考察中把河道橫截面近似為寬 4 m、平均深 0.5 m 的長方形，平均流速 2 m/s。按此簡化模型，流量是多少？","cn":"考察中把河道横截面近似为宽 4 m、平均深 0.5 m 的长方形，平均流速 2 m/s。按此简化模型，流量是多少？","en":"A field study approximates a river cross-section as 4 m wide and 0.5 m deep on average. Mean velocity is 2 m/s. Under this simplified model, what is discharge?"},"options":[{"text":{"zh":"1 m³/s","cn":"1 m³/s","en":"1 m³/s"},"correct":false,"feedback":{"zh":"流量應乘以流速，不能把面積除以流速。","cn":"流量应乘以流速，不能把面积除以流速。","en":"Discharge multiplies area by velocity; it does not divide area by velocity."},"id":"a"},{"text":{"zh":"4 m³/s","cn":"4 m³/s","en":"4 m³/s"},"correct":true,"feedback":{"zh":"橫截面積 4×0.5=2 m²；流量=面積×流速=4 m³/s。","cn":"横截面积 4×0.5=2 m²；流量=面积×流速=4 m³/s。","en":"Cross-sectional area is 2 m²; discharge is area×velocity=4 m³/s."},"id":"b"},{"text":{"zh":"8 m/s","cn":"8 m/s","en":"8 m/s"},"correct":false,"feedback":{"zh":"這忽略深度，而且 m/s 是速度單位，不是流量。","cn":"这忽略深度，而且 m/s 是速度单位，不是流量。","en":"This ignores depth and uses a velocity unit rather than volume per time."},"id":"c"}],"takeaway":{"zh":"將流量連結到截面積和平均流速，並檢查模型假設與單位。","cn":"将流量连结到截面积和平均流速，并检查模型假设与单位。","en":"Relate discharge to cross-sectional area and mean velocity; check assumptions and units."}},{"id":"s4-geography-03","grade":4,"subjectId":"geography","roomId":"geography","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"災害強度與災害風險","cn":"灾害强度与灾害风险","en":"Hazard intensity and disaster risk"},"question":{"zh":"兩城面對相近地震強度，甲城損失較低，且建築抗震、疏散演練較完善。哪項評估最恰當？","cn":"两城面对相近地震强度，甲城损失较低，且建筑抗震、疏散演练较完善。哪项评估最恰当？","en":"Two cities experience similar earthquake intensity. A has lower losses and stronger buildings and evacuation preparation. Which assessment is most appropriate?"},"options":[{"text":{"zh":"甲城損失少，證明沒有真正發生地震。","cn":"甲城损失少，证明没有真正发生地震。","en":"Lower losses prove A did not experience an earthquake."},"correct":false,"feedback":{"zh":"相近強度是已知條件；損失少不等於沒有災害事件。","cn":"相近强度是已知条件；损失少不等于没有灾害事件。","en":"Similar intensity is given; lower losses do not mean no hazard occurred."},"id":"a"},{"text":{"zh":"單憑兩城比較可證明演練是唯一原因。","cn":"单凭两城比较可证明演练是唯一原因。","en":"The two-city comparison proves drills are the sole cause."},"correct":false,"feedback":{"zh":"建築、暴露等因素也可能不同，不能只歸因於演練。","cn":"建筑、暴露等因素也可能不同，不能只归因于演练。","en":"Buildings, exposure and other factors may also differ; drills cannot be isolated as the sole cause."},"id":"b"},{"text":{"zh":"損失差異可能與脆弱度和應對能力有關，不能只看地震強度。","cn":"损失差异可能与脆弱度和应对能力有关，不能只看地震强度。","en":"Losses may differ because of vulnerability and response capacity, not hazard intensity alone."},"correct":true,"feedback":{"zh":"風險涉及暴露、脆弱度及能力；還需比較人口與資產等背景。","cn":"风险涉及暴露、脆弱度及能力；还需比较人口与资产等背景。","en":"Risk also involves exposure, vulnerability and capacity; population and assets still need comparison."},"id":"c"}],"takeaway":{"zh":"災害分析需區分自然事件、暴露、脆弱度和應對能力。","cn":"灾害分析需区分自然事件、暴露、脆弱度和应对能力。","en":"Distinguish the physical hazard, exposure, vulnerability and capacity in disaster analysis."}},{"id":"s5-geography-01","grade":5,"subjectId":"geography","roomId":"geography","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"工業區位的多重因素","cn":"工业区位的多重因素","en":"Multiple factors in industrial location"},"question":{"zh":"高科技企業選擇工資較高但鄰近大學、研發機構和專業供應商的城市。哪項解釋最合理？","cn":"高科技企业选择工资较高但邻近大学、研发机构和专业供应商的城市。哪项解释最合理？","en":"A high-tech firm chooses a higher-wage city near universities, research institutes and specialist suppliers. Which explanation is most reasonable?"},"options":[{"text":{"zh":"鄰近供應商會自動令所有運輸成本變成零。","cn":"邻近供应商会自动令所有运输成本变成零。","en":"Nearby suppliers automatically reduce every transport cost to zero."},"correct":false,"feedback":{"zh":"鄰近可減少部分成本，但不代表所有原料和產品都無需運輸。","cn":"邻近可减少部分成本，但不代表所有原料和产品都无需运输。","en":"Proximity may reduce some costs but does not eliminate every transport requirement."},"id":"a"},{"text":{"zh":"人才、知識交流和產業聯繫的利益可能超過較高工資成本。","cn":"人才、知识交流和产业联系的利益可能超过较高工资成本。","en":"Skilled labour, knowledge exchange and production links may outweigh higher wage costs."},"correct":true,"feedback":{"zh":"區位選擇取決於企業需求及多種成本效益，不只是最低工資。","cn":"区位选择取决于企业需求及多种成本效益，不只是最低工资。","en":"Location depends on the firm's needs and multiple costs and benefits, not wages alone."},"id":"b"},{"text":{"zh":"工資越高必定代表每件產品的總成本越低。","cn":"工资越高必定代表每件产品的总成本越低。","en":"Higher wages always mean a lower total cost per product."},"correct":false,"feedback":{"zh":"生產力可能抵銷工資，但不能只憑工資高低保證總成本。","cn":"生产力可能抵销工资，但不能只凭工资高低保证总成本。","en":"Productivity may offset wages, but wage level alone cannot guarantee total unit cost."},"id":"c"}],"takeaway":{"zh":"工業區位是多因素的權衡，因素的重要性隨產業改變。","cn":"工业区位是多因素的权衡，因素的重要性随产业改变。","en":"Industrial location is a multi-factor trade-off whose priorities vary by industry."}},{"id":"s5-geography-02","grade":5,"subjectId":"geography","roomId":"geography","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"糧食產量與取得糧食的能力","cn":"粮食产量与取得粮食的能力","en":"Food supply and access"},"question":{"zh":"某地區全年糧食總量足夠，但洪水阻斷道路、價格急升，低收入家庭挨餓。哪項措施最直接處理題目的成因？","cn":"某地区全年粮食总量足够，但洪水阻断道路、价格急升，低收入家庭挨饿。哪项措施最直接处理题目的成因？","en":"A region has enough food overall, but floods block roads, prices rise and low-income households go hungry. Which measure most directly addresses the stated causes?"},"options":[{"text":{"zh":"只公佈全區總產量，便可確保人人喫飽。","cn":"只公布全区总产量，便可确保人人吃饱。","en":"Publish regional production totals to ensure everyone is fed."},"correct":false,"feedback":{"zh":"數據公佈本身不會修復道路或恢復家庭購買力。","cn":"数据公布本身不会修复道路或恢复家庭购买力。","en":"Publishing data does not repair roads or restore purchasing power."},"id":"a"},{"text":{"zh":"只增加下一季出口，完全不用處理當前道路。","cn":"只增加下一季出口，完全不用处理当前道路。","en":"Increase next season's exports without addressing current roads."},"correct":false,"feedback":{"zh":"這沒有直接解決受困家庭眼前的配送及價格困難。","cn":"这没有直接解决受困家庭眼前的配送及价格困难。","en":"This does not directly address the current distribution and affordability barriers."},"id":"b"},{"text":{"zh":"恢復配送通道，並為受影響家庭提供有針對性的糧食或購買支援。","cn":"恢复配送通道，并为受影响家庭提供有针对性的粮食或购买支援。","en":"Restore distribution routes and provide targeted food or purchasing support to affected households."},"correct":true,"feedback":{"zh":"問題是分配及取得糧食的能力，單看總產量會漏掉這些障礙。","cn":"问题是分配及取得粮食的能力，单看总产量会漏掉这些障碍。","en":"The problem concerns distribution and access, which aggregate supply alone misses."},"id":"c"}],"takeaway":{"zh":"糧食安全涉及供應、取得、利用及穩定性，不能只看平均產量。","cn":"粮食安全涉及供应、取得、利用及稳定性，不能只看平均产量。","en":"Food security involves availability, access, use and stability, not only average output."}},{"id":"s5-geography-03","grade":5,"subjectId":"geography","roomId":"geography","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"氣候趨勢與地點變化","cn":"气候趋势与地点变化","en":"Climate trends and station changes"},"question":{"zh":"某測站 30 年升溫 1.5°C，期間附近由草地變成密集樓宇。要估計更廣泛的區域氣候趨勢，最需要補充甚麼？","cn":"某测站 30 年升温 1.5°C，期间附近由草地变成密集楼宇。要估计更广泛的区域气候趋势，最需要补充甚么？","en":"A station warms by 1.5°C over 30 years while nearby grassland becomes dense buildings. What additional evidence is most useful for estimating the wider regional climate trend?"},"options":[{"text":{"zh":"周邊多個長期測站及土地利用、儀器遷移記錄。","cn":"周边多个长期测站及土地利用、仪器迁移记录。","en":"Records from multiple long-term stations plus land-use and instrument/site changes."},"correct":true,"feedback":{"zh":"這可協助區分區域變化和本地都市化、量度條件的影響。","cn":"这可协助区分区域变化和本地都市化、量度条件的影响。","en":"These help distinguish regional change from local urbanisation and measurement changes."},"id":"a"},{"text":{"zh":"只選該站最熱的一天代表三十年。","cn":"只选该站最热的一天代表三十年。","en":"Use only the station's hottest day to represent thirty years."},"correct":false,"feedback":{"zh":"極端單日不能代表長期趨勢或分辨原因。","cn":"极端单日不能代表长期趋势或分辨原因。","en":"A single extreme day cannot represent a long-term trend or separate causes."},"id":"b"},{"text":{"zh":"假定所有升溫只由城市化造成，毋須比較。","cn":"假定所有升温只由城市化造成，毋须比较。","en":"Assume all warming is caused by urbanisation without comparison."},"correct":false,"feedback":{"zh":"城市化是可能因素，但不能預先排除區域氣候變化。","cn":"城市化是可能因素，但不能预先排除区域气候变化。","en":"Urbanisation is a possible factor, but regional climate change cannot be ruled out in advance."},"id":"c"}],"takeaway":{"zh":"長期環境數據的解讀要檢查地點、儀器和空間尺度。","cn":"长期环境数据的解读要检查地点、仪器和空间尺度。","en":"Interpret long-term environmental data with attention to site, instruments and spatial scale."}},{"id":"s6-geography-01","grade":6,"subjectId":"geography","roomId":"geography","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"重現期的風險含義","cn":"重现期的风险含义","en":"Interpreting a return period"},"question":{"zh":"某洪水規模在簡化且穩定的模型中，每年超越機率是 2%，稱為五十年一遇。哪項理解正確？","cn":"某洪水规模在简化且稳定的模型中，每年超越机率是 2%，称为五十年一遇。哪项理解正确？","en":"In a simplified stationary model, a flood magnitude has a 2% annual exceedance probability, described as a 50-year event. Which interpretation is correct?"},"options":[{"text":{"zh":"發生後的四十九年必定安全。","cn":"发生后的四十九年必定安全。","en":"The next forty-nine years are guaranteed safe after a flood."},"correct":false,"feedback":{"zh":"曾發生並不令其後年份的風險自動消失。","cn":"曾发生并不令其后年份的风险自动消失。","en":"An event does not automatically remove the following years' risk."},"id":"a"},{"text":{"zh":"五十年內一定剛好發生一次。","cn":"五十年内一定刚好发生一次。","en":"Exactly one event must occur in every fifty-year period."},"correct":false,"feedback":{"zh":"機率不能保證固定次數。","cn":"机率不能保证固定次数。","en":"A probability does not guarantee a fixed event count."},"id":"b"},{"text":{"zh":"每年仍有 2% 機會，不保證兩次洪水相隔五十年。","cn":"每年仍有 2% 机会，不保证两次洪水相隔五十年。","en":"Each year still has a 2% chance; floods are not guaranteed to be fifty years apart."},"correct":true,"feedback":{"zh":"重現期是長期機率概念，不是事件時間表；模型也依賴穩定性假設。","cn":"重现期是长期机率概念，不是事件时间表；模型也依赖稳定性假设。","en":"A return period is a probability concept, not a timetable, and depends on stationarity assumptions."},"id":"c"}],"takeaway":{"zh":"將重現期解讀為模型中的機率，並留意氣候和土地利用可令假設改變。","cn":"将重现期解读为模型中的机率，并留意气候和土地利用可令假设改变。","en":"Read return periods as model probabilities and consider changes in climate and land use."}},{"id":"s6-geography-02","grade":6,"subjectId":"geography","roomId":"geography","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"可持續旅遊的多準則決策","cn":"可持续旅游的多准则决策","en":"Multi-criteria decisions in sustainable tourism"},"question":{"zh":"某海岸旅遊區高峯期擠迫、步道侵蝕，但居民依賴旅遊收入。哪項方案最能同時回應三個條件？","cn":"某海岸旅游区高峰期挤迫、步道侵蚀，但居民依赖旅游收入。哪项方案最能同时回应三个条件？","en":"A coastal destination has peak-time crowding and trail erosion, while residents rely on tourism income. Which plan best addresses all three conditions?"},"options":[{"text":{"zh":"按生態監測調整預約人數、引導離峯旅遊，並讓居民參與收益和管理。","cn":"按生态监测调整预约人数、引导离峰旅游，并让居民参与收益和管理。","en":"Adjust booking limits using ecological monitoring, spread visits off-peak and involve residents in benefits and management."},"correct":true,"feedback":{"zh":"方案同時處理承載壓力、時間分佈和居民生計；仍需持續評估。","cn":"方案同时处理承载压力、时间分布和居民生计；仍需持续评估。","en":"The plan addresses ecological pressure, timing and livelihoods, with ongoing evaluation still needed."},"id":"a"},{"text":{"zh":"只宣傳吸引更多高峯期遊客，不改善步道。","cn":"只宣传吸引更多高峰期游客，不改善步道。","en":"Advertise more peak-time visits without managing trails."},"correct":false,"feedback":{"zh":"收入可能增加，但會加劇題目指出的擠迫及侵蝕。","cn":"收入可能增加，但会加剧题目指出的挤迫及侵蚀。","en":"Revenue may rise, but the stated crowding and erosion pressures may worsen."},"id":"b"},{"text":{"zh":"永久封閉整區，毋須討論居民替代生計。","cn":"永久封闭整区，毋须讨论居民替代生计。","en":"Close the entire area permanently without considering alternative livelihoods."},"correct":false,"feedback":{"zh":"可能減少遊客壓力，但沒有回應依賴旅遊的居民需要。","cn":"可能减少游客压力，但没有回应依赖旅游的居民需要。","en":"This may reduce visitor pressure but does not address residents' livelihood needs."},"id":"c"}],"takeaway":{"zh":"可持續管理需要比較環境、社會和經濟取捨及其分配。","cn":"可持续管理需要比较环境、社会和经济取舍及其分配。","en":"Sustainable management compares environmental, social and economic trade-offs and who experiences them."}},{"id":"s6-geography-03","grade":6,"subjectId":"geography","roomId":"geography","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"GIS 選址與權重敏感度","cn":"GIS 选址与权重敏感度","en":"GIS siting and sensitivity to weights"},"question":{"zh":"GIS 模型以交通便利和土地價格加權選出新診所位置；模型未加入長者分佈或水浸風險。決策前哪步最關鍵？","cn":"GIS 模型以交通便利和土地价格加权选出新诊所位置；模型未加入长者分布或水浸风险。决策前哪步最关键？","en":"A GIS model weights transport access and land cost to select a clinic site, omitting older residents and flood risk. What is most important before deciding?"},"options":[{"text":{"zh":"模型由電腦計算，所以毋須檢查權重。","cn":"模型由电脑计算，所以毋须检查权重。","en":"A computer calculated it, so the weights need no review."},"correct":false,"feedback":{"zh":"權重仍包含人的價值判斷與設計選擇。","cn":"权重仍包含人的价值判断与设计选择。","en":"Weights still embody human values and design choices."},"id":"a"},{"text":{"zh":"加入服務需要和風險圖層，與持份者檢視權重，測試排名是否穩定。","cn":"加入服务需要和风险图层，与持份者检视权重，测试排名是否稳定。","en":"Add need and risk layers, review weights with stakeholders and test whether rankings remain stable."},"correct":true,"feedback":{"zh":"地圖結果取決於選用準則、數據和權重，不能把最高分視為中立的唯一答案。","cn":"地图结果取决于选用准则、数据和权重，不能把最高分视为中立的唯一答案。","en":"The ranking depends on criteria, data and weights; the top score is not a uniquely neutral answer."},"id":"b"},{"text":{"zh":"只提高交通便利的權重，因為它已有完整數據。","cn":"只提高交通便利的权重，因为它已有完整数据。","en":"Increase only the transport weight because its data are complete."},"correct":false,"feedback":{"zh":"容易取得的資料不應自動壓過服務需要或安全；這仍遺漏重要圖層。","cn":"容易取得的资料不应自动压过服务需要或安全；这仍遗漏重要图层。","en":"Convenient data should not automatically outweigh need or safety; important layers remain omitted."},"id":"c"}],"takeaway":{"zh":"空間模型是決策工具；應檢視資料遺漏、權重及受影響羣體。","cn":"空间模型是决策工具；应检视资料遗漏、权重及受影响群体。","en":"Spatial models support decisions; inspect missing data, weights and affected groups."}},{"id":"s1-computer-01","grade":1,"subjectId":"computer","roomId":"computer","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"輸入、處理與輸出","cn":"输入、处理与输出","en":"Input, processing and output"},"question":{"zh":"校園溫度系統接收感應器數值，計算平均值，再在屏幕顯示。哪項屬於處理？","cn":"校园温度系统接收感应器数值，计算平均值，再在屏幕显示。哪项属于处理？","en":"A campus temperature system receives sensor readings, calculates their mean and displays it. Which step is processing?"},"options":[{"text":{"zh":"屏幕顯示平均溫度。","cn":"屏幕显示平均温度。","en":"Displaying the mean temperature."},"correct":false,"feedback":{"zh":"這是輸出，把已算好的結果呈現給使用者。","cn":"这是输出，把已算好的结果呈现给使用者。","en":"This is output: presenting an already computed result."},"id":"a"},{"text":{"zh":"計算平均值。","cn":"计算平均值。","en":"Calculating the mean."},"correct":true,"feedback":{"zh":"處理把輸入資料按規則轉化成結果。","cn":"处理把输入资料按规则转化成结果。","en":"Processing transforms input data according to rules."},"id":"b"},{"text":{"zh":"感應器傳入溫度數值。","cn":"感应器传入温度数值。","en":"Receiving the sensor readings."},"correct":false,"feedback":{"zh":"這是輸入，尚未計算結果。","cn":"这是输入，尚未计算结果。","en":"This is input, before calculation."},"id":"c"}],"takeaway":{"zh":"按資料在系統中的作用，分清輸入、處理與輸出。","cn":"按资料在系统中的作用，分清输入、处理与输出。","en":"Distinguish input, processing and output by each step's role in the system."}},{"id":"s1-computer-02","grade":1,"subjectId":"computer","roomId":"computer","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"試算表的範圍公式","cn":"试算表的范围公式","en":"Spreadsheet range formulas"},"question":{"zh":"B2 至 B6 存放五天回收紙張質量。B7 要自動計算總和。哪個公式正確？","cn":"B2 至 B6 存放五天回收纸张质量。B7 要自动计算总和。哪个公式正确？","en":"Cells B2 to B6 contain paper-recycling masses for five days. B7 should update their total automatically. Which formula is correct?"},"options":[{"text":{"zh":"=SUM(B2,B6)","cn":"=SUM(B2,B6)","en":"=SUM(B2,B6)"},"correct":false,"feedback":{"zh":"這只加 B2 和 B6，遺漏中間三格。","cn":"这只加 B2 和 B6，遗漏中间三格。","en":"This adds only B2 and B6, omitting the three cells between them."},"id":"a"},{"text":{"zh":"=SUM(B2:B7)","cn":"=SUM(B2:B7)","en":"=SUM(B2:B7)"},"correct":false,"feedback":{"zh":"B7 的公式包含自己，會造成循環參照。","cn":"B7 的公式包含自己，会造成循环参照。","en":"A formula in B7 that includes B7 creates a circular reference."},"id":"b"},{"text":{"zh":"=SUM(B2:B6)","cn":"=SUM(B2:B6)","en":"=SUM(B2:B6)"},"correct":true,"feedback":{"zh":"冒號表示包含兩端的連續範圍；公式會隨數值改變重新計算。","cn":"冒号表示包含两端的连续范围；公式会随数值改变重新计算。","en":"The colon specifies the inclusive range, and the formula recalculates when values change."},"id":"c"}],"takeaway":{"zh":"公式要包括正確資料範圍，同時避免把結果格納入自身計算。","cn":"公式要包括正确资料范围，同时避免把结果格纳入自身计算。","en":"Include the correct data range and avoid referencing the result cell itself."}},{"id":"s1-computer-03","grade":1,"subjectId":"computer","roomId":"computer","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"逐步追蹤條件演算法","cn":"逐步追踪条件演算法","en":"Tracing a conditional algorithm"},"question":{"zh":"演算法：count=0；依次讀取 4、7、7、2；每次若數值≥5，count 加 1。最後 count 是多少？","cn":"演算法：count=0；依次读取 4、7、7、2；每次若数值≥5，count 加 1。最后 count 是多少？","en":"Algorithm: count=0; read 4, 7, 7, 2 in order; add 1 to count whenever the value is ≥5. What is the final count?"},"options":[{"text":{"zh":"2","cn":"2","en":"2"},"correct":true,"feedback":{"zh":"兩個 7 都符合條件，各自增加一次計數。","cn":"两个 7 都符合条件，各自增加一次计数。","en":"Both occurrences of 7 meet the condition and each increments the count."},"id":"a"},{"text":{"zh":"1","cn":"1","en":"1"},"correct":false,"feedback":{"zh":"演算法數的是符合條件的出現次數，不是不同數值的種類。","cn":"演算法数的是符合条件的出现次数，不是不同数值的种类。","en":"The algorithm counts qualifying occurrences, not distinct values."},"id":"b"},{"text":{"zh":"14","cn":"14","en":"14"},"correct":false,"feedback":{"zh":"它每次加 1，並不是把符合條件的數值相加。","cn":"它每次加 1，并不是把符合条件的数值相加。","en":"It adds 1 each time rather than summing the qualifying values."},"id":"c"}],"takeaway":{"zh":"追蹤變量每一步的改變，分清計數與加總。","cn":"追踪变量每一步的改变，分清计数与加总。","en":"Trace variable updates step by step and distinguish counting from summing."}},{"id":"s2-computer-01","grade":2,"subjectId":"computer","roomId":"computer","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"二進制位值","cn":"二进制位值","en":"Binary place values"},"question":{"zh":"把二進制 00101101 轉為十進制，結果是多少？","cn":"把二进制 00101101 转为十进制，结果是多少？","en":"Convert binary 00101101 to decimal. What is the result?"},"options":[{"text":{"zh":"29","cn":"29","en":"29"},"correct":false,"feedback":{"zh":"這遺漏了 32 位並錯置位值，應由右按 1、2、4、8… 計算。","cn":"这遗漏了 32 位并错置位值，应由右按 1、2、4、8… 计算。","en":"This misreads the positions; count 1, 2, 4, 8 and so on from the right."},"id":"a"},{"text":{"zh":"101101","cn":"101101","en":"101101"},"correct":false,"feedback":{"zh":"刪去前導零不會把二進制字串自動變成十進制數值。","cn":"删去前导零不会把二进制字串自动变成十进制数值。","en":"Removing leading zeroes does not convert binary notation into decimal."},"id":"b"},{"text":{"zh":"45","cn":"45","en":"45"},"correct":true,"feedback":{"zh":"有 1 的位值為 32、8、4、1；總和是 45。","cn":"有 1 的位值为 32、8、4、1；总和是 45。","en":"The active place values are 32, 8, 4 and 1, totalling 45."},"id":"c"}],"takeaway":{"zh":"數值取決於數碼及其進制位值，字串外觀並不等於數量。","cn":"数值取决于数码及其进制位值，字串外观并不等于数量。","en":"A value depends on digits and their base-specific positions, not just the string's appearance."}},{"id":"s2-computer-02","grade":2,"subjectId":"computer","roomId":"computer","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"布林邏輯與存取條件","cn":"布林逻辑与存取条件","en":"Boolean logic and access conditions"},"question":{"zh":"系統只有在 passwordValid AND NOT accountLocked 時容許登入。passwordValid=true、accountLocked=true，結果怎樣？","cn":"系统只有在 passwordValid AND NOT accountLocked 时容许登入。passwordValid=true、accountLocked=true，结果怎样？","en":"Access is allowed only when passwordValid AND NOT accountLocked. If both passwordValid and accountLocked are true, what happens?"},"options":[{"text":{"zh":"拒絕登入，因為 NOT accountLocked 為 false。","cn":"拒绝登入，因为 NOT accountLocked 为 false。","en":"Access is denied because NOT accountLocked is false."},"correct":true,"feedback":{"zh":"true AND false 的結果是 false；正確密碼不能忽略鎖定狀態。","cn":"true AND false 的结果是 false；正确密码不能忽略锁定状态。","en":"True AND false evaluates to false; a valid password does not override the lock."},"id":"a"},{"text":{"zh":"容許登入，只要其中一項是 true。","cn":"容许登入，只要其中一项是 true。","en":"Access is allowed whenever either condition is true."},"correct":false,"feedback":{"zh":"這是把 AND 誤當成 OR。","cn":"这是把 AND 误当成 OR。","en":"This confuses AND with OR."},"id":"b"},{"text":{"zh":"容許登入，因為 NOT 會把整句變成 true。","cn":"容许登入，因为 NOT 会把整句变成 true。","en":"Access is allowed because NOT makes the whole expression true."},"correct":false,"feedback":{"zh":"NOT 只作用於 accountLocked，不會把整句任意改成 true。","cn":"NOT 只作用于 accountLocked，不会把整句任意改成 true。","en":"NOT applies to accountLocked; it does not make the whole expression arbitrarily true."},"id":"c"}],"takeaway":{"zh":"先處理否定，再依運算子判斷條件組合。","cn":"先处理否定，再依运算子判断条件组合。","en":"Evaluate negation and then combine conditions using the stated operator."}},{"id":"s2-computer-03","grade":2,"subjectId":"computer","roomId":"computer","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"迴圈的更新次序","cn":"回圈的更新次序","en":"Order of updates in a loop"},"question":{"zh":"程式：total=0；FOR i=1 TO 3：total=total+2*i；END FOR。最後 total 是多少？","cn":"程式：total=0；FOR i=1 TO 3：total=total+2*i；END FOR。最后 total 是多少？","en":"Program: total=0; FOR i=1 TO 3: total=total+2*i; END FOR. What is the final total?"},"options":[{"text":{"zh":"18","cn":"18","en":"18"},"correct":false,"feedback":{"zh":"不能每次都使用最後的 i=3；i 依次是 1、2、3。","cn":"不能每次都使用最后的 i=3；i 依次是 1、2、3。","en":"Do not use the final i=3 on every iteration; i takes 1, 2 and 3 in turn."},"id":"a"},{"text":{"zh":"12","cn":"12","en":"12"},"correct":true,"feedback":{"zh":"三次分別加 2、4、6，累計 12。","cn":"三次分别加 2、4、6，累计 12。","en":"The iterations add 2, 4 and 6, giving 12."},"id":"b"},{"text":{"zh":"6","cn":"6","en":"6"},"correct":false,"feedback":{"zh":"6 只是最後一次加上的值；total 保留前面累計。","cn":"6 只是最后一次加上的值；total 保留前面累计。","en":"6 is only the last added value; total retains earlier additions."},"id":"c"}],"takeaway":{"zh":"迴圈追蹤表要記錄每輪控制變量與累計變量。","cn":"回圈追踪表要记录每轮控制变量与累计变量。","en":"A loop trace records both the loop-control variable and the accumulator on each iteration."}},{"id":"s3-computer-01","grade":3,"subjectId":"computer","roomId":"computer","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"壓縮與資料完整性","cn":"压缩与资料完整性","en":"Compression and data integrity"},"question":{"zh":"學校要儲存可還原每個字元的程式原始碼。哪種壓縮方法適合？","cn":"学校要储存可还原每个字元的程式原始码。哪种压缩方法适合？","en":"A school needs to store source code so that every original character can be recovered. Which compression approach is appropriate?"},"options":[{"text":{"zh":"無損壓縮。","cn":"无损压缩。","en":"Lossless compression."},"correct":true,"feedback":{"zh":"無損壓縮可精確還原原始資料，程式不能任意遺失字元。","cn":"无损压缩可精确还原原始资料，程式不能任意遗失字元。","en":"Lossless compression restores the exact original data; code cannot arbitrarily lose characters."},"id":"a"},{"text":{"zh":"有損壓縮，因為看起來差不多就足夠。","cn":"有损压缩，因为看起来差不多就足够。","en":"Lossy compression because looking similar is sufficient."},"correct":false,"feedback":{"zh":"少一個符號也可能改變程式意思，外觀相似並不足夠。","cn":"少一个符号也可能改变程式意思，外观相似并不足够。","en":"A missing symbol can change program behaviour; visual similarity is insufficient."},"id":"b"},{"text":{"zh":"把所有變量名稱刪除，仍稱為同一份原始碼。","cn":"把所有变量名称删除，仍称为同一份原始码。","en":"Delete all variable names and call it the same source code."},"correct":false,"feedback":{"zh":"刪除有意義字元不能精確重建原始碼。","cn":"删除有意义字元不能精确重建原始码。","en":"Removing meaningful characters prevents exact reconstruction."},"id":"c"}],"takeaway":{"zh":"壓縮方法要配合資料用途和可容許的資訊損失。","cn":"压缩方法要配合资料用途和可容许的资讯损失。","en":"Choose compression according to the data's purpose and acceptable information loss."}},{"id":"s3-computer-02","grade":3,"subjectId":"computer","roomId":"computer","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"最大值演算法的初始值","cn":"最大值演算法的初始值","en":"Initialisation in a maximum algorithm"},"question":{"zh":"程式把 max 設為 0，再逐一比較溫度 −6、−3、−8；只有讀數比 max 大才更新。結果錯誤為 0。最好怎樣修正？","cn":"程式把 max 设为 0，再逐一比较温度 −6、−3、−8；只有读数比 max 大才更新。结果错误为 0。最好怎样修正？","en":"A program sets max=0, then checks temperatures −6, −3, −8, updating only when a value exceeds max. It wrongly returns 0. What is the best repair?"},"options":[{"text":{"zh":"永遠把 max 設為 100。","cn":"永远把 max 设为 100。","en":"Always initialise max to 100."},"correct":false,"feedback":{"zh":"資料全低於 100 時仍不更新，同一類錯誤會持續。","cn":"资料全低于 100 时仍不更新，同一类错误会持续。","en":"Values below 100 would still never update it, preserving the same defect."},"id":"a"},{"text":{"zh":"以第一個實際讀數初始化 max，再比較餘下讀數。","cn":"以第一个实际读数初始化 max，再比较余下读数。","en":"Initialise max with the first actual reading, then compare the rest."},"correct":true,"feedback":{"zh":"初值來自資料，能正確處理全部為負數的情況。","cn":"初值来自资料，能正确处理全部为负数的情况。","en":"A data-based initial value correctly handles an all-negative list."},"id":"b"},{"text":{"zh":"把所有負號刪除後再找最大值。","cn":"把所有负号删除后再找最大值。","en":"Remove all minus signs before finding the maximum."},"correct":false,"feedback":{"zh":"這改變了溫度資料，所得不再是原來的最大值。","cn":"这改变了温度资料，所得不再是原来的最大值。","en":"This changes the temperature data and no longer finds its original maximum."},"id":"c"}],"takeaway":{"zh":"用邊界和特殊資料測試演算法；初始值必須符合資料範圍。","cn":"用边界和特殊资料测试演算法；初始值必须符合资料范围。","en":"Test edge cases and ensure initial values fit the data domain."}},{"id":"s3-computer-03","grade":3,"subjectId":"computer","roomId":"computer","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"遺漏資料與零值","cn":"遗漏资料与零值","en":"Missing data versus zero"},"question":{"zh":"感應器五次讀數為 10、12、空白、8、10。程式把空白當作 0，算出平均 8。若空白代表斷線，應怎樣報告？","cn":"感应器五次读数为 10、12、空白、8、10。程式把空白当作 0，算出平均 8。若空白代表断线，应怎样报告？","en":"Five sensor entries are 10, 12, blank, 8, 10. Software treats blank as zero and reports a mean of 8. If blank means disconnection, what should be reported?"},"options":[{"text":{"zh":"平均 8 一定正確，因為空白必定表示沒有數量。","cn":"平均 8 一定正确，因为空白必定表示没有数量。","en":"8 must be correct because blank always means no quantity."},"correct":false,"feedback":{"zh":"題目明確說空白代表斷線，不是量得零。","cn":"题目明确说空白代表断线，不是量得零。","en":"The blank is explicitly a disconnection, not a measured zero."},"id":"a"},{"text":{"zh":"用 100 填空白，確保平均較高。","cn":"用 100 填空白，确保平均较高。","en":"Replace the blank with 100 to ensure a higher mean."},"correct":false,"feedback":{"zh":"沒有根據的填補會製造資料並改變結果。","cn":"没有根据的填补会制造资料并改变结果。","en":"An unsupported replacement fabricates data and changes the result."},"id":"b"},{"text":{"zh":"四個有效讀數平均 10，並註明缺失一次；不能聲稱代表所有時段。","cn":"四个有效读数平均 10，并注明缺失一次；不能声称代表所有时段。","en":"The four valid readings average 10; report one missing observation and avoid claiming full time coverage."},"correct":true,"feedback":{"zh":"零是實際數值，缺失是未知；剔除後仍要交代資料覆蓋限制。","cn":"零是实际数值，缺失是未知；剔除后仍要交代资料覆盖限制。","en":"Zero is a measured value; missing is unknown, and exclusion still needs a coverage caveat."},"id":"c"}],"takeaway":{"zh":"資料清理需保留零值和未知值的差別，並記錄處理規則。","cn":"资料清理需保留零值和未知值的差别，并记录处理规则。","en":"Data cleaning should preserve the distinction between zero and unknown and document its rules."}},{"id":"s4-computer-01","grade":4,"subjectId":"computer","roomId":"computer","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"數碼影像的儲存量","cn":"数码影像的储存量","en":"Digital image storage"},"question":{"zh":"未壓縮 RGB 影像為 1,000×800 像素，每像素 24 bits，忽略檔頭。用 1 MB=1,000,000 bytes 計，需多少空間？","cn":"未压缩 RGB 影像为 1,000×800 像素，每像素 24 bits，忽略档头。用 1 MB=1,000,000 bytes 计，需多少空间？","en":"An uncompressed RGB image is 1,000×800 pixels at 24 bits per pixel, ignoring headers. With 1 MB=1,000,000 bytes, how much storage is needed?"},"options":[{"text":{"zh":"0.8 MB","cn":"0.8 MB","en":"0.8 MB"},"correct":false,"feedback":{"zh":"這相當於每像素只有 1 byte；24 bits 需要 3 bytes。","cn":"这相当于每像素只有 1 byte；24 bits 需要 3 bytes。","en":"This assumes one byte per pixel, but 24 bits requires three."},"id":"a"},{"text":{"zh":"2.4 MB","cn":"2.4 MB","en":"2.4 MB"},"correct":true,"feedback":{"zh":"800,000×24÷8=2,400,000 bytes，即 2.4 MB。","cn":"800,000×24÷8=2,400,000 bytes，即 2.4 MB。","en":"800,000×24/8=2,400,000 bytes, or 2.4 MB."},"id":"b"},{"text":{"zh":"19.2 MB","cn":"19.2 MB","en":"19.2 MB"},"correct":false,"feedback":{"zh":"19.2 百萬是 bits，轉 bytes 要除以 8。","cn":"19.2 百万是 bits，转 bytes 要除以 8。","en":"19.2 million is the bit count; divide by 8 to obtain bytes."},"id":"c"}],"takeaway":{"zh":"儲存量由像素數、色深及單位共同決定；壓縮和檔頭另作考慮。","cn":"储存量由像素数、色深及单位共同决定；压缩和档头另作考虑。","en":"Storage depends on pixel count, bit depth and units; compression and headers are separate factors."}},{"id":"s4-computer-02","grade":4,"subjectId":"computer","roomId":"computer","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"SQL 篩選與排序","cn":"SQL 筛选与排序","en":"SQL filtering and ordering"},"question":{"zh":"Results(name,score) 表中，要找 score 至少 80 的學生，並按分數由高至低排序。哪個查詢正確？","cn":"Results(name,score) 表中，要找 score 至少 80 的学生，并按分数由高至低排序。哪个查询正确？","en":"In Results(name,score), select students scoring at least 80 and order highest first. Which query is correct?"},"options":[{"text":{"zh":"SELECT name,score FROM Results WHERE score>80 ORDER BY score ASC;","cn":"SELECT name,score FROM Results WHERE score>80 ORDER BY score ASC;","en":"SELECT name,score FROM Results WHERE score>80 ORDER BY score ASC;"},"correct":false,"feedback":{"zh":"這排除剛好 80 分，並由低至高排序。","cn":"这排除刚好 80 分，并由低至高排序。","en":"This excludes exactly 80 and sorts lowest first."},"id":"a"},{"text":{"zh":"SELECT name,score FROM Results ORDER BY name WHERE score>=80;","cn":"SELECT name,score FROM Results ORDER BY name WHERE score>=80;","en":"SELECT name,score FROM Results ORDER BY name WHERE score>=80;"},"correct":false,"feedback":{"zh":"SQL 子句次序不對，也沒有按分數排序。","cn":"SQL 子句次序不对，也没有按分数排序。","en":"The clause order is invalid and it does not order by score."},"id":"b"},{"text":{"zh":"SELECT name,score FROM Results WHERE score>=80 ORDER BY score DESC;","cn":"SELECT name,score FROM Results WHERE score>=80 ORDER BY score DESC;","en":"SELECT name,score FROM Results WHERE score>=80 ORDER BY score DESC;"},"correct":true,"feedback":{"zh":"WHERE 篩選記錄，DESC 指由大至小排序。","cn":"WHERE 筛选记录，DESC 指由大至小排序。","en":"WHERE filters rows; DESC orders values from highest to lowest."},"id":"c"}],"takeaway":{"zh":"把查詢需求拆成所需欄位、篩選條件及排序規則。","cn":"把查询需求拆成所需栏位、筛选条件及排序规则。","en":"Break a query into required columns, filtering conditions and ordering rules."}},{"id":"s4-computer-03","grade":4,"subjectId":"computer","roomId":"computer","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"HTTPS 與可信度的界線","cn":"HTTPS 与可信度的界线","en":"HTTPS and the limits of trust"},"question":{"zh":"一個仿冒校務登入網站也有 HTTPS 鎖頭。學生因此認為它必定屬於學校。哪項解釋正確？","cn":"一个仿冒校务登入网站也有 HTTPS 锁头。学生因此认为它必定属于学校。哪项解释正确？","en":"A fake school-login website also has an HTTPS padlock. A student concludes that it must belong to the school. Which explanation is correct?"},"options":[{"text":{"zh":"HTTPS 保護連線傳輸，但不保證網站內容或經營者可信；仍要核對正式網域。","cn":"HTTPS 保护连线传输，但不保证网站内容或经营者可信；仍要核对正式网域。","en":"HTTPS protects data in transit but does not guarantee trustworthy content or ownership; verify the official domain."},"correct":true,"feedback":{"zh":"加密連線和網站是否獲學校授權是不同問題。","cn":"加密连线和网站是否获学校授权是不同问题。","en":"Encrypted transport and authorisation by the school are different questions."},"id":"a"},{"text":{"zh":"有鎖頭便代表教育局已審核所有內容。","cn":"有锁头便代表教育局已审核所有内容。","en":"A padlock means the Education Bureau has reviewed every page."},"correct":false,"feedback":{"zh":"TLS 憑證不等於教育機構對網站內容的審核。","cn":"TLS 凭证不等于教育机构对网站内容的审核。","en":"A TLS certificate is not an educational authority's content review."},"id":"b"},{"text":{"zh":"只要畫面有學校標誌，就不用核對網址。","cn":"只要画面有学校标志，就不用核对网址。","en":"A school logo removes the need to check the address."},"correct":false,"feedback":{"zh":"標誌和介面可以被複製，不能代替網域及來源核對。","cn":"标志和介面可以被复制，不能代替网域及来源核对。","en":"Logos and interfaces can be copied and cannot replace domain and source checks."},"id":"c"}],"takeaway":{"zh":"區分傳輸安全、身份核實和資訊可信度。","cn":"区分传输安全、身份核实和资讯可信度。","en":"Distinguish transport security, identity verification and information credibility."}},{"id":"s5-computer-01","grade":5,"subjectId":"computer","roomId":"computer","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"資料庫更新異常","cn":"资料库更新异常","en":"Database update anomalies"},"question":{"zh":"借書表每一筆借閱都重複儲存同一學生的電話。學生改電話後，只更新一筆，出現兩個號碼。哪個設計較合理？","cn":"借书表每一笔借阅都重复储存同一学生的电话。学生改电话后，只更新一笔，出现两个号码。哪个设计较合理？","en":"Every loan record repeats the student's phone number. After one record is updated, conflicting numbers remain. Which design is more appropriate?"},"options":[{"text":{"zh":"把每個電話複製到更多欄位。","cn":"把每个电话复制到更多栏位。","en":"Copy each phone number into more columns."},"correct":false,"feedback":{"zh":"更多重複會增加需要同步更新的位置。","cn":"更多重复会增加需要同步更新的位置。","en":"More duplication increases the places needing consistent updates."},"id":"a"},{"text":{"zh":"刪除所有學生識別欄，讓記錄無法連結。","cn":"删除所有学生识别栏，让记录无法连结。","en":"Remove all student identifiers so records cannot be linked."},"correct":false,"feedback":{"zh":"這破壞必要的關聯，不能兼顧正確查詢。","cn":"这破坏必要的关联，不能兼顾正确查询。","en":"This destroys necessary relationships rather than enabling reliable queries."},"id":"b"},{"text":{"zh":"以學生表儲存聯絡資料，借閱表用 studentId 連結。","cn":"以学生表储存联络资料，借阅表用 studentId 连结。","en":"Store contact details in a Students table and link Loans using studentId."},"correct":true,"feedback":{"zh":"減少重複儲存可降低更新異常；關聯鍵保留資料連結。","cn":"减少重复储存可降低更新异常；关联键保留资料连结。","en":"Reducing duplicated storage limits update anomalies while keys preserve relationships."},"id":"c"}],"takeaway":{"zh":"正規化以合理分表減少重複與異常，同時保留鍵的關聯。","cn":"正规化以合理分表减少重复与异常，同时保留键的关联。","en":"Normalisation reduces duplication and anomalies through sensible tables and keys."}},{"id":"s5-computer-02","grade":5,"subjectId":"computer","roomId":"computer","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"二分搜尋的前提","cn":"二分搜寻的前提","en":"The prerequisite for binary search"},"question":{"zh":"程式在未排序的學生編號清單直接使用二分搜尋，偶爾找不到存在的編號。根本原因是甚麼？","cn":"程式在未排序的学生编号清单直接使用二分搜寻，偶尔找不到存在的编号。根本原因是甚么？","en":"A program applies binary search directly to an unsorted list of student numbers and sometimes misses an existing value. What is the root cause?"},"options":[{"text":{"zh":"二分搜尋依賴排序，否則不能按中間值安全排除一半。","cn":"二分搜寻依赖排序，否则不能按中间值安全排除一半。","en":"Binary search requires ordering; without it, comparing the middle value cannot safely discard half the list."},"correct":true,"feedback":{"zh":"正確性來自有序結構，不只是每次減少資料量。","cn":"正确性来自有序结构，不只是每次减少资料量。","en":"Its correctness comes from order, not merely reducing the search space."},"id":"a"},{"text":{"zh":"二分搜尋只適用於完全沒有重複值的清單。","cn":"二分搜寻只适用于完全没有重复值的清单。","en":"Binary search works only when every value is unique."},"correct":false,"feedback":{"zh":"有序清單可含重複值；查找其中一次出現仍可使用二分搜尋。","cn":"有序清单可含重复值；查找其中一次出现仍可使用二分搜寻。","en":"A sorted list may contain duplicates; binary search can still locate an occurrence."},"id":"b"},{"text":{"zh":"清單索引必須由 1 開始，不能由 0 開始。","cn":"清单索引必须由 1 开始，不能由 0 开始。","en":"The list index must start at 1 rather than 0."},"correct":false,"feedback":{"zh":"只要邊界計算一致，兩種索引都可用；未排序才是題目問題。","cn":"只要边界计算一致，两种索引都可用；未排序才是题目问题。","en":"Either indexing convention works with consistent bounds; lack of sorting is the stated problem."},"id":"c"}],"takeaway":{"zh":"選擇演算法時，要檢查其資料前提，不能只比較速度。","cn":"选择演算法时，要检查其资料前提，不能只比较速度。","en":"Check an algorithm's data prerequisites, not only its speed."}},{"id":"s5-computer-03","grade":5,"subjectId":"computer","roomId":"computer","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"分類模型的漏報","cn":"分类模型的漏报","en":"Missed positives in a classifier"},"question":{"zh":"一批 100 封郵件中有 30 封釣魚郵件。模型找出其中 18 封，漏掉 12 封；另誤報 2 封正常郵件。對真正釣魚郵件的召回率是多少？","cn":"一批 100 封邮件中有 30 封钓鱼邮件。模型找出其中 18 封，漏掉 12 封；另误报 2 封正常邮件。对真正钓鱼邮件的召回率是多少？","en":"Of 100 emails, 30 are phishing. A model detects 18, misses 12 and falsely flags 2 legitimate emails. What is recall for actual phishing emails?"},"options":[{"text":{"zh":"86%","cn":"86%","en":"86%"},"correct":false,"feedback":{"zh":"(18+68)÷100 是整體準確率，沒有單獨描述漏報程度。","cn":"(18+68)÷100 是整体准确率，没有单独描述漏报程度。","en":"(18+68)/100 is overall accuracy, not a direct measure of missed positives."},"id":"a"},{"text":{"zh":"60%","cn":"60%","en":"60%"},"correct":true,"feedback":{"zh":"召回率=找出的真正釣魚郵件÷全部真正釣魚郵件=18÷30。","cn":"召回率=找出的真正钓鱼邮件÷全部真正钓鱼邮件=18÷30。","en":"Recall is detected actual positives divided by all actual positives: 18/30."},"id":"b"},{"text":{"zh":"90%","cn":"90%","en":"90%"},"correct":false,"feedback":{"zh":"18÷20 是被標記郵件的精確率，不是召回率。","cn":"18÷20 是被标记邮件的精确率，不是召回率。","en":"18/20 is precision among flagged emails, not recall."},"id":"c"}],"takeaway":{"zh":"不同評估指標回答不同問題；漏報風險要查看召回率和實際代價。","cn":"不同评估指标回答不同问题；漏报风险要查看召回率和实际代价。","en":"Metrics answer different questions; assess missed-positive risk through recall and consequences."}},{"id":"s6-computer-01","grade":6,"subjectId":"computer","roomId":"computer","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"關聯鍵與參照完整性","cn":"关联键与参照完整性","en":"Relational keys and referential integrity"},"question":{"zh":"Enrollments(studentId,clubId) 的 studentId 參照 Students(id)。要避免不存在學生的報名記錄，最直接使用甚麼？","cn":"Enrollments(studentId,clubId) 的 studentId 参照 Students(id)。要避免不存在学生的报名记录，最直接使用甚么？","en":"Enrollments(studentId,clubId) references Students(id). What most directly prevents an enrolment from referring to a nonexistent student?"},"options":[{"text":{"zh":"studentId 的外來鍵約束。","cn":"studentId 的外来键约束。","en":"A foreign-key constraint on studentId."},"correct":true,"feedback":{"zh":"外來鍵要求參照值對應到被參照表的有效鍵。","cn":"外来键要求参照值对应到被参照表的有效键。","en":"A foreign key requires the referenced value to match a valid key in the target table."},"id":"a"},{"text":{"zh":"只為每筆報名加入獨立的主鍵，不設學生外來鍵。","cn":"只为每笔报名加入独立的主键，不设学生外来键。","en":"Give each enrolment its own primary key but no student foreign key."},"correct":false,"feedback":{"zh":"主鍵避免報名識別重複，並不保證 studentId 對應存在的學生。","cn":"主键避免报名识别重复，并不保证 studentId 对应存在的学生。","en":"A primary key distinguishes enrolments but does not ensure studentId references an existing student."},"id":"b"},{"text":{"zh":"只限制 studentId 必須是整數。","cn":"只限制 studentId 必须是整数。","en":"Require studentId to be an integer only."},"correct":false,"feedback":{"zh":"資料類型可限制格式，但不存在學生的整數仍可符合格式。","cn":"资料类型可限制格式，但不存在学生的整数仍可符合格式。","en":"A type constraint checks format, but an integer can still refer to no student."},"id":"c"}],"takeaway":{"zh":"資料完整性應由適當約束保障，而不只靠介面提示。","cn":"资料完整性应由适当约束保障，而不只靠介面提示。","en":"Protect data integrity through suitable constraints, not interface hints alone."}},{"id":"s6-computer-02","grade":6,"subjectId":"computer","roomId":"computer","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"查詢保留沒有記錄的學生","cn":"查询保留没有记录的学生","en":"Keeping students with no matching records"},"question":{"zh":"老師要列出全班每個學生的答題次數，包括尚未答題者顯示 0。Students 與 Attempts 以 studentId 連結。哪種策略正確？","cn":"老师要列出全班每个学生的答题次数，包括尚未答题者显示 0。Students 与 Attempts 以 studentId 连结。哪种策略正确？","en":"A teacher needs every student's attempt count, including zero for students with no attempts. Students and Attempts link by studentId. Which strategy is correct?"},"options":[{"text":{"zh":"LEFT JOIN 後一律 COUNT(*)，未答題者必為 0。","cn":"LEFT JOIN 后一律 COUNT(*)，未答题者必为 0。","en":"After LEFT JOIN, use COUNT(*) and expect zero for unmatched students."},"correct":false,"feedback":{"zh":"保留的學生列仍算一列，COUNT(*) 可能把無配對列計為 1。","cn":"保留的学生列仍算一列，COUNT(*) 可能把无配对列计为 1。","en":"The preserved student row still exists, so COUNT(*) can count an unmatched row as one."},"id":"a"},{"text":{"zh":"由 Students LEFT JOIN Attempts，按學生分組並 COUNT(Attempts.id)。","cn":"由 Students LEFT JOIN Attempts，按学生分组并 COUNT(Attempts.id)。","en":"LEFT JOIN Attempts from Students, group by student and COUNT(Attempts.id)."},"correct":true,"feedback":{"zh":"LEFT JOIN 保留無配對學生；COUNT 非空 attempt id 可得 0。","cn":"LEFT JOIN 保留无配对学生；COUNT 非空 attempt id 可得 0。","en":"LEFT JOIN retains unmatched students; counting non-null attempt IDs gives zero."},"id":"b"},{"text":{"zh":"只 INNER JOIN，沒有答題者自然會顯示 0。","cn":"只 INNER JOIN，没有答题者自然会显示 0。","en":"Use only INNER JOIN; unmatched students will automatically appear as zero."},"correct":false,"feedback":{"zh":"INNER JOIN 會移除沒有配對答題的學生。","cn":"INNER JOIN 会移除没有配对答题的学生。","en":"INNER JOIN excludes students without matching attempts."},"id":"c"}],"takeaway":{"zh":"查詢的連接方式與計數欄位會改變零記錄個案是否正確保留。","cn":"查询的连接方式与计数栏位会改变零记录个案是否正确保留。","en":"Join type and counted column determine whether zero-record cases are represented correctly."}},{"id":"s6-computer-03","grade":6,"subjectId":"computer","roomId":"computer","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"伺服器授權與最小權限","cn":"伺服器授权与最小权限","en":"Server authorisation and least privilege"},"question":{"zh":"成績網站只在學生畫面隱藏「刪除題目」按鈕，但伺服器接受任何已登入者的刪除請求。最關鍵的修正是甚麼？","cn":"成绩网站只在学生画面隐藏「删除题目」按钮，但伺服器接受任何已登入者的删除请求。最关键的修正是甚么？","en":"A results site hides ‘delete question’ from students, but its server accepts deletion requests from any logged-in user. What is the essential repair?"},"options":[{"text":{"zh":"伺服器只檢查登入工作階段有效，不檢查角色。","cn":"伺服器只检查登入工作阶段有效，不检查角色。","en":"Check only that the server session is valid, without checking role."},"correct":false,"feedback":{"zh":"學生也有有效工作階段；身份驗證不能代替教師操作授權。","cn":"学生也有有效工作阶段；身份验证不能代替教师操作授权。","en":"Students also have valid sessions; authentication does not establish teacher permission."},"id":"a"},{"text":{"zh":"由瀏覽器在請求加入 role=teacher，伺服器相信該值。","cn":"由浏览器在请求加入 role=teacher，伺服器相信该值。","en":"Let the browser send role=teacher and have the server trust it."},"correct":false,"feedback":{"zh":"用戶可以改動請求欄位；角色須由可信的伺服器資料判定。","cn":"用户可以改动请求栏位；角色须由可信的伺服器资料判定。","en":"Users can alter request fields; role must come from trusted server-side records."},"id":"b"},{"text":{"zh":"伺服器逐次核實教師角色及該題庫權限，拒絕未授權操作並記錄變更。","cn":"伺服器逐次核实教师角色及该题库权限，拒绝未授权操作并记录变更。","en":"Check teacher role and bank-specific permission on every server request; reject unauthorised operations and log changes."},"correct":true,"feedback":{"zh":"隱藏介面不是授權；請求可繞過按鈕，權限必須在伺服器驗證。","cn":"隐藏介面不是授权；请求可绕过按钮，权限必须在伺服器验证。","en":"Hiding UI is not authorisation; requests can bypass buttons, so permissions must be checked on the server."},"id":"c"}],"takeaway":{"zh":"身份驗證與操作授權不同；每次敏感操作均須核對適當權限。","cn":"身份验证与操作授权不同；每次敏感操作均须核对适当权限。","en":"Authentication and authorisation differ; check appropriate permission for every sensitive action."}},{"id":"s1-history-01","grade":1,"subjectId":"history","roomId":"history","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"古代事件的先後","cn":"古代事件的先后","en":"Ordering ancient events"},"question":{"zh":"展板列出：甲公元前221年、乙公元前500年、丙公元220年。由最早到最遲應怎樣排列？","cn":"展板列出：甲公元前221年、乙公元前500年、丙公元220年。由最早到最迟应怎样排列？","en":"A display dates A to 221 BCE, B to 500 BCE and C to 220 CE. Which order runs from earliest to latest?"},"options":[{"text":{"zh":"甲→乙→丙","cn":"甲→乙→丙","en":"A → B → C"},"correct":false,"feedback":{"zh":"這把公元前的數字當作公元後順序；公元前500年早於公元前221年。","cn":"这把公元前的数字当作公元后顺序；公元前500年早于公元前221年。","en":"This treats BCE numbering like CE numbering; 500 BCE comes before 221 BCE."},"id":"a"},{"text":{"zh":"丙→甲→乙","cn":"丙→甲→乙","en":"C → A → B"},"correct":false,"feedback":{"zh":"這是由較近至較遠的方向，與題目要求相反。","cn":"这是由较近至较远的方向，与题目要求相反。","en":"This runs towards the more distant past, opposite to the requested order."},"id":"b"},{"text":{"zh":"乙→甲→丙","cn":"乙→甲→丙","en":"B → A → C"},"correct":true,"feedback":{"zh":"公元前年份數字愈大，年代愈早；兩個公元前事件都早於公元220年。","cn":"公元前年份数字愈大，年代愈早；两个公元前事件都早于公元220年。","en":"Larger BCE year numbers are earlier; both BCE events precede 220 CE."},"id":"c"}],"takeaway":{"zh":"排列年代前，先分辨公元前與公元後的計年方向。","cn":"排列年代前，先分辨公元前与公元后的计年方向。","en":"Distinguish BCE and CE before placing events on a timeline."}},{"id":"s1-history-02","grade":1,"subjectId":"history","roomId":"history","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"河流與文明","cn":"河流与文明","en":"Rivers and civilisations"},"question":{"zh":"古埃及農民利用尼羅河氾濫後留下的肥沃泥土耕種。哪條因果鏈最能解釋這項環境條件與定居生活的關係？","cn":"古埃及农民利用尼罗河泛滥后留下的肥沃泥土耕种。哪条因果链最能解释这项环境条件与定居生活的关系？","en":"Ancient Egyptian farmers grew crops in fertile soil left by Nile floods. Which causal chain best links this environment to settled life?"},"options":[{"text":{"zh":"肥沃土壤→較穩定的農業供應→支持定居人口","cn":"肥沃土壤→较稳定的农业供应→支持定居人口","en":"Fertile soil → a more dependable food supply → support for settled communities"},"correct":true,"feedback":{"zh":"農業剩餘有助支持定居人口，但並不代表每年都沒有旱災或饑荒。","cn":"农业剩余有助支持定居人口，但并不代表每年都没有旱灾或饥荒。","en":"Agricultural surplus can support settlement; it does not mean every year was free of drought or famine."},"id":"a"},{"text":{"zh":"河流存在→人人不需工作→城市自然出現","cn":"河流存在→人人不需工作→城市自然出现","en":"A river exists → nobody needs to work → cities appear automatically"},"correct":false,"feedback":{"zh":"河流仍須配合耕作及組織，不會自動提供生活所需。","cn":"河流仍须配合耕作及组织，不会自动提供生活所需。","en":"A river still requires farming and organisation; it does not automatically provide all necessities."},"id":"b"},{"text":{"zh":"洪水→不能耕種→永久放棄河谷","cn":"洪水→不能耕种→永久放弃河谷","en":"Floods → no farming is possible → permanent abandonment of the valley"},"correct":false,"feedback":{"zh":"這忽略題目所述氾濫帶來肥沃土壤的作用。","cn":"这忽略题目所述泛滥带来肥沃土壤的作用。","en":"This ignores the fertile deposits described in the question."},"id":"c"}],"takeaway":{"zh":"歷史因果解釋須指出中間機制，避免把環境視為唯一決定因素。","cn":"历史因果解释须指出中间机制，避免把环境视为唯一决定因素。","en":"Explain the mechanism linking an environment to change, without treating geography as the only cause."}},{"id":"s1-history-03","grade":1,"subjectId":"history","roomId":"history","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"陶片能告訴我們甚麼","cn":"陶片能告诉我们甚么","en":"What can pottery show?"},"question":{"zh":"虛構考古練習：兩個相距很遠、年代相近的聚落出土同類陶器。未有文字記錄。哪項是證據最能支持、但仍需覈查的推論？","cn":"虚构考古练习：两个相距很远、年代相近的聚落出土同类陶器。未有文字记录。哪项是证据最能支持、但仍需核查的推论？","en":"Fictional archaeology exercise: two distant settlements from a similar period contain similar pottery, with no written records. Which inference is best supported but still needs checking?"},"options":[{"text":{"zh":"兩地的人一定說同一種語言","cn":"两地的人一定说同一种语言","en":"Everyone in both places must have spoken the same language"},"correct":false,"feedback":{"zh":"陶器形制不能直接證明使用哪種語言。","cn":"陶器形制不能直接证明使用哪种语言。","en":"Pottery form cannot directly establish the language people spoke."},"id":"a"},{"text":{"zh":"兩地可能有交流，須再比較原料與製作方法","cn":"两地可能有交流，须再比较原料与制作方法","en":"The places may have had contact; compare clay sources and production methods"},"correct":true,"feedback":{"zh":"相似器物可提示交流；原料及工藝比較能檢查貿易、仿製等解釋。","cn":"相似器物可提示交流；原料及工艺比较能检查贸易、仿制等解释。","en":"Similar objects suggest contact; materials and techniques can test trade, imitation and other explanations."},"id":"b"},{"text":{"zh":"兩地一定由同一位君主統治","cn":"两地一定由同一位君主统治","en":"Both places must have had the same ruler"},"correct":false,"feedback":{"zh":"器物相似本身不足以證明政治統治相同。","cn":"器物相似本身不足以证明政治统治相同。","en":"Similar pottery alone cannot establish common political rule."},"id":"c"}],"takeaway":{"zh":"區分器物所顯示的線索與尚未證實的政治或文化結論。","cn":"区分器物所显示的线索与尚未证实的政治或文化结论。","en":"Separate material clues from unproven political or cultural conclusions."}},{"id":"s2-history-01","grade":2,"subjectId":"history","roomId":"history","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"印刷的影響","cn":"印刷的影响","en":"The effects of printing"},"question":{"zh":"研究近代歐洲時，學生比較手抄書與活字印刷。同一篇文字可重複排印，主要直接降低哪項限制？","cn":"研究近代欧洲时，学生比较手抄书与活字印刷。同一篇文字可重复排印，主要直接降低哪项限制？","en":"A class compares manuscripts and movable-type printing in early modern Europe. Reusing type to print the same text most directly reduces which constraint?"},"options":[{"text":{"zh":"每份書都要重新逐字抄寫的時間","cn":"每份书都要重新逐字抄写的时间","en":"The need to copy every book again by hand"},"correct":true,"feedback":{"zh":"重複印製減少每份複本所需的抄寫工作，有助文字流通。","cn":"重复印制减少每份复本所需的抄写工作，有助文字流通。","en":"Repeated printing reduces the copying work per copy and helps texts circulate."},"id":"a"},{"text":{"zh":"讀者必須學習閱讀的需要","cn":"读者必须学习阅读的需要","en":"The need for readers to learn to read"},"correct":false,"feedback":{"zh":"印刷增加書籍供應，卻不會自動令讀者識字。","cn":"印刷增加书籍供应，却不会自动令读者识字。","en":"Printing increases supply but does not automatically make readers literate."},"id":"b"},{"text":{"zh":"所有出版物受到審查的可能性","cn":"所有出版物受到审查的可能性","en":"Every possibility of censorship"},"correct":false,"feedback":{"zh":"生產技術改變不等於審查制度必定消失。","cn":"生产技术改变不等于审查制度必定消失。","en":"A production change does not necessarily remove censorship."},"id":"c"}],"takeaway":{"zh":"分析技術影響時，要分清直接效果與不一定發生的社會結果。","cn":"分析技术影响时，要分清直接效果与不一定发生的社会结果。","en":"Distinguish a technology’s direct effects from social outcomes that are not automatic."}},{"id":"s2-history-02","grade":2,"subjectId":"history","roomId":"history","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"工廠選址的改變","cn":"工厂选址的改变","en":"Changing factory locations"},"question":{"zh":"工業革命課堂模型：甲廠只能用河流水力；乙廠改用燃煤蒸汽機。其他條件相同，乙廠選址的哪項限制最直接減少？","cn":"工业革命课堂模型：甲厂只能用河流水力；乙厂改用燃煤蒸汽机。其他条件相同，乙厂选址的哪项限制最直接减少？","en":"Industrial Revolution classroom model: factory A depends on river power; B uses a coal-fired steam engine. Other conditions equal, which location constraint is most directly reduced for B?"},"options":[{"text":{"zh":"必須有工人操作機器","cn":"必须有工人操作机器","en":"Having workers operate machinery"},"correct":false,"feedback":{"zh":"動力來源改變，並不代表當時工廠完全不需要工人。","cn":"动力来源改变，并不代表当时工厂完全不需要工人。","en":"Changing the power source did not make contemporary factories entirely worker-free."},"id":"a"},{"text":{"zh":"必須靠近合適的急流","cn":"必须靠近合适的急流","en":"Having to be beside a suitable fast-flowing river"},"correct":true,"feedback":{"zh":"蒸汽動力減少對天然流水動力的依賴；燃料及運輸仍然重要。","cn":"蒸汽动力减少对天然流水动力的依赖；燃料及运输仍然重要。","en":"Steam reduces dependence on flowing water for power; fuel and transport still matter."},"id":"b"},{"text":{"zh":"必須考慮燃料運輸","cn":"必须考虑燃料运输","en":"Having to consider fuel transport"},"correct":false,"feedback":{"zh":"燃煤蒸汽機需要燃料，運輸限制不會因此消失。","cn":"燃煤蒸汽机需要燃料，运输限制不会因此消失。","en":"A coal-fired engine needs fuel, so fuel transport remains relevant."},"id":"c"}],"takeaway":{"zh":"用技術所改變的實際條件解釋工業發展，而非假定所有限制都消失。","cn":"用技术所改变的实际条件解释工业发展，而非假定所有限制都消失。","en":"Explain industrial change through the specific constraints a technology alters."}},{"id":"s2-history-03","grade":2,"subjectId":"history","roomId":"history","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"十九世紀香港的兩種記錄","cn":"十九世纪香港的两种记录","en":"Two records of nineteenth-century Hong Kong"},"question":{"zh":"以下為虛構教學資料：一份1890年代商會報告說「港口貿易興旺」；工人的日記說「工時長，住處擠迫」。哪個研究結論最合理？","cn":"以下为虚构教学资料：一份1890年代商会报告说「港口贸易兴旺」；工人的日记说「工时长，住处挤迫」。哪个研究结论最合理？","en":"Fictional teaching sources: an 1890s chamber-of-commerce report says port trade is thriving; a worker’s diary describes long hours and crowded housing. Which conclusion is most reasonable?"},"options":[{"text":{"zh":"日記必然推翻所有貿易增長資料","cn":"日记必然推翻所有贸易增长资料","en":"The diary necessarily disproves all evidence of trade growth"},"correct":false,"feedback":{"zh":"居住及工時資料不會直接否定貿易量增長。","cn":"居住及工时资料不会直接否定贸易量增长。","en":"Housing and working-hour evidence does not directly disprove growing trade."},"id":"a"},{"text":{"zh":"商會報告足以證明所有居民生活改善","cn":"商会报告足以证明所有居民生活改善","en":"The report proves every resident’s life improved"},"correct":false,"feedback":{"zh":"商會的貿易觀點不足以代表所有居民的生活經驗。","cn":"商会的贸易观点不足以代表所有居民的生活经验。","en":"A trade organisation’s account cannot represent every resident’s experience."},"id":"b"},{"text":{"zh":"經濟擴張與工人生活困難可以同時存在","cn":"经济扩张与工人生活困难可以同时存在","en":"Economic expansion and difficult worker living conditions can coexist"},"correct":true,"feedback":{"zh":"兩份資料關注不同層面；經濟總量增長不表示每個羣體同樣受惠。","cn":"两份资料关注不同层面；经济总量增长不表示每个群体同样受惠。","en":"The sources address different dimensions; growth does not mean every group benefits equally."},"id":"c"}],"takeaway":{"zh":"比較不同羣體的材料，可辨識同一發展帶來的不均等經驗。","cn":"比较不同群体的材料，可辨识同一发展带来的不均等经验。","en":"Compare perspectives to recognise uneven experiences within the same historical development."}},{"id":"s3-history-01","grade":3,"subjectId":"history","roomId":"history","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"導火線與長期原因","cn":"导火线与长期原因","en":"Trigger and long-term causes"},"question":{"zh":"第一次世界大戰前，歐洲存在同盟競爭及軍備擴張；1914年薩拉熱窩刺殺事件加劇危機。哪項最能區分兩類因素？","cn":"第一次世界大战前，欧洲存在同盟竞争及军备扩张；1914年萨拉热窝刺杀事件加剧危机。哪项最能区分两类因素？","en":"Before the First World War, Europe experienced alliance rivalry and an arms build-up; the Sarajevo assassination in 1914 intensified the crisis. Which distinction is most useful?"},"options":[{"text":{"zh":"事件發生在最後，所以必定是唯一原因","cn":"事件发生在最后，所以必定是唯一原因","en":"The last event must be the sole cause"},"correct":false,"feedback":{"zh":"時間接近不能證明它足以獨自解釋整場戰爭。","cn":"时间接近不能证明它足以独自解释整场战争。","en":"Being close in time does not make an event a sufficient explanation of the whole war."},"id":"a"},{"text":{"zh":"同盟及軍備屬長期背景；刺殺事件是直接導火線之一","cn":"同盟及军备属长期背景；刺杀事件是直接导火线之一","en":"Alliances and armaments were longer-term conditions; the assassination was an immediate trigger"},"correct":true,"feedback":{"zh":"這能區分累積的緊張與促使危機迅速升級的事件。","cn":"这能区分累积的紧张与促使危机迅速升级的事件。","en":"This distinguishes accumulated tensions from an event that rapidly escalated the crisis."},"id":"b"},{"text":{"zh":"只有先發生的因素纔可能是原因","cn":"只有先发生的因素才可能是原因","en":"Only the earliest factor can be a cause"},"correct":false,"feedback":{"zh":"歷史事件可有長期與短期因素共同作用。","cn":"历史事件可有长期与短期因素共同作用。","en":"Long-term and short-term factors can interact in historical causation."},"id":"c"}],"takeaway":{"zh":"歷史解釋可同時包含結構性背景、促成因素與導火線。","cn":"历史解释可同时包含结构性背景、促成因素与导火线。","en":"Historical explanations can combine structural conditions, contributing factors and triggers."}},{"id":"s3-history-02","grade":3,"subjectId":"history","roomId":"history","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"國際合作的執行問題","cn":"国际合作的执行问题","en":"Enforcing international cooperation"},"question":{"zh":"教學簡化模型：一個戰後國際組織可以譴責侵略，但執行制裁依賴會員合作。若主要會員拒絕合作，最直接的限制是甚麼？","cn":"教学简化模型：一个战后国际组织可以谴责侵略，但执行制裁依赖会员合作。若主要会员拒绝合作，最直接的限制是甚么？","en":"Simplified teaching model: a post-war international organisation can condemn aggression, but sanctions depend on members’ cooperation. If major members refuse, what is the most direct limitation?"},"options":[{"text":{"zh":"組織的所有會議記錄立即失效","cn":"组织的所有会议记录立即失效","en":"Every meeting record immediately becomes invalid"},"correct":false,"feedback":{"zh":"執行困難不會令已存在的會議記錄消失或自動失效。","cn":"执行困难不会令已存在的会议记录消失或自动失效。","en":"Enforcement problems do not erase or automatically invalidate existing records."},"id":"a"},{"text":{"zh":"會員之間不再有任何共同利益","cn":"会员之间不再有任何共同利益","en":"Members no longer share any interests"},"correct":false,"feedback":{"zh":"拒絕某項制裁不足以證明所有合作利益均不存在。","cn":"拒绝某项制裁不足以证明所有合作利益均不存在。","en":"Refusing one sanction does not establish that all shared interests have vanished."},"id":"b"},{"text":{"zh":"決議與實際執行之間出現落差","cn":"决议与实际执行之间出现落差","en":"A gap develops between a resolution and its enforcement"},"correct":true,"feedback":{"zh":"組織能作出決議，不代表自動取得會員提供的執行資源。","cn":"组织能作出决议，不代表自动取得会员提供的执行资源。","en":"Passing a resolution does not automatically secure resources or action from members."},"id":"c"}],"takeaway":{"zh":"分析國際組織時，分辨正式權限、會員意願與執行能力。","cn":"分析国际组织时，分辨正式权限、会员意愿与执行能力。","en":"Distinguish an international organisation’s formal powers, members’ willingness and practical capacity."}},{"id":"s3-history-03","grade":3,"subjectId":"history","roomId":"history","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"戰後就業結構","cn":"战后就业结构","en":"Post-war employment structure"},"question":{"zh":"虛構香港教學數據：1960年製造業佔就業45%、服務業40%；1990年分別25%、65%。數據最直接支持哪項描述？","cn":"虚构香港教学数据：1960年制造业占就业45%、服务业40%；1990年分别25%、65%。数据最直接支持哪项描述？","en":"Fictional Hong Kong teaching data: manufacturing accounts for 45% of employment and services 40% in 1960; in 1990 they account for 25% and 65%. What do the data most directly support?"},"options":[{"text":{"zh":"就業比重由製造業向服務業轉移","cn":"就业比重由制造业向服务业转移","en":"The employment mix shifted from manufacturing towards services"},"correct":true,"feedback":{"zh":"這是比例的變化；沒有總就業數，不能判定製造業人數減少多少。","cn":"这是比例的变化；没有总就业数，不能判定制造业人数减少多少。","en":"This describes changing shares; without total employment, the fall in manufacturing headcount is unknown."},"id":"a"},{"text":{"zh":"製造業就業人數恰好減少20萬","cn":"制造业就业人数恰好减少20万","en":"Manufacturing employment fell by exactly 200,000"},"correct":false,"feedback":{"zh":"百分點變化不能直接轉成人數，還需要兩年的總就業數。","cn":"百分点变化不能直接转成人数，还需要两年的总就业数。","en":"Percentage-point changes cannot give headcounts without the totals for both years."},"id":"b"},{"text":{"zh":"1990年已經沒有製造業","cn":"1990年已经没有制造业","en":"Manufacturing had disappeared by 1990"},"correct":false,"feedback":{"zh":"數據仍列出25%的製造業就業比重。","cn":"数据仍列出25%的制造业就业比重。","en":"The data still show manufacturing at 25% of employment."},"id":"c"}],"takeaway":{"zh":"描述歷史統計時，區分比例、百分點及絕對人數。","cn":"描述历史统计时，区分比例、百分点及绝对人数。","en":"Distinguish shares, percentage points and headcounts when using historical statistics."}},{"id":"s4-history-01","grade":4,"subjectId":"history","roomId":"history","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"革命中的延續","cn":"革命中的延续","en":"Continuity through revolution"},"question":{"zh":"研究1911年後的中國。虛構地方檔案顯示：官署名稱改變，但某縣翌年的主要稅收方式維持。哪句最貼合這兩項證據？","cn":"研究1911年后的中国。虚构地方档案显示：官署名称改变，但某县翌年的主要税收方式维持。哪句最贴合这两项证据？","en":"A study of China after 1911 uses fictional local records: the government office’s name changes, but one county retains its main tax-collection method the next year. Which statement best fits both?"},"options":[{"text":{"zh":"名稱改變證明所有制度立即完全改變","cn":"名称改变证明所有制度立即完全改变","en":"The new name proves every institution changed immediately"},"correct":false,"feedback":{"zh":"名稱是變化證據，卻不能代表所有制度與地方實務。","cn":"名称是变化证据，却不能代表所有制度与地方实务。","en":"A new name is evidence of change, not proof about every institution and local practice."},"id":"a"},{"text":{"zh":"稅收方式延續證明沒有發生任何政治變化","cn":"税收方式延续证明没有发生任何政治变化","en":"Continuity in taxation proves no political change occurred"},"correct":false,"feedback":{"zh":"一項延續不能抹去官署等其他層面的變化。","cn":"一项延续不能抹去官署等其他层面的变化。","en":"One continuity does not erase changes in other dimensions."},"id":"b"},{"text":{"zh":"政治名稱改變，部分地方行政做法仍延續","cn":"政治名称改变，部分地方行政做法仍延续","en":"Political labels changed while some local administrative practices continued"},"correct":true,"feedback":{"zh":"不同層面的變化速度可以不同，兩項證據並不矛盾。","cn":"不同层面的变化速度可以不同，两项证据并不矛盾。","en":"Different dimensions can change at different speeds; the two observations are compatible."},"id":"c"}],"takeaway":{"zh":"以明確層面及時段比較延續與轉變，避免全有或全無的結論。","cn":"以明确层面及时段比较延续与转变，避免全有或全无的结论。","en":"Compare specified dimensions and periods rather than treating change as all-or-nothing."}},{"id":"s4-history-02","grade":4,"subjectId":"history","roomId":"history","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"宣傳海報的用途","cn":"宣传海报的用途","en":"Using a propaganda poster"},"question":{"zh":"虛構1930年代政府海報把工廠畫得整潔繁榮，標語鼓勵加入生產。它最直接適合研究甚麼？","cn":"虚构1930年代政府海报把工厂画得整洁繁荣，标语鼓励加入生产。它最直接适合研究甚么？","en":"A fictional 1930s government poster depicts spotless, thriving factories and urges people to join production. What can it most directly help investigate?"},"options":[{"text":{"zh":"政府希望向公眾塑造的工業形象","cn":"政府希望向公众塑造的工业形象","en":"The industrial image the government wanted to promote"},"correct":true,"feedback":{"zh":"發行者、畫面與呼籲可顯示宣傳目的；不等於實際工廠普查。","cn":"发行者、画面与呼吁可显示宣传目的；不等于实际工厂普查。","en":"Producer, imagery and appeal reveal promotional intent, not a survey of actual factories."},"id":"a"},{"text":{"zh":"每間工廠真實的衛生水平","cn":"每间工厂真实的卫生水平","en":"The actual hygiene level in every factory"},"correct":false,"feedback":{"zh":"理想化宣傳圖像不能直接量度所有工廠的環境。","cn":"理想化宣传图像不能直接量度所有工厂的环境。","en":"Idealised promotional images cannot directly measure conditions in every factory."},"id":"b"},{"text":{"zh":"所有工人對政府的私人態度","cn":"所有工人对政府的私人态度","en":"Every worker’s private attitude to the government"},"correct":false,"feedback":{"zh":"政府發布的海報不是工人的代表性意見調查。","cn":"政府发布的海报不是工人的代表性意见调查。","en":"A government poster is not a representative survey of workers’ views."},"id":"c"}],"takeaway":{"zh":"有立場的史料仍可用；用途須配合它的來源與目的。","cn":"有立场的史料仍可用；用途须配合它的来源与目的。","en":"A partisan source can be useful when the research question fits its origin and purpose."}},{"id":"s4-history-03","grade":4,"subjectId":"history","roomId":"history","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"反證與有限主張","cn":"反证与有限主张","en":"Counter-evidence and a limited claim"},"question":{"zh":"虛構材料：1920年代一份城市婦女雜誌倡議新教育；同年某鄉村入學記錄顯示女童入學仍少。哪項論點能同時處理兩者？","cn":"虚构材料：1920年代一份城市妇女杂志倡议新教育；同年某乡村入学记录显示女童入学仍少。哪项论点能同时处理两者？","en":"Fictional sources: a 1920s urban women’s magazine advocates new education; a rural enrolment record from the same year shows few girls attending school. Which argument accommodates both?"},"options":[{"text":{"zh":"一村女童入學少，所以城市沒有教育改革討論","cn":"一村女童入学少，所以城市没有教育改革讨论","en":"Low enrolment in one village proves cities had no reform debate"},"correct":false,"feedback":{"zh":"局部實況不能否定另一地區已有的公開討論。","cn":"局部实况不能否定另一地区已有的公开讨论。","en":"A local outcome does not disprove documented discussion elsewhere."},"id":"a"},{"text":{"zh":"教育新觀念正在流傳，但實際機會因地區而異","cn":"教育新观念正在流传，但实际机会因地区而异","en":"New educational ideas circulated, but access varied by locality"},"correct":true,"feedback":{"zh":"雜誌反映倡議，入學記錄反映一地實況；兩者不能互相替代。","cn":"杂志反映倡议，入学记录反映一地实况；两者不能互相替代。","en":"The magazine shows advocacy and the register shows local practice; neither substitutes for the other."},"id":"b"},{"text":{"zh":"倡議已出現，所以全國男女已平等入學","cn":"倡议已出现，所以全国男女已平等入学","en":"Advocacy proves equal enrolment nationwide"},"correct":false,"feedback":{"zh":"理念的出現不等於已在所有地方實現。","cn":"理念的出现不等于已在所有地方实现。","en":"The appearance of an ideal does not establish universal implementation."},"id":"c"}],"takeaway":{"zh":"把思想、政策與落實情況分開，按地域及羣體限定主張。","cn":"把思想、政策与落实情况分开，按地域及群体限定主张。","en":"Distinguish ideas, policy and implementation, and qualify claims by place and group."}},{"id":"s5-history-01","grade":5,"subjectId":"history","roomId":"history","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"冷戰材料的措辭","cn":"冷战材料的措辞","en":"Language in Cold War sources"},"question":{"zh":"兩份虛構冷戰報章談同一援助計劃：甲稱「友好合作」，乙稱「擴大勢力」。單看這兩個詞組，可最有把握指出甚麼？","cn":"两份虚构冷战报章谈同一援助计划：甲称「友好合作」，乙称「扩大势力」。单看这两个词组，可最有把握指出甚么？","en":"Two fictional Cold War newspapers describe the same aid programme: A calls it “friendly cooperation”; B calls it “expanding influence”. What can these phrases most securely show?"},"options":[{"text":{"zh":"兩份報章採用不同的評價框架","cn":"两份报章采用不同的评价框架","en":"The newspapers use different evaluative frames"},"correct":true,"feedback":{"zh":"詞語揭示態度差異；要判斷計劃實際效果仍須其他證據。","cn":"词语揭示态度差异；要判断计划实际效果仍须其他证据。","en":"The wording reveals different attitudes; judging actual effects requires further evidence."},"id":"a"},{"text":{"zh":"甲必定掌握較多未公開文件","cn":"甲必定掌握较多未公开文件","en":"A must possess more confidential documents"},"correct":false,"feedback":{"zh":"正面措辭本身不能證明報章有更多內部資料。","cn":"正面措辞本身不能证明报章有更多内部资料。","en":"Positive wording alone cannot establish access to more internal documents."},"id":"b"},{"text":{"zh":"乙所報道的所有數字必然錯誤","cn":"乙所报道的所有数字必然错误","en":"Every numerical claim in B must be false"},"correct":false,"feedback":{"zh":"立場可能影響選材，但不能據此判定每項數字皆錯。","cn":"立场可能影响选材，但不能据此判定每项数字皆错。","en":"A viewpoint may shape selection but does not make every number false."},"id":"c"}],"takeaway":{"zh":"辨認用語立場後，再逐項覈查事實，不把偏向等同全無史料價值。","cn":"辨认用语立场后，再逐项核查事实，不把偏向等同全无史料价值。","en":"Identify framing, then test factual claims individually rather than dismissing an entire source."}},{"id":"s5-history-02","grade":5,"subjectId":"history","roomId":"history","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"口述歷史的追問","cn":"口述历史的追问","en":"Following up oral history"},"question":{"zh":"一位受訪者在1980年回憶1950年的遷居：「大家都是為了工作而來。」哪個追問最能改善這項證據的可用性？","cn":"一位受访者在1980年回忆1950年的迁居：「大家都是为了工作而来。」哪个追问最能改善这项证据的可用性？","en":"In 1980, an interviewee recalls a move in 1950: “Everyone came for work.” Which follow-up best improves the evidence?"},"options":[{"text":{"zh":"我們已知只有工作因素，你同意嗎？","cn":"我们已知只有工作因素，你同意吗？","en":"We know work was the only factor; do you agree?"},"correct":false,"feedback":{"zh":"這是引導式提問，容易壓縮或扭曲受訪者的原有經驗。","cn":"这是引导式提问，容易压缩或扭曲受访者的原有经验。","en":"This leading question may narrow or distort the interviewee’s account."},"id":"a"},{"text":{"zh":"你當時親自認識哪些遷居者？他們還提過甚麼原因？","cn":"你当时亲自认识哪些迁居者？他们还提过甚么原因？","en":"Which migrants did you know personally, and what other reasons did they mention?"},"correct":true,"feedback":{"zh":"追問經驗範圍及其他動機，可檢查「大家」這個概括。","cn":"追问经验范围及其他动机，可检查「大家」这个概括。","en":"This establishes the scope of direct experience and tests the generalisation “everyone”."},"id":"b"},{"text":{"zh":"可否把答案說得更有信心？","cn":"可否把答案说得更有信心？","en":"Could you say that more confidently?"},"correct":false,"feedback":{"zh":"語氣更堅定不會增加記憶或樣本的可靠性。","cn":"语气更坚定不会增加记忆或样本的可靠性。","en":"Greater confidence does not improve the evidence’s memory accuracy or coverage."},"id":"c"}],"takeaway":{"zh":"口述史追問應釐清接觸範圍、時間與記憶，而非誘導預定答案。","cn":"口述史追问应厘清接触范围、时间与记忆，而非诱导预定答案。","en":"Use oral-history follow-ups to clarify scope, timing and memory without steering the answer."}},{"id":"s5-history-03","grade":5,"subjectId":"history","roomId":"history","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"比較不等於因果","cn":"比较不等于因果","en":"Comparison is not causation"},"question":{"zh":"虛構1960年代數據：甲地出口增長快且擴建港口；乙地出口增長慢且沒有擴建。兩地同時在教育及市場准入上不同。哪個結論最嚴謹？","cn":"虚构1960年代数据：甲地出口增长快且扩建港口；乙地出口增长慢且没有扩建。两地同时在教育及市场准入上不同。哪个结论最严谨？","en":"Fictional 1960s data: region A expands its port and exports grow rapidly; B does neither. They also differ in education and market access. Which conclusion is most defensible?"},"options":[{"text":{"zh":"出口差距完全由港口擴建造成","cn":"出口差距完全由港口扩建造成","en":"Port expansion entirely caused the export gap"},"correct":false,"feedback":{"zh":"這忽略已知的教育及市場條件等其他解釋。","cn":"这忽略已知的教育及市场条件等其他解释。","en":"This ignores known alternatives involving education and market access."},"id":"a"},{"text":{"zh":"存在其他因素，所以港口絕對不可能有影響","cn":"存在其他因素，所以港口绝对不可能有影响","en":"Other factors mean the port could have had no effect"},"correct":false,"feedback":{"zh":"其他原因的存在不會排除港口作為共同因素。","cn":"其他原因的存在不会排除港口作为共同因素。","en":"Other causes do not exclude the port as a contributing factor."},"id":"b"},{"text":{"zh":"港口可能有作用，但須比較其他差異及擴建時間","cn":"港口可能有作用，但须比较其他差异及扩建时间","en":"The port may matter, but other differences and the timing of expansion must be examined"},"correct":true,"feedback":{"zh":"多項條件同時不同，單一比較不足以隔離港口的效果。","cn":"多项条件同时不同，单一比较不足以隔离港口的效果。","en":"Several conditions differ, so one comparison cannot isolate the port’s effect."},"id":"c"}],"takeaway":{"zh":"多因解釋應比較機制、時序及替代因素，而非只找單一相關性。","cn":"多因解释应比较机制、时序及替代因素，而非只找单一相关性。","en":"Evaluate mechanisms, timing and alternatives when constructing a multi-causal explanation."}},{"id":"s6-history-01","grade":6,"subjectId":"history","roomId":"history","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"三篇報道是否三份證據","cn":"三篇报道是否三份证据","en":"Are three reports three independent sources?"},"question":{"zh":"三份虛構1956年報章報道同一罷工，都註明轉載同一家通訊社。研究者說「已有三個獨立見證」。問題在哪裏？","cn":"三份虚构1956年报章报道同一罢工，都注明转载同一家通讯社。研究者说「已有三个独立见证」。问题在哪里？","en":"Three fictional 1956 newspapers report the same strike and credit one news agency. A researcher calls them “three independent witnesses”. What is the problem?"},"options":[{"text":{"zh":"只要文字相同，事件必定沒有發生","cn":"只要文字相同，事件必定没有发生","en":"Identical wording proves the event never happened"},"correct":false,"feedback":{"zh":"文字共源影響獨立性，不會自行證明事件虛構。","cn":"文字共源影响独立性，不会自行证明事件虚构。","en":"Shared wording affects independence, not whether the event happened."},"id":"a"},{"text":{"zh":"三篇可能共用一個原始消息來源","cn":"三篇可能共用一个原始消息来源","en":"The reports may share one underlying source"},"correct":true,"feedback":{"zh":"出版於三份報章不等於三次獨立觀察；須追查資料來源。","cn":"出版于三份报章不等于三次独立观察；须追查资料来源。","en":"Three publications do not establish three independent observations; trace their source."},"id":"b"},{"text":{"zh":"報章不能用作任何歷史研究","cn":"报章不能用作任何历史研究","en":"Newspapers cannot be used in any historical research"},"correct":false,"feedback":{"zh":"報章可作史料；本題限制是來源重複，並非媒介完全無用。","cn":"报章可作史料；本题限制是来源重复，并非媒介完全无用。","en":"Newspapers can be evidence; the issue is duplicated sourcing, not a useless medium."},"id":"c"}],"takeaway":{"zh":"證據的數量須連同來源獨立性評估。","cn":"证据的数量须连同来源独立性评估。","en":"Assess the number of sources together with their independence."}},{"id":"s6-history-02","grade":6,"subjectId":"history","roomId":"history","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"總量與分配的歷史解釋","cn":"总量与分配的历史解释","en":"Historical totals and distribution"},"question":{"zh":"虛構戰後研究：全地區平均實質工資上升，某個工人家庭的日記卻記載生活惡化。哪種處理最合理？","cn":"虚构战后研究：全地区平均实质工资上升，某个工人家庭的日记却记载生活恶化。哪种处理最合理？","en":"Fictional post-war research shows rising regional average real wages, while one worker’s family diary describes worsening living conditions. What is the best response?"},"options":[{"text":{"zh":"刪除日記，因為統計必定適用每個人","cn":"删除日记，因为统计必定适用每个人","en":"Discard the diary because the average applies to everyone"},"correct":false,"feedback":{"zh":"平均值不代表所有家庭都出現同樣變化。","cn":"平均值不代表所有家庭都出现同样变化。","en":"An average does not imply the same change for every household."},"id":"a"},{"text":{"zh":"只保留日記，因為個案足以推翻全區平均","cn":"只保留日记，因为个案足以推翻全区平均","en":"Keep only the diary because one case disproves the regional average"},"correct":false,"feedback":{"zh":"個案可揭示差異，但本身不能計算或推翻全區平均。","cn":"个案可揭示差异，但本身不能计算或推翻全区平均。","en":"A case can reveal variation but cannot by itself calculate or disprove the regional average."},"id":"b"},{"text":{"zh":"核對家庭收入、就業狀況與開支，檢查平均值掩蓋的差異","cn":"核对家庭收入、就业状况与开支，检查平均值掩盖的差异","en":"Examine the household’s income, employment and expenses for differences hidden by the average"},"correct":true,"feedback":{"zh":"總體平均與個案可同時成立，家庭結構及收入分配值得調查。","cn":"总体平均与个案可同时成立，家庭结构及收入分配值得调查。","en":"An average and an individual case can both be accurate; household circumstances and distribution matter."},"id":"c"}],"takeaway":{"zh":"綜合宏觀與個人史料，先檢查它們是否回答相同層面的問題。","cn":"综合宏观与个人史料，先检查它们是否回答相同层面的问题。","en":"When synthesising aggregate and personal sources, check whether they address the same level of analysis."}},{"id":"s6-history-03","grade":6,"subjectId":"history","roomId":"history","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"有條件的歷史結論","cn":"有条件的历史结论","en":"A qualified historical conclusion"},"question":{"zh":"虛構改革資料：法令在1905年頒布，1907年只有首都執行，1912年才擴至多個省份。哪句最適合作研究結論？","cn":"虚构改革资料：法令在1905年颁布，1907年只有首都执行，1912年才扩至多个省份。哪句最适合作研究结论？","en":"Fictional reform evidence: a law is issued in 1905, implemented only in the capital in 1907, and extended to several provinces in 1912. Which conclusion best fits?"},"options":[{"text":{"zh":"1905年是法律起點，實際推行分階段且地域不均","cn":"1905年是法律起点，实际推行分阶段且地域不均","en":"1905 marks the legal beginning, while implementation was phased and geographically uneven"},"correct":true,"feedback":{"zh":"結論同時處理頒布、落實時差及地域差異，沒有超出證據。","cn":"结论同时处理颁布、落实时差及地域差异，没有超出证据。","en":"This accounts for enactment, implementation delays and regional variation without exceeding the evidence."},"id":"a"},{"text":{"zh":"改革在1905年已於全國完成","cn":"改革在1905年已于全国完成","en":"The reform was complete nationwide in 1905"},"correct":false,"feedback":{"zh":"法令日期不能當作所有地區完成實施的日期。","cn":"法令日期不能当作所有地区完成实施的日期。","en":"The law’s date is not the date of full implementation everywhere."},"id":"b"},{"text":{"zh":"1912年前沒有任何改革發生","cn":"1912年前没有任何改革发生","en":"No reform occurred before 1912"},"correct":false,"feedback":{"zh":"1905年的頒布及1907年的首都執行都是較早的變化。","cn":"1905年的颁布及1907年的首都执行都是较早的变化。","en":"Enactment in 1905 and implementation in the capital in 1907 were earlier changes."},"id":"c"}],"takeaway":{"zh":"高質素歷史論證以證據限定起點、範圍及變化程度。","cn":"高质素历史论证以证据限定起点、范围及变化程度。","en":"A strong historical argument qualifies its timing, scope and degree of change with evidence."}},{"id":"s1-art-01","grade":1,"subjectId":"art","roomId":"art","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"線條的方向感","cn":"线条的方向感","en":"Directional lines"},"question":{"zh":"一幅畫用多條斜線帶領視線向右上方移動。哪個描述直接指出所用的視覺元素？","cn":"一幅画用多条斜线带领视线向右上方移动。哪个描述直接指出所用的视觉元素？","en":"A drawing uses repeated diagonal lines to lead the eye upwards and right. Which description identifies the visual element?"},"options":[{"text":{"zh":"線條的方向與重複","cn":"线条的方向与重复","en":"Direction and repetition of lines"},"correct":true,"feedback":{"zh":"斜線及其重複形成視覺動勢。","cn":"斜线及其重复形成视觉动势。","en":"Repeated diagonals create directional movement."},"id":"a"},{"text":{"zh":"色彩的冷暖對比","cn":"色彩的冷暖对比","en":"Warm–cool colour contrast"},"correct":false,"feedback":{"zh":"題目描述斜線的方向，沒有提供色彩冷暖資料。","cn":"题目描述斜线的方向，没有提供色彩冷暖资料。","en":"The prompt describes diagonal direction, not warm or cool colours."},"id":"b"},{"text":{"zh":"形狀的左右對稱","cn":"形状的左右对称","en":"Left–right symmetry of shapes"},"correct":false,"feedback":{"zh":"對稱關乎兩側對應，不能直接描述斜線引導視線的作用。","cn":"对称关乎两侧对应，不能直接描述斜线引导视线的作用。","en":"Symmetry concerns correspondence across sides, not the stated directional effect."},"id":"c"}],"takeaway":{"zh":"描述作品時，先指出可觀察的視覺元素及效果。","cn":"描述作品时，先指出可观察的视觉元素及效果。","en":"Describe observable visual elements and their effects."}},{"id":"s1-art-02","grade":1,"subjectId":"art","roomId":"art","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"主體與負空間","cn":"主体与负空间","en":"Subject and negative space"},"question":{"zh":"要畫出兩個杯子之間空隙的形狀，你應集中觀察甚麼？","cn":"要画出两个杯子之间空隙的形状，你应集中观察甚么？","en":"To draw the shape of the gap between two cups, what should you observe?"},"options":[{"text":{"zh":"只記住一般杯子的符號畫法","cn":"只记住一般杯子的符号画法","en":"Only a memorised symbol for a cup"},"correct":false,"feedback":{"zh":"套用符號容易忽略眼前實際的間距及輪廓。","cn":"套用符号容易忽略眼前实际的间距及轮廓。","en":"A memorised symbol may miss the actual spacing and contours."},"id":"a"},{"text":{"zh":"由杯子外緣界定的空白形狀","cn":"由杯子外缘界定的空白形状","en":"The empty shape bounded by the cups’ edges"},"correct":true,"feedback":{"zh":"負空間是主體周圍或之間的空間，也有可觀察形狀。","cn":"负空间是主体周围或之间的空间，也有可观察形状。","en":"Negative space around or between subjects has an observable shape."},"id":"b"},{"text":{"zh":"杯子內部能盛多少水","cn":"杯子内部能盛多少水","en":"How much water the cups hold"},"correct":false,"feedback":{"zh":"容量並不是杯子之間空隙的外形。","cn":"容量并不是杯子之间空隙的外形。","en":"Capacity does not describe the gap between the cups."},"id":"c"}],"takeaway":{"zh":"同時觀察主體與負空間，有助檢查比例及位置。","cn":"同时观察主体与负空间，有助检查比例及位置。","en":"Observing both the subject and negative space helps check proportion and placement."}},{"id":"s1-art-03","grade":1,"subjectId":"art","roomId":"art","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"低彩度中的焦點","cn":"低彩度中的焦点","en":"A focal point in muted colours"},"question":{"zh":"海報大部分用低彩度灰綠色，只有中央一朵花用鮮橙色。哪個理由最能解釋花為何突出？","cn":"海报大部分用低彩度灰绿色，只有中央一朵花用鲜橙色。哪个理由最能解释花为何突出？","en":"A poster is mostly muted grey-green, with one bright orange flower in the centre. Why does the flower stand out?"},"options":[{"text":{"zh":"橙色物件在所有作品中必定最大","cn":"橙色物件在所有作品中必定最大","en":"Orange objects must be the largest in every artwork"},"correct":false,"feedback":{"zh":"顏色不會決定物件的實際大小。","cn":"颜色不会决定物件的实际大小。","en":"Colour does not determine an object’s size."},"id":"a"},{"text":{"zh":"中央位置令顏色完全沒有作用","cn":"中央位置令颜色完全没有作用","en":"A central position makes colour irrelevant"},"correct":false,"feedback":{"zh":"位置與色彩可以共同建立焦點。","cn":"位置与色彩可以共同建立焦点。","en":"Position and colour can work together to establish focus."},"id":"b"},{"text":{"zh":"花與背景的彩度及色相形成對比","cn":"花与背景的彩度及色相形成对比","en":"Its saturation and hue contrast with the background"},"correct":true,"feedback":{"zh":"鮮明程度及顏色差異使視線容易集中在花。","cn":"鲜明程度及颜色差异使视线容易集中在花。","en":"Differences in vividness and hue draw attention to the flower."},"id":"c"}],"takeaway":{"zh":"解釋焦點時，要連結具體對比與觀者的視線。","cn":"解释焦点时，要连结具体对比与观者的视线。","en":"Explain a focal point by connecting a specific contrast to the viewer’s attention."}},{"id":"s2-art-01","grade":2,"subjectId":"art","roomId":"art","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"互補色的配搭","cn":"互补色的配搭","en":"Complementary colour pairing"},"question":{"zh":"本題使用傳統紅、黃、藍色輪；色輪上藍色的對面是橙色。哪組屬互補色？","cn":"本题使用传统红、黄、蓝色轮；色轮上蓝色的对面是橙色。哪组属互补色？","en":"Use a traditional red-yellow-blue colour wheel, where orange is opposite blue. Which pair is complementary?"},"options":[{"text":{"zh":"藍與淺藍","cn":"蓝与浅蓝","en":"Blue and light blue"},"correct":false,"feedback":{"zh":"這是同一色相的明度變化，不是相對色相。","cn":"这是同一色相的明度变化，不是相对色相。","en":"These differ in value within one hue, rather than being opposite hues."},"id":"a"},{"text":{"zh":"藍與橙","cn":"蓝与橙","en":"Blue and orange"},"correct":true,"feedback":{"zh":"互補色位於此色輪的相對位置。","cn":"互补色位于此色轮的相对位置。","en":"Complementary colours occupy opposite positions on this wheel."},"id":"b"},{"text":{"zh":"藍與藍綠","cn":"蓝与蓝绿","en":"Blue and blue-green"},"correct":false,"feedback":{"zh":"這兩色相鄰，屬近似色關係。","cn":"这两色相邻，属近似色关系。","en":"These are neighbouring, analogous colours."},"id":"c"}],"takeaway":{"zh":"色彩判斷須說明所用色輪，分辨色相、明度與彩度。","cn":"色彩判断须说明所用色轮，分辨色相、明度与彩度。","en":"Specify the colour model and distinguish hue, value and saturation."}},{"id":"s2-art-02","grade":2,"subjectId":"art","roomId":"art","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"版印的左右反轉","cn":"版印的左右反转","en":"Reversal in printing"},"question":{"zh":"把字母R刻在印版上，想印出方向正常的R。印版上的字母應如何安排？","cn":"把字母R刻在印版上，想印出方向正常的R。印版上的字母应如何安排？","en":"You carve the letter R into a block and want the printed R to face normally. How should it appear on the block?"},"options":[{"text":{"zh":"保持正常方向","cn":"保持正常方向","en":"Keep it in its normal orientation"},"correct":false,"feedback":{"zh":"這樣印在紙上會得到反轉的R。","cn":"这样印在纸上会得到反转的R。","en":"This would produce a reversed R on the paper."},"id":"a"},{"text":{"zh":"只把字母放大","cn":"只把字母放大","en":"Only enlarge the letter"},"correct":false,"feedback":{"zh":"放大會改變大小，不能處理方向反轉。","cn":"放大会改变大小，不能处理方向反转。","en":"Enlargement changes size, not orientation."},"id":"b"},{"text":{"zh":"先左右鏡像反轉","cn":"先左右镜像反转","en":"Reverse it left to right first"},"correct":true,"feedback":{"zh":"印版接觸紙張時，圖像左右方向會反轉。","cn":"印版接触纸张时，图像左右方向会反转。","en":"The printed impression reverses the image left to right."},"id":"c"}],"takeaway":{"zh":"瞭解媒材的操作特性，再規劃圖像。","cn":"了解媒材的操作特性，再规划图像。","en":"Plan an image around the working properties of its medium."}},{"id":"s2-art-03","grade":2,"subjectId":"art","roomId":"art","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"不用加字的空間感","cn":"不用加字的空间感","en":"Creating depth without a label"},"question":{"zh":"畫面中甲樹擋住乙樹一部分，甲樹亦畫得較大。若兩棵真樹大小相近，觀者通常會怎樣理解？","cn":"画面中甲树挡住乙树一部分，甲树亦画得较大。若两棵真树大小相近，观者通常会怎样理解？","en":"Tree A partly overlaps tree B and is drawn larger. If the real trees are similar in size, how will viewers usually read this?"},"options":[{"text":{"zh":"甲樹較靠近觀者","cn":"甲树较靠近观者","en":"A is closer to the viewer"},"correct":true,"feedback":{"zh":"重疊與相對大小共同提供前後距離線索。","cn":"重叠与相对大小共同提供前后距离线索。","en":"Overlap and relative size jointly suggest depth."},"id":"a"},{"text":{"zh":"乙樹一定位於甲樹內部","cn":"乙树一定位于甲树内部","en":"B must be inside A"},"correct":false,"feedback":{"zh":"被遮擋部分不表示一物位於另一物內部。","cn":"被遮挡部分不表示一物位于另一物内部。","en":"Partial occlusion does not imply one object is inside another."},"id":"b"},{"text":{"zh":"兩棵樹必定位於同一平面","cn":"两棵树必定位于同一平面","en":"Both trees must lie on the same plane"},"correct":false,"feedback":{"zh":"題目提供的重疊與大小線索通常指向不同深度。","cn":"题目提供的重叠与大小线索通常指向不同深度。","en":"The overlap and size cues usually suggest different depths."},"id":"c"}],"takeaway":{"zh":"空間感可由重疊、相對大小及位置等線索共同建立。","cn":"空间感可由重叠、相对大小及位置等线索共同建立。","en":"Depth can be constructed through overlap, relative size and placement."}},{"id":"s3-art-01","grade":3,"subjectId":"art","roomId":"art","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"閱讀次序","cn":"阅读次序","en":"Reading hierarchy"},"question":{"zh":"展覽海報要讓人先讀活動名稱，再看日期，最後看報名細節。哪個安排最符合目的？","cn":"展览海报要让人先读活动名称，再看日期，最后看报名细节。哪个安排最符合目的？","en":"An exhibition poster should lead readers from title to date to registration details. Which arrangement best serves this?"},"options":[{"text":{"zh":"全部字體同大，字距全部收窄","cn":"全部字体同大，字距全部收窄","en":"Use one size and tightly pack all text"},"correct":false,"feedback":{"zh":"缺乏層次及間距會增加尋找重點的負擔。","cn":"缺乏层次及间距会增加寻找重点的负担。","en":"Lack of hierarchy and spacing makes key information harder to find."},"id":"a"},{"text":{"zh":"把日期放在最不顯眼的裝飾內","cn":"把日期放在最不显眼的装饰内","en":"Hide the date inside a minor decoration"},"correct":false,"feedback":{"zh":"日期是第二重要資訊，不能靠隱藏達成清楚次序。","cn":"日期是第二重要资讯，不能靠隐藏达成清楚次序。","en":"The second-priority information should not be hidden."},"id":"b"},{"text":{"zh":"標題最突出，日期次之，細節分組並保留間距","cn":"标题最突出，日期次之，细节分组并保留间距","en":"Emphasise the title, then the date, grouping details with spacing"},"correct":true,"feedback":{"zh":"大小、位置及留白共同建立資訊層次。","cn":"大小、位置及留白共同建立资讯层次。","en":"Scale, position and spacing establish an information hierarchy."},"id":"c"}],"takeaway":{"zh":"視覺層次須配合資訊優先次序及使用情境。","cn":"视觉层次须配合资讯优先次序及使用情境。","en":"Match visual hierarchy to information priorities and the viewing context."}},{"id":"s3-art-02","grade":3,"subjectId":"art","roomId":"art","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"灰階後仍可讀","cn":"灰阶后仍可读","en":"Readable in greyscale"},"question":{"zh":"校園地圖以紅色和綠色區分兩條路線，影印成灰階後難以分辨。哪項修改最有效保留區分？","cn":"校园地图以红色和绿色区分两条路线，影印成灰阶后难以分辨。哪项修改最有效保留区分？","en":"A campus map distinguishes routes in red and green, but they merge in a greyscale photocopy. Which change best preserves the distinction?"},"options":[{"text":{"zh":"一條用實線，一條用虛線，兩者加路線名稱","cn":"一条用实线，一条用虚线，两者加路线名称","en":"Use solid and dashed lines and label both routes"},"correct":true,"feedback":{"zh":"線型及文字提供不依靠顏色的資訊。","cn":"线型及文字提供不依靠颜色的资讯。","en":"Line patterns and labels provide information independently of colour."},"id":"a"},{"text":{"zh":"把紅綠都換成相近深淺的藍色","cn":"把红绿都换成相近深浅的蓝色","en":"Replace both with blue shades of similar value"},"correct":false,"feedback":{"zh":"相近灰階明度仍可能難以區分。","cn":"相近灰阶明度仍可能难以区分。","en":"Similar values may still be indistinguishable in greyscale."},"id":"b"},{"text":{"zh":"只把地圖外框加粗","cn":"只把地图外框加粗","en":"Only thicken the map’s outer border"},"correct":false,"feedback":{"zh":"外框不會改變兩條路線的辨識線索。","cn":"外框不会改变两条路线的辨识线索。","en":"The border does not distinguish the routes."},"id":"c"}],"takeaway":{"zh":"重要資訊應以多於一種視覺線索傳達。","cn":"重要资讯应以多于一种视觉线索传达。","en":"Communicate essential information through more than one visual cue."}},{"id":"s3-art-03","grade":3,"subjectId":"art","roomId":"art","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"對稱不等於唯一平衡","cn":"对称不等于唯一平衡","en":"Balance beyond symmetry"},"question":{"zh":"構圖左邊有一塊大型淡灰形狀，右邊有一小塊濃黑形狀。評估是否平衡，哪個說法最恰當？","cn":"构图左边有一块大型淡灰形状，右边有一小块浓黑形状。评估是否平衡，哪个说法最恰当？","en":"A composition has a large pale-grey shape on the left and a small black shape on the right. Which approach best evaluates balance?"},"options":[{"text":{"zh":"只要有黑色，其他元素就完全不影響","cn":"只要有黑色，其他元素就完全不影响","en":"Once black appears, other elements have no influence"},"correct":false,"feedback":{"zh":"面積、距離及其他視覺元素仍會共同影響效果。","cn":"面积、距离及其他视觉元素仍会共同影响效果。","en":"Area, distance and other elements still contribute."},"id":"a"},{"text":{"zh":"比較面積、明暗、位置產生的視覺重量","cn":"比较面积、明暗、位置产生的视觉重量","en":"Compare the visual weight created by area, value and position"},"correct":true,"feedback":{"zh":"小而濃黑的形狀也可有較強視覺重量，平衡不只看面積。","cn":"小而浓黑的形状也可有较强视觉重量，平衡不只看面积。","en":"A small dark shape may carry strong visual weight; area is not the only factor."},"id":"b"},{"text":{"zh":"只要兩邊面積不同，就必定失衡","cn":"只要两边面积不同，就必定失衡","en":"Different areas always mean imbalance"},"correct":false,"feedback":{"zh":"非對稱構圖亦可透過不同因素取得平衡。","cn":"非对称构图亦可透过不同因素取得平衡。","en":"Asymmetrical compositions can balance through different factors."},"id":"c"}],"takeaway":{"zh":"以視覺重量解釋構圖，而非只套用左右相等的規則。","cn":"以视觉重量解释构图，而非只套用左右相等的规则。","en":"Analyse balance through visual weight rather than simply requiring equal sides."}},{"id":"s4-art-01","grade":4,"subjectId":"art","roomId":"art","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"媒材與表達","cn":"媒材与表达","en":"Medium and expression"},"question":{"zh":"創作目標是表現邊緣逐漸消散的霧。哪個水彩操作最直接配合此目標？","cn":"创作目标是表现边缘逐渐消散的雾。哪个水彩操作最直接配合此目标？","en":"The artistic aim is to suggest mist with gradually dissolving edges. Which watercolour method most directly supports it?"},"options":[{"text":{"zh":"在濕紙上加水彩，讓色彩柔和擴散","cn":"在湿纸上加水彩，让色彩柔和扩散","en":"Apply watercolour to wet paper for soft spreading edges"},"correct":true,"feedback":{"zh":"濕畫法可產生柔和滲化，切合題目的邊緣效果。","cn":"湿画法可产生柔和渗化，切合题目的边缘效果。","en":"Wet-on-wet can produce soft diffusion matching the stated aim."},"id":"a"},{"text":{"zh":"每個色塊都先用防水黑線封邊","cn":"每个色块都先用防水黑线封边","en":"Outline every area with waterproof black lines"},"correct":false,"feedback":{"zh":"清楚硬邊通常削弱題目要求的消散感。","cn":"清楚硬边通常削弱题目要求的消散感。","en":"Strong hard outlines usually work against dissolving edges."},"id":"b"},{"text":{"zh":"在乾紙上用少水顏料畫出清晰邊界","cn":"在干纸上用少水颜料画出清晰边界","en":"Use concentrated paint on dry paper for crisp boundaries"},"correct":false,"feedback":{"zh":"清楚乾燥的邊界較難呈現題目指定的柔和消散。","cn":"清楚干燥的边界较难呈现题目指定的柔和消散。","en":"Crisp dry edges work against the requested soft diffusion."},"id":"c"}],"takeaway":{"zh":"媒材技巧應有明確表達目的，而非以昂貴程度判斷效果。","cn":"媒材技巧应有明确表达目的，而非以昂贵程度判断效果。","en":"Choose techniques for their expressive purpose, not their cost."}},{"id":"s4-art-02","grade":4,"subjectId":"art","roomId":"art","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"詮釋與作品脈絡","cn":"诠释与作品脉络","en":"Interpretation and context"},"question":{"zh":"一件虛構作品用舊車票拼成路線；作者說主題是家人每天往返兩區的生活。哪段評論結合了形式與脈絡？","cn":"一件虚构作品用旧车票拼成路线；作者说主题是家人每天往返两区的生活。哪段评论结合了形式与脉络？","en":"A fictional artwork arranges used tickets into routes. The artist links it to family journeys between two districts. Which comment connects form and context?"},"options":[{"text":{"zh":"作者有家庭，所以作品不需要視覺分析","cn":"作者有家庭，所以作品不需要视觉分析","en":"The artist has a family, so visual analysis is unnecessary"},"correct":false,"feedback":{"zh":"脈絡不能代替對作品形式及材料的分析。","cn":"脉络不能代替对作品形式及材料的分析。","en":"Context does not replace analysis of form and materials."},"id":"a"},{"text":{"zh":"重複車票及交錯路線呼應日常移動與家庭經驗","cn":"重复车票及交错路线呼应日常移动与家庭经验","en":"Repeated tickets and intersecting routes echo everyday movement and family experience"},"correct":true,"feedback":{"zh":"評論把可見材料、組織方式及已提供脈絡連起來。","cn":"评论把可见材料、组织方式及已提供脉络连起来。","en":"This links visible materials and organisation with the stated context."},"id":"b"},{"text":{"zh":"所有舊物必然只代表懷舊","cn":"所有旧物必然只代表怀旧","en":"All old objects can only mean nostalgia"},"correct":false,"feedback":{"zh":"這把單一象徵套在所有作品，忽略本作資料。","cn":"这把单一象征套在所有作品，忽略本作资料。","en":"This imposes one meaning on every work and ignores the supplied context."},"id":"c"}],"takeaway":{"zh":"有根據的詮釋連結可見特徵、材料及具體脈絡。","cn":"有根据的诠释连结可见特征、材料及具体脉络。","en":"Support interpretation with visible features, materials and specific context."}},{"id":"s4-art-03","grade":4,"subjectId":"art","roomId":"art","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"策展中的對話","cn":"策展中的对话","en":"Dialogue between exhibits"},"question":{"zh":"展覽主題是「城市的節奏」。甲作以規律重複窗格呈現秩序；乙作以不規則街道線條呈現變化。哪段並置說明最貼題？","cn":"展览主题是「城市的节奏」。甲作以规律重复窗格呈现秩序；乙作以不规则街道线条呈现变化。哪段并置说明最贴题？","en":"An exhibition explores “urban rhythms”. Work A repeats window grids regularly; B uses irregular street lines. Which explanation best justifies showing them together?"},"options":[{"text":{"zh":"只因兩幅作品大小相同","cn":"只因两幅作品大小相同","en":"Only because both works have the same size"},"correct":false,"feedback":{"zh":"尺寸方便陳列，但不足以解釋主題關係。","cn":"尺寸方便陈列，但不足以解释主题关系。","en":"Similar dimensions help installation but do not explain the thematic relationship."},"id":"a"},{"text":{"zh":"乙作必然比甲作更真實","cn":"乙作必然比甲作更真实","en":"B must be more truthful than A"},"correct":false,"feedback":{"zh":"不規則形式本身不能證明作品較真實。","cn":"不规则形式本身不能证明作品较真实。","en":"Irregular form alone does not establish greater truthfulness."},"id":"b"},{"text":{"zh":"兩作以不同節奏處理城市秩序與變化，形成對照","cn":"两作以不同节奏处理城市秩序与变化，形成对照","en":"Their contrasting rhythms explore urban order and change"},"correct":true,"feedback":{"zh":"策展理由同時回應主題及兩作的具體形式差異。","cn":"策展理由同时回应主题及两作的具体形式差异。","en":"The rationale connects the theme to specific formal differences."},"id":"c"}],"takeaway":{"zh":"策展選擇須說明作品之間如何共同建立意義。","cn":"策展选择须说明作品之间如何共同建立意义。","en":"Explain how relationships between works contribute to an exhibition’s meaning."}},{"id":"s5-art-01","grade":5,"subjectId":"art","roomId":"art","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"過程記錄的價值","cn":"过程记录的价值","en":"The value of process records"},"question":{"zh":"作品集保留三次草圖、修改註解及試材照片。這些資料最直接展示甚麼？","cn":"作品集保留三次草图、修改注解及试材照片。这些资料最直接展示甚么？","en":"A portfolio retains three sketches, revision notes and material tests. What do they most directly demonstrate?"},"options":[{"text":{"zh":"每次修改都一定比前次更好","cn":"每次修改都一定比前次更好","en":"That every revision was necessarily an improvement"},"correct":false,"feedback":{"zh":"試驗也可能失敗；記錄有助說明如何從中學習。","cn":"试验也可能失败；记录有助说明如何从中学习。","en":"Experiments may fail; recording them can show what was learned."},"id":"a"},{"text":{"zh":"意念如何經試驗及反思發展","cn":"意念如何经试验及反思发展","en":"How ideas developed through experimentation and reflection"},"correct":true,"feedback":{"zh":"過程資料可追蹤選擇與修改的理由。","cn":"过程资料可追踪选择与修改的理由。","en":"Process evidence traces decisions and reasons for revision."},"id":"b"},{"text":{"zh":"最後作品必定獲所有觀眾喜歡","cn":"最后作品必定获所有观众喜欢","en":"That every viewer must like the final work"},"correct":false,"feedback":{"zh":"完整過程不保證所有人的審美反應相同。","cn":"完整过程不保证所有人的审美反应相同。","en":"A documented process does not guarantee universal approval."},"id":"c"}],"takeaway":{"zh":"作品集應呈現思考與取捨，而不只是最終成品。","cn":"作品集应呈现思考与取舍，而不只是最终成品。","en":"A portfolio should reveal reasoning and choices as well as finished work."}},{"id":"s5-art-02","grade":5,"subjectId":"art","roomId":"art","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"一次只改一個設計因素","cn":"一次只改一个设计因素","en":"Testing a design variable"},"question":{"zh":"想知道指示牌的字體大小會否影響辨讀距離。哪個比較較能隔離字體大小的作用？","cn":"想知道指示牌的字体大小会否影响辨读距离。哪个比较较能隔离字体大小的作用？","en":"To investigate whether type size affects a sign’s reading distance, which comparison best isolates size?"},"options":[{"text":{"zh":"同時更換文字、色彩及字體大小","cn":"同时更换文字、色彩及字体大小","en":"Change wording, colour and size together"},"correct":false,"feedback":{"zh":"多個因素同時改變，不能知道是哪項造成差異。","cn":"多个因素同时改变，不能知道是哪项造成差异。","en":"Several simultaneous changes prevent attribution to size."},"id":"a"},{"text":{"zh":"讓設計者選自己較喜歡的一張","cn":"让设计者选自己较喜欢的一张","en":"Ask the designer to choose a personal favourite"},"correct":false,"feedback":{"zh":"喜好不等於實際辨讀距離的測試。","cn":"喜好不等于实际辨读距离的测试。","en":"Preference is not a test of reading distance."},"id":"b"},{"text":{"zh":"同樣文字、字體及對比，只改字體大小","cn":"同样文字、字体及对比，只改字体大小","en":"Keep wording, typeface and contrast constant; vary type size"},"correct":true,"feedback":{"zh":"控制其他因素可較清楚比較大小的影響。","cn":"控制其他因素可较清楚比较大小的影响。","en":"Holding other factors constant helps isolate size."},"id":"c"}],"takeaway":{"zh":"設計測試先訂可觀察目標，再控制影響比較的因素。","cn":"设计测试先订可观察目标，再控制影响比较的因素。","en":"Define an observable design outcome and control factors that affect the comparison."}},{"id":"s5-art-03","grade":5,"subjectId":"art","roomId":"art","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"再用圖像的清楚署名","cn":"再用图像的清楚署名","en":"Transparent use of an image"},"question":{"zh":"教師已準許使用一張授權照片製作拼貼。作品加入自己的裁切、重排及手繪。哪項說明最能清楚交代貢獻？","cn":"教师已准许使用一张授权照片制作拼贴。作品加入自己的裁切、重排及手绘。哪项说明最能清楚交代贡献？","en":"A teacher has approved a licensed photograph for a collage. The student crops, rearranges and adds drawing. Which note most clearly explains the contributions?"},"options":[{"text":{"zh":"列原照片作者與來源，並說明自己的改動","cn":"列原照片作者与来源，并说明自己的改动","en":"Credit the photograph’s creator and source and describe the student’s changes"},"correct":true,"feedback":{"zh":"署名與過程說明可區分原素材及新增創作。","cn":"署名与过程说明可区分原素材及新增创作。","en":"Credit and a process statement distinguish source material from new contributions."},"id":"a"},{"text":{"zh":"只寫「全部由我拍攝」","cn":"只写「全部由我拍摄」","en":"State “all photography by me”"},"correct":false,"feedback":{"zh":"這與題目中的原照片來源不符。","cn":"这与题目中的原照片来源不符。","en":"This contradicts the photograph’s stated origin."},"id":"b"},{"text":{"zh":"因為加入手繪，就刪除原照片來源","cn":"因为加入手绘，就删除原照片来源","en":"Remove the source because drawing was added"},"correct":false,"feedback":{"zh":"新增創作不會改變原照片的作者身分。","cn":"新增创作不会改变原照片的作者身分。","en":"Adding work does not change who created the source photograph."},"id":"c"}],"takeaway":{"zh":"清楚區分來源素材、使用依據及自己的創作決定。","cn":"清楚区分来源素材、使用依据及自己的创作决定。","en":"Distinguish source material, the basis for using it and your own creative decisions."}},{"id":"s6-art-01","grade":6,"subjectId":"art","roomId":"art","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"評論的證據","cn":"评论的证据","en":"Evidence in criticism"},"question":{"zh":"某評論只說「這雕塑很有張力」。哪項補充能把評語變成可討論的分析？","cn":"某评论只说「这雕塑很有张力」。哪项补充能把评语变成可讨论的分析？","en":"A review only says “this sculpture has tension”. Which addition makes that judgement analysable?"},"options":[{"text":{"zh":"重複「非常非常有張力」","cn":"重复「非常非常有张力」","en":"Repeat “very, very tense”"},"correct":false,"feedback":{"zh":"加強語氣沒有增加可檢查的視覺依據。","cn":"加强语气没有增加可检查的视觉依据。","en":"Stronger wording adds no observable evidence."},"id":"a"},{"text":{"zh":"只推斷作者創作時一定很憤怒","cn":"只推断作者创作时一定很愤怒","en":"Only infer that the artist must have felt angry"},"correct":false,"feedback":{"zh":"作品效果不等於作者當時情緒；仍需具體形式證據。","cn":"作品效果不等于作者当时情绪；仍需具体形式证据。","en":"An artwork’s effect does not establish the artist’s emotions; formal evidence is still needed."},"id":"b"},{"text":{"zh":"指出傾斜軸線、狹窄支點及它們造成的不穩定感","cn":"指出倾斜轴线、狭窄支点及它们造成的不稳定感","en":"Identify its tilted axis, narrow support and the resulting sense of instability"},"correct":true,"feedback":{"zh":"具體形式特徵讓讀者檢查評論與作品的關係。","cn":"具体形式特征让读者检查评论与作品的关系。","en":"Specific formal features let readers assess the interpretation."},"id":"c"}],"takeaway":{"zh":"評價應由具體分析支撐，容許他人提出有根據的不同解讀。","cn":"评价应由具体分析支撑，容许他人提出有根据的不同解读。","en":"Support judgement with analysis that allows informed alternative readings."}},{"id":"s6-art-02","grade":6,"subjectId":"art","roomId":"art","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"修改與創作意圖","cn":"修改与创作意图","en":"Revision and artistic intention"},"question":{"zh":"作品意圖表現擁擠都市中的孤立。一位同學建議刪掉所有人物令畫面更整齊。創作者最有理由先問甚麼？","cn":"作品意图表现拥挤都市中的孤立。一位同学建议删掉所有人物令画面更整齐。创作者最有理由先问甚么？","en":"The intention is isolation within a crowded city. A peer suggests removing every figure to make it neater. What should the artist ask first?"},"options":[{"text":{"zh":"刪掉人羣會否削弱「在人羣中孤立」的關係？","cn":"删掉人群会否削弱「在人群中孤立」的关系？","en":"Would removing the crowd weaken the idea of isolation among people?"},"correct":true,"feedback":{"zh":"修改須按創作目的評估，整齊並非唯一標準。","cn":"修改须按创作目的评估，整齐并非唯一标准。","en":"Evaluate revision against intention; neatness is not the only criterion."},"id":"a"},{"text":{"zh":"怎樣修改才會令所有觀眾都同意？","cn":"怎样修改才会令所有观众都同意？","en":"What change will make every viewer agree?"},"correct":false,"feedback":{"zh":"藝術回應可以不同，不能保證全體一致。","cn":"艺术回应可以不同，不能保证全体一致。","en":"Responses to art can differ; universal agreement cannot be guaranteed."},"id":"b"},{"text":{"zh":"既然有人建議，是否必須全部照做？","cn":"既然有人建议，是否必须全部照做？","en":"Must every suggestion be followed because someone offered it?"},"correct":false,"feedback":{"zh":"同儕回饋是思考材料，不會取代創作者的判斷。","cn":"同侪回馈是思考材料，不会取代创作者的判断。","en":"Feedback informs rather than replaces the artist’s judgement."},"id":"c"}],"takeaway":{"zh":"將回饋與意圖、形式及觀眾反應互相比較，再決定修訂。","cn":"将回馈与意图、形式及观众反应互相比较，再决定修订。","en":"Weigh feedback against intention, form and audience response before revising."}},{"id":"s6-art-03","grade":6,"subjectId":"art","roomId":"art","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"可追溯的創作論述","cn":"可追溯的创作论述","en":"A traceable artistic argument"},"question":{"zh":"展覽要求作品回應「記憶不完整」。哪份創作說明最能建立可追溯的意圖、實踐與評估關係？","cn":"展览要求作品回应「记忆不完整」。哪份创作说明最能建立可追溯的意图、实践与评估关系？","en":"An exhibition asks artists to address “incomplete memory”. Which process statement best connects intention, practice and evaluation?"},"options":[{"text":{"zh":"宣稱素材愈多，主題必定愈深刻","cn":"宣称素材愈多，主题必定愈深刻","en":"Claim that more materials necessarily make the theme deeper"},"correct":false,"feedback":{"zh":"數量不自動構成意義，仍需交代選擇與效果。","cn":"数量不自动构成意义，仍需交代选择与效果。","en":"Quantity does not automatically create meaning; choices and effects require explanation."},"id":"a"},{"text":{"zh":"說明用破碎照片表現缺口，記錄不同拼接試驗，再比較觀眾是否讀出斷續感","cn":"说明用破碎照片表现缺口，记录不同拼接试验，再比较观众是否读出断续感","en":"Explain the use of fragmented photos, record assembly trials and compare whether viewers perceive discontinuity"},"correct":true,"feedback":{"zh":"意圖、形式選擇、試驗及回應形成可檢查的發展過程。","cn":"意图、形式选择、试验及回应形成可检查的发展过程。","en":"Intention, formal choices, trials and responses form a traceable process."},"id":"b"},{"text":{"zh":"只列最後作品尺寸與售價","cn":"只列最后作品尺寸与售价","en":"List only final dimensions and price"},"correct":false,"feedback":{"zh":"這些資料不能說明作品如何回應主題或經過修訂。","cn":"这些资料不能说明作品如何回应主题或经过修订。","en":"These details do not explain the thematic response or development."},"id":"c"}],"takeaway":{"zh":"綜合創作與評賞時，建立意圖、證據、試驗和反思之間的關係。","cn":"综合创作与评赏时，建立意图、证据、试验和反思之间的关系。","en":"Connect intention, evidence, experimentation and reflection when integrating making and criticism."}},{"id":"s1-music-01","grade":1,"subjectId":"music","roomId":"music","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"四拍小節","cn":"四拍小节","en":"A four-beat bar"},"question":{"zh":"在4/4拍中，以四分音符為一拍。一小節先有一個二分音符，還需多少個四分音符才完整？","cn":"在4/4拍中，以四分音符为一拍。一小节先有一个二分音符，还需多少个四分音符才完整？","en":"In 4/4, a quarter note is one beat. A bar begins with one half note. How many quarter notes complete the bar?"},"options":[{"text":{"zh":"4個","cn":"4个","en":"4"},"correct":false,"feedback":{"zh":"再加四拍會令全小節達六拍。","cn":"再加四拍会令全小节达六拍。","en":"Adding four beats would make six in total."},"id":"a"},{"text":{"zh":"2個","cn":"2个","en":"2"},"correct":true,"feedback":{"zh":"二分音符佔兩拍，四拍小節還餘兩拍。","cn":"二分音符占两拍，四拍小节还余两拍。","en":"The half note occupies two beats, leaving two beats."},"id":"b"},{"text":{"zh":"1個","cn":"1个","en":"1"},"correct":false,"feedback":{"zh":"兩拍加一拍只有三拍，小節尚欠一拍。","cn":"两拍加一拍只有三拍，小节尚欠一拍。","en":"Two plus one gives three beats, one short."},"id":"c"}],"takeaway":{"zh":"計算小節時值時，把音符都轉成相同拍值再相加。","cn":"计算小节时值时，把音符都转成相同拍值再相加。","en":"Convert notes to the same beat unit when checking a bar’s duration."}},{"id":"s1-music-02","grade":1,"subjectId":"music","roomId":"music","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"休止仍佔時間","cn":"休止仍占时间","en":"Rests still take time"},"question":{"zh":"4/4拍中依次有四分音符、四分休止符、二分音符。第二拍應怎樣做？","cn":"4/4拍中依次有四分音符、四分休止符、二分音符。第二拍应怎样做？","en":"A 4/4 bar contains a quarter note, quarter rest and half note in that order. What happens on beat two?"},"options":[{"text":{"zh":"略過這一拍，立即奏二分音符","cn":"略过这一拍，立即奏二分音符","en":"Skip the beat and immediately play the half note"},"correct":false,"feedback":{"zh":"略過休止會令節奏提早一拍。","cn":"略过休止会令节奏提早一拍。","en":"Skipping the rest makes the next note a beat early."},"id":"a"},{"text":{"zh":"把速度減半","cn":"把速度减半","en":"Halve the tempo"},"correct":false,"feedback":{"zh":"休止符本身不要求改變整體速度。","cn":"休止符本身不要求改变整体速度。","en":"A rest does not itself require a tempo change."},"id":"b"},{"text":{"zh":"不發聲，但持續數拍","cn":"不发声，但持续数拍","en":"Remain silent but keep counting"},"correct":true,"feedback":{"zh":"休止符是有時值的安靜，不是把一拍刪去。","cn":"休止符是有时值的安静，不是把一拍删去。","en":"A rest is timed silence, not a deleted beat."},"id":"c"}],"takeaway":{"zh":"穩定拍子在發聲和休止時都持續存在。","cn":"稳定拍子在发声和休止时都持续存在。","en":"The underlying pulse continues through notes and rests."}},{"id":"s1-music-03","grade":1,"subjectId":"music","roomId":"music","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"拍子與節奏","cn":"拍子与节奏","en":"Pulse and rhythm"},"question":{"zh":"甲同學穩定地每秒拍一下；乙同學在同樣時間內拍出長短不同的組合。兩人的配合最能示範甚麼？","cn":"甲同学稳定地每秒拍一下；乙同学在同样时间内拍出长短不同的组合。两人的配合最能示范甚么？","en":"Student A taps steadily once a second while B performs a pattern of unequal durations over the same time. What does this best demonstrate?"},"options":[{"text":{"zh":"穩定拍子可承託不同節奏","cn":"稳定拍子可承托不同节奏","en":"A steady pulse can support different rhythms"},"correct":true,"feedback":{"zh":"拍子提供規律時間框架，節奏安排長短及重音。","cn":"拍子提供规律时间框架，节奏安排长短及重音。","en":"Pulse supplies a regular framework; rhythm organises durations and accents."},"id":"a"},{"text":{"zh":"只要節奏改變，拍子必須停止","cn":"只要节奏改变，拍子必须停止","en":"The pulse must stop whenever the rhythm changes"},"correct":false,"feedback":{"zh":"不同節奏可以共用同一穩定拍子。","cn":"不同节奏可以共用同一稳定拍子。","en":"Different rhythms can share one steady pulse."},"id":"b"},{"text":{"zh":"較多聲響必定代表速度較快","cn":"较多声响必定代表速度较快","en":"More sounds always mean a faster tempo"},"correct":false,"feedback":{"zh":"較細的音符可在原有速度內增加聲響數量。","cn":"较细的音符可在原有速度内增加声响数量。","en":"Shorter notes can increase note density without changing tempo."},"id":"c"}],"takeaway":{"zh":"分辨速度、拍子和節奏密度，避免把音符多誤當加速。","cn":"分辨速度、拍子和节奏密度，避免把音符多误当加速。","en":"Distinguish tempo, pulse and rhythmic density."}},{"id":"s2-music-01","grade":2,"subjectId":"music","roomId":"music","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"附點音符","cn":"附点音符","en":"Dotted notes"},"question":{"zh":"附點增加原音符一半的時值。以四分音符為一拍，附點二分音符有多少拍？","cn":"附点增加原音符一半的时值。以四分音符为一拍，附点二分音符有多少拍？","en":"A dot adds half the note’s original value. With a quarter note as one beat, how many beats is a dotted half note?"},"options":[{"text":{"zh":"2.5拍","cn":"2.5拍","en":"2.5 beats"},"correct":false,"feedback":{"zh":"附點增加原音符的一半，不是固定加半拍。","cn":"附点增加原音符的一半，不是固定加半拍。","en":"The dot adds half the note’s value, not always half a beat."},"id":"a"},{"text":{"zh":"4拍","cn":"4拍","en":"4 beats"},"correct":false,"feedback":{"zh":"四拍是二分音符的兩倍，不是增加一半。","cn":"四拍是二分音符的两倍，不是增加一半。","en":"Four beats doubles rather than adds half to the original."},"id":"b"},{"text":{"zh":"3拍","cn":"3拍","en":"3 beats"},"correct":true,"feedback":{"zh":"二分音符兩拍，加一半即一拍，共三拍。","cn":"二分音符两拍，加一半即一拍，共三拍。","en":"A half note is two beats; adding half of that gives three."},"id":"c"}],"takeaway":{"zh":"附點按原音符的時值計算，不是固定加某個拍數。","cn":"附点按原音符的时值计算，不是固定加某个拍数。","en":"Calculate a dot from the original note’s value."}},{"id":"s2-music-02","grade":2,"subjectId":"music","roomId":"music","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"旋律與伴奏織體","cn":"旋律与伴奏织体","en":"Melody and accompaniment"},"question":{"zh":"一名歌手唱清楚的旋律，鋼琴以和絃伴奏。哪個描述最符合此織體？","cn":"一名歌手唱清楚的旋律，钢琴以和弦伴奏。哪个描述最符合此织体？","en":"A singer carries a clear melody while a piano supplies chordal accompaniment. Which texture best fits?"},"options":[{"text":{"zh":"主調織體：主旋律配和聲伴奏","cn":"主调织体：主旋律配和声伴奏","en":"Homophonic: a main melody with harmonic accompaniment"},"correct":true,"feedback":{"zh":"主旋律最突出，其餘部分提供和聲支持。","cn":"主旋律最突出，其余部分提供和声支持。","en":"The melody leads while other parts provide harmonic support."},"id":"a"},{"text":{"zh":"單音織體：只有一條無伴奏旋律","cn":"单音织体：只有一条无伴奏旋律","en":"Monophonic: one unaccompanied melodic line"},"correct":false,"feedback":{"zh":"題目已有鋼琴和絃伴奏，不是單一旋律線。","cn":"题目已有钢琴和弦伴奏，不是单一旋律线。","en":"The piano chords mean there is more than one melodic line alone."},"id":"b"},{"text":{"zh":"複調織體：多條同等突出的獨立旋律","cn":"复调织体：多条同等突出的独立旋律","en":"Polyphonic: several equally prominent independent melodies"},"correct":false,"feedback":{"zh":"題目描述主旋律與和絃伴奏，不是多條同等獨立的旋律。","cn":"题目描述主旋律与和弦伴奏，不是多条同等独立的旋律。","en":"The prompt describes a lead melody and chords rather than several independent melodic lines."},"id":"c"}],"takeaway":{"zh":"根據聲部之間的關係描述織體，而非只數樂器。","cn":"根据声部之间的关系描述织体，而非只数乐器。","en":"Describe texture through relationships between parts, not simply the number of instruments."}},{"id":"s2-music-03","grade":2,"subjectId":"music","roomId":"music","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"樂段與曲式","cn":"乐段与曲式","en":"Sections and form"},"question":{"zh":"一首短曲先奏樂段A，再奏新樂段B，最後原樣重奏A。最簡潔的曲式標記是甚麼？","cn":"一首短曲先奏乐段A，再奏新乐段B，最后原样重奏A。最简洁的曲式标记是甚么？","en":"A short piece presents section A, then contrasting B, then repeats A unchanged. What is the simplest form label?"},"options":[{"text":{"zh":"ABC","cn":"ABC","en":"ABC"},"correct":false,"feedback":{"zh":"最後是A重現，不是第三個全新樂段。","cn":"最后是A重现，不是第三个全新乐段。","en":"The ending repeats A rather than introducing a third new section."},"id":"a"},{"text":{"zh":"ABA","cn":"ABA","en":"ABA"},"correct":true,"feedback":{"zh":"結尾回到原來樂段，形成三段體。","cn":"结尾回到原来乐段，形成三段体。","en":"The return of the opening section creates ternary form."},"id":"b"},{"text":{"zh":"AB","cn":"AB","en":"AB"},"correct":false,"feedback":{"zh":"這遺漏了最後返回A的部分。","cn":"这遗漏了最后返回A的部分。","en":"This omits the final return to A."},"id":"c"}],"takeaway":{"zh":"以材料是否重現或對比來標記曲式。","cn":"以材料是否重现或对比来标记曲式。","en":"Label form by identifying returning and contrasting material."}},{"id":"s3-music-01","grade":3,"subjectId":"music","roomId":"music","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"旋律移調","cn":"旋律移调","en":"Transposing a melody"},"question":{"zh":"把C–D–E整體向上移大二度，並保持各音間距。結果是甚麼？","cn":"把C–D–E整体向上移大二度，并保持各音间距。结果是甚么？","en":"Transpose C–D–E up a major second, preserving intervals. What results?"},"options":[{"text":{"zh":"D–E–F♯","cn":"D–E–F♯","en":"D–E–F♯"},"correct":true,"feedback":{"zh":"每個音都上移兩個半音；E上移後是F♯。","cn":"每个音都上移两个半音；E上移后是F♯。","en":"Each note rises two semitones; E becomes F-sharp."},"id":"a"},{"text":{"zh":"D–E–F","cn":"D–E–F","en":"D–E–F"},"correct":false,"feedback":{"zh":"E至F只有一個半音，沒有保持原來最後的全音距離。","cn":"E至F只有一个半音，没有保持原来最后的全音距离。","en":"E to F is only one semitone and changes the final whole-step interval."},"id":"b"},{"text":{"zh":"D–F–A","cn":"D–F–A","en":"D–F–A"},"correct":false,"feedback":{"zh":"這改變了音程關係，並非整體等距移調。","cn":"这改变了音程关系，并非整体等距移调。","en":"This changes the intervals rather than shifting the whole melody equally."},"id":"c"}],"takeaway":{"zh":"移調時每個音都移相同音程，不能只換起音。","cn":"移调时每个音都移相同音程，不能只换起音。","en":"Transpose every note by the same interval, not just the starting note."}},{"id":"s3-music-02","grade":3,"subjectId":"music","roomId":"music","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"三和絃的構成","cn":"三和弦的构成","en":"Building a triad"},"question":{"zh":"以C大調第1、3、5級音建立主三和絃，應包含哪些音？","cn":"以C大调第1、3、5级音建立主三和弦，应包含哪些音？","en":"Build the tonic triad from degrees 1, 3 and 5 of C major. Which notes belong?"},"options":[{"text":{"zh":"D、F、A","cn":"D、F、A","en":"D, F and A"},"correct":false,"feedback":{"zh":"這是由第2級開始的三和絃，不是主和絃。","cn":"这是由第2级开始的三和弦，不是主和弦。","en":"This is a triad built on degree 2, not the tonic."},"id":"a"},{"text":{"zh":"C、E、G","cn":"C、E、G","en":"C, E and G"},"correct":true,"feedback":{"zh":"C大調第1、3、5級依次是C、E、G。","cn":"C大调第1、3、5级依次是C、E、G。","en":"Degrees 1, 3 and 5 in C major are C, E and G."},"id":"b"},{"text":{"zh":"C、D、E","cn":"C、D、E","en":"C, D and E"},"correct":false,"feedback":{"zh":"這是第1、2、3級的相鄰音，並非指定三和絃。","cn":"这是第1、2、3级的相邻音，并非指定三和弦。","en":"These are adjacent degrees 1, 2 and 3, not the specified triad."},"id":"c"}],"takeaway":{"zh":"用調式中的音級理解和絃功能，與單純連續音階區分。","cn":"用调式中的音级理解和弦功能，与单纯连续音阶区分。","en":"Use scale degrees to understand chords and distinguish them from consecutive scale notes."}},{"id":"s3-music-03","grade":3,"subjectId":"music","roomId":"music","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"力度不等於速度","cn":"力度不等于速度","en":"Dynamics are not tempo"},"question":{"zh":"樂譜標示由p漸強至f，但沒有改變速度記號。最貼合記譜的演奏是甚麼？","cn":"乐谱标示由p渐强至f，但没有改变速度记号。最贴合记谱的演奏是甚么？","en":"A score moves from p to f through a crescendo without a tempo change. Which performance best follows it?"},"options":[{"text":{"zh":"逐漸加快，但音量完全不變","cn":"逐渐加快，但音量完全不变","en":"Accelerate while keeping loudness unchanged"},"correct":false,"feedback":{"zh":"這把力度指示誤當成速度指示。","cn":"这把力度指示误当成速度指示。","en":"This mistakes a dynamic instruction for a tempo instruction."},"id":"a"},{"text":{"zh":"只把所有音提高八度","cn":"只把所有音提高八度","en":"Raise every note by an octave"},"correct":false,"feedback":{"zh":"改變音區並不等於按要求漸強。","cn":"改变音区并不等于按要求渐强。","en":"Changing register is not the requested crescendo."},"id":"b"},{"text":{"zh":"逐漸增加音量，維持原有拍速","cn":"逐渐增加音量，维持原有拍速","en":"Gradually grow louder while maintaining the pulse"},"correct":true,"feedback":{"zh":"漸強處理力度；沒有加速記號時不應自動加速。","cn":"渐强处理力度；没有加速记号时不应自动加速。","en":"A crescendo changes dynamics; it does not automatically require acceleration."},"id":"c"}],"takeaway":{"zh":"分別處理力度、速度與音高的記譜訊息。","cn":"分别处理力度、速度与音高的记谱讯息。","en":"Read dynamic, tempo and pitch information as distinct musical dimensions."}},{"id":"s4-music-01","grade":4,"subjectId":"music","roomId":"music","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"複合拍子的重拍","cn":"复合拍子的重拍","en":"Beats in compound metre"},"question":{"zh":"在通常的6/8拍中，六個八分音符分成兩組，每組三個。主要拍子通常有多少個？","cn":"在通常的6/8拍中，六个八分音符分成两组，每组三个。主要拍子通常有多少个？","en":"In a usual 6/8 pattern, six eighth notes form two groups of three. How many main beats are normally felt?"},"options":[{"text":{"zh":"3個附點四分音符拍","cn":"3个附点四分音符拍","en":"3 dotted-quarter beats"},"correct":false,"feedback":{"zh":"三個附點四分音符共九個八分音符，超出6/8小節。","cn":"三个附点四分音符共九个八分音符，超出6/8小节。","en":"Three dotted quarters equal nine eighth notes, exceeding the bar."},"id":"a"},{"text":{"zh":"2個附點四分音符拍","cn":"2个附点四分音符拍","en":"2 dotted-quarter beats"},"correct":true,"feedback":{"zh":"每組三個八分音符構成一個主要拍子。","cn":"每组三个八分音符构成一个主要拍子。","en":"Each group of three eighth notes forms one main beat."},"id":"b"},{"text":{"zh":"6個二分音符拍","cn":"6个二分音符拍","en":"6 half-note beats"},"correct":false,"feedback":{"zh":"這既改變時值單位，也與每小節六個八分音符不符。","cn":"这既改变时值单位，也与每小节六个八分音符不符。","en":"This changes the duration unit and does not match six eighth notes."},"id":"c"}],"takeaway":{"zh":"複合拍子要區分主要拍子與其三等分細分。","cn":"复合拍子要区分主要拍子与其三等分细分。","en":"In compound metre, distinguish main beats from their three-part subdivisions."}},{"id":"s4-music-02","grade":4,"subjectId":"music","roomId":"music","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"終止式的功能","cn":"终止式的功能","en":"The function of a cadence"},"question":{"zh":"在C大調樂句末，G大三和絃接C大三和絃，即V–I。這通常帶來哪種效果？","cn":"在C大调乐句末，G大三和弦接C大三和弦，即V–I。这通常带来哪种效果？","en":"At the end of a C-major phrase, G major moves to C major, or V–I. What effect does this normally create?"},"options":[{"text":{"zh":"必定轉到一個完全不相關的調","cn":"必定转到一个完全不相关的调","en":"An inevitable move to an unrelated key"},"correct":false,"feedback":{"zh":"此處V–I在原來C大調內完成，不必轉調。","cn":"此处V–I在原来C大调内完成，不必转调。","en":"This V–I occurs within C major and does not require modulation."},"id":"a"},{"text":{"zh":"必定令拍號由4/4變成3/4","cn":"必定令拍号由4/4变成3/4","en":"An inevitable metre change from 4/4 to 3/4"},"correct":false,"feedback":{"zh":"和絃進行不會自行決定拍號改變。","cn":"和弦进行不会自行决定拍号改变。","en":"A chord progression does not itself determine metre."},"id":"b"},{"text":{"zh":"由屬和絃解決至主和絃的結束感","cn":"由属和弦解决至主和弦的结束感","en":"A sense of resolution from dominant to tonic"},"correct":true,"feedback":{"zh":"V–I把和聲帶回主和絃，常用來建立結束感。","cn":"V–I把和声带回主和弦，常用来建立结束感。","en":"V–I returns the harmony to the tonic and commonly supports closure."},"id":"c"}],"takeaway":{"zh":"把和聲功能與調性關係連起來，而非與速度或拍號混淆。","cn":"把和声功能与调性关系连起来，而非与速度或拍号混淆。","en":"Connect harmonic function with tonality rather than tempo or metre."}},{"id":"s4-music-03","grade":4,"subjectId":"music","roomId":"music","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"保留動機的發展","cn":"保留动机的发展","en":"Developing a motif"},"question":{"zh":"原動機是「短、短、長」的節奏，上行三個音。哪種改寫最清楚保留節奏身分，同時發展旋律？","cn":"原动机是「短、短、长」的节奏，上行三个音。哪种改写最清楚保留节奏身分，同时发展旋律？","en":"A motif uses a short–short–long rhythm and three rising notes. Which variation retains its rhythmic identity while developing the melody?"},"options":[{"text":{"zh":"保留短短長，把音高走向改為下行","cn":"保留短短长，把音高走向改为下行","en":"Keep short–short–long but make the pitches descend"},"correct":true,"feedback":{"zh":"節奏身分保持，音高輪廓改變，形成可辨認的變奏。","cn":"节奏身分保持，音高轮廓改变，形成可辨认的变奏。","en":"The rhythm remains recognisable while the contour changes."},"id":"a"},{"text":{"zh":"把節奏及所有音程都換成無關材料","cn":"把节奏及所有音程都换成无关材料","en":"Replace both rhythm and intervals with unrelated material"},"correct":false,"feedback":{"zh":"缺少共同特徵，較難聽出與原動機的關係。","cn":"缺少共同特征，较难听出与原动机的关系。","en":"Without shared features, the connection to the motif becomes weak."},"id":"b"},{"text":{"zh":"完全照奏原動機，不作任何改變","cn":"完全照奏原动机，不作任何改变","en":"Repeat the motif with no change"},"correct":false,"feedback":{"zh":"這是重複，沒有題目要求的旋律發展。","cn":"这是重复，没有题目要求的旋律发展。","en":"This is repetition without the requested melodic development."},"id":"c"}],"takeaway":{"zh":"動機發展在保留可辨認特徵與引入變化之間取捨。","cn":"动机发展在保留可辨认特征与引入变化之间取舍。","en":"Motivic development balances recognisable identity and change."}},{"id":"s5-music-01","grade":5,"subjectId":"music","roomId":"music","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"切分音的重音","cn":"切分音的重音","en":"Syncopated emphasis"},"question":{"zh":"4/4拍中，一個音在第2拍後半拍開始，延續跨過第3拍的開始。這種安排可產生甚麼效果？","cn":"4/4拍中，一个音在第2拍后半拍开始，延续跨过第3拍的开始。这种安排可产生甚么效果？","en":"In 4/4, a note begins on the second half of beat 2 and sustains across the start of beat 3. What effect can this create?"},"options":[{"text":{"zh":"拍號必然變為5/4","cn":"拍号必然变为5/4","en":"The metre necessarily changes to 5/4"},"correct":false,"feedback":{"zh":"切分可發生在原有4/4框架內。","cn":"切分可发生在原有4/4框架内。","en":"Syncopation can occur within the original 4/4 metre."},"id":"a"},{"text":{"zh":"音高必然上升","cn":"音高必然上升","en":"Pitch must rise"},"correct":false,"feedback":{"zh":"節奏位置不會自行決定音高走向。","cn":"节奏位置不会自行决定音高走向。","en":"Rhythmic placement does not determine pitch direction."},"id":"b"},{"text":{"zh":"弱位置的起音跨過強位置，形成切分效果","cn":"弱位置的起音跨过强位置，形成切分效果","en":"An off-beat onset carried across a stronger position creates syncopation"},"correct":true,"feedback":{"zh":"聲音在弱位置開始並跨越拍點，打破預期重音。","cn":"声音在弱位置开始并跨越拍点，打破预期重音。","en":"The off-beat onset across the beat disrupts expected emphasis."},"id":"c"}],"takeaway":{"zh":"切分改變重音與起音的關係，不一定改變拍號。","cn":"切分改变重音与起音的关系，不一定改变拍号。","en":"Syncopation changes the relation of onset to metrical emphasis without necessarily changing metre."}},{"id":"s5-music-02","grade":5,"subjectId":"music","roomId":"music","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"配器中的遮蓋","cn":"配器中的遮盖","en":"Masking in an arrangement"},"question":{"zh":"柔和木管旋律被同音區的厚重銅管伴奏掩蓋。若要保留木管為主角，哪項修改最直接？","cn":"柔和木管旋律被同音区的厚重铜管伴奏掩盖。若要保留木管为主角，哪项修改最直接？","en":"A soft woodwind melody is masked by dense brass accompaniment in the same register. To keep the woodwind prominent, which revision is most direct?"},"options":[{"text":{"zh":"降低伴奏力度並減薄同音區聲部","cn":"降低伴奏力度并减薄同音区声部","en":"Reduce accompaniment dynamics and thin its parts in that register"},"correct":true,"feedback":{"zh":"減少音量及音區競爭可改善旋律清晰度。","cn":"减少音量及音区竞争可改善旋律清晰度。","en":"Reducing loudness and register competition can improve melodic clarity."},"id":"a"},{"text":{"zh":"只把木管樂譜紙印大","cn":"只把木管乐谱纸印大","en":"Only print the woodwind part on larger paper"},"correct":false,"feedback":{"zh":"排版不會改變實際音響平衡。","cn":"排版不会改变实际音响平衡。","en":"Page layout does not alter the sounding balance."},"id":"b"},{"text":{"zh":"增加更多同音區銅管聲部","cn":"增加更多同音区铜管声部","en":"Add more brass parts in the same register"},"correct":false,"feedback":{"zh":"這通常加重遮蓋問題，與目標相反。","cn":"这通常加重遮盖问题，与目标相反。","en":"This generally increases the masking rather than resolving it."},"id":"c"}],"takeaway":{"zh":"配器考慮音色、音區、力度和織體的互相作用。","cn":"配器考虑音色、音区、力度和织体的互相作用。","en":"Consider interactions among timbre, register, dynamics and texture in orchestration."}},{"id":"s5-music-03","grade":5,"subjectId":"music","roomId":"music","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"音高變化與速度變化","cn":"音高变化与速度变化","en":"Pitch change and speed change"},"question":{"zh":"數碼軟件把一段錄音的播放速度由100%改為120%，而沒有啟用音高保留功能。通常會出現甚麼？","cn":"数码软件把一段录音的播放速度由100%改为120%，而没有启用音高保留功能。通常会出现甚么？","en":"Audio software plays a recording at 120% speed without pitch preservation. What usually happens?"},"options":[{"text":{"zh":"時間增加，音高下降","cn":"时间增加，音高下降","en":"Duration increases and pitch falls"},"correct":false,"feedback":{"zh":"這較符合降低播放速度，而非提高至120%。","cn":"这较符合降低播放速度，而非提高至120%。","en":"That describes slower rather than faster playback."},"id":"a"},{"text":{"zh":"時間縮短，音高也上升","cn":"时间缩短，音高也上升","en":"Duration decreases and pitch rises"},"correct":true,"feedback":{"zh":"直接提高播放取樣速度通常同時改變時長與頻率。","cn":"直接提高播放取样速度通常同时改变时长与频率。","en":"Faster sample playback normally changes both duration and frequency."},"id":"b"},{"text":{"zh":"時間縮短，但音高必定完全不變","cn":"时间缩短，但音高必定完全不变","en":"Duration decreases but pitch must remain unchanged"},"correct":false,"feedback":{"zh":"保持音高需要額外處理；題目明確沒有啟用。","cn":"保持音高需要额外处理；题目明确没有启用。","en":"Pitch preservation requires additional processing, which is excluded here."},"id":"c"}],"takeaway":{"zh":"分析音訊工具時，分清一般變速與保留音高的時間伸縮。","cn":"分析音讯工具时，分清一般变速与保留音高的时间伸缩。","en":"Distinguish ordinary speed changes from pitch-preserving time stretching."}},{"id":"s6-music-01","grade":6,"subjectId":"music","roomId":"music","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"有證據的演奏比較","cn":"有证据的演奏比较","en":"Evidence-based performance comparison"},"question":{"zh":"兩次演奏同一樂句。甲每個音等長等強；乙在高潮增加力度、句末稍放鬆。哪段比較最有音樂依據？","cn":"两次演奏同一乐句。甲每个音等长等强；乙在高潮增加力度、句末稍放松。哪段比较最有音乐依据？","en":"Two performances use the same phrase. A gives each note equal duration and emphasis; B grows towards the climax and relaxes at the end. Which comparison is best supported?"},"options":[{"text":{"zh":"乙以力度及句末處理塑造樂句方向","cn":"乙以力度及句末处理塑造乐句方向","en":"B shapes the phrase through dynamics and ending treatment"},"correct":true,"feedback":{"zh":"評論直接引用已描述的可聽特徵。","cn":"评论直接引用已描述的可听特征。","en":"This refers directly to the described audible features."},"id":"a"},{"text":{"zh":"乙全曲必定比甲更快","cn":"乙全曲必定比甲更快","en":"B must be faster throughout the piece"},"correct":false,"feedback":{"zh":"力度及句末處理不能證明全曲速度都較快。","cn":"力度及句末处理不能证明全曲速度都较快。","en":"Dynamic shaping and an ending do not establish a faster overall tempo."},"id":"b"},{"text":{"zh":"甲的音高一定較不準確","cn":"甲的音高一定较不准确","en":"A must have less accurate pitch"},"correct":false,"feedback":{"zh":"題目沒有提供音準資料，不能作此比較。","cn":"题目没有提供音准资料，不能作此比较。","en":"No pitch-accuracy evidence is provided for this comparison."},"id":"c"}],"takeaway":{"zh":"音樂評論應討論可聽證據，不猜測演奏者背景。","cn":"音乐评论应讨论可听证据，不猜测演奏者背景。","en":"Discuss audible evidence rather than guessing a performer’s background."}},{"id":"s6-music-02","grade":6,"subjectId":"music","roomId":"music","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"選擇適合的創作修訂","cn":"选择适合的创作修订","en":"Choosing a purposeful composition revision"},"question":{"zh":"短曲想表現「漸漸聚集的力量」，但整段只有同一力度的單音旋律。哪個修訂最能建立漸進發展？","cn":"短曲想表现「渐渐聚集的力量」，但整段只有同一力度的单音旋律。哪个修订最能建立渐进发展？","en":"A piece aims to convey “gathering strength” but remains a single melody at one dynamic level. Which revision best creates gradual development?"},"options":[{"text":{"zh":"只更改曲名，不改聲音","cn":"只更改曲名，不改声音","en":"Only change the title"},"correct":false,"feedback":{"zh":"曲名不能代替音樂中可聽到的發展。","cn":"曲名不能代替音乐中可听到的发展。","en":"A title cannot substitute for audible musical development."},"id":"a"},{"text":{"zh":"逐步增加聲部密度及力度，保留主要動機","cn":"逐步增加声部密度及力度，保留主要动机","en":"Gradually add textural density and dynamics while retaining the main motif"},"correct":true,"feedback":{"zh":"多個參數有方向地發展，且動機維持整體連貫。","cn":"多个参数有方向地发展，且动机维持整体连贯。","en":"Directed change across parameters builds momentum while the motif maintains coherence."},"id":"b"},{"text":{"zh":"在最後一秒突然插入完全無關的強音","cn":"在最后一秒突然插入完全无关的强音","en":"Insert an unrelated loud sound in the final second"},"correct":false,"feedback":{"zh":"突發強音不等於整段逐漸聚集的過程。","cn":"突发强音不等于整段逐渐聚集的过程。","en":"A sudden loud event is not a gradual build-up."},"id":"c"}],"takeaway":{"zh":"創作修訂須讓聽者在聲音組織中感受到意圖。","cn":"创作修订须让听者在声音组织中感受到意图。","en":"Make an artistic intention audible through the organisation of sound."}},{"id":"s6-music-03","grade":6,"subjectId":"music","roomId":"music","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"公平比較混音版本","cn":"公平比较混音版本","en":"Comparing mixes fairly"},"question":{"zh":"同一演奏有兩個混音版本。B整體音量較大，試聽者因而覺得「細節較清楚」。要比較混音清晰度，最先應怎樣改善測試？","cn":"同一演奏有两个混音版本。B整体音量较大，试听者因而觉得「细节较清楚」。要比较混音清晰度，最先应怎样改善测试？","en":"Two mixes use the same performance. B is louder and listeners call it “clearer”. What should be improved first when comparing clarity?"},"options":[{"text":{"zh":"只保留B，因為較響就是音質較好","cn":"只保留B，因为较响就是音质较好","en":"Keep only B because louder means better quality"},"correct":false,"feedback":{"zh":"音量是比較中的混雜因素，並不直接等於清晰度。","cn":"音量是比较中的混杂因素，并不直接等于清晰度。","en":"Loudness is a confound, not the same as clarity."},"id":"a"},{"text":{"zh":"把兩個版本改成不同樂曲","cn":"把两个版本改成不同乐曲","en":"Replace them with different pieces"},"correct":false,"feedback":{"zh":"改曲會增加新的差異，更難比較混音本身。","cn":"改曲会增加新的差异，更难比较混音本身。","en":"Different music introduces further differences and weakens the comparison."},"id":"b"},{"text":{"zh":"以相近的感知音量播放，再比較聲部可辨程度","cn":"以相近的感知音量播放，再比较声部可辨程度","en":"Match perceived loudness, then compare how clearly parts can be distinguished"},"correct":true,"feedback":{"zh":"控制音量差異可減少把「較響」誤作「較清楚」的偏差。","cn":"控制音量差异可减少把「较响」误作「较清楚」的偏差。","en":"Loudness matching reduces the bias of treating louder as clearer."},"id":"c"}],"takeaway":{"zh":"錄音評估須控制比較條件，再用明確音樂準則判斷。","cn":"录音评估须控制比较条件，再用明确音乐准则判断。","en":"Control listening conditions and use explicit musical criteria when evaluating recordings."}},{"id":"s1-library-01","grade":1,"subjectId":"library","roomId":"library","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"找到指定版本","cn":"找到指定版本","en":"Finding a specified edition"},"question":{"zh":"虛構書目練習：老師指定閱讀《城市樹木》陳文著、2022年版。目錄出現三本同名書。最應先核對哪組欄位？","cn":"虚构书目练习：老师指定阅读《城市树木》陈文著、2022年版。目录出现三本同名书。最应先核对哪组栏位？","en":"Fictional catalogue exercise: A teacher assigns City Trees by Chan Man, 2022 edition. The catalogue shows three books with that title. Which fields should you check first?"},"options":[{"text":{"zh":"封面顏色及書本厚度","cn":"封面颜色及书本厚度","en":"Cover colour and thickness"},"correct":false,"feedback":{"zh":"外觀不能可靠辨識指定作者和版本。","cn":"外观不能可靠辨识指定作者和版本。","en":"Appearance does not reliably identify the assigned author and edition."},"id":"a"},{"text":{"zh":"借閱次數及評分","cn":"借阅次数及评分","en":"Loan count and rating"},"correct":false,"feedback":{"zh":"人氣不能確定是否指定的版本。","cn":"人气不能确定是否指定的版本。","en":"Popularity does not identify the required edition."},"id":"b"},{"text":{"zh":"作者及出版年／版本","cn":"作者及出版年／版本","en":"Author and publication year/edition"},"correct":true,"feedback":{"zh":"同名書未必同作者或同版本，這些欄位可確認指定書目。","cn":"同名书未必同作者或同版本，这些栏位可确认指定书目。","en":"A shared title does not guarantee the same author or edition."},"id":"c"}],"takeaway":{"zh":"查找指定資源時，使用完整書目資料而非只看書名。","cn":"查找指定资源时，使用完整书目资料而非只看书名。","en":"Use complete bibliographic details when locating a specified resource."}},{"id":"s1-library-02","grade":1,"subjectId":"library","roomId":"library","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"書架排序","cn":"书架排序","en":"Shelf order"},"question":{"zh":"本館此書架按索書號數值由小至大排列：510、512.4、513。索書號512.37的書應放在哪裏？","cn":"本馆此书架按索书号数值由小至大排列：510、512.4、513。索书号512.37的书应放在哪里？","en":"This shelf orders call numbers numerically: 510, 512.4, 513. Where should 512.37 go?"},"options":[{"text":{"zh":"510與512.4之間","cn":"510与512.4之间","en":"Between 510 and 512.4"},"correct":true,"feedback":{"zh":"512.37小於512.40，但大於510。","cn":"512.37小于512.40，但大于510。","en":"512.37 is less than 512.40 and greater than 510."},"id":"a"},{"text":{"zh":"512.4與513之間","cn":"512.4与513之间","en":"Between 512.4 and 513"},"correct":false,"feedback":{"zh":"37與4不能當作整數直接比較；應比較小數值。","cn":"37与4不能当作整数直接比较；应比较小数值。","en":"Do not compare 37 and 4 as integers; compare the decimal values."},"id":"b"},{"text":{"zh":"513之後","cn":"513之后","en":"After 513"},"correct":false,"feedback":{"zh":"512.37仍小於513。","cn":"512.37仍小于513。","en":"512.37 is still smaller than 513."},"id":"c"}],"takeaway":{"zh":"依圖書館指定的排序規則逐部分比較索書號。","cn":"依图书馆指定的排序规则逐部分比较索书号。","en":"Follow the library’s stated filing rules when comparing call numbers."}},{"id":"s1-library-03","grade":1,"subjectId":"library","roomId":"library","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"為問題選資料","cn":"为问题选资料","en":"Choosing a source for a question"},"question":{"zh":"你要知道校內圖書館「今天幾點關門」。哪項來源最直接合適？","cn":"你要知道校内图书馆「今天几点关门」。哪项来源最直接合适？","en":"You need to know when the school library closes today. Which source is most directly suitable?"},"options":[{"text":{"zh":"一本介紹世界圖書館的百科全書","cn":"一本介绍世界图书馆的百科全书","en":"An encyclopaedia about libraries worldwide"},"correct":false,"feedback":{"zh":"內容範圍太廣，不能直接回答本校今天的時間。","cn":"内容范围太广，不能直接回答本校今天的时间。","en":"Its scope does not answer today’s local schedule."},"id":"a"},{"text":{"zh":"圖書館今天發布的開放時間通知","cn":"图书馆今天发布的开放时间通知","en":"Today’s opening-hours notice from the library"},"correct":true,"feedback":{"zh":"問題關乎今天的安排，應查負責單位最新通知。","cn":"问题关乎今天的安排，应查负责单位最新通知。","en":"The question concerns today, so use the responsible service’s current notice."},"id":"b"},{"text":{"zh":"三年前的校慶特刊","cn":"三年前的校庆特刊","en":"A school anniversary booklet from three years ago"},"correct":false,"feedback":{"zh":"舊刊可提供歷史資料，卻未必反映今天安排。","cn":"旧刊可提供历史资料，却未必反映今天安排。","en":"It may provide historical information but not today’s schedule."},"id":"c"}],"takeaway":{"zh":"來源是否合適，取決於問題的時間、地點和用途。","cn":"来源是否合适，取决于问题的时间、地点和用途。","en":"A source’s suitability depends on the question’s time, place and purpose."}},{"id":"s2-library-01","grade":2,"subjectId":"library","roomId":"library","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"擴闊同義詞搜尋","cn":"扩阔同义词搜寻","en":"Searching synonyms"},"question":{"zh":"資料庫把OR解釋為「符合任何一個詞」。要同時找到使用teenagers或adolescents的文章，應輸入甚麼？","cn":"资料库把OR解释为「符合任何一个词」。要同时找到使用teenagers或adolescents的文章，应输入甚么？","en":"A database defines OR as matching either term. Which search finds articles using teenagers or adolescents?"},"options":[{"text":{"zh":"teenagers OR adolescents","cn":"teenagers OR adolescents","en":"teenagers OR adolescents"},"correct":true,"feedback":{"zh":"OR把兩組結果合併，有助涵蓋不同用語。","cn":"OR把两组结果合并，有助涵盖不同用语。","en":"OR combines result sets to cover different terminology."},"id":"a"},{"text":{"zh":"teenagers AND adolescents","cn":"teenagers AND adolescents","en":"teenagers AND adolescents"},"correct":false,"feedback":{"zh":"AND要求兩詞同時出現，可能漏掉只用其中一詞的文章。","cn":"AND要求两词同时出现，可能漏掉只用其中一词的文章。","en":"AND requires both terms and may exclude articles using only one."},"id":"b"},{"text":{"zh":"teenagers NOT adolescents","cn":"teenagers NOT adolescents","en":"teenagers NOT adolescents"},"correct":false,"feedback":{"zh":"NOT會排除含adolescents的結果，與目標相反。","cn":"NOT会排除含adolescents的结果，与目标相反。","en":"NOT excludes results containing adolescents, contrary to the aim."},"id":"c"}],"takeaway":{"zh":"搜尋同義或相關詞時，可用OR擴闊覆蓋；AND用來交集。","cn":"搜寻同义或相关词时，可用OR扩阔覆盖；AND用来交集。","en":"Use OR to cover alternatives and AND to intersect concepts."}},{"id":"s2-library-02","grade":2,"subjectId":"library","roomId":"library","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"縮窄過廣搜尋","cn":"缩窄过广搜寻","en":"Narrowing a broad search"},"question":{"zh":"研究題目是「香港中學生的睡眠習慣」。只搜尋sleep得到太多無關結果，哪個修訂最聚焦？","cn":"研究题目是「香港中学生的睡眠习惯」。只搜寻sleep得到太多无关结果，哪个修订最聚焦？","en":"A project concerns sleep habits among Hong Kong secondary students. Searching sleep returns too much irrelevant material. Which revision is most focused?"},"options":[{"text":{"zh":"刪去sleep，只搜尋students","cn":"删去sleep，只搜寻students","en":"Remove sleep and search only students"},"correct":false,"feedback":{"zh":"這失去主題限制，可能得到更多不相關內容。","cn":"这失去主题限制，可能得到更多不相关内容。","en":"This removes the topic constraint and may add irrelevant results."},"id":"a"},{"text":{"zh":"sleep AND \"Hong Kong\" AND \"secondary students\"","cn":"sleep AND \"Hong Kong\" AND \"secondary students\"","en":"sleep AND \"Hong Kong\" AND \"secondary students\""},"correct":true,"feedback":{"zh":"加入地點和研究對象，讓搜尋對應題目範圍。","cn":"加入地点和研究对象，让搜寻对应题目范围。","en":"Adding location and population aligns the search with the topic."},"id":"b"},{"text":{"zh":"sleep OR holidays OR animals","cn":"sleep OR holidays OR animals","en":"sleep OR holidays OR animals"},"correct":false,"feedback":{"zh":"增加無關的OR詞組會擴大而非聚焦結果。","cn":"增加无关的OR词组会扩大而非聚焦结果。","en":"Unrelated OR terms broaden rather than focus the results."},"id":"c"}],"takeaway":{"zh":"把研究題目拆成主題、對象及情境，再組合搜尋詞。","cn":"把研究题目拆成主题、对象及情境，再组合搜寻词。","en":"Break a research topic into concept, population and context when choosing search terms."}},{"id":"s2-library-03","grade":2,"subjectId":"library","roomId":"library","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"摘要與原文","cn":"摘要与原文","en":"Abstract and full text"},"question":{"zh":"搜尋結果摘要說研究「可能有幫助」。你準備引用具體改善幅度，下一步最需要甚麼？","cn":"搜寻结果摘要说研究「可能有帮助」。你准备引用具体改善幅度，下一步最需要甚么？","en":"A search abstract says an intervention “may help”. You want to cite the size of the improvement. What do you need next?"},"options":[{"text":{"zh":"把「可能」改成「一定」，使文章更清楚","cn":"把「可能」改成「一定」，使文章更清楚","en":"Replace “may” with “definitely” for clarity"},"correct":false,"feedback":{"zh":"這提高了確定程度，卻沒有增加證據。","cn":"这提高了确定程度，却没有增加证据。","en":"This increases certainty without adding evidence."},"id":"a"},{"text":{"zh":"只引用搜尋結果的排序位置","cn":"只引用搜寻结果的排序位置","en":"Cite only its position in the search results"},"correct":false,"feedback":{"zh":"排序不是研究效果大小的證據。","cn":"排序不是研究效果大小的证据。","en":"Search rank is not evidence of effect size."},"id":"b"},{"text":{"zh":"閱讀原文的方法及結果，確認數值與適用對象","cn":"阅读原文的方法及结果，确认数值与适用对象","en":"Read the full methods and results to check the value and population"},"correct":true,"feedback":{"zh":"摘要未提供所需數據，原文可確認量度方式及條件。","cn":"摘要未提供所需数据，原文可确认量度方式及条件。","en":"The abstract lacks the required detail; the paper explains measurement and conditions."},"id":"c"}],"takeaway":{"zh":"引用精確結果前，核對原文中的方法、數值與範圍。","cn":"引用精确结果前，核对原文中的方法、数值与范围。","en":"Check methods, values and scope in the original before citing a precise result."}},{"id":"s3-library-01","grade":3,"subjectId":"library","roomId":"library","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"改寫仍須引用","cn":"改写仍须引用","en":"Paraphrasing still needs a citation"},"question":{"zh":"你用自己的句子概括一篇文章的核心論點，沒有逐字抄寫。應如何交代？","cn":"你用自己的句子概括一篇文章的核心论点，没有逐字抄写。应如何交代？","en":"You summarise an article’s central argument in your own words without copying its wording. How should you acknowledge it?"},"options":[{"text":{"zh":"加引號，但不寫來源","cn":"加引号，但不写来源","en":"Use quotation marks without a source"},"correct":false,"feedback":{"zh":"引號用於準確直接引文，亦不能代替來源資料。","cn":"引号用于准确直接引文，亦不能代替来源资料。","en":"Quotation marks indicate exact wording and do not replace attribution."},"id":"a"},{"text":{"zh":"保留原意，並註明文章來源","cn":"保留原意，并注明文章来源","en":"Preserve the meaning and cite the article"},"correct":true,"feedback":{"zh":"表達方式改變，論點來源仍需要交代。","cn":"表达方式改变，论点来源仍需要交代。","en":"Changing the wording does not remove the source of the idea."},"id":"b"},{"text":{"zh":"因為字句不同，所以不用引用","cn":"因为字句不同，所以不用引用","en":"Do not cite because the wording differs"},"correct":false,"feedback":{"zh":"引用不只用於直接引文，也用於借用的觀點。","cn":"引用不只用于直接引文，也用于借用的观点。","en":"Citation also acknowledges borrowed ideas, not just quotations."},"id":"c"}],"takeaway":{"zh":"區分直接引文與改寫，兩者都要讓讀者追查來源。","cn":"区分直接引文与改写，两者都要让读者追查来源。","en":"Distinguish quotation from paraphrase and make both traceable."}},{"id":"s3-library-02","grade":3,"subjectId":"library","roomId":"library","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"引用是否真的支持","cn":"引用是否真的支持","en":"Does the citation support the claim?"},"question":{"zh":"文章說「所有學生都偏好電子書」，引用的調查卻只訪問圖書學會20名會員，其中12人偏好電子書。哪句修訂符合資料？","cn":"文章说「所有学生都偏好电子书」，引用的调查却只访问图书学会20名会员，其中12人偏好电子书。哪句修订符合资料？","en":"An article claims all students prefer e-books. Its cited survey asked 20 library-club members, of whom 12 preferred e-books. Which revision fits?"},"options":[{"text":{"zh":"所有會員及全校學生都偏好電子書","cn":"所有会员及全校学生都偏好电子书","en":"All members and all students prefer e-books"},"correct":false,"feedback":{"zh":"樣本內也不是人人偏好，更不能推廣至未受訪者。","cn":"样本内也不是人人偏好，更不能推广至未受访者。","en":"Not even all respondents preferred them, and others were not surveyed."},"id":"a"},{"text":{"zh":"只有12名學生懂得使用電子書","cn":"只有12名学生懂得使用电子书","en":"Only 12 students know how to use e-books"},"correct":false,"feedback":{"zh":"偏好調查沒有量度使用能力。","cn":"偏好调查没有量度使用能力。","en":"The survey measured preference, not ability."},"id":"b"},{"text":{"zh":"受訪的20名會員中，有12人偏好電子書","cn":"受访的20名会员中，有12人偏好电子书","en":"Of the 20 club members surveyed, 12 preferred e-books"},"correct":true,"feedback":{"zh":"保留樣本範圍及實際結果，沒有推廣至全校。","cn":"保留样本范围及实际结果，没有推广至全校。","en":"This retains the sample and result without generalising to the whole school."},"id":"c"}],"takeaway":{"zh":"檢查引用是否支持主張的對象、數量及確定程度。","cn":"检查引用是否支持主张的对象、数量及确定程度。","en":"Check whether a citation supports a claim’s population, quantity and certainty."}},{"id":"s3-library-03","grade":3,"subjectId":"library","roomId":"library","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"版本更正","cn":"版本更正","en":"Corrections and versions"},"question":{"zh":"某研究原報告寫40%，更正公告說因資料輸入錯誤應為30%。你尚未交功課，最合理的處理是甚麼？","cn":"某研究原报告写40%，更正公告说因资料输入错误应为30%。你尚未交功课，最合理的处理是甚么？","en":"A report originally states 40%; a correction changes it to 30% after a data-entry error. Your assignment is not yet submitted. What should you do?"},"options":[{"text":{"zh":"採用更正值，並記錄所引用的更正版本","cn":"采用更正值，并记录所引用的更正版本","en":"Use the corrected figure and record the corrected version"},"correct":true,"feedback":{"zh":"最新更正直接影響數值，引用須讓讀者辨識版本。","cn":"最新更正直接影响数值，引用须让读者辨识版本。","en":"The correction changes the value; the citation should identify the version."},"id":"a"},{"text":{"zh":"保留40%，因為先看到的版本較可靠","cn":"保留40%，因为先看到的版本较可靠","en":"Keep 40% because the first version you saw is more reliable"},"correct":false,"feedback":{"zh":"先看到不代表正確，且已有明確更正。","cn":"先看到不代表正确，且已有明确更正。","en":"Seeing a version first does not make it more accurate."},"id":"b"},{"text":{"zh":"把40%與30%平均成35%","cn":"把40%与30%平均成35%","en":"Average 40% and 30% to get 35%"},"correct":false,"feedback":{"zh":"舊值是已知輸入錯誤，不是可與新值平均的獨立估計。","cn":"旧值是已知输入错误，不是可与新值平均的独立估计。","en":"The old value is a known error, not an independent estimate to average."},"id":"c"}],"takeaway":{"zh":"研究記錄應保留版本資訊，並處理已發布的更正。","cn":"研究记录应保留版本资讯，并处理已发布的更正。","en":"Track versions and account for published corrections."}},{"id":"s4-library-01","grade":4,"subjectId":"library","roomId":"library","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"把概念變成量度","cn":"把概念变成量度","en":"Operationalising a concept"},"question":{"zh":"研究「圖書館是否更方便使用」，哪個變項最直接量度找書效率？","cn":"研究「图书馆是否更方便使用」，哪个变项最直接量度找书效率？","en":"To study whether the library is easier to use, which variable most directly measures book-finding efficiency?"},"options":[{"text":{"zh":"受訪者喜歡的書封顏色","cn":"受访者喜欢的书封颜色","en":"Respondents’ favourite cover colours"},"correct":false,"feedback":{"zh":"封面喜好並非找書效率的直接量度。","cn":"封面喜好并非找书效率的直接量度。","en":"Cover preference does not directly measure search efficiency."},"id":"a"},{"text":{"zh":"圖書館名稱有多少個字","cn":"图书馆名称有多少个字","en":"The number of letters in the library’s name"},"correct":false,"feedback":{"zh":"名稱長度沒有直接量度使用者完成任務的效率。","cn":"名称长度没有直接量度使用者完成任务的效率。","en":"Name length does not directly measure task efficiency."},"id":"b"},{"text":{"zh":"在相同找書任務中完成所需時間","cn":"在相同找书任务中完成所需时间","en":"Time to complete the same book-finding task"},"correct":true,"feedback":{"zh":"明確任務與時間可形成可比較量度。","cn":"明确任务与时间可形成可比较量度。","en":"A defined task and completion time provide a comparable measure."},"id":"c"}],"takeaway":{"zh":"把抽象概念轉成與研究問題相關、可重複量度的指標。","cn":"把抽象概念转成与研究问题相关、可重复量度的指标。","en":"Translate an abstract concept into relevant, repeatable measures."}},{"id":"s4-library-02","grade":4,"subjectId":"library","roomId":"library","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"避免引導式問卷","cn":"避免引导式问卷","en":"Avoiding a leading survey"},"question":{"zh":"想了解新自修室的使用經驗，哪個問題最中立？","cn":"想了解新自修室的使用经验，哪个问题最中立？","en":"Which question most neutrally investigates experiences of a new study room?"},"options":[{"text":{"zh":"你使用自修室時，哪些安排有幫助，哪些有困難？","cn":"你使用自修室时，哪些安排有帮助，哪些有困难？","en":"Which features helped you, and which caused difficulties?"},"correct":true,"feedback":{"zh":"問題容許正面、負面或混合經驗，不預定結論。","cn":"问题容许正面、负面或混合经验，不预定结论。","en":"It allows positive, negative or mixed experiences without presupposing a result."},"id":"a"},{"text":{"zh":"你是否同意這間出色的自修室應立即擴建？","cn":"你是否同意这间出色的自修室应立即扩建？","en":"Do you agree this excellent room should be expanded immediately?"},"correct":false,"feedback":{"zh":"「出色」及擴建主張已引導評價方向。","cn":"「出色」及扩建主张已引导评价方向。","en":"“Excellent” and the expansion claim steer the response."},"id":"b"},{"text":{"zh":"為何新自修室浪費大家時間？","cn":"为何新自修室浪费大家时间？","en":"Why does the new room waste everyone’s time?"},"correct":false,"feedback":{"zh":"問題先假定負面效果，無法中立收集經驗。","cn":"问题先假定负面效果，无法中立收集经验。","en":"This assumes a negative effect before collecting evidence."},"id":"c"}],"takeaway":{"zh":"問卷措辭應讓不同經驗都能被表達。","cn":"问卷措辞应让不同经验都能被表达。","en":"Phrase surveys so different experiences can be expressed."}},{"id":"s4-library-03","grade":4,"subjectId":"library","roomId":"library","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"自選樣本","cn":"自选样本","en":"Self-selected samples"},"question":{"zh":"網上閱讀問卷只在閱讀獎勵羣組發布，80%的回覆者每天閱讀。最重要的推論限制是甚麼？","cn":"网上阅读问卷只在阅读奖励群组发布，80%的回复者每天阅读。最重要的推论限制是甚么？","en":"A reading survey is posted only in a reading-award group; 80% of respondents read daily. What is the main limitation?"},"options":[{"text":{"zh":"所有回覆必定是假資料","cn":"所有回复必定是假资料","en":"Every response must be fabricated"},"correct":false,"feedback":{"zh":"代表性不足不等於個別回覆必定造假。","cn":"代表性不足不等于个别回复必定造假。","en":"Limited representativeness does not mean responses are fabricated."},"id":"a"},{"text":{"zh":"羣組成員及自願回覆者可能較喜歡閱讀","cn":"群组成员及自愿回复者可能较喜欢阅读","en":"Group members and volunteers may be more interested in reading"},"correct":true,"feedback":{"zh":"招募途徑與自選回覆可能偏向特定習慣。","cn":"招募途径与自选回复可能偏向特定习惯。","en":"Recruitment and self-selection may favour particular habits."},"id":"b"},{"text":{"zh":"只要有百分率，就已代表全校","cn":"只要有百分率，就已代表全校","en":"A percentage automatically represents the school"},"correct":false,"feedback":{"zh":"百分率不能消除取樣偏差。","cn":"百分率不能消除取样偏差。","en":"Expressing a result as a percentage does not remove sampling bias."},"id":"c"}],"takeaway":{"zh":"評估調查時，先問誰有機會被邀請及誰選擇回覆。","cn":"评估调查时，先问谁有机会被邀请及谁选择回复。","en":"Ask who could be recruited and who chose to respond."}},{"id":"s5-library-01","grade":5,"subjectId":"library","roomId":"library","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"相對增加與基準","cn":"相对增加与基准","en":"Relative growth and the baseline"},"question":{"zh":"報告標題說「借閱量增加100%」，正文說由每週2本增至4本。哪個摘要最完整？","cn":"报告标题说「借阅量增加100%」，正文说由每周2本增至4本。哪个摘要最完整？","en":"A headline says borrowing rose 100%; the report specifies an increase from two to four books weekly. Which summary is most informative?"},"options":[{"text":{"zh":"每週由2本增至4本，增加2本，即100%","cn":"每周由2本增至4本，增加2本，即100%","en":"Weekly borrowing rose from 2 to 4 books: 2 more, or 100%"},"correct":true,"feedback":{"zh":"同時列基準、絕對差和相對變化，有助理解規模。","cn":"同时列基准、绝对差和相对变化，有助理解规模。","en":"The baseline, absolute difference and relative change clarify the scale."},"id":"a"},{"text":{"zh":"借閱量增加100本","cn":"借阅量增加100本","en":"Borrowing rose by 100 books"},"correct":false,"feedback":{"zh":"100%是相對比例，不是增加100本。","cn":"100%是相对比例，不是增加100本。","en":"100% is a relative change, not 100 additional books."},"id":"b"},{"text":{"zh":"因為增幅大，所以已證明政策成功","cn":"因为增幅大，所以已证明政策成功","en":"The large percentage proves the policy succeeded"},"correct":false,"feedback":{"zh":"兩個數值不會自行證明因果或政策成效。","cn":"两个数值不会自行证明因果或政策成效。","en":"Two figures alone do not establish causation or policy success."},"id":"c"}],"takeaway":{"zh":"報道百分率時，保留基準和絕對數，避免放大印象。","cn":"报道百分率时，保留基准和绝对数，避免放大印象。","en":"Report baselines and absolute values alongside percentages."}},{"id":"s5-library-02","grade":5,"subjectId":"library","roomId":"library","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"區分觀察與實驗","cn":"区分观察与实验","en":"Observational and experimental evidence"},"question":{"zh":"研究發現常到圖書館的學生平均成績較高，但沒有隨機分配使用次數。哪個結論最合適？","cn":"研究发现常到图书馆的学生平均成绩较高，但没有随机分配使用次数。哪个结论最合适？","en":"Students who visit the library often have higher average grades, but visits were not randomly assigned. Which conclusion is best?"},"options":[{"text":{"zh":"兩者沒有任何關係，因為不是實驗","cn":"两者没有任何关系，因为不是实验","en":"There is no relationship because it was not an experiment"},"correct":false,"feedback":{"zh":"觀察資料仍可顯示關聯，只是因果推論有限。","cn":"观察资料仍可显示关联，只是因果推论有限。","en":"Observational data can show association despite limited causal inference."},"id":"a"},{"text":{"zh":"兩者有關聯，但學習動機等因素也可能影響結果","cn":"两者有关联，但学习动机等因素也可能影响结果","en":"There is an association, but motivation and other factors may contribute"},"correct":true,"feedback":{"zh":"觀察性比較不能單獨排除共同影響因素。","cn":"观察性比较不能单独排除共同影响因素。","en":"An observational comparison cannot by itself exclude confounders."},"id":"b"},{"text":{"zh":"每多到圖書館一次都必然令成績上升","cn":"每多到图书馆一次都必然令成绩上升","en":"Every extra visit necessarily raises a student’s grade"},"correct":false,"feedback":{"zh":"研究沒有隔離每次到訪的因果效果。","cn":"研究没有隔离每次到访的因果效果。","en":"The study did not isolate the causal effect of each visit."},"id":"c"}],"takeaway":{"zh":"研究設計決定可作出的推論，不把關聯寫成已證實因果。","cn":"研究设计决定可作出的推论，不把关联写成已证实因果。","en":"Match the strength of a conclusion to the study design."}},{"id":"s5-library-03","grade":5,"subjectId":"library","roomId":"library","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"有系統地找反方證據","cn":"有系统地找反方证据","en":"Searching beyond agreement"},"question":{"zh":"研究者主張延長開放時間有效，卻只搜尋「延長開放的好處」。怎樣改善文獻搜尋最合適？","cn":"研究者主张延长开放时间有效，却只搜寻「延长开放的好处」。怎样改善文献搜寻最合适？","en":"A researcher argues that longer opening hours help but searches only for “benefits of longer hours”. What best improves the search?"},"options":[{"text":{"zh":"只增加更多「好處」同義詞","cn":"只增加更多「好处」同义词","en":"Add only more synonyms for benefits"},"correct":false,"feedback":{"zh":"這可能增加數量，但仍保留同一方向的選材偏差。","cn":"这可能增加数量，但仍保留同一方向的选材偏差。","en":"This may add results while retaining the same directional bias."},"id":"a"},{"text":{"zh":"遇到不同結論就刪除文章","cn":"遇到不同结论就删除文章","en":"Delete any article reaching another conclusion"},"correct":false,"feedback":{"zh":"依結論篩選會令綜合失去公正的證據基礎。","cn":"依结论筛选会令综合失去公正的证据基础。","en":"Filtering by conclusion undermines a fair synthesis."},"id":"b"},{"text":{"zh":"加入成效有限、成本及不同情境的搜尋詞，記錄納入準則","cn":"加入成效有限、成本及不同情境的搜寻词，记录纳入准则","en":"Search also for limited effects, costs and contexts, recording inclusion criteria"},"correct":true,"feedback":{"zh":"搜尋設計須容許找到挑戰原有主張的資料。","cn":"搜寻设计须容许找到挑战原有主张的资料。","en":"A search should be capable of finding evidence that challenges the initial claim."},"id":"c"}],"takeaway":{"zh":"搜尋及納入準則應先於結論，避免只收集支持自己的資料。","cn":"搜寻及纳入准则应先于结论，避免只收集支持自己的资料。","en":"Set search and inclusion criteria independently of the desired conclusion."}},{"id":"s6-library-01","grade":6,"subjectId":"library","roomId":"library","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"引用鏈與原始研究","cn":"引用链与原始研究","en":"Citation chains and original studies"},"question":{"zh":"五篇網誌都引用同一項研究，卻沒有新增資料。作證據綜合時，應如何計算獨立研究數目？","cn":"五篇网志都引用同一项研究，却没有新增资料。作证据综合时，应如何计算独立研究数目？","en":"Five blog posts cite the same study and add no new data. How should a synthesis count independent studies?"},"options":[{"text":{"zh":"網誌沒有新增資料，所以原研究也不存在","cn":"网志没有新增资料，所以原研究也不存在","en":"Because the blogs add no data, the original study does not exist"},"correct":false,"feedback":{"zh":"二手報道無新增證據，不代表原研究不存在。","cn":"二手报道无新增证据，不代表原研究不存在。","en":"Secondary repetition does not erase the underlying study."},"id":"a"},{"text":{"zh":"這條引用鏈只有一項原始研究","cn":"这条引用链只有一项原始研究","en":"This citation chain contains one original study"},"correct":true,"feedback":{"zh":"轉述次數不會增加獨立研究或樣本數。","cn":"转述次数不会增加独立研究或样本数。","en":"Repeated reporting does not add independent studies or participants."},"id":"b"},{"text":{"zh":"共有六項互相驗證的研究","cn":"共有六项互相验证的研究","en":"There are six mutually confirming studies"},"correct":false,"feedback":{"zh":"原研究加五篇轉述不是六次獨立調查。","cn":"原研究加五篇转述不是六次独立调查。","en":"One study plus five reports is not six independent investigations."},"id":"c"}],"takeaway":{"zh":"追溯到原始資料，避免把多次轉述重複計入證據。","cn":"追溯到原始资料，避免把多次转述重复计入证据。","en":"Trace original data to avoid double-counting repeated reports."}},{"id":"s6-library-02","grade":6,"subjectId":"library","roomId":"library","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"結果不同如何綜合","cn":"结果不同如何综合","en":"Synthesising different results"},"question":{"zh":"研究甲：有導師支援的初學者進步；研究乙：獨立使用同一工具的熟練者沒有明顯進步。哪個綜合最合理？","cn":"研究甲：有导师支援的初学者进步；研究乙：独立使用同一工具的熟练者没有明显进步。哪个综合最合理？","en":"Study A finds gains for beginners with tutoring; B finds no clear gains for experienced users working alone with the same tool. Which synthesis is most reasonable?"},"options":[{"text":{"zh":"兩個結論互相抵消，所以不需再看方法","cn":"两个结论互相抵消，所以不需再看方法","en":"The findings cancel out, so methods are irrelevant"},"correct":false,"feedback":{"zh":"研究結果不能像相反數字般直接抵消。","cn":"研究结果不能像相反数字般直接抵消。","en":"Findings cannot simply be cancelled like opposite numbers."},"id":"a"},{"text":{"zh":"只選自己較喜歡的一項","cn":"只选自己较喜欢的一项","en":"Choose only the study you prefer"},"correct":false,"feedback":{"zh":"個人喜好不能代替方法與適用範圍的比較。","cn":"个人喜好不能代替方法与适用范围的比较。","en":"Preference cannot replace comparing methods and scope."},"id":"b"},{"text":{"zh":"效果可能與原有能力及支援條件有關，需比較設計","cn":"效果可能与原有能力及支援条件有关，需比较设计","en":"Effects may depend on prior skill and support; compare the study designs"},"correct":true,"feedback":{"zh":"兩項研究的對象及條件不同，不能只把結果視為直接矛盾。","cn":"两项研究的对象及条件不同，不能只把结果视为直接矛盾。","en":"Different participants and conditions mean the findings are not simply contradictory."},"id":"c"}],"takeaway":{"zh":"證據綜合要解釋差異可能來自甚麼，而非只統計支持或反對篇數。","cn":"证据综合要解释差异可能来自甚么，而非只统计支持或反对篇数。","en":"Synthesis should explain differences rather than merely count favourable and unfavourable studies."}},{"id":"s6-library-03","grade":6,"subjectId":"library","roomId":"library","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"可重做的研究記錄","cn":"可重做的研究记录","en":"A reproducible research record"},"question":{"zh":"同學要依你的文獻搜尋重做一次。哪組記錄最能協助重現？","cn":"同学要依你的文献搜寻重做一次。哪组记录最能协助重现？","en":"A classmate wants to repeat your literature search. Which record best supports replication?"},"options":[{"text":{"zh":"資料庫、日期、完整搜尋式、篩選準則及排除原因","cn":"资料库、日期、完整搜寻式、筛选准则及排除原因","en":"Databases, dates, full queries, selection criteria and exclusion reasons"},"correct":true,"feedback":{"zh":"這些資料讓他人理解如何找到及選擇證據。","cn":"这些资料让他人理解如何找到及选择证据。","en":"These details reveal how evidence was located and selected."},"id":"a"},{"text":{"zh":"只列最後三篇最喜歡的文章","cn":"只列最后三篇最喜欢的文章","en":"Only the final three favourite articles"},"correct":false,"feedback":{"zh":"結果清單沒有交代搜尋範圍和篩選過程。","cn":"结果清单没有交代搜寻范围和筛选过程。","en":"A final list does not document search scope or selection."},"id":"b"},{"text":{"zh":"只保存文章封面的截圖","cn":"只保存文章封面的截图","en":"Only screenshots of article covers"},"correct":false,"feedback":{"zh":"封面通常不包含重做搜尋所需的方法資訊。","cn":"封面通常不包含重做搜寻所需的方法资讯。","en":"Covers usually lack the methodological details needed."},"id":"c"}],"takeaway":{"zh":"透明研究須保存搜尋與選擇過程，讓限制可被檢查。","cn":"透明研究须保存搜寻与选择过程，让限制可被检查。","en":"Document search and selection processes so the research and its limits can be examined."}},{"id":"s1-rooftop-01","grade":1,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"探究：觀察與推論","cn":"探究：观察与推论","en":"Enquiry: observation and inference"},"question":{"zh":"學生記錄天台植物：「三片葉變黃，所以一定缺肥。」哪部分是直接觀察？","cn":"学生记录天台植物：「三片叶变黄，所以一定缺肥。」哪部分是直接观察？","en":"A student writes: ‘Three rooftop-plant leaves turned yellow, so the plant must lack fertiliser.’ Which part is a direct observation?"},"options":[{"text":{"zh":"有三片葉變黃。","cn":"有三片叶变黄。","en":"Three leaves turned yellow."},"correct":true,"feedback":{"zh":"顏色和數目可直接記錄；缺肥是仍需證據的原因推論。","cn":"颜色和数目可直接记录；缺肥是仍需证据的原因推论。","en":"Colour and count can be recorded directly; nutrient deficiency is a causal inference needing evidence."},"id":"a"},{"text":{"zh":"缺肥必定是唯一原因。","cn":"缺肥必定是唯一原因。","en":"Lack of fertiliser must be the only cause."},"correct":false,"feedback":{"zh":"水分、光照、病害等也可能造成黃葉。","cn":"水分、光照、病害等也可能造成黄叶。","en":"Water, light, disease and other factors can also cause yellowing."},"id":"b"},{"text":{"zh":"施肥後植物必定立即康復。","cn":"施肥后植物必定立即康复。","en":"The plant will certainly recover immediately after fertilising."},"correct":false,"feedback":{"zh":"這是未經測試的預測，不是已觀察結果。","cn":"这是未经测试的预测，不是已观察结果。","en":"This is an untested prediction, not an observed result."},"id":"c"}],"takeaway":{"zh":"先記錄可觀察的現象，再提出可檢驗的解釋。","cn":"先记录可观察的现象，再提出可检验的解释。","en":"Record observable features before proposing testable explanations."}},{"id":"s1-rooftop-02","grade":1,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"探究：水量收支","cn":"探究：水量收支","en":"Enquiry: a water balance"},"question":{"zh":"天台水箱早上有 40 L，收集雨水 18 L，澆花用去 25 L；假設沒有其他流入或流出。剩下多少？","cn":"天台水箱早上有 40 L，收集雨水 18 L，浇花用去 25 L；假设没有其他流入或流出。剩下多少？","en":"A rooftop tank starts with 40 L, collects 18 L of rainwater and uses 25 L for watering. With no other flows, how much remains?"},"options":[{"text":{"zh":"7 L","cn":"7 L","en":"7 L"},"correct":false,"feedback":{"zh":"25−18 把流出減流入，而且漏計原有 40 L；應是 40+18−25。","cn":"25−18 把流出减流入，而且漏计原有 40 L；应是 40+18−25。","en":"25−18 reverses the inflow/outflow balance and omits the initial 40 L; use 40+18−25."},"id":"a"},{"text":{"zh":"33 L","cn":"33 L","en":"33 L"},"correct":true,"feedback":{"zh":"期末水量=40+18−25=33 L。","cn":"期末水量=40+18−25=33 L。","en":"Final storage=40+18−25=33 L."},"id":"b"},{"text":{"zh":"83 L","cn":"83 L","en":"83 L"},"correct":false,"feedback":{"zh":"用去的水應扣除，不能當成流入相加。","cn":"用去的水应扣除，不能当成流入相加。","en":"Water used is an outflow and must be subtracted."},"id":"c"}],"takeaway":{"zh":"系統收支要包含初始存量、輸入與輸出。","cn":"系统收支要包含初始存量、输入与输出。","en":"A system balance includes initial storage, inputs and outputs."}},{"id":"s1-rooftop-03","grade":1,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"探究：公平比較生長","cn":"探究：公平比较生长","en":"Enquiry: fairly comparing growth"},"question":{"zh":"學生把一盆豆苗放陽光下並每天澆水，另一盆放陰暗處且不澆水，想知道光照影響。哪個設計較好？","cn":"学生把一盆豆苗放阳光下并每天浇水，另一盆放阴暗处且不浇水，想知道光照影响。哪个设计较好？","en":"One seedling is placed in sunlight and watered daily; another is kept dark without water. To investigate light, which design is better?"},"options":[{"text":{"zh":"每組只留一盆，並給陽光組更多肥料。","cn":"每组只留一盆，并给阳光组更多肥料。","en":"Keep one plant per group and add more fertiliser to the sunny group."},"correct":false,"feedback":{"zh":"這增加肥料的混雜影響，也沒有重複。","cn":"这增加肥料的混杂影响，也没有重复。","en":"This adds fertiliser as a confound and provides no replication."},"id":"a"},{"text":{"zh":"直接比較兩盆最後高度，不記錄起始高度。","cn":"直接比较两盆最后高度，不记录起始高度。","en":"Compare final height only and ignore starting height."},"correct":false,"feedback":{"zh":"起點不同可影響最後高度，且原設計水量仍不同。","cn":"起点不同可影响最后高度，且原设计水量仍不同。","en":"Different starting heights can affect final heights, and the water confound remains."},"id":"b"},{"text":{"zh":"使用多盆相近豆苗，水量和土壤相同，只改變光照。","cn":"使用多盆相近豆苗，水量和土壤相同，只改变光照。","en":"Use several comparable seedlings with equal water and soil, varying only light."},"correct":true,"feedback":{"zh":"控制水分並增加重複，可更合理比較光照的影響。","cn":"控制水分并增加重复，可更合理比较光照的影响。","en":"Controlling water and including replicates gives a fairer comparison of light."},"id":"c"}],"takeaway":{"zh":"生長比較需要相近起點、控制條件與重複觀察。","cn":"生长比较需要相近起点、控制条件与重复观察。","en":"Growth comparisons need comparable baselines, controlled conditions and repeated observations."}},{"id":"s2-rooftop-01","grade":2,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"探究：食物網的間接影響","cn":"探究：食物网的间接影响","en":"Enquiry: indirect effects in a food web"},"question":{"zh":"簡化天台食物鏈為植物 → 毛蟲 → 小鳥，箭嘴表示食物能量流向。若毛蟲大量減少，小鳥最直接面對甚麼？","cn":"简化天台食物链为植物 → 毛虫 → 小鸟，箭嘴表示食物能量流向。若毛虫大量减少，小鸟最直接面对甚么？","en":"A simplified rooftop food chain is plants → caterpillars → birds, with arrows showing food-energy flow. If caterpillars decline sharply, what do birds most directly face?"},"options":[{"text":{"zh":"小鳥必定完全不受影響，因為可以飛。","cn":"小鸟必定完全不受影响，因为可以飞。","en":"Birds must be completely unaffected because they can fly."},"correct":false,"feedback":{"zh":"移動能力不代表食物供應不影響生存；其他食物仍須調查。","cn":"移动能力不代表食物供应不影响生存；其他食物仍须调查。","en":"Mobility does not remove food dependence; alternative foods would need investigation."},"id":"a"},{"text":{"zh":"這條食物鏈中的食物供應減少。","cn":"这条食物链中的食物供应减少。","en":"Less food supply through this chain."},"correct":true,"feedback":{"zh":"毛蟲是此鏈中小鳥的食物，減少會影響能量來源。","cn":"毛虫是此链中小鸟的食物，减少会影响能量来源。","en":"Caterpillars are the birds' food in this chain, so fewer means less energy supply."},"id":"b"},{"text":{"zh":"植物立刻變成小鳥。","cn":"植物立刻变成小鸟。","en":"Plants immediately turn into birds."},"correct":false,"feedback":{"zh":"箭嘴表示能量傳遞，不是生物變成另一種生物。","cn":"箭嘴表示能量传递，不是生物变成另一种生物。","en":"Arrows represent energy transfer, not organisms transforming into one another."},"id":"c"}],"takeaway":{"zh":"食物網連結不同生物；簡化模型亦可能省略替代食物。","cn":"食物网连结不同生物；简化模型亦可能省略替代食物。","en":"Food webs connect organisms; simplified models may omit alternative foods."}},{"id":"s2-rooftop-02","grade":2,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"探究：面積與雨水收集","cn":"探究：面积与雨水收集","en":"Enquiry: area and rainwater collection"},"question":{"zh":"降雨 10 mm 落在 20 m² 屋頂。假設每 1 mm 落在 1 m² 等於 1 L，收集效率為 80%。可收多少水？","cn":"降雨 10 mm 落在 20 m² 屋顶。假设每 1 mm 落在 1 m² 等于 1 L，收集效率为 80%。可收多少水？","en":"10 mm of rain falls on a 20 m² roof. Each 1 mm over 1 m² equals 1 L; collection efficiency is 80%. How much water is collected?"},"options":[{"text":{"zh":"200 L","cn":"200 L","en":"200 L"},"correct":false,"feedback":{"zh":"這是未考慮收集損失的理論總量。","cn":"这是未考虑收集损失的理论总量。","en":"This is the theoretical total before collection losses."},"id":"a"},{"text":{"zh":"16 L","cn":"16 L","en":"16 L"},"correct":false,"feedback":{"zh":"10×20×0.8=160，結果少了一個十倍。","cn":"10×20×0.8=160，结果少了一个十倍。","en":"10×20×0.8=160, so this is ten times too small."},"id":"b"},{"text":{"zh":"160 L","cn":"160 L","en":"160 L"},"correct":true,"feedback":{"zh":"理論雨量 10×20=200 L，再乘 0.8 得 160 L。","cn":"理论雨量 10×20=200 L，再乘 0.8 得 160 L。","en":"Theoretical rain volume is 10×20=200 L; multiplying by 0.8 gives 160 L."},"id":"c"}],"takeaway":{"zh":"估算資源量要連結深度、面積及系統效率。","cn":"估算资源量要连结深度、面积及系统效率。","en":"Resource estimates connect depth, area and system efficiency."}},{"id":"s2-rooftop-03","grade":2,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"探究：用比例比較發芽","cn":"探究：用比例比较发芽","en":"Enquiry: comparing germination rates"},"question":{"zh":"甲種子發芽 18/20，乙種子發芽 32/40。哪個比較正確？","cn":"甲种子发芽 18/20，乙种子发芽 32/40。哪个比较正确？","en":"Seed type A germinates in 18 of 20 cases; B in 32 of 40. Which comparison is correct?"},"options":[{"text":{"zh":"甲發芽率 90%，乙 80%；乙發芽總數多，但比例較低。","cn":"甲发芽率 90%，乙 80%；乙发芽总数多，但比例较低。","en":"A's rate is 90% and B's 80%; B has more germinated seeds but a lower rate."},"correct":true,"feedback":{"zh":"樣本數不同，要同時區分總數和比例。","cn":"样本数不同，要同时区分总数和比例。","en":"Different sample sizes require distinguishing counts from rates."},"id":"a"},{"text":{"zh":"乙較好，因為 32 永遠大於 18。","cn":"乙较好，因为 32 永远大于 18。","en":"B has a higher rate because 32 exceeds 18."},"correct":false,"feedback":{"zh":"單看分子忽略了乙用了雙倍種子。","cn":"单看分子忽略了乙用了双倍种子。","en":"Looking only at the numerator ignores B's doubled starting count."},"id":"b"},{"text":{"zh":"兩者差 14 個百分點。","cn":"两者差 14 个百分点。","en":"The rates differ by 14 percentage points."},"correct":false,"feedback":{"zh":"14 是發芽數差；比例差為 90%−80%=10 個百分點。","cn":"14 是发芽数差；比例差为 90%−80%=10 个百分点。","en":"14 is the count difference; the rate difference is ten percentage points."},"id":"c"}],"takeaway":{"zh":"比較效果須使用合適比例，同時保留樣本數及不確定性。","cn":"比较效果须使用合适比例，同时保留样本数及不确定性。","en":"Compare outcomes with suitable rates while retaining sample size and uncertainty."}},{"id":"s3-rooftop-01","grade":3,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"探究：物種豐富度與均勻度","cn":"探究：物种丰富度与均匀度","en":"Enquiry: richness and evenness"},"question":{"zh":"兩個花槽各有三種植物。甲的數量為 10、10、10；乙為 28、1、1。哪項正確？","cn":"两个花槽各有三种植物。甲的数量为 10、10、10；乙为 28、1、1。哪项正确？","en":"Two planters each contain three plant species. Counts are 10,10,10 in A and 28,1,1 in B. Which statement is correct?"},"options":[{"text":{"zh":"乙有二十八種植物。","cn":"乙有二十八种植物。","en":"B contains twenty-eight species."},"correct":false,"feedback":{"zh":"28 是其中一種的個體數，不是種類數。","cn":"28 是其中一种的个体数，不是种类数。","en":"28 is the number of individuals of one species, not species richness."},"id":"a"},{"text":{"zh":"總數相同，所以所有多樣性特徵都相同。","cn":"总数相同，所以所有多样性特征都相同。","en":"Equal totals mean every aspect of diversity is identical."},"correct":false,"feedback":{"zh":"相同總數和種類數仍可有不同均勻度。","cn":"相同总数和种类数仍可有不同均匀度。","en":"Equal totals and richness can still have different evenness."},"id":"b"},{"text":{"zh":"物種豐富度相同，甲的均勻度較高。","cn":"物种丰富度相同，甲的均匀度较高。","en":"Species richness is equal; A has greater evenness."},"correct":true,"feedback":{"zh":"豐富度數種類，均勻度描述個體分佈是否接近。","cn":"丰富度数种类，均匀度描述个体分布是否接近。","en":"Richness counts species; evenness describes how similarly individuals are distributed."},"id":"c"}],"takeaway":{"zh":"描述生物多樣性時，區分種類數、個體總數與分佈。","cn":"描述生物多样性时，区分种类数、个体总数与分布。","en":"Distinguish species count, total individuals and their distribution when describing biodiversity."}},{"id":"s3-rooftop-02","grade":3,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"探究：堆肥的物質循環","cn":"探究：堆肥的物质循环","en":"Enquiry: material cycling in compost"},"question":{"zh":"落葉堆肥後質量減少，學生說物質消失了。哪個解釋較合理？","cn":"落叶堆肥后质量减少，学生说物质消失了。哪个解释较合理？","en":"A leaf compost pile loses mass. A student says matter has disappeared. Which explanation is more reasonable?"},"options":[{"text":{"zh":"分解過程中部分物質以二氧化碳、水等離開量度系統。","cn":"分解过程中部分物质以二氧化碳、水等离开量度系统。","en":"During decomposition, some material leaves the measured system as carbon dioxide, water and other products."},"correct":true,"feedback":{"zh":"開放系統的堆肥質量可減少，並不違反物質守恆。","cn":"开放系统的堆肥质量可减少，并不违反物质守恒。","en":"Mass in an open compost system can decrease without violating conservation of matter."},"id":"a"},{"text":{"zh":"微生物把所有原子變成沒有質量的能量。","cn":"微生物把所有原子变成没有质量的能量。","en":"Microorganisms convert all atoms into massless energy."},"correct":false,"feedback":{"zh":"一般生物化學分解不會把全部物質消滅。","cn":"一般生物化学分解不会把全部物质消灭。","en":"Ordinary biochemical decomposition does not annihilate all matter."},"id":"b"},{"text":{"zh":"天平一定壞了，因為任何開放系統質量都不會改變。","cn":"天平一定坏了，因为任何开放系统质量都不会改变。","en":"The balance must be broken because open-system mass cannot change."},"correct":false,"feedback":{"zh":"開放系統可以與環境交換物質。","cn":"开放系统可以与环境交换物质。","en":"An open system can exchange matter with its surroundings."},"id":"c"}],"takeaway":{"zh":"解釋環境系統的質量變化時，先界定系統邊界和物質流。","cn":"解释环境系统的质量变化时，先界定系统边界和物质流。","en":"Define system boundaries and material flows before explaining environmental mass changes."}},{"id":"s3-rooftop-03","grade":3,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"探究：樣方取樣的偏差","cn":"探究：样方取样的偏差","en":"Enquiry: bias in quadrat sampling"},"question":{"zh":"學生只在開花最多的角落放五個樣方，估計整個天台花朵密度。應如何改良？","cn":"学生只在开花最多的角落放五个样方，估计整个天台花朵密度。应如何改良？","en":"Students place five quadrats only in the most flowery corner to estimate flower density over the whole roof. How should they improve?"},"options":[{"text":{"zh":"刪除沒有花的樣方，令平均值更穩定。","cn":"删除没有花的样方，令平均值更稳定。","en":"Delete empty quadrats to stabilise the mean."},"correct":false,"feedback":{"zh":"刪去真實零值會系統性提高估計密度。","cn":"删去真实零值会系统性提高估计密度。","en":"Removing genuine zeroes systematically inflates estimated density."},"id":"a"},{"text":{"zh":"用預先決定的隨機或系統取樣位置覆蓋整個研究範圍，保留零花樣方。","cn":"用预先决定的随机或系统取样位置覆盖整个研究范围，保留零花样方。","en":"Use predetermined random or systematic positions across the study area and retain zero-flower quadrats."},"correct":true,"feedback":{"zh":"按結果選位置會高估密度；零值也是研究範圍的資料。","cn":"按结果选位置会高估密度；零值也是研究范围的资料。","en":"Selecting sites by the outcome inflates density; zeroes are also valid area data."},"id":"b"},{"text":{"zh":"只增加該角落的樣方數到五十。","cn":"只增加该角落的样方数到五十。","en":"Increase the same corner's quadrats to fifty."},"correct":false,"feedback":{"zh":"樣本多仍可能有位置偏差，不能代替範圍覆蓋。","cn":"样本多仍可能有位置偏差，不能代替范围覆盖。","en":"A larger sample can remain spatially biased and does not replace coverage."},"id":"c"}],"takeaway":{"zh":"取樣位置要先於結果決定，並保留研究範圍內的真實零值。","cn":"取样位置要先于结果决定，并保留研究范围内的真实零值。","en":"Choose sampling positions independently of results and retain genuine zeroes."}},{"id":"s4-rooftop-01","grade":4,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"延伸：太陽能轉換效率","cn":"延伸：太阳能转换效率","en":"Extension: solar conversion efficiency"},"question":{"zh":"一小時內太陽能板接收 2.0 kWh 輻射能，輸出 0.40 kWh 電能。轉換效率是多少？","cn":"一小时内太阳能板接收 2.0 kWh 辐射能，输出 0.40 kWh 电能。转换效率是多少？","en":"In one hour, a solar panel receives 2.0 kWh of radiant energy and supplies 0.40 kWh of electrical energy. What is its conversion efficiency?"},"options":[{"text":{"zh":"20%","cn":"20%","en":"20%"},"correct":true,"feedback":{"zh":"效率=有用輸出÷輸入=0.40÷2.0=20%。","cn":"效率=有用输出÷输入=0.40÷2.0=20%。","en":"Efficiency=useful output/input=0.40/2.0=20%."},"id":"a"},{"text":{"zh":"80%","cn":"80%","en":"80%"},"correct":false,"feedback":{"zh":"80% 是沒有轉成這部分電能的比例，不是所求輸出效率。","cn":"80% 是没有转成这部分电能的比例，不是所求输出效率。","en":"80% is the fraction not converted into the stated electrical output."},"id":"b"},{"text":{"zh":"500%","cn":"500%","en":"500%"},"correct":false,"feedback":{"zh":"這把輸入除以輸出，倒轉了效率定義。","cn":"这把输入除以输出，倒转了效率定义。","en":"This divides input by output, reversing the definition."},"id":"c"}],"takeaway":{"zh":"效率要明確界定輸入、有用輸出及相同量綱。","cn":"效率要明确界定输入、有用输出及相同量纲。","en":"Define input and useful output in matching quantities when calculating efficiency."}},{"id":"s4-rooftop-02","grade":4,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"延伸：量度不確定度","cn":"延伸：量度不确定度","en":"Extension: measurement uncertainty"},"question":{"zh":"兩感應器顯示 28.4°C 和 28.7°C，兩者標示誤差均可達 ±0.5°C。最合理的初步結論？","cn":"两感应器显示 28.4°C 和 28.7°C，两者标示误差均可达 ±0.5°C。最合理的初步结论？","en":"Two sensors read 28.4°C and 28.7°C, each with stated error up to ±0.5°C. What is the most reasonable initial conclusion?"},"options":[{"text":{"zh":"誤差存在，所有溫度資料都完全無用。","cn":"误差存在，所有温度资料都完全无用。","en":"Any measurement error makes all temperature data useless."},"correct":false,"feedback":{"zh":"量度可在適當精確度和不確定性說明下使用。","cn":"量度可在适当精确度和不确定性说明下使用。","en":"Measurements remain useful when reported with appropriate precision and uncertainty."},"id":"a"},{"text":{"zh":"0.3°C 差異小於量度誤差尺度，需校準和重複纔可判斷實際差別。","cn":"0.3°C 差异小于量度误差尺度，需校准和重复才可判断实际差别。","en":"The 0.3°C difference is small relative to measurement error; calibrate and repeat before inferring a real difference."},"correct":true,"feedback":{"zh":"可能值範圍重疊，單次讀數不支持精確的實際差異。","cn":"可能值范围重叠，单次读数不支持精确的实际差异。","en":"The possible ranges overlap, so single readings do not establish a precise real difference."},"id":"b"},{"text":{"zh":"第二處肯定比第一處恰好熱 0.3°C。","cn":"第二处肯定比第一处恰好热 0.3°C。","en":"The second location is certainly exactly 0.3°C warmer."},"correct":false,"feedback":{"zh":"這忽略了感應器誤差及重複量度需要。","cn":"这忽略了感应器误差及重复量度需要。","en":"This ignores instrument error and the need for repeated measurement."},"id":"c"}],"takeaway":{"zh":"差異大小應與儀器不確定度比較，不把顯示的小數當成保證。","cn":"差异大小应与仪器不确定度比较，不把显示的小数当成保证。","en":"Compare differences with instrument uncertainty; displayed decimals are not guarantees."}},{"id":"s4-rooftop-03","grade":4,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"延伸：控制與重複","cn":"延伸：控制与重复","en":"Extension: controls and replication"},"question":{"zh":"比較兩種屋頂塗層的降溫效果，甲塗層只有一塊向北板，乙塗層只有一塊向南板。最佳下一步是甚麼？","cn":"比较两种屋顶涂层的降温效果，甲涂层只有一块向北板，乙涂层只有一块向南板。最佳下一步是甚么？","en":"To compare cooling coatings, A is tested on one north-facing panel and B on one south-facing panel. What is the best next step?"},"options":[{"text":{"zh":"每分鐘量同一兩塊板，便完全消除朝向差異。","cn":"每分钟量同一两块板，便完全消除朝向差异。","en":"Measure the same two panels every minute to eliminate orientation differences."},"correct":false,"feedback":{"zh":"重複時間讀數不能消除塗層與朝向綁定的混雜。","cn":"重复时间读数不能消除涂层与朝向绑定的混杂。","en":"Repeated time readings do not remove the confounding of coating with orientation."},"id":"a"},{"text":{"zh":"只比較最高溫的一次，因為它最明顯。","cn":"只比较最高温的一次，因为它最明显。","en":"Compare only the hottest observation because it is most striking."},"correct":false,"feedback":{"zh":"挑選極端結果會增加偏差，也未修正設計。","cn":"挑选极端结果会增加偏差，也未修正设计。","en":"Selecting an extreme result adds bias without repairing the design."},"id":"b"},{"text":{"zh":"把多塊相同板隨機分配兩塗層，控制朝向並同步量度。","cn":"把多块相同板随机分配两涂层，控制朝向并同步量度。","en":"Randomly assign multiple identical panels to each coating, control orientation and measure simultaneously."},"correct":true,"feedback":{"zh":"朝向與單一樣本會影響比較；隨機分配、控制及重複改善設計。","cn":"朝向与单一样本会影响比较；随机分配、控制及重复改善设计。","en":"Orientation and single samples weaken comparison; randomisation, control and replication improve it."},"id":"c"}],"takeaway":{"zh":"重複讀數不等於獨立實驗重複；設計要分離處理與環境因素。","cn":"重复读数不等于独立实验重复；设计要分离处理与环境因素。","en":"Repeated readings are not the same as independent replication; separate treatment from environmental factors."}},{"id":"s5-rooftop-01","grade":5,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"延伸：生命週期的排放範圍","cn":"延伸：生命周期的排放范围","en":"Extension: life-cycle emission boundaries"},"question":{"zh":"兩款花盆使用時都不耗電。要比較生命週期碳排放，還需考慮甚麼？","cn":"两款花盆使用时都不耗电。要比较生命周期碳排放，还需考虑甚么？","en":"Neither of two planter designs uses electricity during use. What else is needed to compare life-cycle carbon emissions?"},"options":[{"text":{"zh":"只比較送到學校後的排放，忽略生產和運輸。","cn":"只比较送到学校后的排放，忽略生产和运输。","en":"Compare emissions only after arrival at school, omitting production and transport."},"correct":false,"feedback":{"zh":"這縮窄系統邊界，不能回答全生命週期的問題。","cn":"这缩窄系统边界，不能回答全生命周期的问题。","en":"This narrower boundary cannot answer the full life-cycle question."},"id":"a"},{"text":{"zh":"材料生產、運輸、使用年期、重用及棄置，並採相同功能單位。","cn":"材料生产、运输、使用年期、重用及弃置，并采相同功能单位。","en":"Material production, transport, service life, reuse and disposal, using the same functional unit."},"correct":true,"feedback":{"zh":"只看使用時耗電會漏掉其他階段；相同功能纔有可比性。","cn":"只看使用时耗电会漏掉其他阶段；相同功能才有可比性。","en":"Use-phase electricity alone misses other stages; a common function enables comparison."},"id":"b"},{"text":{"zh":"只比較每個花盆的製造排放，不管容量和可用年期。","cn":"只比较每个花盆的制造排放，不管容量和可用年期。","en":"Compare manufacturing emissions per planter, ignoring capacity and service life."},"correct":false,"feedback":{"zh":"不同容量或壽命不能只按一個花盆直接比較，需相同功能單位及邊界。","cn":"不同容量或寿命不能只按一个花盆直接比较，需相同功能单位及边界。","en":"Different capacities or lifetimes require a common functional unit and boundary, not only a per-planter figure."},"id":"c"}],"takeaway":{"zh":"環境比較要交代系統邊界和功能單位，避免把單一階段代表全程。","cn":"环境比较要交代系统边界和功能单位，避免把单一阶段代表全程。","en":"State system boundaries and functional units rather than treating one stage as the entire life cycle."}},{"id":"s5-rooftop-02","grade":5,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"延伸：能源回收期","cn":"延伸：能源回收期","en":"Extension: energy payback time"},"question":{"zh":"裝置製造需 1,200 kWh 能量，每年淨節省 300 kWh；假設節省穩定且沒有其他投入。能源回收期是多少？","cn":"装置制造需 1,200 kWh 能量，每年净节省 300 kWh；假设节省稳定且没有其他投入。能源回收期是多少？","en":"A device requires 1,200 kWh to manufacture and saves a net 300 kWh annually. Assuming constant savings and no other inputs, what is its energy payback time?"},"options":[{"text":{"zh":"0.25 年。","cn":"0.25 年。","en":"0.25 years."},"correct":false,"feedback":{"zh":"這把年節省除以投入，倒轉了所需時間的計算。","cn":"这把年节省除以投入，倒转了所需时间的计算。","en":"This reverses the investment-to-annual-saving ratio."},"id":"a"},{"text":{"zh":"900 年。","cn":"900 年。","en":"900 years."},"correct":false,"feedback":{"zh":"1,200−300 是首年尚未回收的能量，不是年數。","cn":"1,200−300 是首年尚未回收的能量，不是年数。","en":"1,200−300 is unrecovered energy after year one, not a time in years."},"id":"b"},{"text":{"zh":"4 年。","cn":"4 年。","en":"4 years."},"correct":true,"feedback":{"zh":"1,200 kWh ÷ 300 kWh/年 = 4 年；這不是金錢回本期。","cn":"1,200 kWh ÷ 300 kWh/年 = 4 年；这不是金钱回本期。","en":"1,200 kWh divided by 300 kWh/year gives 4 years; this is not financial payback."},"id":"c"}],"takeaway":{"zh":"回收期計算需保持單位一致，並辨明能源、碳或金錢的不同指標。","cn":"回收期计算需保持单位一致，并辨明能源、碳或金钱的不同指标。","en":"Keep units consistent and distinguish energy, carbon and financial payback measures."}},{"id":"s5-rooftop-03","grade":5,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"延伸：非隨機資料缺失","cn":"延伸：非随机资料缺失","en":"Extension: non-random missing observations"},"question":{"zh":"濕度感應器只在大雨時斷線。分析者刪去缺失日後聲稱「天台全年都乾燥」。主要問題是甚麼？","cn":"湿度感应器只在大雨时断线。分析者删去缺失日后声称「天台全年都干燥」。主要问题是甚么？","en":"A humidity sensor disconnects only during heavy rain. An analyst removes missing days and claims the roof is dry throughout the year. What is the main problem?"},"options":[{"text":{"zh":"缺失與潮濕情況有關，保留資料可能低估全年濕度。","cn":"缺失与潮湿情况有关，保留资料可能低估全年湿度。","en":"Missingness is related to wet conditions, so retained data may underestimate year-round humidity."},"correct":true,"feedback":{"zh":"資料缺失並非隨機，刪除後不能代表原來全年時段。","cn":"资料缺失并非随机，删除后不能代表原来全年时段。","en":"The missingness is not random; deletion does not preserve full-year representation."},"id":"a"},{"text":{"zh":"只要保留數據超過十筆，缺失模式便不重要。","cn":"只要保留数据超过十笔，缺失模式便不重要。","en":"Once more than ten records remain, the missingness pattern no longer matters."},"correct":false,"feedback":{"zh":"固定筆數不能消除系統性漏掉濕潤時段的偏差。","cn":"固定笔数不能消除系统性漏掉湿润时段的偏差。","en":"A fixed record count cannot remove bias from systematically missing wet periods."},"id":"b"},{"text":{"zh":"應把所有缺失日都填成 0% 濕度。","cn":"应把所有缺失日都填成 0% 湿度。","en":"Set all missing days to 0% humidity."},"correct":false,"feedback":{"zh":"這既無證據，也會把斷線錯當成極乾燥量度。","cn":"这既无证据，也会把断线错当成极干燥量度。","en":"This is unsupported and mistakes disconnection for an extremely dry measurement."},"id":"c"}],"takeaway":{"zh":"資料缺失的原因可能影響結論方向，需調查而非機械刪除。","cn":"资料缺失的原因可能影响结论方向，需调查而非机械删除。","en":"The cause of missing data can affect the direction of a conclusion and needs investigation."}},{"id":"s6-rooftop-01","grade":6,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"延伸：環境權衡的系統邊界","cn":"延伸：环境权衡的系统边界","en":"Extension: system boundaries in environmental trade-offs"},"question":{"zh":"更換天台種植系統節水 30%，卻增加抽水用電。哪項評估最恰當？","cn":"更换天台种植系统节水 30%，却增加抽水用电。哪项评估最恰当？","en":"A replacement rooftop growing system saves 30% of water but increases pumping electricity. Which assessment is most appropriate?"},"options":[{"text":{"zh":"節水 30% 必然等於總環境負荷降低 30%。","cn":"节水 30% 必然等于总环境负荷降低 30%。","en":"A 30% water saving must mean a 30% reduction in total environmental burden."},"correct":false,"feedback":{"zh":"水量不是所有環境影響的同一尺度。","cn":"水量不是所有环境影响的同一尺度。","en":"Water volume is not a common measure of every environmental impact."},"id":"a"},{"text":{"zh":"用電增加便證明所有節水都沒有價值。","cn":"用电增加便证明所有节水都没有价值。","en":"Any electricity increase proves all water savings have no value."},"correct":false,"feedback":{"zh":"這忽略水資源情況、能源來源及其他實際效益。","cn":"这忽略水资源情况、能源来源及其他实际效益。","en":"This ignores water scarcity, energy source and other practical benefits."},"id":"b"},{"text":{"zh":"同時比較節水、能源來源、產量、材料和使用年期，不能只憑單一百分比判定整體更好。","cn":"同时比较节水、能源来源、产量、材料和使用年期，不能只凭单一百分比判定整体更好。","en":"Compare water savings, energy source, output, materials and service life rather than judging overall benefit from one percentage."},"correct":true,"feedback":{"zh":"改善一項指標可能把負擔轉移到另一項，需要一致邊界的綜合比較。","cn":"改善一项指标可能把负担转移到另一项，需要一致边界的综合比较。","en":"Improving one indicator can shift burdens elsewhere, requiring a comparison within consistent boundaries."},"id":"c"}],"takeaway":{"zh":"環境決策要辨認負擔轉移，並明確選用的評估準則。","cn":"环境决策要辨认负担转移，并明确选用的评估准则。","en":"Environmental decisions should identify burden shifting and make evaluation criteria explicit."}},{"id":"s6-rooftop-02","grade":6,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"延伸：權重改變與敏感度","cn":"延伸：权重改变与敏感度","en":"Extension: changing weights and sensitivity"},"question":{"zh":"兩方案按 0–10 評分：A 節水 9、生態 4；B 節水 6、生態 8。兩項同權重時，哪個平均較高？若把節水權重改成 80%，結果怎樣？","cn":"两方案按 0–10 评分：A 节水 9、生态 4；B 节水 6、生态 8。两项同权重时，哪个平均较高？若把节水权重改成 80%，结果怎样？","en":"Scores out of 10: A has water-saving 9 and ecology 4; B has 6 and 8. Which has the higher equal-weight mean, and what happens with an 80% water-saving weight?"},"options":[{"text":{"zh":"同權重 B 較高；80% 節水時 A 較高。","cn":"同权重 B 较高；80% 节水时 A 较高。","en":"B ranks higher with equal weights; A ranks higher with 80% on water saving."},"correct":true,"feedback":{"zh":"同權重 A=6.5、B=7；新權重 A=8、B=6.4，排名會改變。","cn":"同权重 A=6.5、B=7；新权重 A=8、B=6.4，排名会改变。","en":"Equal weights give A=6.5, B=7; changed weights give A=8, B=6.4, reversing the ranking."},"id":"a"},{"text":{"zh":"A 在兩種權重都較高。","cn":"A 在两种权重都较高。","en":"A ranks higher under both weightings."},"correct":false,"feedback":{"zh":"同權重 B 的平均為 7，高於 A 的 6.5。","cn":"同权重 B 的平均为 7，高于 A 的 6.5。","en":"With equal weights B averages 7, above A's 6.5."},"id":"b"},{"text":{"zh":"改權重不會改排名，因為原始分數固定。","cn":"改权重不会改排名，因为原始分数固定。","en":"Weights cannot change rankings when raw scores stay fixed."},"correct":false,"feedback":{"zh":"加權結果同時取決於分數和準則權重。","cn":"加权结果同时取决于分数和准则权重。","en":"Weighted results depend on both scores and criterion weights."},"id":"c"}],"takeaway":{"zh":"多準則評估需公開權重並做敏感度分析，不能把排名當成唯一客觀真相。","cn":"多准则评估需公开权重并做敏感度分析，不能把排名当成唯一客观真相。","en":"Multi-criteria evaluations should disclose weights and test sensitivity rather than treating a ranking as uniquely objective."}},{"id":"s6-rooftop-03","grade":6,"subjectId":"rooftop","roomId":"rooftop","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"延伸：前後比較與反事實","cn":"延伸：前后比较与反事实","en":"Extension: before–after comparison and a counterfactual"},"question":{"zh":"裝綠化屋頂後，甲樓夏季用電跌 12%；同年未改裝的相似乙樓跌 10%，兩樓天氣及使用情況相近。哪項初步解讀最謹慎？","cn":"装绿化屋顶后，甲楼夏季用电跌 12%；同年未改装的相似乙楼跌 10%，两楼天气及使用情况相近。哪项初步解读最谨慎？","en":"After installing a green roof, A's summer electricity use falls 12%; a similar unchanged building B falls 10% in the same year under comparable weather and use. Which initial interpretation is most cautious?"},"options":[{"text":{"zh":"12−10=2，所以已精確證明每座樓永遠節電 2%。","cn":"12−10=2，所以已精确证明每座楼永远节电 2%。","en":"12−10=2 proves every building will always save exactly 2%."},"correct":false,"feedback":{"zh":"這只是有假設的初步差異，不能泛化到所有建築或永久效果。","cn":"这只是有假设的初步差异，不能泛化到所有建筑或永久效果。","en":"This is an assumption-dependent initial difference, not a universal or permanent effect."},"id":"a"},{"text":{"zh":"共同因素可能解釋大部分跌幅；額外約 2 個百分點可作初步線索，仍需檢查比較假設。","cn":"共同因素可能解释大部分跌幅；额外约 2 个百分点可作初步线索，仍需检查比较假设。","en":"Common factors may explain much of the decline; an extra two percentage points is a preliminary signal, subject to comparison assumptions."},"correct":true,"feedback":{"zh":"比較組有助估計沒有改裝時可能的變化，但仍不能保證兩樓完全可比。","cn":"比较组有助估计没有改装时可能的变化，但仍不能保证两楼完全可比。","en":"A comparison group informs the possible no-intervention change, but complete comparability is not guaranteed."},"id":"b"},{"text":{"zh":"12% 必定全部由綠化屋頂造成。","cn":"12% 必定全部由绿化屋顶造成。","en":"The roof must have caused the entire 12% reduction."},"correct":false,"feedback":{"zh":"乙樓沒有改裝也下降，顯示可能有共同時間因素。","cn":"乙楼没有改装也下降，显示可能有共同时间因素。","en":"B also declines without the intervention, suggesting shared time-related factors."},"id":"c"}],"takeaway":{"zh":"評估介入效果要考慮沒有介入時的合理比較，並交代假設及外推限制。","cn":"评估介入效果要考虑没有介入时的合理比较，并交代假设及外推限制。","en":"Evaluate interventions against a plausible no-intervention comparison and state assumptions and generalisation limits."}},{"id":"s1-playground-01","grade":1,"subjectId":"playground","roomId":"playground","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"傳球後的支援","cn":"传球后的支援","en":"Supporting after a pass"},"question":{"zh":"三人傳球練習中，你把球傳給隊友後，怎樣最有助下一次配合？","cn":"三人传球练习中，你把球传给队友后，怎样最有助下一次配合？","en":"In a three-player passing drill, what best supports the next move after you pass?"},"options":[{"text":{"zh":"傳球後完全停止觀察場面","cn":"传球后完全停止观察场面","en":"Stop watching the play after passing"},"correct":false,"feedback":{"zh":"支援需要持續留意隊友、防守者及空位。","cn":"支援需要持续留意队友、防守者及空位。","en":"Support requires continued awareness of players and space."},"id":"a"},{"text":{"zh":"移到可接應的空位，讓持球者看見你","cn":"移到可接应的空位，让持球者看见你","en":"Move into visible space to offer a return pass"},"correct":true,"feedback":{"zh":"移動可建立新的傳球角度，避免與持球者擠在一起。","cn":"移动可建立新的传球角度，避免与持球者挤在一起。","en":"Movement creates a new passing angle instead of crowding the ball carrier."},"id":"b"},{"text":{"zh":"一直跟在持球者身後貼近他","cn":"一直跟在持球者身后贴近他","en":"Stay immediately behind the ball carrier"},"correct":false,"feedback":{"zh":"這容易重疊位置，減少可用傳球角度。","cn":"这容易重叠位置，减少可用传球角度。","en":"This crowds the same space and reduces passing options."},"id":"c"}],"takeaway":{"zh":"球類配合不只看持球動作，也看無球時的位置。","cn":"球类配合不只看持球动作，也看无球时的位置。","en":"Team play depends on off-ball positioning as well as actions with the ball."}},{"id":"s1-playground-02","grade":1,"subjectId":"playground","roomId":"playground","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"身體平衡","cn":"身体平衡","en":"Body balance"},"question":{"zh":"在老師指導的靜態平衡示範中，其他條件相同，哪個姿勢通常較穩定？","cn":"在老师指导的静态平衡示范中，其他条件相同，哪个姿势通常较稳定？","en":"In a teacher-led static-balance demonstration, other conditions equal, which position is generally more stable?"},"options":[{"text":{"zh":"支撐面較窄，重心較高","cn":"支撑面较窄，重心较高","en":"A narrower base and a higher centre of gravity"},"correct":false,"feedback":{"zh":"這通常令身體較容易失去平衡。","cn":"这通常令身体较容易失去平衡。","en":"This generally makes loss of balance easier."},"id":"a"},{"text":{"zh":"支撐面不變，只把重心升得更高","cn":"支撑面不变，只把重心升得更高","en":"Keep the base unchanged but raise the centre of gravity"},"correct":false,"feedback":{"zh":"其他條件相同，提高重心通常不會增加靜態穩定性。","cn":"其他条件相同，提高重心通常不会增加静态稳定性。","en":"Other conditions equal, raising the centre of gravity generally does not improve static stability."},"id":"b"},{"text":{"zh":"支撐面較闊，重心較低","cn":"支撑面较阔，重心较低","en":"A wider base of support and a lower centre of gravity"},"correct":true,"feedback":{"zh":"較闊支撐面及較低重心通常增加抗傾倒的穩定性。","cn":"较阔支撑面及较低重心通常增加抗倾倒的稳定性。","en":"A wider base and lower centre of gravity generally improve resistance to tipping."},"id":"c"}],"takeaway":{"zh":"以重心及支撐面解釋穩定性，並在教師安排下練習。","cn":"以重心及支撑面解释稳定性，并在教师安排下练习。","en":"Explain stability through centre of gravity and base of support in supervised practice."}},{"id":"s1-playground-03","grade":1,"subjectId":"playground","roomId":"playground","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"清楚的比賽訊號","cn":"清楚的比赛讯号","en":"Clear signals in a game"},"question":{"zh":"小組遊戲用哨聲表示停止，但有同學未能清楚聽到。怎樣保留同一規則並改善全組參與？","cn":"小组游戏用哨声表示停止，但有同学未能清楚听到。怎样保留同一规则并改善全组参与？","en":"A group game uses a whistle to signal stop, but some players cannot hear it clearly. How can the same rule be made accessible?"},"options":[{"text":{"zh":"同步使用大家先練習過的明顯手勢或旗號","cn":"同步使用大家先练习过的明显手势或旗号","en":"Pair the whistle with a visible gesture or flag practised by everyone"},"correct":true,"feedback":{"zh":"多種訊號傳達同一指令，讓所有人及時理解。","cn":"多种讯号传达同一指令，让所有人及时理解。","en":"Multiple signals communicate the same instruction in time."},"id":"a"},{"text":{"zh":"只要求沒聽到的人退出","cn":"只要求没听到的人退出","en":"Require those who missed it to leave"},"correct":false,"feedback":{"zh":"退出沒有改善訊號，也減少參與機會。","cn":"退出没有改善讯号，也减少参与机会。","en":"Exclusion does not improve the signal and reduces participation."},"id":"b"},{"text":{"zh":"隨機更改停止的意思","cn":"随机更改停止的意思","en":"Randomly change what stop means"},"correct":false,"feedback":{"zh":"規則不一致會令所有人更難安全配合。","cn":"规则不一致会令所有人更难安全配合。","en":"Inconsistent meanings make coordinated play harder."},"id":"c"}],"takeaway":{"zh":"清楚、一致及可感知的規則訊號有助安全參與。","cn":"清楚、一致及可感知的规则讯号有助安全参与。","en":"Clear, consistent and perceptible signals support safe participation."}},{"id":"s2-playground-01","grade":2,"subjectId":"playground","roomId":"playground","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"訓練頻率","cn":"训练频率","en":"Training frequency"},"question":{"zh":"FITT中的frequency指頻率。計劃由每週兩次活動改為三次，而每次時長和強度不變，主要改了甚麼？","cn":"FITT中的frequency指频率。计划由每周两次活动改为三次，而每次时长和强度不变，主要改了甚么？","en":"In FITT, frequency describes how often activity occurs. A plan changes from two sessions weekly to three, with duration and intensity unchanged. What changes?"},"options":[{"text":{"zh":"每次時長","cn":"每次时长","en":"Duration per session"},"correct":false,"feedback":{"zh":"題目已說每次時長不變。","cn":"题目已说每次时长不变。","en":"The question states that session duration stays the same."},"id":"a"},{"text":{"zh":"活動類型","cn":"活动类型","en":"Activity type"},"correct":false,"feedback":{"zh":"題目沒有更換活動種類。","cn":"题目没有更换活动种类。","en":"No change of activity type is stated."},"id":"b"},{"text":{"zh":"頻率","cn":"频率","en":"Frequency"},"correct":true,"feedback":{"zh":"改變的是每週次數，而非每次時間或強度。","cn":"改变的是每周次数，而非每次时间或强度。","en":"The number of weekly sessions changes, not session duration or intensity."},"id":"c"}],"takeaway":{"zh":"用頻率、強度、時間與類型分開描述活動計劃。","cn":"用频率、强度、时间与类型分开描述活动计划。","en":"Describe frequency, intensity, time and type separately."}},{"id":"s2-playground-02","grade":2,"subjectId":"playground","roomId":"playground","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"技能回饋的焦點","cn":"技能回馈的焦点","en":"Focused skill feedback"},"question":{"zh":"傳球練習後，哪句回饋最能讓同學知道下一次要改甚麼？","cn":"传球练习后，哪句回馈最能让同学知道下一次要改甚么？","en":"After a passing drill, which feedback most clearly identifies what to change next?"},"options":[{"text":{"zh":"「傳球前先望接球者，確認他已準備好。」","cn":"「传球前先望接球者，确认他已准备好。」","en":"“Look at the receiver before passing and check they are ready.”"},"correct":true,"feedback":{"zh":"回饋指出可觀察、可實行的一項動作。","cn":"回馈指出可观察、可实行的一项动作。","en":"It identifies one observable and actionable behaviour."},"id":"a"},{"text":{"zh":"「你永遠都不擅長球類。」","cn":"「你永远都不擅长球类。」","en":"“You are always bad at ball games.”"},"correct":false,"feedback":{"zh":"固定標籤沒有提供改進方法。","cn":"固定标签没有提供改进方法。","en":"A fixed label offers no method for improvement."},"id":"b"},{"text":{"zh":"「總之做得好一點。」","cn":"「总之做得好一点。」","en":"“Just do better.”"},"correct":false,"feedback":{"zh":"說法太籠統，沒有指出可調整的行動。","cn":"说法太笼统，没有指出可调整的行动。","en":"This is too vague to identify a change."},"id":"c"}],"takeaway":{"zh":"有效回饋針對可改變的動作，而非給人固定能力標籤。","cn":"有效回馈针对可改变的动作，而非给人固定能力标签。","en":"Useful feedback targets adjustable actions rather than fixed ability labels."}},{"id":"s2-playground-03","grade":2,"subjectId":"playground","roomId":"playground","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"控制球場空間","cn":"控制球场空间","en":"Using playing space"},"question":{"zh":"進攻時四名隊員全擠在持球者旁邊，防守者容易封鎖傳球。哪個調整最能改善局面？","cn":"进攻时四名队员全挤在持球者旁边，防守者容易封锁传球。哪个调整最能改善局面？","en":"Four attackers crowd around the ball carrier, making passes easy to block. Which adjustment best improves the attack?"},"options":[{"text":{"zh":"只增加傳球力度，不改站位","cn":"只增加传球力度，不改站位","en":"Pass harder without changing positions"},"correct":false,"feedback":{"zh":"力度不能直接解決路線被集中封鎖的問題。","cn":"力度不能直接解决路线被集中封锁的问题。","en":"Power alone does not solve blocked passing lanes."},"id":"a"},{"text":{"zh":"拉開適當距離，形成不同方向的接應點","cn":"拉开适当距离，形成不同方向的接应点","en":"Spread out to create receiving options in different directions"},"correct":true,"feedback":{"zh":"寬度及不同角度可增加防守者要覆蓋的空間。","cn":"宽度及不同角度可增加防守者要覆盖的空间。","en":"Width and varied angles increase the space defenders must cover."},"id":"b"},{"text":{"zh":"全部再靠近持球者","cn":"全部再靠近持球者","en":"Move everyone even closer to the ball"},"correct":false,"feedback":{"zh":"這會進一步減少空間與傳球選擇。","cn":"这会进一步减少空间与传球选择。","en":"This further reduces space and passing options."},"id":"c"}],"takeaway":{"zh":"戰術選擇要回應空間、隊友及對手的位置。","cn":"战术选择要回应空间、队友及对手的位置。","en":"Base tactical choices on space and the positions of teammates and opponents."}},{"id":"s3-playground-01","grade":3,"subjectId":"playground","roomId":"playground","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"速度的量度","cn":"速度的量度","en":"Measuring speed"},"question":{"zh":"教學數據：一名學生用20秒跑100米，平均速度是多少？","cn":"教学数据：一名学生用20秒跑100米，平均速度是多少？","en":"Teaching data: a student covers 100 metres in 20 seconds. What is the average speed?"},"options":[{"text":{"zh":"5米／秒","cn":"5米／秒","en":"5 m/s"},"correct":true,"feedback":{"zh":"平均速度＝距離÷時間＝100÷20。","cn":"平均速度＝距离÷时间＝100÷20。","en":"Average speed equals distance divided by time: 100 ÷ 20."},"id":"a"},{"text":{"zh":"0.2米／秒","cn":"0.2米／秒","en":"0.2 m/s"},"correct":false,"feedback":{"zh":"這把時間除以距離，單位也不是速度。","cn":"这把时间除以距离，单位也不是速度。","en":"This divides time by distance rather than distance by time."},"id":"b"},{"text":{"zh":"2000米／秒","cn":"2000米／秒","en":"2000 m/s"},"correct":false,"feedback":{"zh":"距離乘時間不會得到速度。","cn":"距离乘时间不会得到速度。","en":"Multiplying distance by time does not give speed."},"id":"c"}],"takeaway":{"zh":"運動數據應同時核對計算方法及單位。","cn":"运动数据应同时核对计算方法及单位。","en":"Check both the calculation and its units when analysing performance data."}},{"id":"s3-playground-02","grade":3,"subjectId":"playground","roomId":"playground","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"動作學習的練習安排","cn":"动作学习的练习安排","en":"Practice for skill learning"},"question":{"zh":"初學者剛學會一個基本傳球動作。老師想先讓他穩定掌握，再適應變化。哪個安排較符合這個次序？","cn":"初学者刚学会一个基本传球动作。老师想先让他稳定掌握，再适应变化。哪个安排较符合这个次序？","en":"A beginner has just learned a basic pass. The teacher wants consistency first, then adaptation. Which sequence fits?"},"options":[{"text":{"zh":"永遠只練一個固定情境","cn":"永远只练一个固定情境","en":"Practise one fixed situation forever"},"correct":false,"feedback":{"zh":"這可建立熟悉感，卻不足以練習情境適應。","cn":"这可建立熟悉感，却不足以练习情境适应。","en":"This builds familiarity but does not develop adaptation."},"id":"a"},{"text":{"zh":"先在穩定條件重複，再逐步改變距離及接應位置","cn":"先在稳定条件重复，再逐步改变距离及接应位置","en":"Repeat under stable conditions, then gradually vary distance and receiver position"},"correct":true,"feedback":{"zh":"先建立動作，再加入變化，可配合不同學習階段。","cn":"先建立动作，再加入变化，可配合不同学习阶段。","en":"Establishing the action before adding variability fits different learning stages."},"id":"b"},{"text":{"zh":"首次就同時改變所有條件且不給回饋","cn":"首次就同时改变所有条件且不给回馈","en":"Change every condition immediately and provide no feedback"},"correct":false,"feedback":{"zh":"大量新變項會令初學者難以找出動作問題。","cn":"大量新变项会令初学者难以找出动作问题。","en":"Many new variables make it harder for a beginner to identify errors."},"id":"c"}],"takeaway":{"zh":"練習結構應配合技能熟練程度及所需遷移。","cn":"练习结构应配合技能熟练程度及所需迁移。","en":"Match practice structure to skill stage and transfer needs."}},{"id":"s3-playground-03","grade":3,"subjectId":"playground","roomId":"playground","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"勝負以外的體育精神","cn":"胜负以外的体育精神","en":"Sportsmanship beyond winning"},"question":{"zh":"在自行裁判的友誼賽，你清楚看到己方球員最後碰球出界，但對方未看見。哪個行動符合雙方事前同意的誠實報界規則？","cn":"在自行裁判的友谊赛，你清楚看到己方球员最后碰球出界，但对方未看见。哪个行动符合双方事前同意的诚实报界规则？","en":"In a self-officiated friendly game, you clearly see your teammate touch the ball last before it goes out; opponents miss it. What follows the agreed honest-calling rule?"},"options":[{"text":{"zh":"因為沒有裁判，就可隨時更改規則","cn":"因为没有裁判，就可随时更改规则","en":"Change the rule because no referee is present"},"correct":false,"feedback":{"zh":"自行裁判仍依靠共同規則，並非沒有規則。","cn":"自行裁判仍依靠共同规则，并非没有规则。","en":"Self-officiating still depends on shared rules."},"id":"a"},{"text":{"zh":"只在己方領先時才誠實報界","cn":"只在己方领先时才诚实报界","en":"Make honest calls only when your team leads"},"correct":false,"feedback":{"zh":"按比分選擇是否守規則並不一致。","cn":"按比分选择是否守规则并不一致。","en":"Applying honesty selectively by score is inconsistent."},"id":"b"},{"text":{"zh":"主動指出己方最後觸球，按規則交球","cn":"主动指出己方最后触球，按规则交球","en":"Acknowledge your team’s last touch and award possession by the rules"},"correct":true,"feedback":{"zh":"遵守已同意的規則需要在對己方不利時也誠實報告。","cn":"遵守已同意的规则需要在对己方不利时也诚实报告。","en":"Following the agreement includes honest calls when they disadvantage your team."},"id":"c"}],"takeaway":{"zh":"體育精神包括一致遵守共同規則與承擔責任。","cn":"体育精神包括一致遵守共同规则与承担责任。","en":"Sportsmanship includes consistent rules and responsibility."}},{"id":"s4-playground-01","grade":4,"subjectId":"playground","roomId":"playground","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"訓練的專項性","cn":"训练的专项性","en":"Training specificity"},"question":{"zh":"兩個課堂訓練例子：甲反覆練短距離快速起步，乙做持續較長時間的穩定活動。甲較直接針對哪項能力？","cn":"两个课堂训练例子：甲反复练短距离快速起步，乙做持续较长时间的稳定活动。甲较直接针对哪项能力？","en":"Two classroom examples: A practises repeated short, fast starts; B performs steady activity for longer periods. Which ability does A target more directly?"},"options":[{"text":{"zh":"讀懂比賽規則的速度","cn":"读懂比赛规则的速度","en":"Speed of reading game rules"},"correct":false,"feedback":{"zh":"題目練習的是身體動作，沒有直接訓練閱讀。","cn":"题目练习的是身体动作，没有直接训练阅读。","en":"These are movement tasks, not direct reading practice."},"id":"a"},{"text":{"zh":"起步加速表現","cn":"起步加速表现","en":"Starting acceleration"},"correct":true,"feedback":{"zh":"短距離快速起步較接近加速動作的要求。","cn":"短距离快速起步较接近加速动作的要求。","en":"Fast short starts more closely match the demands of acceleration."},"id":"b"},{"text":{"zh":"長時間持續活動能力","cn":"长时间持续活动能力","en":"Capacity for prolonged continuous activity"},"correct":false,"feedback":{"zh":"這較接近乙的練習形式。","cn":"这较接近乙的练习形式。","en":"That more closely matches B’s activity."},"id":"c"}],"takeaway":{"zh":"訓練適應與練習所施加的具體要求有關。","cn":"训练适应与练习所施加的具体要求有关。","en":"Training adaptations relate to the specific demands practised."}},{"id":"s4-playground-02","grade":4,"subjectId":"playground","roomId":"playground","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"衝量與接球","cn":"冲量与接球","en":"Impulse and catching"},"question":{"zh":"簡化力學模型：同一顆球以相同速度到達，最後都停止。若接球時把減速時間延長，平均作用力通常怎樣變化？","cn":"简化力学模型：同一颗球以相同速度到达，最后都停止。若接球时把减速时间延长，平均作用力通常怎样变化？","en":"Simplified mechanics: the same ball arrives at the same speed and is brought to rest. If stopping time increases, what normally happens to average force?"},"options":[{"text":{"zh":"增加","cn":"增加","en":"It increases"},"correct":false,"feedback":{"zh":"在相同動量改變下，時間增加會使平均力減少。","cn":"在相同动量改变下，时间增加会使平均力减少。","en":"With momentum change fixed, increasing time reduces average force."},"id":"a"},{"text":{"zh":"必定變成零","cn":"必定变成零","en":"It must become zero"},"correct":false,"feedback":{"zh":"只要球的動量改變，有限時間內仍需要作用力。","cn":"只要球的动量改变，有限时间内仍需要作用力。","en":"Changing momentum over a finite time still requires force."},"id":"b"},{"text":{"zh":"減少","cn":"减少","en":"It decreases"},"correct":true,"feedback":{"zh":"動量改變相同時，平均力＝動量改變÷作用時間。","cn":"动量改变相同时，平均力＝动量改变÷作用时间。","en":"For the same momentum change, average force equals that change divided by time."},"id":"c"}],"takeaway":{"zh":"把運動技巧與作用時間、動量改變及平均力連繫。","cn":"把运动技巧与作用时间、动量改变及平均力连系。","en":"Connect movement technique with contact time, momentum change and average force."}},{"id":"s4-playground-03","grade":4,"subjectId":"playground","roomId":"playground","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"技能成功率的比較","cn":"技能成功率的比较","en":"Comparing skill success rates"},"question":{"zh":"虛構練習：甲近距離射門10次中8次，乙遠距離射門10次中6次。能否只憑數字判定甲的射門能力較高？","cn":"虚构练习：甲近距离射门10次中8次，乙远距离射门10次中6次。能否只凭数字判定甲的射门能力较高？","en":"Fictional practice: A scores 8 of 10 close shots; B scores 6 of 10 long shots. Can these figures alone rank their shooting skill?"},"options":[{"text":{"zh":"不能；距離不同，應在可比較條件再測","cn":"不能；距离不同，应在可比较条件再测","en":"No; distances differ, so retest under comparable conditions"},"correct":true,"feedback":{"zh":"難度條件不同，成功率不能直接作相同能力的比較。","cn":"难度条件不同，成功率不能直接作相同能力的比较。","en":"Different difficulty conditions prevent a direct like-for-like comparison."},"id":"a"},{"text":{"zh":"能；8永遠代表比6更高的能力","cn":"能；8永远代表比6更高的能力","en":"Yes; 8 always represents greater ability than 6"},"correct":false,"feedback":{"zh":"得分數未反映兩種任務的難度差異。","cn":"得分数未反映两种任务的难度差异。","en":"The counts do not account for different task difficulty."},"id":"b"},{"text":{"zh":"不能，因為成功率完全沒有用途","cn":"不能，因为成功率完全没有用途","en":"No, because success rates are entirely useless"},"correct":false,"feedback":{"zh":"成功率有用，但須配合相同或已調整的條件。","cn":"成功率有用，但须配合相同或已调整的条件。","en":"Success rates are useful when conditions are comparable or adjusted."},"id":"c"}],"takeaway":{"zh":"比較運動表現前，確認任務難度和量度條件相稱。","cn":"比较运动表现前，确认任务难度和量度条件相称。","en":"Check task difficulty and measurement conditions before comparing performance."}},{"id":"s5-playground-01","grade":5,"subjectId":"playground","roomId":"playground","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"開放與閉鎖技能","cn":"开放与闭锁技能","en":"Open and closed skills"},"question":{"zh":"以下哪項較接近開放技能：環境會改變，運動員需即時適應？","cn":"以下哪项较接近开放技能：环境会改变，运动员需即时适应？","en":"Which task most closely illustrates an open skill, requiring adaptation to a changing environment?"},"options":[{"text":{"zh":"在固定環境獨自投向同一靜止目標","cn":"在固定环境独自投向同一静止目标","en":"Throwing alone at the same stationary target in fixed conditions"},"correct":false,"feedback":{"zh":"環境較穩定、可預測，較接近閉鎖技能。","cn":"环境较稳定、可预测，较接近闭锁技能。","en":"The stable, predictable environment is closer to a closed skill."},"id":"a"},{"text":{"zh":"在固定位置、無對手幹擾時自行決定發球時間","cn":"在固定位置、无对手干扰时自行决定发球时间","en":"Serving at a chosen moment from a fixed position without opponent interference"},"correct":false,"feedback":{"zh":"這個起始環境較穩定且可自行控制時間，較接近閉鎖技能。","cn":"这个起始环境较稳定且可自行控制时间，较接近闭锁技能。","en":"The initial environment is stable and self-paced, closer to a closed skill."},"id":"b"},{"text":{"zh":"比賽中因應對手移動選擇傳球路線","cn":"比赛中因应对手移动选择传球路线","en":"Choosing a pass as opponents move during a game"},"correct":true,"feedback":{"zh":"對手及隊友動態變化，需要持續調整。","cn":"对手及队友动态变化，需要持续调整。","en":"Changing players’ positions require ongoing adjustment."},"id":"c"}],"takeaway":{"zh":"技能分類要看環境可預測程度及所需即時調整。","cn":"技能分类要看环境可预测程度及所需即时调整。","en":"Classify skills by environmental predictability and adaptation demands."}},{"id":"s5-playground-02","grade":5,"subjectId":"playground","roomId":"playground","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"速度測試的可靠性","cn":"速度测试的可靠性","en":"Reliability of a speed test"},"question":{"zh":"兩次短跑測試的起跑提示、距離、地面及計時方法都不同。要提高重測可靠性，應先怎樣做？","cn":"两次短跑测试的起跑提示、距离、地面及计时方法都不同。要提高重测可靠性，应先怎样做？","en":"Two sprint tests use different start cues, distances, surfaces and timing methods. What should be done first to improve test–retest reliability?"},"options":[{"text":{"zh":"標準化上述程序，安排一致的測試條件","cn":"标准化上述程序，安排一致的测试条件","en":"Standardise procedures and keep testing conditions consistent"},"correct":true,"feedback":{"zh":"減少量度程序差異，較能比較同一表現。","cn":"减少量度程序差异，较能比较同一表现。","en":"Reducing procedural variation makes repeated measurements more comparable."},"id":"a"},{"text":{"zh":"只記錄較快的一次並刪掉其他資料","cn":"只记录较快的一次并删掉其他资料","en":"Keep only the faster trial and delete the rest"},"correct":false,"feedback":{"zh":"選擇性保留無法改善測試程序，也掩蓋變異。","cn":"选择性保留无法改善测试程序，也掩盖变异。","en":"Selective recording does not improve the procedure and hides variability."},"id":"b"},{"text":{"zh":"每次更換全新的測試方法","cn":"每次更换全新的测试方法","en":"Use an entirely new test each time"},"correct":false,"feedback":{"zh":"方法更不一致，重測比較更困難。","cn":"方法更不一致，重测比较更困难。","en":"Greater inconsistency makes repeated comparison harder."},"id":"c"}],"takeaway":{"zh":"可靠性關乎一致量度，不等於只挑看來最好的結果。","cn":"可靠性关乎一致量度，不等于只挑看来最好的结果。","en":"Reliability concerns consistent measurement, not selecting the best-looking result."}},{"id":"s5-playground-03","grade":5,"subjectId":"playground","roomId":"playground","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"回饋逐步減少","cn":"回馈逐步减少","en":"Reducing feedback gradually"},"question":{"zh":"同學已能穩定完成技能，卻每次都要等教練立即評語。若目標是提升自我判斷，哪個安排較合適？","cn":"同学已能稳定完成技能，却每次都要等教练立即评语。若目标是提升自我判断，哪个安排较合适？","en":"A learner performs consistently but waits for immediate coaching after every attempt. To develop self-evaluation, which arrangement is more suitable?"},"options":[{"text":{"zh":"從此不准他尋求任何回饋","cn":"从此不准他寻求任何回馈","en":"Never allow feedback again"},"correct":false,"feedback":{"zh":"完全禁止回饋不等於有計劃地發展自我調節。","cn":"完全禁止回馈不等于有计划地发展自我调节。","en":"Banning all feedback is not a planned approach to self-regulation."},"id":"a"},{"text":{"zh":"先讓他自評，再間歇提供具體回饋","cn":"先让他自评，再间歇提供具体回馈","en":"Ask for self-evaluation first, then provide specific feedback intermittently"},"correct":true,"feedback":{"zh":"自評與逐步減少外來提示可練習獨立辨識動作效果。","cn":"自评与逐步减少外来提示可练习独立辨识动作效果。","en":"Self-evaluation and reduced external prompting develop independent error recognition."},"id":"b"},{"text":{"zh":"每個動作都增加更多即時指令","cn":"每个动作都增加更多即时指令","en":"Add more immediate instructions to every movement"},"correct":false,"feedback":{"zh":"這可能加強依賴，而不是自我判斷。","cn":"这可能加强依赖，而不是自我判断。","en":"This may increase dependence rather than self-evaluation."},"id":"c"}],"takeaway":{"zh":"按學習階段調整回饋頻率，逐步培養自主監察。","cn":"按学习阶段调整回馈频率，逐步培养自主监察。","en":"Adjust feedback frequency to develop self-monitoring as skill grows."}},{"id":"s6-playground-01","grade":6,"subjectId":"playground","roomId":"playground","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"效度與測試目的","cn":"效度与测试目的","en":"Validity and test purpose"},"question":{"zh":"老師想量度球員的傳球決策能力，卻只用100米跑時間排名。主要問題是甚麼？","cn":"老师想量度球员的传球决策能力，却只用100米跑时间排名。主要问题是甚么？","en":"A teacher wants to assess passing decisions but ranks players solely by 100-metre sprint time. What is the main problem?"},"options":[{"text":{"zh":"測試與要量度的能力不相符","cn":"测试与要量度的能力不相符","en":"The test does not match the intended ability"},"correct":true,"feedback":{"zh":"跑速可量度速度，卻未直接觀察傳球判斷。","cn":"跑速可量度速度，却未直接观察传球判断。","en":"Sprint time measures speed, not passing decisions directly."},"id":"a"},{"text":{"zh":"只要秒錶準確，便能量度任何能力","cn":"只要秒表准确，便能量度任何能力","en":"An accurate stopwatch can measure any ability"},"correct":false,"feedback":{"zh":"量度準確不等於測到正確構念。","cn":"量度准确不等于测到正确构念。","en":"Precise measurement does not guarantee the right construct is measured."},"id":"b"},{"text":{"zh":"所有體育測試都不能提供資料","cn":"所有体育测试都不能提供资料","en":"No sports test can provide information"},"correct":false,"feedback":{"zh":"問題在測試選擇，不是所有測試皆無用。","cn":"问题在测试选择，不是所有测试皆无用。","en":"The issue is test selection, not the usefulness of all testing."},"id":"c"}],"takeaway":{"zh":"先界定學習目標，再選能直接觀察該能力的量度。","cn":"先界定学习目标，再选能直接观察该能力的量度。","en":"Define the learning objective before selecting a measure that captures it."}},{"id":"s6-playground-02","grade":6,"subjectId":"playground","roomId":"playground","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"觀察者評分的一致性","cn":"观察者评分的一致性","en":"Consistency between observers"},"question":{"zh":"兩位評判用同一張傳球決策量表，對同段影片評分差距很大。哪個改善最直接？","cn":"两位评判用同一张传球决策量表，对同段影片评分差距很大。哪个改善最直接？","en":"Two assessors use the same passing-decision rubric but give very different scores to one video. Which improvement is most direct?"},"options":[{"text":{"zh":"刪去量表，只憑印象","cn":"删去量表，只凭印象","en":"Remove the rubric and rely on impressions"},"correct":false,"feedback":{"zh":"缺乏清楚準則通常更難保持一致。","cn":"缺乏清楚准则通常更难保持一致。","en":"Removing clear criteria generally makes consistency harder."},"id":"a"},{"text":{"zh":"共同評分示例，釐清各級描述及分歧","cn":"共同评分示例，厘清各级描述及分歧","en":"Score examples together and clarify criteria and disagreements"},"correct":true,"feedback":{"zh":"以示例校準判斷可改善評判對準則的共同理解。","cn":"以示例校准判断可改善评判对准则的共同理解。","en":"Calibration with examples improves shared interpretation of criteria."},"id":"b"},{"text":{"zh":"把兩人的分數相加就當作沒有分歧","cn":"把两人的分数相加就当作没有分歧","en":"Add their scores and treat the disagreement as resolved"},"correct":false,"feedback":{"zh":"加總不能解釋或改善評分差異的原因。","cn":"加总不能解释或改善评分差异的原因。","en":"Adding scores does not resolve why they differ."},"id":"c"}],"takeaway":{"zh":"評分工具需要清楚準則及共同校準，而不只是同一張表格。","cn":"评分工具需要清楚准则及共同校准，而不只是同一张表格。","en":"A shared rubric needs clear criteria and calibration, not merely an identical form."}},{"id":"s6-playground-03","grade":6,"subjectId":"playground","roomId":"playground","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"調適後仍評核同一目標","cn":"调适后仍评核同一目标","en":"Adapting access without changing the goal"},"question":{"zh":"課堂目標是傳球決策，某同學需要較慢的比賽節奏。哪個調適最能保留目標？","cn":"课堂目标是传球决策，某同学需要较慢的比赛节奏。哪个调适最能保留目标？","en":"The lesson assesses passing decisions, and one student needs a slower pace. Which adaptation best preserves the objective?"},"options":[{"text":{"zh":"替該同學決定每次傳球對象","cn":"替该同学决定每次传球对象","en":"Choose every receiver for the student"},"correct":false,"feedback":{"zh":"這移除了要評核的決策本身。","cn":"这移除了要评核的决策本身。","en":"This removes the decision-making being assessed."},"id":"a"},{"text":{"zh":"只讓他抄寫比賽規則，當作完成傳球決策","cn":"只让他抄写比赛规则，当作完成传球决策","en":"Replace the task with copying rules and count it as passing decisions"},"correct":false,"feedback":{"zh":"抄寫規則沒有展示在場上的觀察與選擇。","cn":"抄写规则没有展示在场上的观察与选择。","en":"Copying rules does not demonstrate decisions in play."},"id":"b"},{"text":{"zh":"降低整組移動速度，仍要求觀察空位並選擇傳球","cn":"降低整组移动速度，仍要求观察空位并选择传球","en":"Slow the group’s movement while retaining choices based on available space"},"correct":true,"feedback":{"zh":"調整參與條件，同時保留觀察及決策的核心要求。","cn":"调整参与条件，同时保留观察及决策的核心要求。","en":"This changes access conditions while retaining observation and decision-making."},"id":"c"}],"takeaway":{"zh":"包容調適應區分參與障礙與真正要學習、評核的能力。","cn":"包容调适应区分参与障碍与真正要学习、评核的能力。","en":"Distinguish access barriers from the actual learning and assessment target."}},{"id":"s1-hall-01","grade":1,"subjectId":"hall","roomId":"hall","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"有限資源與選擇","cn":"有限资源与选择","en":"Scarcity and choice"},"question":{"zh":"班會只有一小時場地時間，但兩個活動各需完整一小時，不能同時進行。問題最直接反映哪個概念？","cn":"班会只有一小时场地时间，但两个活动各需完整一小时，不能同时进行。问题最直接反映哪个概念？","en":"A class has one hour of venue time, but two activities each require a full hour and cannot run together. Which concept is illustrated?"},"options":[{"text":{"zh":"只要活動免費，就沒有資源限制","cn":"只要活动免费，就没有资源限制","en":"Free activities face no resource constraints"},"correct":false,"feedback":{"zh":"金錢不是唯一資源，時間及場地仍有限。","cn":"金钱不是唯一资源，时间及场地仍有限。","en":"Money is not the only resource; time and space are limited too."},"id":"a"},{"text":{"zh":"所有人的偏好必定相同","cn":"所有人的偏好必定相同","en":"Everyone must have identical preferences"},"correct":false,"feedback":{"zh":"資源限制並不決定大家有相同偏好。","cn":"资源限制并不决定大家有相同偏好。","en":"Resource scarcity does not determine people’s preferences."},"id":"b"},{"text":{"zh":"資源有限，必須作出選擇","cn":"资源有限，必须作出选择","en":"Limited resources require a choice"},"correct":true,"feedback":{"zh":"可用時間不足以同時滿足兩項用途，因此要取捨。","cn":"可用时间不足以同时满足两项用途，因此要取舍。","en":"Available time cannot meet both uses, so a choice is necessary."},"id":"c"}],"takeaway":{"zh":"免費不等於沒有成本；時間、空間及人力同樣有限。","cn":"免费不等于没有成本；时间、空间及人力同样有限。","en":"Free admission does not remove constraints on time, space and labour."}},{"id":"s1-hall-02","grade":1,"subjectId":"hall","roomId":"hall","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"機會成本","cn":"机会成本","en":"Opportunity cost"},"question":{"zh":"你只有足夠時間參加一項活動，偏好次序是籃球、戲劇、棋藝。若選籃球，最主要放棄的下一最佳選擇是甚麼？","cn":"你只有足够时间参加一项活动，偏好次序是篮球、戏剧、棋艺。若选篮球，最主要放弃的下一最佳选择是甚么？","en":"You have time for one activity and rank basketball first, drama second and chess third. If you choose basketball, what is the next-best alternative forgone?"},"options":[{"text":{"zh":"戲劇活動","cn":"戏剧活动","en":"Drama"},"correct":true,"feedback":{"zh":"機會成本是所放棄的下一最佳選擇，不是所有選項相加。","cn":"机会成本是所放弃的下一最佳选择，不是所有选项相加。","en":"Opportunity cost is the next-best alternative forgone, not the sum of all alternatives."},"id":"a"},{"text":{"zh":"戲劇和棋藝的全部價值總和","cn":"戏剧和棋艺的全部价值总和","en":"The combined value of drama and chess"},"correct":false,"feedback":{"zh":"你本來也不能同時參加兩者，不能把它們全部相加。","cn":"你本来也不能同时参加两者，不能把它们全部相加。","en":"You could not take both, so their values should not simply be added."},"id":"b"},{"text":{"zh":"籃球活動本身","cn":"篮球活动本身","en":"Basketball itself"},"correct":false,"feedback":{"zh":"籃球是得到的選擇，不是放棄的替代方案。","cn":"篮球是得到的选择，不是放弃的替代方案。","en":"Basketball is the chosen activity, not the alternative forgone."},"id":"c"}],"takeaway":{"zh":"分析選擇時，找出真正可行的下一最佳替代方案。","cn":"分析选择时，找出真正可行的下一最佳替代方案。","en":"Identify the feasible next-best alternative when analysing a choice."}},{"id":"s1-hall-03","grade":1,"subjectId":"hall","roomId":"hall","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"活動預算","cn":"活动预算","en":"An activity budget"},"question":{"zh":"虛構班會預算：收入600元，場地200元，材料每人15元，共20人。活動後餘額是多少？","cn":"虚构班会预算：收入600元，场地200元，材料每人15元，共20人。活动后余额是多少？","en":"Fictional class budget: income is $600, venue cost $200, and materials cost $15 each for 20 students. What remains?"},"options":[{"text":{"zh":"300元","cn":"300元","en":"$300"},"correct":false,"feedback":{"zh":"只扣材料費會漏掉200元場地開支。","cn":"只扣材料费会漏掉200元场地开支。","en":"Subtracting only materials omits the $200 venue cost."},"id":"a"},{"text":{"zh":"100元","cn":"100元","en":"$100"},"correct":true,"feedback":{"zh":"材料費15×20＝300元；600−200−300＝100元。","cn":"材料费15×20＝300元；600−200−300＝100元。","en":"Materials cost 15 × 20 = 300; 600 − 200 − 300 = 100."},"id":"b"},{"text":{"zh":"385元","cn":"385元","en":"$385"},"correct":false,"feedback":{"zh":"這只扣了一人的材料費，漏算其餘19人。","cn":"这只扣了一人的材料费，漏算其余19人。","en":"This subtracts materials for only one student."},"id":"c"}],"takeaway":{"zh":"預算要區分固定開支和隨人數改變的開支。","cn":"预算要区分固定开支和随人数改变的开支。","en":"Distinguish fixed costs from costs that vary with participation."}},{"id":"s2-hall-01","grade":2,"subjectId":"hall","roomId":"hall","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"按單位比較價格","cn":"按单位比较价格","en":"Comparing unit prices"},"question":{"zh":"同款果汁：甲600毫升售12元，乙1000毫升售18元。只比較每100毫升價格，哪個較低？","cn":"同款果汁：甲600毫升售12元，乙1000毫升售18元。只比较每100毫升价格，哪个较低？","en":"The same juice costs $12 for 600 mL or $18 for 1000 mL. Which has the lower price per 100 mL?"},"options":[{"text":{"zh":"乙，每100毫升1.8元","cn":"乙，每100毫升1.8元","en":"B, at $1.80 per 100 mL"},"correct":true,"feedback":{"zh":"甲每100毫升2元，乙1.8元；比較需使用相同單位。","cn":"甲每100毫升2元，乙1.8元；比较需使用相同单位。","en":"A costs $2 per 100 mL and B $1.80; use a common unit."},"id":"a"},{"text":{"zh":"甲，因為總價12元較少","cn":"甲，因为总价12元较少","en":"A, because $12 is the smaller total"},"correct":false,"feedback":{"zh":"總價較低不代表每單位較便宜。","cn":"总价较低不代表每单位较便宜。","en":"A lower total price does not mean a lower unit price."},"id":"b"},{"text":{"zh":"兩者相同，因為是同款果汁","cn":"两者相同，因为是同款果汁","en":"They are equal because the juice is the same"},"correct":false,"feedback":{"zh":"產品相同也可能有不同包裝單價。","cn":"产品相同也可能有不同包装单价。","en":"Identical products can have different unit prices."},"id":"c"}],"takeaway":{"zh":"單價有助比較，但購買時仍要考慮實際需要與可用預算。","cn":"单价有助比较，但购买时仍要考虑实际需要与可用预算。","en":"Unit prices support comparison, alongside actual need and available budget."}},{"id":"s2-hall-02","grade":2,"subjectId":"hall","roomId":"hall","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"需求增加的模型","cn":"需求增加的模型","en":"A rise in demand"},"question":{"zh":"簡化市場模型：學校紀念冊供應量暫時固定，更多人願意在原價購買。其他條件不變，市場價格通常面對哪種壓力？","cn":"简化市场模型：学校纪念册供应量暂时固定，更多人愿意在原价购买。其他条件不变，市场价格通常面对哪种压力？","en":"Simplified market model: yearbook supply is fixed in the short run and more people want to buy at the original price. Other things equal, what price pressure arises?"},"options":[{"text":{"zh":"完全沒有任何壓力，因為印製成本未改","cn":"完全没有任何压力，因为印制成本未改","en":"No pressure because printing costs are unchanged"},"correct":false,"feedback":{"zh":"市場價格也受需求與供應影響，不只看成本。","cn":"市场价格也受需求与供应影响，不只看成本。","en":"Market price depends on demand and supply as well as cost."},"id":"a"},{"text":{"zh":"上升壓力","cn":"上升压力","en":"Upward pressure"},"correct":true,"feedback":{"zh":"原價下需求增加而供應未增，出現向上的價格壓力。","cn":"原价下需求增加而供应未增，出现向上的价格压力。","en":"Higher demand with unchanged supply creates upward price pressure."},"id":"b"},{"text":{"zh":"下降壓力，因更多人想買就會自動增加供應","cn":"下降压力，因更多人想买就会自动增加供应","en":"Downward pressure because more buyers automatically create more copies"},"correct":false,"feedback":{"zh":"需求增加不會自動增加題目中暫時固定的供應。","cn":"需求增加不会自动增加题目中暂时固定的供应。","en":"Extra demand does not automatically expand the stipulated fixed supply."},"id":"c"}],"takeaway":{"zh":"在「其他條件不變」的模型中，分別分析需求與供應的變動。","cn":"在「其他条件不变」的模型中，分别分析需求与供应的变动。","en":"Analyse demand and supply changes separately under an other-things-equal assumption."}},{"id":"s2-hall-03","grade":2,"subjectId":"hall","roomId":"hall","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"可比較的消費資訊","cn":"可比较的消费资讯","en":"Comparable consumer information"},"question":{"zh":"兩款水樽都聲稱「更耐用」，但測試方法不同。哪項資訊最有助有根據地比較？","cn":"两款水樽都声称「更耐用」，但测试方法不同。哪项资讯最有助有根据地比较？","en":"Two bottles both claim to be more durable but use different tests. Which information best supports a reasoned comparison?"},"options":[{"text":{"zh":"只比較兩款廣告對「耐用」一詞的使用次數","cn":"只比较两款广告对「耐用」一词的使用次数","en":"Only count how often each advert says “durable”"},"correct":false,"feedback":{"zh":"宣傳次數不能代替可比較的產品測試。","cn":"宣传次数不能代替可比较的产品测试。","en":"Repetition of a claim cannot replace comparable product testing."},"id":"a"},{"text":{"zh":"只看哪個售價較高","cn":"只看哪个售价较高","en":"Only which costs more"},"correct":false,"feedback":{"zh":"售價較高並不直接證明相同測試下更耐用。","cn":"售价较高并不直接证明相同测试下更耐用。","en":"A higher price does not prove better durability under the same test."},"id":"b"},{"text":{"zh":"相同條件的測試方法、結果及限制","cn":"相同条件的测试方法、结果及限制","en":"Methods, results and limitations from comparable test conditions"},"correct":true,"feedback":{"zh":"同條件資料較能比較產品表現，而不只是廣告措辭。","cn":"同条件资料较能比较产品表现，而不只是广告措辞。","en":"Comparable conditions support a performance comparison beyond advertising language."},"id":"c"}],"takeaway":{"zh":"消費判斷應檢查主張的量度方式、比較基準及限制。","cn":"消费判断应检查主张的量度方式、比较基准及限制。","en":"Assess how consumer claims are measured, compared and qualified."}},{"id":"s3-hall-01","grade":3,"subjectId":"hall","roomId":"hall","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"第三者受到的影響","cn":"第三者受到的影响","en":"Effects on third parties"},"question":{"zh":"午間音樂活動令參加者開心，但鄰近自修室使用者難以集中；他們沒有參加活動。哪項分析最準確？","cn":"午间音乐活动令参加者开心，但邻近自修室使用者难以集中；他们没有参加活动。哪项分析最准确？","en":"A lunchtime music event benefits participants but distracts nearby study-room users who are not taking part. Which analysis fits?"},"options":[{"text":{"zh":"所有音樂活動必須永久取消","cn":"所有音乐活动必须永久取消","en":"Every music event must be permanently cancelled"},"correct":false,"feedback":{"zh":"指出外部影響不等於只有取消一種處理方法。","cn":"指出外部影响不等于只有取消一种处理方法。","en":"Recognising an external effect does not make cancellation the only response."},"id":"a"},{"text":{"zh":"活動對非參與者產生外部影響","cn":"活动对非参与者产生外部影响","en":"The activity creates an external effect on non-participants"},"correct":true,"feedback":{"zh":"影響落在活動參與者以外的人身上，也應納入決策。","cn":"影响落在活动参与者以外的人身上，也应纳入决策。","en":"Effects on people outside the activity should also be considered."},"id":"b"},{"text":{"zh":"只要參加者滿意，就沒有其他影響","cn":"只要参加者满意，就没有其他影响","en":"If participants are happy, there are no other effects"},"correct":false,"feedback":{"zh":"這忽略題目中已出現的第三者影響。","cn":"这忽略题目中已出现的第三者影响。","en":"This ignores the stated effects on third parties."},"id":"c"}],"takeaway":{"zh":"公共決策須考慮直接參與者以外的人受到的影響。","cn":"公共决策须考虑直接参与者以外的人受到的影响。","en":"Consider effects on people beyond the direct participants in a public decision."}},{"id":"s3-hall-02","grade":3,"subjectId":"hall","roomId":"hall","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"共同資源的安排","cn":"共同资源的安排","en":"Managing a shared resource"},"question":{"zh":"自修室有20個座位，30名學生同時需要使用。若目標是讓更多人有合理使用機會，哪個方案最直接處理座位限制？","cn":"自修室有20个座位，30名学生同时需要使用。若目标是让更多人有合理使用机会，哪个方案最直接处理座位限制？","en":"A study room has 20 seats and 30 students need it at once. Which plan most directly addresses capacity while broadening access?"},"options":[{"text":{"zh":"讓最早到的20人每天整天保留座位","cn":"让最早到的20人每天整天保留座位","en":"Let the first 20 arrivals keep their seats all day"},"correct":false,"feedback":{"zh":"這雖容易執行，卻未增加其餘學生的使用機會。","cn":"这虽容易执行，却未增加其余学生的使用机会。","en":"This is simple to administer but does not broaden access for the remaining students."},"id":"a"},{"text":{"zh":"容許首批使用者永久保留座位","cn":"容许首批使用者永久保留座位","en":"Let the first users reserve seats permanently"},"correct":false,"feedback":{"zh":"這可能排除後來有需要的人，沒有增加使用機會。","cn":"这可能排除后来有需要的人，没有增加使用机会。","en":"This can exclude later users rather than broaden access."},"id":"b"},{"text":{"zh":"公佈分時段預約及合理使用時限，並檢查實際需求","cn":"公布分时段预约及合理使用时限，并检查实际需求","en":"Publish timed bookings and reasonable limits, then review demand"},"correct":true,"feedback":{"zh":"時段安排把有限容量分配到不同時間，亦可依需求調整。","cn":"时段安排把有限容量分配到不同时间，亦可依需求调整。","en":"Time slots distribute limited capacity over time and can be adjusted to demand."},"id":"c"}],"takeaway":{"zh":"共同資源分配須有清楚程序，並按實際使用情況檢討。","cn":"共同资源分配须有清楚程序，并按实际使用情况检讨。","en":"Use clear procedures and review real usage when allocating shared resources."}},{"id":"s3-hall-03","grade":3,"subjectId":"hall","roomId":"hall","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"多數意見的界限","cn":"多数意见的界限","en":"Limits of a majority view"},"question":{"zh":"80%的受訪者贊成把通知只放在手機應用程式，但部分學生沒有合適裝置。決定前最應補充哪項資料？","cn":"80%的受访者赞成把通知只放在手机应用程式，但部分学生没有合适装置。决定前最应补充哪项资料？","en":"Eighty percent of respondents favour app-only notices, but some students lack a suitable device. What additional information matters most before deciding?"},"options":[{"text":{"zh":"無法使用的人數、原因，以及可行的替代接收方法","cn":"无法使用的人数、原因，以及可行的替代接收方法","en":"How many cannot access it, why, and what alternative delivery is feasible"},"correct":true,"feedback":{"zh":"多數偏好不能回答少數是否會失去必要資訊。","cn":"多数偏好不能回答少数是否会失去必要资讯。","en":"Majority preference does not establish whether others would lose essential information."},"id":"a"},{"text":{"zh":"只計算全校平均每人擁有多少部裝置","cn":"只计算全校平均每人拥有多少部装置","en":"Only calculate the average number of devices per student"},"correct":false,"feedback":{"zh":"平均數可能掩蓋有人沒有合適裝置，仍未回答誰無法接收通知。","cn":"平均数可能掩盖有人没有合适装置，仍未回答谁无法接收通知。","en":"An average can conceal students with no suitable device and does not identify who misses notices."},"id":"b"},{"text":{"zh":"假定未回覆者全部同意","cn":"假定未回复者全部同意","en":"Assume every non-respondent agrees"},"correct":false,"feedback":{"zh":"未回覆不能當作贊成，也不能忽略其接收限制。","cn":"未回复不能当作赞成，也不能忽略其接收限制。","en":"Non-response is not agreement and may reflect access barriers."},"id":"c"}],"takeaway":{"zh":"使用調查結果時，同時檢查未被平均數或多數票反映的需要。","cn":"使用调查结果时，同时检查未被平均数或多数票反映的需要。","en":"Examine needs that averages or majority preferences may hide."}},{"id":"s4-hall-01","grade":4,"subjectId":"hall","roomId":"hall","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"名義收入與購買力","cn":"名义收入与购买力","en":"Nominal income and purchasing power"},"question":{"zh":"教學模型：每月零用錢由100元增至110元，同一籃物品價格由100元增至120元。購買同一籃物品的能力如何變化？","cn":"教学模型：每月零用钱由100元增至110元，同一篮物品价格由100元增至120元。购买同一篮物品的能力如何变化？","en":"Teaching model: monthly allowance rises from $100 to $110, while the same basket of goods rises from $100 to $120. What happens to purchasing power?"},"options":[{"text":{"zh":"上升，因為收到的金額增加","cn":"上升，因为收到的金额增加","en":"It rises because the cash amount increases"},"correct":false,"feedback":{"zh":"名義金額增加不代表相對價格後的購買力增加。","cn":"名义金额增加不代表相对价格后的购买力增加。","en":"More cash does not necessarily mean greater purchasing power after price changes."},"id":"a"},{"text":{"zh":"不變，因兩項都增加10%以上","cn":"不变，因两项都增加10%以上","en":"It is unchanged because both increase by at least 10%"},"correct":false,"feedback":{"zh":"兩項增幅不同，不能因同樣上升就視為抵消。","cn":"两项增幅不同，不能因同样上升就视为抵消。","en":"Different growth rates do not cancel merely because both rise."},"id":"b"},{"text":{"zh":"下降，因收入增幅低於該籃物品價格增幅","cn":"下降，因收入增幅低于该篮物品价格增幅","en":"It falls because income grows less than the basket’s price"},"correct":true,"feedback":{"zh":"原先可買一籃，現在110÷120不足一籃。","cn":"原先可买一篮，现在110÷120不足一篮。","en":"The allowance previously bought one basket; 110 ÷ 120 now buys less than one."},"id":"c"}],"takeaway":{"zh":"比較生活負擔時，區分金額變化與相對價格後的購買力。","cn":"比较生活负担时，区分金额变化与相对价格后的购买力。","en":"Distinguish nominal amounts from purchasing power after price changes."}},{"id":"s4-hall-02","grade":4,"subjectId":"hall","roomId":"hall","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"事實判斷與價值判斷","cn":"事实判断与价值判断","en":"Factual and value judgements"},"question":{"zh":"以下哪句主要是可用資料檢查的事實主張，而非對應然分配的價值判斷？","cn":"以下哪句主要是可用资料检查的事实主张，而非对应然分配的价值判断？","en":"Which statement is primarily an empirically testable claim rather than a value judgement about allocation?"},"options":[{"text":{"zh":"新安排下，每週可預約時段由10個增至14個","cn":"新安排下，每周可预约时段由10个增至14个","en":"Under the new plan, weekly bookable slots rose from 10 to 14"},"correct":true,"feedback":{"zh":"可以核對時間表驗證數量變化。","cn":"可以核对时间表验证数量变化。","en":"Timetables can verify the numerical change."},"id":"a"},{"text":{"zh":"所有人都應優先選自己最喜歡的時段","cn":"所有人都应优先选自己最喜欢的时段","en":"Everyone should have priority for their favourite slot"},"correct":false,"feedback":{"zh":"「應」表達分配上的價值立場，需討論準則。","cn":"「应」表达分配上的价值立场，需讨论准则。","en":"“Should” expresses an allocation principle that requires evaluation."},"id":"b"},{"text":{"zh":"公平一定比效率更重要","cn":"公平一定比效率更重要","en":"Fairness must always matter more than efficiency"},"correct":false,"feedback":{"zh":"這是對價值優先次序的判斷，不能只用時段數證明。","cn":"这是对价值优先次序的判断，不能只用时段数证明。","en":"This ranks values and cannot be proved solely by counting slots."},"id":"c"}],"takeaway":{"zh":"分辨可查證的實然主張與需說明理由的價值立場。","cn":"分辨可查证的实然主张与需说明理由的价值立场。","en":"Distinguish testable descriptive claims from value positions requiring justification."}},{"id":"s4-hall-03","grade":4,"subjectId":"hall","roomId":"hall","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"諮詢的代表性","cn":"咨询的代表性","en":"Representation in consultation"},"question":{"zh":"新校園路線只諮詢每天坐校車的學生，但方案也改變步行者和輪椅使用者的出入口。哪個補充最能改善諮詢？","cn":"新校园路线只咨询每天坐校车的学生，但方案也改变步行者和轮椅使用者的出入口。哪个补充最能改善咨询？","en":"A route plan consults only school-bus users but changes entrances for walkers and wheelchair users too. What best improves the consultation?"},"options":[{"text":{"zh":"只模擬校車上落客時間，代替所有使用者測試","cn":"只模拟校车上落客时间，代替所有使用者测试","en":"Simulate only bus boarding times instead of testing with all users"},"correct":false,"feedback":{"zh":"這可改善校車資料，卻仍未涵蓋步行及無障礙出入口。","cn":"这可改善校车资料，却仍未涵盖步行及无障碍出入口。","en":"This improves bus data but still omits walking and accessible entrances."},"id":"a"},{"text":{"zh":"讓受影響但未被訪問的使用者試走並提供回饋","cn":"让受影响但未被访问的使用者试走并提供回馈","en":"Invite affected, previously unconsulted users to test the routes and comment"},"correct":true,"feedback":{"zh":"補足使用經驗，有助發現現有樣本未涵蓋的問題。","cn":"补足使用经验，有助发现现有样本未涵盖的问题。","en":"Additional user experience can reveal problems absent from the initial sample."},"id":"b"},{"text":{"zh":"只增加更多校車使用者，仍不問其他人","cn":"只增加更多校车使用者，仍不问其他人","en":"Add more bus users but no other groups"},"correct":false,"feedback":{"zh":"增加相同羣體數量不會填補未涵蓋的經驗。","cn":"增加相同群体数量不会填补未涵盖的经验。","en":"A larger sample of the same group does not fill the missing perspectives."},"id":"c"}],"takeaway":{"zh":"諮詢品質不只看人數，也看是否涵蓋受影響的經驗。","cn":"咨询品质不只看人数，也看是否涵盖受影响的经验。","en":"Consultation quality depends on coverage of affected experiences, not only headcount."}},{"id":"s5-hall-01","grade":5,"subjectId":"hall","roomId":"hall","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"利益衝突的程序","cn":"利益冲突的程序","en":"A conflict-of-interest procedure"},"question":{"zh":"學生委員會選活動供應商，一名委員的家人擁有其中一家公司。最能維持可檢查決策程序的安排是甚麼？","cn":"学生委员会选活动供应商，一名委员的家人拥有其中一家公司。最能维持可检查决策程序的安排是甚么？","en":"A student committee selects an event supplier; one member’s family owns a bidding company. Which procedure best supports an accountable decision?"},"options":[{"text":{"zh":"申報關係，按既定規則退出相關評分，由其他人按同一準則評估","cn":"申报关系，按既定规则退出相关评分，由其他人按同一准则评估","en":"Declare the connection and follow recusal rules, with others using the same criteria"},"correct":true,"feedback":{"zh":"申報及適當避席可減少私人利益影響評分的風險。","cn":"申报及适当避席可减少私人利益影响评分的风险。","en":"Disclosure and appropriate recusal reduce the risk of private interests shaping the score."},"id":"a"},{"text":{"zh":"只要委員保證公正，就不用告知其他人","cn":"只要委员保证公正，就不用告知其他人","en":"Keep it undisclosed if the member promises fairness"},"correct":false,"feedback":{"zh":"未申報關係令他人無法檢查可能影響判斷的因素。","cn":"未申报关系令他人无法检查可能影响判断的因素。","en":"Undisclosed connections prevent scrutiny of possible influences."},"id":"b"},{"text":{"zh":"直接選另一家公司，不需比較質素及價格","cn":"直接选另一家公司，不需比较质素及价格","en":"Automatically choose another company without comparing quality or price"},"correct":false,"feedback":{"zh":"處理衝突不等於放棄透明、一致的評估準則。","cn":"处理冲突不等于放弃透明、一致的评估准则。","en":"Managing a conflict does not remove the need for consistent evaluation criteria."},"id":"c"}],"takeaway":{"zh":"問責程序要使關係、準則和決定可被檢查。","cn":"问责程序要使关系、准则和决定可被检查。","en":"Accountable procedures make relevant relationships, criteria and decisions examinable."}},{"id":"s5-hall-02","grade":5,"subjectId":"hall","roomId":"hall","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"平均改善與羣體差異","cn":"平均改善与群体差异","en":"Average improvement and group differences"},"question":{"zh":"虛構試行：全校平均排隊時間由8分鐘降至6分鐘，但需要無障礙櫃位者由10分鐘升至15分鐘。哪句最準確？","cn":"虚构试行：全校平均排队时间由8分钟降至6分钟，但需要无障碍柜位者由10分钟升至15分钟。哪句最准确？","en":"Fictional pilot: average queuing time falls from 8 to 6 minutes overall, but rises from 10 to 15 for users of an accessible counter. Which statement is most accurate?"},"options":[{"text":{"zh":"只看15分鐘就能判定全校平均上升","cn":"只看15分钟就能判定全校平均上升","en":"The 15-minute figure proves the school-wide average increased"},"correct":false,"feedback":{"zh":"單一羣體結果不能取代題目已提供的整體平均。","cn":"单一群体结果不能取代题目已提供的整体平均。","en":"One subgroup does not replace the stated overall average."},"id":"a"},{"text":{"zh":"整體平均改善，但某羣體的經驗惡化，需分開檢討","cn":"整体平均改善，但某群体的经验恶化，需分开检讨","en":"The overall average improves while one group fares worse, requiring separate review"},"correct":true,"feedback":{"zh":"分組資料顯示平均值未反映的負擔。","cn":"分组资料显示平均值未反映的负担。","en":"Disaggregated data reveal burdens hidden by the overall average."},"id":"b"},{"text":{"zh":"所有人都快了2分鐘","cn":"所有人都快了2分钟","en":"Everyone waits 2 minutes less"},"correct":false,"feedback":{"zh":"平均差額不能套用到每個羣體或個人。","cn":"平均差额不能套用到每个群体或个人。","en":"An average difference cannot be assigned to every group or person."},"id":"c"}],"takeaway":{"zh":"評估公共方案時，同時看整體效果及負擔如何分配。","cn":"评估公共方案时，同时看整体效果及负担如何分配。","en":"Evaluate both overall effects and how benefits and burdens are distributed."}},{"id":"s5-hall-03","grade":5,"subjectId":"hall","roomId":"hall","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"短期成本與持續成本","cn":"短期成本与持续成本","en":"Initial and recurring costs"},"question":{"zh":"兩個活動方案：甲初期300元，其後每月80元；乙初期600元，其後每月20元。若完整使用6個月，哪個總成本較低？","cn":"两个活动方案：甲初期300元，其后每月80元；乙初期600元，其后每月20元。若完整使用6个月，哪个总成本较低？","en":"Two plans cost: A, $300 initially plus $80 per month; B, $600 initially plus $20 per month. Over six full months, which total is lower?"},"options":[{"text":{"zh":"甲：只需300元","cn":"甲：只需300元","en":"A: only $300"},"correct":false,"feedback":{"zh":"這漏掉持續六個月的每月費用。","cn":"这漏掉持续六个月的每月费用。","en":"This omits six months of recurring charges."},"id":"a"},{"text":{"zh":"兩者同為600元","cn":"两者同为600元","en":"Both cost $600"},"correct":false,"feedback":{"zh":"初期與每月費用必須分別累加，不能忽略其中一項。","cn":"初期与每月费用必须分别累加，不能忽略其中一项。","en":"Initial and recurring costs must both be counted."},"id":"b"},{"text":{"zh":"乙：720元；甲：780元","cn":"乙：720元；甲：780元","en":"B: $720; A: $780"},"correct":true,"feedback":{"zh":"甲300＋6×80＝780；乙600＋6×20＝720。","cn":"甲300＋6×80＝780；乙600＋6×20＝720。","en":"A costs 300 + 6 × 80 = 780; B costs 600 + 6 × 20 = 720."},"id":"c"}],"takeaway":{"zh":"比較方案要選定共同時段，計入初期及持續開支。","cn":"比较方案要选定共同时段，计入初期及持续开支。","en":"Compare plans over the same time horizon, including initial and recurring costs."}},{"id":"s6-hall-01","grade":6,"subjectId":"hall","roomId":"hall","category":"subject","level":"foundation","stars":1,"maxScore":1,"title":{"zh":"準則與可行方案","cn":"准则与可行方案","en":"Criteria and feasible options"},"question":{"zh":"學校預算1000元，要求方案至少服務50人且提供無障礙入口。甲900元／60人／有入口；乙800元／70人／無入口；丙1100元／80人／有入口。哪個符合全部既定條件？","cn":"学校预算1000元，要求方案至少服务50人且提供无障碍入口。甲900元／60人／有入口；乙800元／70人／无入口；丙1100元／80人／有入口。哪个符合全部既定条件？","en":"A school has $1000 and requires capacity for at least 50 people and an accessible entrance. A: $900/60 people/accessible; B: $800/70/no access; C: $1100/80/accessible. Which meets all conditions?"},"options":[{"text":{"zh":"丙","cn":"丙","en":"C"},"correct":false,"feedback":{"zh":"丙雖有人數及入口優勢，卻超出預算。","cn":"丙虽有人数及入口优势，却超出预算。","en":"C meets capacity and access but exceeds the budget."},"id":"a"},{"text":{"zh":"甲","cn":"甲","en":"A"},"correct":true,"feedback":{"zh":"甲符合預算、人數及入口三項限制。","cn":"甲符合预算、人数及入口三项限制。","en":"A meets the budget, capacity and access constraints."},"id":"b"},{"text":{"zh":"乙","cn":"乙","en":"B"},"correct":false,"feedback":{"zh":"乙成本較低、人數較多，但未符合無障礙入口條件。","cn":"乙成本较低、人数较多，但未符合无障碍入口条件。","en":"B is cheaper and larger but fails the access requirement."},"id":"c"}],"takeaway":{"zh":"先識別必須符合的限制，再比較可行方案的優劣。","cn":"先识别必须符合的限制，再比较可行方案的优劣。","en":"Identify binding constraints before comparing feasible alternatives."}},{"id":"s6-hall-02","grade":6,"subjectId":"hall","roomId":"hall","category":"subject","level":"application","stars":2,"maxScore":1,"title":{"zh":"未回覆者的聲音","cn":"未回复者的声音","en":"Understanding non-response"},"question":{"zh":"網上諮詢有40%學生回覆，多數支持方案；未回覆者中有不少較少使用網上平臺。哪個後續最能檢查是否漏掉重要意見？","cn":"网上咨询有40%学生回复，多数支持方案；未回复者中有不少较少使用网上平台。哪个后续最能检查是否漏掉重要意见？","en":"An online consultation receives responses from 40% of students, mostly supportive; many non-respondents rarely use the platform. What follow-up best checks missing views?"},"options":[{"text":{"zh":"把60%未回覆者都算作支持","cn":"把60%未回复者都算作支持","en":"Count the 60% non-response as support"},"correct":false,"feedback":{"zh":"沉默沒有提供贊成的證據。","cn":"沉默没有提供赞成的证据。","en":"Silence supplies no evidence of support."},"id":"a"},{"text":{"zh":"只把同一網上連結重貼給原來回覆者","cn":"只把同一网上连结重贴给原来回复者","en":"Resend the same link only to previous respondents"},"correct":false,"feedback":{"zh":"這沒有接觸原本被漏掉的人。","cn":"这没有接触原本被漏掉的人。","en":"This does not reach those missing from the initial responses."},"id":"b"},{"text":{"zh":"用紙本或面談接觸部分未回覆者，再比較需要與意見","cn":"用纸本或面谈接触部分未回复者，再比较需要与意见","en":"Reach some non-respondents by paper or interview and compare needs and views"},"correct":true,"feedback":{"zh":"改變接觸方式可檢查平臺使用習慣是否造成系統性遺漏。","cn":"改变接触方式可检查平台使用习惯是否造成系统性遗漏。","en":"Another contact method can test whether platform use caused systematic omissions."},"id":"c"}],"takeaway":{"zh":"未回覆並不等於沒有需要；評估接觸方式對參與的影響。","cn":"未回复并不等于没有需要；评估接触方式对参与的影响。","en":"Non-response does not mean no need; examine how access methods shape participation."}},{"id":"s6-hall-03","grade":6,"subjectId":"hall","roomId":"hall","category":"subject","level":"challenge","stars":3,"maxScore":1,"title":{"zh":"有指標的政策檢討","cn":"有指标的政策检讨","en":"Reviewing a policy with indicators"},"question":{"zh":"新自修室安排目標是縮短等候並保留不同羣體的使用機會。哪個三個月檢討最能回應兩項目標？","cn":"新自修室安排目标是缩短等候并保留不同群体的使用机会。哪个三个月检讨最能回应两项目标？","en":"A new study-room plan aims to reduce waits while preserving access for different groups. Which three-month review best addresses both?"},"options":[{"text":{"zh":"比較前後等候時間、各羣體成功預約比例及未能使用的原因","cn":"比较前后等候时间、各群体成功预约比例及未能使用的原因","en":"Compare waiting times, booking success by group and reasons for failed access"},"correct":true,"feedback":{"zh":"指標直接對應效率和機會分配，並能指出需要修訂之處。","cn":"指标直接对应效率和机会分配，并能指出需要修订之处。","en":"The measures address efficiency and access distribution and can guide revisions."},"id":"a"},{"text":{"zh":"只看總預約次數增加了多少","cn":"只看总预约次数增加了多少","en":"Only count the increase in total bookings"},"correct":false,"feedback":{"zh":"總次數不能充分反映等候或哪些羣體未能使用。","cn":"总次数不能充分反映等候或哪些群体未能使用。","en":"Total bookings do not adequately show waits or excluded groups."},"id":"b"},{"text":{"zh":"只問工作人員是否喜歡新表格","cn":"只问工作人员是否喜欢新表格","en":"Only ask whether staff like the new form"},"correct":false,"feedback":{"zh":"工作便利可以考慮，但不能取代原定學生使用目標。","cn":"工作便利可以考虑，但不能取代原定学生使用目标。","en":"Staff convenience matters but does not replace the stated access objectives."},"id":"c"}],"takeaway":{"zh":"公共方案須把目標轉成可檢查指標，並預留根據結果修訂的機會。","cn":"公共方案须把目标转成可检查指标，并预留根据结果修订的机会。","en":"Translate public goals into testable indicators and allow revision based on results."}}];
